declare(strict_types=1);
// Предварительно извлекаем действие, чтобы использовать его при дальнейшем
// разборе запроса (в том числе при обработке JSON-данных).
$preloadedAction = $_GET['action'] ?? $_POST['action'] ?? '';
if (!is_string($preloadedAction)) {
    $preloadedAction = '';
}
$preloadedAction = trim($preloadedAction);
if ($preloadedAction === '' && isset($_GET['f']) && is_string($_GET['f'])) {
    $preloadedAction = 'd';
}
// Резерв памяти позволяет вернуть JSON-диагностику даже при memory_limit fatal
// во время сохранения документа или действия Mini App, вместо пустого HTTP 500.
$docsFatalResponseReserve = str_repeat(' ', 262144);
register_shutdown_function(static function () use (&$docsFatalResponseReserve, &$preloadedAction): void {
    $docsFatalResponseReserve = '';
    $error = error_get_last();
    $fatalTypes = [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR];
    if (!is_array($error)
        || !in_array((int) ($error['type'] ?? 0), $fatalTypes, true)
        || !in_array($preloadedAction, ['create', 'update', 'mini_app_update_task'], true)
        || http_response_code() < 500
    ) {
        return;
    }
    if (!headers_sent()) {
        header('Content-Type: application/json; charset=UTF-8');
    }
    while (ob_get_level() > 0) {
        @ob_end_clean();
    }
    http_response_code(500);
    $payload = json_encode([
        'success' => false,
        'error' => 'PHP аварийно завершил сохранение задачи.',
        'reason' => 'php_fatal',
        'developer' => [
            'type' => (int) ($error['type'] ?? 0),
            'message' => substr((string) ($error['message'] ?? ''), 0, 2000),
            'file' => basename((string) ($error['file'] ?? '')),
            'line' => max(0, (int) ($error['line'] ?? 0)),
            'memoryLimit' => (string) ini_get('memory_limit'),
            'peakMemoryBytes' => memory_get_peak_usage(true),
            'serverTime' => date('c'),
        ],
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
    echo is_string($payload) ? $payload : '{"success":false,"error":"php_fatal","reason":"php_fatal"}';
});
function resolve_documents_root(): string
{
    $candidates = [];
    $envPath = getenv('BIMMAX_DOCUMENTS_ROOT');
    if (is_string($envPath) && trim($envPath) !== '') {
        $candidates[] = trim($envPath);
    }
    $candidates[] = '/var/www/www-root/data/www/bimmax.pro/documents';
    $candidates[] = __DIR__ . '/documents';
    foreach ($candidates as $candidate) {
        $normalized = rtrim($candidate, '/');
        if ($normalized !== '' && is_dir($normalized)) {
            return $normalized;
        }
    }
    return rtrim($candidates[0], '/');
}
define('DOCUMENTS_ROOT', resolve_documents_root());
