function docs_detect_client_platform(?string $userAgent): string
{
    if ($userAgent === null) {
        return 'unknown';
    }
    $normalized = trim(mb_strtolower($userAgent, 'UTF-8'));
    if ($normalized === '') {
        return 'unknown';
    }
    if (strpos($normalized, 'iphone') !== false || strpos($normalized, 'ipad') !== false
        || strpos($normalized, 'ipod') !== false) {
        return 'ios';
    }
    if (strpos($normalized, 'android') !== false) {
        return 'android';
    }
    if (strpos($normalized, 'mac os') !== false || strpos($normalized, 'macintosh') !== false) {
        return 'macos';
    }
    if (strpos($normalized, 'windows') !== false) {
        return 'windows';
    }
    if (strpos($normalized, 'linux') !== false) {
        return 'linux';
    }
    return 'unknown';
}
function docs_trim_wrapping_quotes(string $value): string
{
    $value = trim($value);
    $length = strlen($value);
    if ($length < 2) {
        return $value;
    }
    $first = $value[0];
    $last = $value[$length - 1];
    if (($first === '"' && $last === '"') || ($first === "'" && $last === "'")) {
        return substr($value, 1, $length - 2);
    }
    return $value;
}
function docs_extract_token_from_env_content(string $content): ?string
{
    $lines = preg_split('/\r\n|\r|\n/', $content);
    $allowedKeys = ['TELEGRAM_BOT_TOKEN', 'BOT_TOKEN', 'TOKEN'];
    foreach ($lines as $line) {
        if (!is_string($line)) {
            continue;
        }
        $trimmed = trim($line);
        if ($trimmed === '') {
            continue;
        }
        $firstChar = $trimmed[0];
        if ($firstChar === '#' || $firstChar === ';') {
            continue;
        }
        if (strpos($trimmed, '#') !== false) {
            $parts = preg_split('/\s+#/', $trimmed, 2);
            if (isset($parts[0])) {
                $trimmed = trim($parts[0]);
            }
        }
        if ($trimmed === '') {
            continue;
        }
        if (strpos($trimmed, ';') !== false) {
            $parts = preg_split('/\s+;/', $trimmed, 2);
            if (isset($parts[0])) {
                $trimmed = trim($parts[0]);
            }
        }
        if ($trimmed === '') {
            continue;
        }
        if (preg_match('/^([A-Za-z0-9_]+)\s*=\s*(.+)$/', $trimmed, $matches)) {
            $key = strtoupper(trim($matches[1]));
            $value = trim($matches[2]);
            if ($value === '') {
                continue;
            }
            $value = docs_trim_wrapping_quotes($value);
            if ($value === '') {
                continue;
            }
            if (in_array($key, $allowedKeys, true)) {
                return $value;
            }
            continue;
        }
        if (strpos($trimmed, '=') === false && $trimmed !== '') {
            return docs_trim_wrapping_quotes($trimmed);
        }
    }
    $fallback = docs_trim_wrapping_quotes(trim($content));
    if ($fallback !== '' && strpos($fallback, "\n") === false && strpos($fallback, '=') === false) {
        return $fallback;
    }
    return null;
}
function docs_resolve_telegram_bot_token(): ?string
{
    static $loaded = false;
    static $token = null;
    if ($loaded) {
        return $token;
    }
    $loaded = true;
    $envToken = getenv('TELEGRAM_BOT_TOKEN');
    if (is_string($envToken)) {
        $envToken = trim($envToken);
        if ($envToken !== '') {
            $token = $envToken;
            return $token;
        }
    }
    $candidateFiles = [];
    $envFile = getenv('TELEGRAM_BOT_TOKEN_FILE');
    if (is_string($envFile)) {
        $envFile = trim($envFile);
        if ($envFile !== '') {
            $candidateFiles[] = $envFile;
        }
    }
    $directories = [];
    if (defined('TELEGRAM_BOT_TOKEN_SECURE_DIRECTORY')) {
        $secureDir = TELEGRAM_BOT_TOKEN_SECURE_DIRECTORY;
        if (is_string($secureDir) && $secureDir !== '') {
            $directories[] = $secureDir;
        }
    }
    $directories[] = __DIR__ . '/js/documents/app';
    $filenames = [
        'telegram-appdosc.env',
        'telegram-appdosc.ev',
        'telegram-appdosc.env.local',
        'telegram-appdosc.ev.local',
        '.env',
        '.ev',
    ];
    foreach ($directories as $directory) {
        if (!is_string($directory) || $directory === '') {
            continue;
        }
        if (is_file($directory)) {
            $candidateFiles[] = $directory;
            continue;
        }
        foreach ($filenames as $filename) {
            $normalizedDirectory = rtrim($directory, "/\\");
            if ($normalizedDirectory === '') {
                $path = $filename;
            } else {
                $path = $normalizedDirectory . '/' . $filename;
            }
            $candidateFiles[] = $path;
        }
    }
    foreach ($candidateFiles as $path) {
        if (!is_string($path) || $path === '' || !is_file($path)) {
            continue;
        }
        $content = @file_get_contents($path);
        if (!is_string($content) || $content === '') {
            continue;
        }
        $candidate = docs_extract_token_from_env_content($content);
        if ($candidate !== null && $candidate !== '') {
            $token = $candidate;
            break;
        }
    }
    return $token;
}
function docs_resolve_application_base_url(): string
{
    $scheme = 'https';
    $forwardedProto = isset($_SERVER['HTTP_X_FORWARDED_PROTO'])
        ? trim((string) $_SERVER['HTTP_X_FORWARDED_PROTO'])
        : '';
    if ($forwardedProto !== '') {
        $segments = explode(',', $forwardedProto);
        $candidate = trim((string) ($segments[0] ?? ''));
        if ($candidate !== '') {
            $scheme = strtolower($candidate) === 'http' ? 'http' : 'https';
        }
    } elseif (isset($_SERVER['REQUEST_SCHEME'])) {
        $candidate = strtolower(trim((string) $_SERVER['REQUEST_SCHEME']));
        if ($candidate === 'http' || $candidate === 'https') {
            $scheme = $candidate;
        }
    } elseif (!empty($_SERVER['HTTPS']) && strtolower((string) $_SERVER['HTTPS']) !== 'off') {
        $scheme = 'https';
    } elseif (isset($_SERVER['SERVER_PORT']) && (string) $_SERVER['SERVER_PORT'] === '80') {
        $scheme = 'http';
    }
    $host = 'bimmax.pro';
    $forwardedHost = isset($_SERVER['HTTP_X_FORWARDED_HOST'])
        ? trim((string) $_SERVER['HTTP_X_FORWARDED_HOST'])
        : '';
    if ($forwardedHost !== '') {
        $segments = explode(',', $forwardedHost);
        $candidate = trim((string) ($segments[0] ?? ''));
        if ($candidate !== '') {
            $host = $candidate;
        }
    } elseif (!empty($_SERVER['HTTP_HOST'])) {
        $host = trim((string) $_SERVER['HTTP_HOST']);
    } elseif (!empty($_SERVER['SERVER_NAME'])) {
        $host = trim((string) $_SERVER['SERVER_NAME']);
    }
    if ($host === '') {
        $host = 'bimmax.pro';
    }
    return $scheme . '://' . $host;
}
function docs_fetch_remote_url(string $url, array $httpOptions, int $timeout): array
{
    $timeout = max(1, min($timeout, 10));
    $method = isset($httpOptions['method']) && is_string($httpOptions['method'])
        ? strtoupper($httpOptions['method'])
        : 'GET';
    $options = $httpOptions;
    $options['method'] = $method;
    $options['timeout'] = $timeout;
    $options['ignore_errors'] = true;
    $context = stream_context_create(['http' => $options]);
    $startedAt = microtime(true);
    $response = @file_get_contents($url, false, $context);
    $durationMs = (int) round((microtime(true) - $startedAt) * 1000);
    if ($response === false) {
        $error = error_get_last();
        return [
            'ok' => false,
            'body' => '',
            'durationMs' => $durationMs,
            'error' => $error['message'] ?? 'request_failed',
        ];
    }
    return [
        'ok' => true,
        'body' => $response,
        'durationMs' => $durationMs,
        'error' => '',
    ];
}
function docs_send_telegram_message(string $chatId, string $text, ?string $botToken = null, ?array $replyMarkup = null, ?string $parseMode = null): array
{
    $chatId = trim($chatId);
    $text = trim($text);
    if ($chatId === '' || $text === '') {
        return [
            'success' => false,
            'error' => 'chat_id_or_text_empty',
        ];
    }
    if ($botToken === null || $botToken === '') {
        $botToken = docs_resolve_telegram_bot_token();
    }
    if ($botToken === null || $botToken === '') {
        return [
            'success' => false,
            'error' => 'bot_token_missing',
        ];
    }
    $endpoint = 'https://api.telegram.org/bot' . $botToken . '/sendMessage';
    $payload = [
        'chat_id' => $chatId,
        'text' => $text,
        'disable_web_page_preview' => '1',
    ];
    $parseMode = $parseMode !== null ? trim($parseMode) : '';
    if ($parseMode !== '') {
        $payload['parse_mode'] = $parseMode;
    }
    if ($replyMarkup !== null) {
        $encodedReplyMarkup = json_encode($replyMarkup, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($encodedReplyMarkup !== false) {
            $payload['reply_markup'] = $encodedReplyMarkup;
        }
    }
    $request = docs_fetch_remote_url($endpoint, [
        'method' => 'POST',
        'header' => "Content-Type: application/x-www-form-urlencoded\r\n",
        'content' => http_build_query($payload, '', '&', PHP_QUERY_RFC3986),
    ], DOCS_TELEGRAM_SEND_TIMEOUT_SECONDS);
    if (empty($request['ok'])) {
        return [
            'success' => false,
            'error' => $request['error'] ?? 'request_failed',
        ];
    }
    $decoded = json_decode((string) $request['body'], true);
    $success = is_array($decoded) ? !empty($decoded['ok']) : false;
    if ($success) {
        return [
            'success' => true,
            'response' => $decoded,
        ];
    }
    return [
        'success' => false,
        'error' => is_array($decoded) ? ($decoded['description'] ?? 'unknown_response') : 'invalid_response',
        'response' => $decoded,
    ];
}
function docs_request_telegram_api(string $method, array $params = [], ?string $botToken = null): array
{
    if ($botToken === null || $botToken === '') {
        $botToken = docs_resolve_telegram_bot_token();
    }
    if ($botToken === null || $botToken === '') {
        return ['ok' => false, 'error' => 'bot_token_missing'];
    }
    $endpoint = 'https://api.telegram.org/bot' . $botToken . '/' . ltrim($method, '/');
    if (!empty($params)) {
        $endpoint .= (strpos($endpoint, '?') === false ? '?' : '&')
            . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
    }
    $request = docs_fetch_remote_url($endpoint, ['method' => 'GET'], DOCS_TELEGRAM_API_TIMEOUT_SECONDS);
    if (empty($request['ok'])) {
        return ['ok' => false, 'error' => $request['error'] ?? 'request_failed'];
    }
    $decoded = json_decode((string) $request['body'], true);
    if (!is_array($decoded) || empty($decoded['ok'])) {
        return [
            'ok' => false,
            'error' => is_array($decoded) ? ($decoded['description'] ?? 'invalid_response') : 'invalid_response',
            'response' => $decoded,
        ];
    }
    return ['ok' => true, 'result' => $decoded['result'] ?? null];
}
function docs_telegram_avatar_miss_path(string $cacheDir, string $telegramUserId): string
{
    return rtrim($cacheDir, "/\\") . '/' . $telegramUserId . '.miss';
}
function docs_telegram_avatar_lock_path(string $cacheDir, string $telegramUserId): string
{
    return rtrim($cacheDir, "/\\") . '/' . $telegramUserId . '.lock';
}
function docs_is_telegram_avatar_miss_cached(string $cacheDir, string $telegramUserId): bool
{
    $missFile = docs_telegram_avatar_miss_path($cacheDir, $telegramUserId);
    if (!is_file($missFile)) {
        return false;
    }
    $mtime = @filemtime($missFile);
    if ($mtime === false) {
        return false;
    }
    if ((time() - (int) $mtime) <= DOCS_TELEGRAM_AVATAR_MISS_TTL) {
        return true;
    }
    @unlink($missFile);
    return false;
}
function docs_mark_telegram_avatar_miss(string $cacheDir, string $telegramUserId): void
{
    @file_put_contents(docs_telegram_avatar_miss_path($cacheDir, $telegramUserId), (string) time(), LOCK_EX);
}
function docs_stream_telegram_avatar(string $telegramUserId): bool
{
    $telegramUserId = preg_replace('/[^\d-]/', '', trim($telegramUserId));
    if ($telegramUserId === '' || !preg_match('/^-?\d{4,20}$/', $telegramUserId)) {
        return false;
    }
    $botToken = docs_resolve_telegram_bot_token();
    if ($botToken === null || $botToken === '') {
        return false;
    }
    $cacheDir = __DIR__ . '/uploads/telegram-avatar-cache';
    if (!is_dir($cacheDir)) {
        @mkdir($cacheDir, 0775, true);
    }
    $cacheFile = rtrim($cacheDir, "/\\") . '/' . $telegramUserId . '.jpg';
    $cacheTtl = 3600;
    if (is_file($cacheFile) && (time() - (int) @filemtime($cacheFile)) <= $cacheTtl) {
        header('Content-Type: image/jpeg');
        header('Cache-Control: public, max-age=3600');
        readfile($cacheFile);
        return true;
    }
    if (docs_is_telegram_avatar_miss_cached($cacheDir, $telegramUserId)) {
        return false;
    }
    $lockHandle = @fopen(docs_telegram_avatar_lock_path($cacheDir, $telegramUserId), 'c');
    if (!is_resource($lockHandle)) {
        return false;
    }
    if (!@flock($lockHandle, LOCK_EX | LOCK_NB)) {
        @fclose($lockHandle);
        return false;
    }
    try {
        if (is_file($cacheFile) && (time() - (int) @filemtime($cacheFile)) <= $cacheTtl) {
            header('Content-Type: image/jpeg');
            header('Cache-Control: public, max-age=3600');
            readfile($cacheFile);
            return true;
        }
        $photos = docs_request_telegram_api('getUserProfilePhotos', [
            'user_id' => $telegramUserId,
            'limit' => 1,
        ], $botToken);
        if (empty($photos['ok']) || !isset($photos['result']['photos'][0]) || !is_array($photos['result']['photos'][0])) {
            docs_mark_telegram_avatar_miss($cacheDir, $telegramUserId);
            return false;
        }
        $sizes = $photos['result']['photos'][0];
        $best = end($sizes);
        if (!is_array($best) || empty($best['file_id'])) {
            docs_mark_telegram_avatar_miss($cacheDir, $telegramUserId);
            return false;
        }
        $fileInfo = docs_request_telegram_api('getFile', ['file_id' => (string) $best['file_id']], $botToken);
        if (empty($fileInfo['ok']) || empty($fileInfo['result']['file_path'])) {
            docs_mark_telegram_avatar_miss($cacheDir, $telegramUserId);
            return false;
        }
        $filePath = (string) $fileInfo['result']['file_path'];
        $fileUrl = 'https://api.telegram.org/file/bot' . $botToken . '/' . ltrim($filePath, '/');
        $request = docs_fetch_remote_url($fileUrl, ['method' => 'GET'], DOCS_TELEGRAM_FILE_TIMEOUT_SECONDS);
        $binary = !empty($request['ok']) ? (string) $request['body'] : '';
        if ($binary === '') {
            docs_mark_telegram_avatar_miss($cacheDir, $telegramUserId);
            return false;
        }
        @file_put_contents($cacheFile, $binary, LOCK_EX);
        @unlink(docs_telegram_avatar_miss_path($cacheDir, $telegramUserId));
        $finfo = function_exists('finfo_open') ? @finfo_open(FILEINFO_MIME_TYPE) : false;
        $mime = 'image/jpeg';
        if ($finfo) {
            $detected = @finfo_buffer($finfo, $binary);
            @finfo_close($finfo);
            if (is_string($detected) && strpos($detected, 'image/') === 0) {
                $mime = $detected;
            }
        }
        header('Content-Type: ' . $mime);
        header('Cache-Control: public, max-age=3600');
        echo $binary;
        return true;
    } finally {
        @flock($lockHandle, LOCK_UN);
        @fclose($lockHandle);
    }
}
function docs_build_task_start_param(array $record): string
{
    if (!empty($record['_useTaskKeyStartParam'])) {
        $taskKey = sanitize_text_field((string) ($record['taskKey'] ?? ''), 500);
        if ($taskKey !== '') {
            return 'taskkey:' . $taskKey;
        }
    }
    $taskId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
    if ($taskId !== '') {
        return 'task:' . $taskId;
    }
    $entryNumber = sanitize_text_field((string) ($record['entryNumber'] ?? ''), 200);
    if ($entryNumber !== '') {
        return 'entry:' . $entryNumber;
    }
    $registryNumber = sanitize_text_field((string) ($record['registryNumber'] ?? ''), 200);
    if ($registryNumber !== '') {
        return 'registry:' . $registryNumber;
    }
    $documentNumber = sanitize_text_field((string) ($record['documentNumber'] ?? ''), 200);
    if ($documentNumber !== '') {
        return 'document:' . $documentNumber;
    }
    return '';
}
function docs_build_mini_app_link(string $baseUrl, string $appPath, ?string $chatId, string $startParam): string
{
    $link = $baseUrl . $appPath;
    $query = ['v' => TELEGRAM_MINI_APP_RELEASE_VERSION];
    if ($chatId !== null && preg_match('/^\d{4,}$/', (string) $chatId)) {
        $query['telegram_user_id'] = (string) $chatId;
    }
    if ($startParam !== '') {
        $query['start_param'] = $startParam;
    }
    if (!empty($query)) {
        $separator = strpos($link, '?') === false ? '?' : '&';
        $link .= $separator . http_build_query($query);
    }
    return $link;
}
function docs_truncate_notification_text(string $text, int $limit = 350): string
{
    if ($limit < 1) {
        return '';
    }
    if (mb_strlen($text, 'UTF-8') <= $limit) {
        return $text;
    }
    $slice = mb_substr($text, 0, max(1, $limit - 1), 'UTF-8');
    return rtrim($slice) . '…';
}
function docs_format_human_date(?string $value): string
{
    $sanitized = sanitize_date_field($value);
    if ($sanitized === '') {
        return '';
    }
    $date = DateTime::createFromFormat('Y-m-d', $sanitized);
    if ($date === false) {
        return '';
    }
    return $date->format('d.m.Y');
}
function docs_resolve_telegram_chat_id_from_assignee(array $assignee): ?string
{
    foreach (['telegram', 'telegramId', 'telegram_id', 'chatId', 'chat_id', 'userId', 'id'] as $field) {
        if (!isset($assignee[$field])) {
            continue;
        }
        $candidate = normalize_identifier_value($assignee[$field]);
        if ($candidate === '') {
            continue;
        }
        if ($candidate[0] === '@') {
            continue;
        }
        if (!preg_match('/^-?\d{4,}$/', $candidate)) {
            continue;
        }
        return $candidate;
    }
    return null;
}
function docs_extract_assignee_display_name(array $assignee): string
{
    $fields = ['name', 'responsible', 'director', 'fullName', 'fio'];
    foreach ($fields as $field) {
        if (!array_key_exists($field, $assignee)) {
            continue;
        }
        $value = sanitize_text_field((string) $assignee[$field], 200);
        if ($value !== '') {
            return $value;
        }
    }
    return '';
}
function docs_collect_unique_assignee_names(array $entries): array
{
    $names = [];
    foreach ($entries as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $name = docs_extract_assignee_display_name($entry);
        if ($name === '') {
            continue;
        }
        $names[$name] = true;
    }
    if (empty($names)) {
        return [];
    }
    return array_values(array_keys($names));
}
function docs_collect_director_names_from_record(array $record): array
{
