    foreach ($assignees as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $role = docs_normalize_assignment_role($entry['role'] ?? '');
        if ($role !== 'subordinate') {
            continue;
        }
        $subordinates[] = $entry;
