    if (strlen($json) >= 1024 && docs_client_accepts_gzip() && function_exists('gzencode')) {
        $compressed = gzencode($json, 5);
        if (is_string($compressed) && $compressed !== '') {
            header('Content-Encoding: gzip');
            header('Content-Length: ' . strlen($compressed));
            echo $compressed;
            return;
        }
    }
    header('Content-Length: ' . strlen($json));
    echo $json;
}
function respond_error(string $message, int $status = 400, array $extra = []): void
{
    log_docs_event('Error response', [
        'status' => $status,
        'message' => $message,
        'extra' => $extra,
        'action' => docs_current_action(),
    ]);
    $action = docs_current_action();
    if ($action === 'mini_app_update_task' || $action === 'mini_app_log') {
        docs_log_file_debug('Mini app error response', [
            'status' => $status,
            'message' => $message,
            'extra' => $extra,
            'action' => $action,
        ]);
    }
    respond(array_merge(['success' => false, 'error' => $message], $extra), $status);
}
function respond_success(array $payload = []): void
{
    $coldStorageQueueFolder = docs_cold_storage_queue_request_folder($payload);
    $shouldRunColdStorageQueue = $coldStorageQueueFolder !== ''
        && docs_should_run_cold_storage_queue($coldStorageQueueFolder);
    if (docs_has_pending_registry_s3_backups() || $shouldRunColdStorageQueue) {
        respond_success_with_background_fallback(
            $payload,
            static function () use ($coldStorageQueueFolder, $shouldRunColdStorageQueue): void {
                if ($shouldRunColdStorageQueue) {
                    docs_run_automatic_cold_storage_queue_step($coldStorageQueueFolder);
                }
            }
        );
    }
    log_docs_event('Success response', [
        'status' => 200,
        'action' => docs_current_action(),
        'payload' => summarize_response_payload($payload),
    ]);
    respond(array_merge(['success' => true], $payload));
}
function respond_success_with_background_task(array $payload, callable $backgroundTask): void
{
    log_docs_event('Success response', [
        'status' => 200,
        'action' => docs_current_action(),
        'payload' => summarize_response_payload($payload),
    ]);
    if (!function_exists('fastcgi_finish_request')) {
        log_docs_event('Background task skipped: fastcgi_finish_request unavailable', [
            'action' => docs_current_action(),
        ]);
        docs_flush_success_response_before_background($payload);
        docs_run_pending_registry_s3_backups();
        exit;
    }
    http_response_code(200);
    docs_send_json_payload(array_merge(['success' => true], $payload));
    fastcgi_finish_request();
    docs_run_pending_registry_s3_backups();
    $backgroundTask();
    docs_run_pending_registry_s3_backups();
    exit;
}
function respond_success_with_background_fallback(array $payload, callable $backgroundTask): void
{
    if (function_exists('fastcgi_finish_request')) {
        respond_success_with_background_task($payload, $backgroundTask);
    }
    docs_flush_success_response_before_background($payload);
    docs_run_pending_registry_s3_backups();
    $backgroundTask();
    docs_run_pending_registry_s3_backups();
    exit;
}
function docs_flush_success_response_before_background(array $payload): void
{
    log_docs_event('Success response', [
        'status' => 200,
        'action' => docs_current_action(),
        'payload' => summarize_response_payload($payload),
        'backgroundMode' => 'connection_close',
    ]);
    ignore_user_abort(true);
    http_response_code(200);
    header('Connection: close');
    docs_send_json_payload(array_merge(['success' => true], $payload));
    while (ob_get_level() > 0) {
        @ob_end_flush();
    }
    @flush();
}
function docs_collect_login_response_diagnostics(array $sessionSummary, string $stage): array
{
    $setCookieHeader = null;
    if (function_exists('headers_list')) {
        foreach (headers_list() as $header) {
            if (stripos($header, 'Set-Cookie:') === 0) {
                $setCookieHeader = $header;
                break;
            }
        }
    }
    return [
        'stage' => $stage,
        'sessionId' => session_id(),
        'sessionStatus' => session_status(),
        'sessionAuthenticated' => $sessionSummary['authenticated'] ?? null,
        'sessionAccessGranted' => $sessionSummary['accessGranted'] ?? null,
        'sessionRole' => $sessionSummary['role'] ?? null,
        'sessionOrganization' => $sessionSummary['organization'] ?? null,
        'setCookiePresent' => $setCookieHeader !== null,
        'setCookieHeader' => $setCookieHeader,
    ];
}
function load_json_payload(): array
{
    $raw = get_raw_input();
    if (trim($raw) === '') {
        return [];
    }
    $data = json_decode($raw, true);
    if (!is_array($data)) {
        return [];
    }
    return $data;
}
function sanitize_text_field(?string $value, int $maxLength = 500): string
{
    if ($value === null) {
        return '';
    }
    $value = trim($value);
    if ($value === '') {
        return '';
    }
    $value = preg_replace('/[\x00-\x1F\x7F]+/u', ' ', $value);
    $value = preg_replace('/\s+/u', ' ', $value);
    if ($maxLength > 0 && mb_strlen($value) > $maxLength) {
        $value = mb_substr($value, 0, $maxLength);
    }
    return $value;
}
function sanitize_date_field(?string $value): string
{
    if ($value === null) {
        return '';
    }
    $value = trim($value);
    if ($value === '') {
        return '';
    }
    $date = DateTime::createFromFormat('Y-m-d', $value);
    if ($date === false) {
        return '';
    }
    return $date->format('Y-m-d');
}
function docs_normalize_uploaded_filename(?string $name): string
{
    if ($name === null) {
        return 'attachment';
    }
    $normalized = trim((string) $name);
    if ($normalized === '') {
        return 'attachment';
    }
    $converted = @iconv('UTF-8', 'UTF-8//IGNORE', $normalized);
    if (is_string($converted)) {
        $normalized = $converted;
    }
    $normalized = preg_replace('/[\x00-\x1F\x7F]+/u', ' ', $normalized) ?? '';
    $normalized = preg_replace('/\s+/u', ' ', $normalized) ?? '';
    $normalized = trim($normalized);
    return $normalized !== '' ? $normalized : 'attachment';
}
function docs_format_file_size(int $size): string
{
    if ($size >= 1024 * 1024) {
        $value = $size / (1024 * 1024);
        return rtrim(rtrim(number_format($value, $value >= 10 ? 0 : 1, '.', ''), '0'), '.') . ' МБ';
    }
    if ($size >= 1024) {
        return (string) ceil($size / 1024) . ' КБ';
    }
    return $size . ' Б';
}
function docs_rclone_binary(): string
{
    $binary = getenv('BIMMAX_DOCS_RCLONE_BINARY');
    $binary = is_string($binary) ? trim($binary) : '';
    return $binary !== '' ? $binary : DOCS_RCLONE_DEFAULT_BINARY;
}
function docs_rclone_config_path(): string
{
    $path = getenv('BIMMAX_DOCS_RCLONE_CONFIG');
    $path = is_string($path) ? trim($path) : '';
    return $path !== '' ? $path : DOCS_RCLONE_DEFAULT_CONFIG_PATH;
}
function docs_rclone_remote(): string
{
    $remote = getenv('BIMMAX_DOCS_RCLONE_REMOTE');
    $remote = is_string($remote) ? trim($remote) : '';
    return $remote !== '' ? $remote : DOCS_RCLONE_DEFAULT_REMOTE;
}
function docs_cold_storage_prefix(): string
{
    $prefix = getenv('BIMMAX_DOCS_RCLONE_PREFIX');
    $prefix = is_string($prefix) ? trim($prefix) : '';
    if ($prefix === '') {
        $prefix = DOCS_RCLONE_DEFAULT_PREFIX;
    }
    $prefix = str_replace('\\', '/', $prefix);
    $prefix = preg_replace('#/+#', '/', $prefix) ?? '';
    return trim($prefix, '/');
}
function docs_cold_storage_remote_path(string $key): string
{
    return docs_rclone_remote() . ':' . ltrim($key, '/');
}
function docs_normalize_cold_storage_relative_path(string $relativePath): string
{
    $relativePath = str_replace('\\', '/', $relativePath);
    $segments = preg_split('#/+#', $relativePath, -1, PREG_SPLIT_NO_EMPTY);
    $safeSegments = [];
    if (is_array($segments)) {
        foreach ($segments as $segment) {
            $segment = trim((string) $segment);
            if ($segment === '' || $segment === '.' || $segment === '..') {
                continue;
            }
            $segment = str_replace(["\0", '/', '\\'], '', $segment);
            if ($segment !== '') {
                $safeSegments[] = $segment;
            }
        }
    }
    return implode('/', $safeSegments);
}
function docs_build_cold_storage_key(string $folder, string $relativePath): string
{
    $folder = trim($folder) !== '' ? sanitize_folder_name($folder) : '';
    $relativePath = docs_normalize_cold_storage_relative_path($relativePath);
    $parts = [];
    $prefix = docs_cold_storage_prefix();
    if ($prefix !== '') {
        $parts[] = $prefix;
    }
    if ($folder !== '') {
        $parts[] = $folder;
    }
    if ($relativePath !== '') {
        $parts[] = $relativePath;
    }
    return implode('/', $parts);
}
function docs_extract_cold_storage_key(array $file): string
{
    if (isset($file['coldStorage']) && is_array($file['coldStorage'])) {
        $key = sanitize_text_field((string) ($file['coldStorage']['key'] ?? ''), 1000);
        if ($key !== '') {
            return docs_normalize_cold_storage_relative_path($key);
        }
    }
    return sanitize_text_field((string) ($file['storageKey'] ?? ''), 1000);
}
function docs_run_process_with_timeout(array $args, int $timeoutSeconds, array $environment = []): array
{
    if (empty($args) || !function_exists('proc_open')) {
        return [
            'ok' => false,
            'exitCode' => 127,
            'output' => '',
            'error' => empty($args) ? 'Команда не указана.' : 'Функция proc_open недоступна в PHP.',
            'timedOut' => false,
        ];
    }
    $timeoutSeconds = max(1, min($timeoutSeconds, 300));
    $command = array_map('strval', $args);
    if (PHP_VERSION_ID < 70400) {
        $command = 'exec ' . implode(' ', array_map('escapeshellarg', $command));
    }
    $processEnvironment = null;
    if (!empty($environment)) {
        $inheritedEnvironment = getenv();
        $processEnvironment = is_array($inheritedEnvironment) ? $inheritedEnvironment : [];
        foreach ($environment as $key => $value) {
            if (!is_string($key) || preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/', $key) !== 1 || !is_scalar($value)) {
                continue;
            }
            $processEnvironment[$key] = (string) $value;
        }
    }
    try {
        $process = @proc_open($command, [
            0 => ['file', '/dev/null', 'r'],
            1 => ['pipe', 'w'],
            2 => ['pipe', 'w'],
        ], $pipes, null, $processEnvironment);
    } catch (Throwable $error) {
        $process = false;
    }
    if (!is_resource($process)) {
        return [
            'ok' => false,
            'exitCode' => 127,
            'output' => '',
            'error' => 'Не удалось запустить дочерний процесс.',
            'timedOut' => false,
        ];
    }
    foreach ([1, 2] as $pipeIndex) {
        if (isset($pipes[$pipeIndex]) && is_resource($pipes[$pipeIndex])) {
            stream_set_blocking($pipes[$pipeIndex], false);
        }
    }
    $output = '';
    $error = '';
    $outputTruncated = false;
    $deadline = microtime(true) + $timeoutSeconds;
    $timedOut = false;
    $lastStatus = null;
    $append = static function (string &$target, string $chunk) use (&$outputTruncated): void {
        if ($chunk === '') {
            return;
        }
        $remaining = DOCS_EXTERNAL_COMMAND_OUTPUT_MAX_BYTES - strlen($target);
        if ($remaining <= 0) {
            $outputTruncated = true;
            return;
        }
        if (strlen($chunk) > $remaining) {
            $target .= substr($chunk, 0, $remaining);
            $outputTruncated = true;
            return;
        }
        $target .= $chunk;
    };
    while (true) {
        $status = proc_get_status($process);
        $lastStatus = is_array($status) ? $status : null;
        $append($output, isset($pipes[1]) && is_resource($pipes[1]) ? (string) stream_get_contents($pipes[1]) : '');
        $append($error, isset($pipes[2]) && is_resource($pipes[2]) ? (string) stream_get_contents($pipes[2]) : '');
        if (!is_array($status) || empty($status['running'])) {
            break;
        }
        if (microtime(true) >= $deadline) {
            $timedOut = true;
            @proc_terminate($process);
            usleep(200000);
            $afterTerminate = proc_get_status($process);
            if (is_array($afterTerminate) && !empty($afterTerminate['running'])) {
                @proc_terminate($process, 9);
            }
            break;
        }
        usleep(100000);
    }
    $append($output, isset($pipes[1]) && is_resource($pipes[1]) ? (string) stream_get_contents($pipes[1]) : '');
    $append($error, isset($pipes[2]) && is_resource($pipes[2]) ? (string) stream_get_contents($pipes[2]) : '');
    foreach ($pipes as $pipe) {
        if (is_resource($pipe)) {
            fclose($pipe);
        }
    }
    $exitCode = proc_close($process);
    if ($exitCode === -1 && is_array($lastStatus) && isset($lastStatus['exitcode']) && (int) $lastStatus['exitcode'] >= 0) {
        $exitCode = (int) $lastStatus['exitcode'];
    }
    return [
        'ok' => !$timedOut && $exitCode === 0,
        'exitCode' => $timedOut ? 124 : $exitCode,
        'output' => trim($output),
        'error' => $timedOut ? 'Команда не ответила за ' . $timeoutSeconds . ' сек.' : trim($error),
        'timedOut' => $timedOut,
        'outputTruncated' => $outputTruncated,
    ];
}
function docs_run_rclone_command(array $args, int $timeoutSeconds = 45): array
{
    $binary = docs_rclone_binary();
    $commandParts = [$binary];
    $configPath = docs_rclone_config_path();
    if ($configPath !== '') {
        $commandParts[] = '--config';
        $commandParts[] = $configPath;
    }
    $commandParts[] = '--contimeout';
    $commandParts[] = max(5, $timeoutSeconds) . 's';
    $commandParts[] = '--timeout';
    $commandParts[] = max(10, $timeoutSeconds * 2) . 's';
    foreach ($args as $arg) {
        $commandParts[] = (string) $arg;
    }
    $result = docs_run_process_with_timeout($commandParts, $timeoutSeconds);
    $outputText = trim((string) ($result['output'] ?? ''));
    $errorText = trim((string) ($result['error'] ?? ''));
    return [
        'ok' => !empty($result['ok']),
        'exitCode' => (int) ($result['exitCode'] ?? 127),
        'output' => $outputText,
        'error' => !empty($result['ok']) ? '' : ($errorText !== '' ? $errorText : ($outputText !== '' ? $outputText : 'rclone завершился с ошибкой.')),
        'timedOut' => !empty($result['timedOut']),
        'outputTruncated' => !empty($result['outputTruncated']),
    ];
}
function docs_cold_storage_base_status(): array
{
    $binary = docs_rclone_binary();
    $configPath = docs_rclone_config_path();
    $remote = docs_rclone_remote();
    $status = [
        'provider' => DOCS_COLD_STORAGE_PROVIDER,
        'binary' => $binary,
        'configPath' => $configPath,
        'configExists' => $configPath !== '' && is_file($configPath),
        'remote' => $remote,
        'prefix' => docs_cold_storage_prefix(),
        'available' => false,
        'message' => '',
    ];
    if ($remote === '') {
        $status['message'] = 'Не указан remote rclone.';
        return $status;
    }
    $about = docs_run_rclone_command(['about', $remote . ':'], 12);
    if (!empty($about['ok'])) {
        $status['available'] = true;
        $status['message'] = 'rclone доступен, remote отвечает.';
        return $status;
    }
    $lsd = docs_run_rclone_command(['lsd', $remote . ':'], 12);
    $status['available'] = !empty($lsd['ok']);
    $status['message'] = $status['available']
        ? 'rclone доступен, remote отвечает.'
        : (string) ($about['error'] ?: ($lsd['error'] ?? 'rclone remote недоступен.'));
    return $status;
}
function docs_verify_cold_storage_file_size(
    string $key,
    int $expectedBytes,
    int $timeoutSeconds = DOCS_COLD_STORAGE_VERIFY_TIMEOUT_SECONDS
): array
{
    if ($key === '' || $expectedBytes < 1) {
        return ['ok' => false, 'error' => 'Нельзя подтвердить пустой S3-файл.'];
    }
    $result = docs_run_rclone_command(
        ['lsjson', '--stat', docs_cold_storage_remote_path($key)],
        max(1, min(60, $timeoutSeconds))
    );
    if (empty($result['ok'])) {
        return [
            'ok' => false,
            'error' => (string) ($result['error'] ?? 'Не удалось проверить размер S3-файла.'),
        ];
    }
    $decoded = json_decode((string) ($result['output'] ?? ''), true);
    if (isset($decoded[0]) && is_array($decoded[0])) {
        $decoded = $decoded[0];
    }
    $remoteBytes = is_array($decoded) && isset($decoded['Size']) ? (int) $decoded['Size'] : -1;
    if ($remoteBytes !== $expectedBytes) {
        return [
            'ok' => false,
            'error' => 'Размер S3-файла не совпал с локальным после загрузки.',
            'expectedBytes' => $expectedBytes,
            'remoteBytes' => $remoteBytes,
        ];
    }
    return ['ok' => true, 'bytes' => $remoteBytes, 'error' => ''];
}
function docs_upload_file_to_cold_storage(string $localPath, string $folder, string $relativePath): array
{
    if (!is_file($localPath) || !is_readable($localPath)) {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Локальный файл недоступен для S3-копии.',
        ];
    }
    clearstatcache(true, $localPath);
    $localBytes = @filesize($localPath);
    if ($localBytes === false || $localBytes < 1) {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Пустой файл нельзя отправлять в S3.',
        ];
    }
    $key = docs_build_cold_storage_key($folder, $relativePath);
    if ($key === '') {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Не удалось построить ключ S3.',
        ];
    }
    $result = docs_run_rclone_command(['copyto', $localPath, docs_cold_storage_remote_path($key)], 60);
    if (empty($result['ok'])) {
        return [
            'ok' => false,
            'key' => $key,
            'error' => (string) ($result['error'] ?? 'Не удалось отправить файл в S3.'),
        ];
    }
    $verification = docs_verify_cold_storage_file_size($key, (int) $localBytes);
    if (empty($verification['ok'])) {
        return [
            'ok' => false,
            'key' => $key,
            'error' => (string) ($verification['error'] ?? 'S3-файл не прошёл проверку размера.'),
        ];
    }
    return [
        'ok' => true,
        'key' => $key,
        'bytes' => (int) $localBytes,
        'error' => '',
    ];
}
function docs_apply_cold_storage_metadata(
    array $file,
    string $folder,
