        'context' => $context,
    ];
    return $storedFile;
}
function docs_is_live_ocr_supported_file(array $file): bool
{
    $name = (string) ($file['originalName'] ?? ($file['storedName'] ?? ''));
    $extension = strtolower((string) pathinfo($name, PATHINFO_EXTENSION));
    return in_array($extension, [
        'pdf', 'doc', 'docx',
        'png', 'jpg', 'jpeg', 'tif', 'tiff', 'bmp', 'gif', 'webp',
    ], true);
}
function docs_build_new_file_ocr_state(): array
{
    return [
        'status' => 'pending',
        'engine' => 'n8n_jobs',
        'source' => 'live_upload',
        'queuedAt' => date('c'),
    ];
}
function docs_attach_live_ocr_state(array $file): array
{
    if (docs_is_live_ocr_supported_file($file)) {
        $file['ocr'] = docs_build_new_file_ocr_state();
    }
    return $file;
}
function docs_resolve_private_ocr_webhook_url(): string
{
    $env = docs_ai_task_search_load_env();
    $url = trim((string) ($env['PRIVATE_OCR_WEBHOOK_URL'] ?? DOCS_PRIVATE_OCR_DEFAULT_WEBHOOK_URL));
    $url = preg_replace('~/(?:jobs|status|result)/?$~i', '', rtrim($url, '/')) ?? $url;
    return filter_var($url, FILTER_VALIDATE_URL) !== false
        ? $url
        : DOCS_PRIVATE_OCR_DEFAULT_WEBHOOK_URL;
}
function docs_detect_private_ocr_mime_type(string $localPath, string $originalName = ''): string
{
    if (!is_file($localPath) || !is_readable($localPath) || !function_exists('finfo_open')) {
        return '';
    }
    $finfo = @finfo_open(FILEINFO_MIME_TYPE);
    if ($finfo === false) {
        return '';
    }
    try {
        $mimeType = @finfo_file($finfo, $localPath);
    } finally {
        if (PHP_VERSION_ID < 80500) {
            finfo_close($finfo);
        }
    }
    $detectedMimeType = is_string($mimeType) ? strtolower(trim($mimeType)) : '';
    $sourceName = trim($originalName) !== '' ? $originalName : $localPath;
    $extension = strtolower((string) pathinfo($sourceName, PATHINFO_EXTENSION));
    if ($extension === 'docx') {
        return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    }
    if ($extension === 'doc') {
        return 'application/msword';
    }
    return $detectedMimeType;
}
function docs_private_ocr_json_request(
    string $url,
    int $timeoutSeconds,
    array $curlOptions = [],
    int $maxResponseBytes = DOCS_PRIVATE_OCR_MAX_RESPONSE_BYTES
): array {
    if (!function_exists('curl_init')) {
        return ['ok' => false, 'httpStatus' => 0, 'error' => 'PHP cURL недоступен.'];
    }
    $responseBody = '';
    $responseTooLarge = false;
    $curl = curl_init($url);
    if ($curl === false) {
        return ['ok' => false, 'httpStatus' => 0, 'error' => 'Не удалось подготовить OCR-запрос.'];
    }
    curl_setopt_array($curl, array_replace([
        CURLOPT_RETURNTRANSFER => false,
        CURLOPT_CONNECTTIMEOUT => DOCS_PRIVATE_OCR_CONNECT_TIMEOUT_SECONDS,
        CURLOPT_TIMEOUT => max(1, $timeoutSeconds),
        CURLOPT_FOLLOWLOCATION => false,
        CURLOPT_WRITEFUNCTION => static function ($handle, string $chunk) use (
            &$responseBody,
            &$responseTooLarge,
            $maxResponseBytes
        ): int {
            if (strlen($responseBody) + strlen($chunk) > $maxResponseBytes) {
                $responseTooLarge = true;
                return 0;
            }
            $responseBody .= $chunk;
            return strlen($chunk);
        },
    ], $curlOptions));
    try {
        curl_exec($curl);
        $httpStatus = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
        $curlError = trim((string) curl_error($curl));
    } finally {
        if (PHP_VERSION_ID < 80500) {
            curl_close($curl);
        }
    }
    if ($responseTooLarge) {
        return ['ok' => false, 'httpStatus' => $httpStatus, 'error' => 'Ответ OCR превышает допустимый размер.'];
    }
    $decoded = json_decode($responseBody, true);
    if ($httpStatus < 200 || $httpStatus >= 300) {
        $serverError = is_array($decoded)
            ? sanitize_text_field((string) ($decoded['error'] ?? ($decoded['message'] ?? '')), 500)
            : '';
        return [
            'ok' => false,
            'httpStatus' => $httpStatus,
            'error' => $serverError !== ''
                ? $serverError
                : ($curlError !== '' ? $curlError : 'OCR-сервер вернул HTTP ' . $httpStatus . '.'),
        ];
    }
    if (!is_array($decoded)) {
        return ['ok' => false, 'httpStatus' => $httpStatus, 'error' => 'OCR-сервер вернул некорректный JSON.'];
    }
    return ['ok' => true, 'httpStatus' => $httpStatus, 'payload' => $decoded];
}
function docs_private_ocr_idempotency_key(string $localPath): string
{
    $digest = @hash_file('sha256', $localPath);
    if (!is_string($digest) || $digest === '') {
        $digest = hash('sha256', $localPath . '|' . (string) (@filesize($localPath) ?: 0));
    }
    return 'documents-live-ocr-' . $digest;
}
function docs_normalize_private_ocr_job_payload(array $payload): array
{
    return isset($payload[0]) && is_array($payload[0]) ? $payload[0] : $payload;
}
function docs_private_ocr_missing_job_error(array $payload): string
{
    $payload = docs_normalize_private_ocr_job_payload($payload);
    $error = sanitize_text_field(
        (string) ($payload['detail'] ?? ($payload['error'] ?? ($payload['message'] ?? ''))),
        500
    );
    if ($error === '' || preg_match('/\b(?:ocr\s+)?job\b.*\bnot\s+found\b/i', $error) !== 1) {
        return '';
    }
    return $error;
}
function docs_create_private_ocr_job(
    string $localPath,
    string $originalName,
    string $idempotencyKey = ''
): array
{
    if (!is_file($localPath) || !is_readable($localPath)) {
        return ['ok' => false, 'error' => 'Файл недоступен для OCR.'];
    }
    if (!class_exists('CURLFile')) {
        return ['ok' => false, 'error' => 'PHP CURLFile недоступен.'];
    }
    $mimeType = docs_detect_private_ocr_mime_type($localPath, $originalName);
    if ($mimeType === '') {
        $mimeType = 'application/octet-stream';
    }
    $uploadName = trim($originalName) !== '' ? basename($originalName) : basename($localPath);
    $idempotencyKey = sanitize_text_field($idempotencyKey, 240);
    if ($idempotencyKey === '') {
        $idempotencyKey = docs_private_ocr_idempotency_key($localPath);
    }
    $response = docs_private_ocr_json_request(
        docs_resolve_private_ocr_webhook_url() . '/jobs',
        DOCS_PRIVATE_OCR_CREATE_TIMEOUT_SECONDS,
        [
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => ['file' => new CURLFile($localPath, $mimeType, $uploadName)],
            CURLOPT_HTTPHEADER => ['Idempotency-Key: ' . $idempotencyKey],
        ],
        1048576
    );
    if (empty($response['ok'])) {
        return [
            'ok' => false,
            'httpStatus' => (int) ($response['httpStatus'] ?? 0),
            'error' => sanitize_text_field((string) ($response['error'] ?? 'Не удалось создать OCR-задание.'), 500),
        ];
    }
    $payload = docs_normalize_private_ocr_job_payload((array) ($response['payload'] ?? []));
    $jobId = sanitize_text_field((string) ($payload['job_id'] ?? ''), 160);
    if ($jobId === '') {
        return ['ok' => false, 'httpStatus' => (int) ($response['httpStatus'] ?? 0), 'error' => 'OCR-сервер не вернул job_id.'];
    }
    return [
        'ok' => true,
        'jobId' => $jobId,
        'status' => strtolower(sanitize_text_field((string) ($payload['status'] ?? 'queued'), 40)),
        'progress' => max(0, min(100, (int) ($payload['progress'] ?? 0))),
        'reused' => !empty($payload['reused']),
    ];
}
function docs_fetch_private_ocr_job_status(string $jobId): array
{
    $jobId = sanitize_text_field($jobId, 160);
    if ($jobId === '') {
        return ['ok' => false, 'error' => 'Не указан OCR job_id.'];
    }
    $response = docs_private_ocr_json_request(
        docs_resolve_private_ocr_webhook_url() . '/status?' . http_build_query(['job_id' => $jobId]),
        DOCS_PRIVATE_OCR_REQUEST_TIMEOUT_SECONDS,
        [],
        1048576
    );
    if (empty($response['ok'])) {
        return [
            'ok' => false,
            'httpStatus' => (int) ($response['httpStatus'] ?? 0),
            'error' => sanitize_text_field((string) ($response['error'] ?? 'Не удалось проверить OCR-задание.'), 500),
        ];
    }
    $payload = docs_normalize_private_ocr_job_payload((array) ($response['payload'] ?? []));
    $missingJobError = docs_private_ocr_missing_job_error($payload);
    if ($missingJobError !== '') {
        return ['ok' => false, 'httpStatus' => 404, 'error' => $missingJobError];
    }
    $status = strtolower(sanitize_text_field((string) ($payload['status'] ?? ''), 40));
    if (!in_array($status, ['queued', 'running', 'succeeded', 'failed', 'cancelled'], true)) {
        return ['ok' => false, 'error' => 'OCR-сервер вернул неизвестный статус задания.'];
    }
    return [
        'ok' => true,
        'status' => $status,
        'progress' => max(0, min(100, (int) ($payload['progress'] ?? 0))),
        'currentPage' => max(0, (int) ($payload['current_page'] ?? 0)),
        'totalPages' => max(0, (int) ($payload['total_pages'] ?? 0)),
        'error' => sanitize_text_field((string) ($payload['error'] ?? ($payload['message'] ?? '')), 500),
    ];
}
function docs_fetch_private_ocr_job_result(string $jobId, int $pageLimit = 0): array
{
    $jobId = sanitize_text_field($jobId, 160);
    if ($jobId === '') {
        return ['ok' => false, 'error' => 'Не указан OCR job_id.'];
    }
    $response = docs_private_ocr_json_request(
        docs_resolve_private_ocr_webhook_url() . '/result?' . http_build_query([
            'job_id' => $jobId,
            'compact' => 1,
            'max_text_bytes' => DOCS_PRIVATE_OCR_RESULT_TEXT_MAX_BYTES,
        ]),
        DOCS_PRIVATE_OCR_REQUEST_TIMEOUT_SECONDS
    );
    if (empty($response['ok'])) {
        return [
            'ok' => false,
            'httpStatus' => (int) ($response['httpStatus'] ?? 0),
            'error' => sanitize_text_field((string) ($response['error'] ?? 'Не удалось получить результат OCR.'), 500),
        ];
    }
    $payload = docs_normalize_private_ocr_job_payload((array) ($response['payload'] ?? []));
    $missingJobError = docs_private_ocr_missing_job_error($payload);
    if ($missingJobError !== '') {
        return ['ok' => false, 'httpStatus' => 404, 'error' => $missingJobError];
    }
    $pages = isset($payload['pages']) && is_array($payload['pages']) ? $payload['pages'] : [];
    $pagesCount = max(0, (int) ($payload['pages_count'] ?? count($pages)));
    $pagesUsed = 0;
    $text = isset($payload['text']) && is_string($payload['text']) ? trim($payload['text']) : '';
    if ($pages && ($pageLimit > 0 || $text === '')) {
        $pageTexts = [];
        $pagesToRead = $pageLimit > 0 ? array_slice($pages, 0, $pageLimit) : $pages;
        foreach ($pagesToRead as $page) {
            if (!is_array($page)) {
                continue;
            }
            $pageText = isset($page['text']) && is_string($page['text']) ? trim($page['text']) : '';
            if ($pageText === '') {
                continue;
            }
            $pageNumber = max(1, (int) ($page['page'] ?? ($pagesUsed + 1)));
            $pageTexts[] = '[Страница ' . $pageNumber . "]\n" . $pageText;
            $pagesUsed++;
        }
        if ($pageTexts) {
            $text = implode("\n\n", $pageTexts);
        }
    }
    if ($text === '') {
        return [
            'ok' => false,
            'httpStatus' => 422,
            'emptyResult' => true,
            'pagesCount' => $pagesCount,
            'error' => 'OCR завершён, но текст пуст и в общем результате, и на всех страницах.',
        ];
    }
    $textWasTruncated = !empty($payload['text_truncated'])
        || mb_strlen($text, 'UTF-8') > DOCS_PRIVATE_OCR_MAX_TEXT_LENGTH;
    if ($textWasTruncated) {
        $text = mb_substr($text, 0, DOCS_PRIVATE_OCR_MAX_TEXT_LENGTH, 'UTF-8');
    }
    return [
        'ok' => true,
        'jobId' => $jobId,
        'text' => $text,
        'pagesCount' => $pagesCount,
        'pagesUsed' => $pagesUsed > 0 ? $pagesUsed : $pagesCount,
        'textTruncated' => $textWasTruncated,
    ];
}
function docs_wait_for_private_ocr_text(string $jobId, int $pageLimit = 0): array
{
    $deadline = microtime(true) + DOCS_AI_BRIEF_OCR_WAIT_SECONDS;
    $lastProgress = 0;
    while (microtime(true) < $deadline) {
        $status = docs_fetch_private_ocr_job_status($jobId);
        if (empty($status['ok'])) {
            return $status;
        }
        $lastProgress = max($lastProgress, (int) ($status['progress'] ?? 0));
        $state = (string) ($status['status'] ?? '');
        if ($state === 'succeeded') {
            return docs_fetch_private_ocr_job_result($jobId, $pageLimit);
        }
        if ($state === 'failed' || $state === 'cancelled') {
            return [
                'ok' => false,
                'error' => sanitize_text_field(
                    (string) ($status['error'] ?? 'Приватный OCR не смог обработать файл.'),
                    500
                ),
            ];
        }
        usleep(750000);
    }
    return [
        'ok' => false,
        'error' => 'Приватный OCR не завершился за отведённое время.',
        'progress' => $lastProgress,
    ];
}
function docs_normalize_ai_brief_provider($value): string
{
    $provider = strtolower(sanitize_text_field(is_scalar($value) ? (string) $value : '', 30));
    return $provider === 'deepseek' ? 'deepseek' : 'default';
}
function docs_resolve_ai_brief_config(array $settings): array
{
    $provider = docs_normalize_ai_brief_provider($settings['aiBriefProvider'] ?? 'default');
    if ($provider !== 'deepseek') {
        return docs_ai_task_search_resolve_ai_config() + [
            'provider' => 'default',
            'providerLabel' => 'Основная модель',
        ];
    }
    $env = docs_ai_task_search_load_env();
    $apiKey = trim((string) ($env['DEEPSEEK_API_KEY'] ?? ''));
    $model = trim((string) ($env['DEEPSEEK_MODEL'] ?? 'deepseek-v4-flash'));
    $baseUrl = trim((string) ($env['DEEPSEEK_BASE_URL'] ?? 'https://api.deepseek.com'));
    return [
        'apiKey' => $apiKey,
        'model' => $model !== '' ? $model : 'deepseek-v4-flash',
        'baseUrl' => $baseUrl !== '' ? $baseUrl : 'https://api.deepseek.com',
        'isGroq' => false,
        'isGoogleOpenAiCompat' => false,
        'provider' => 'deepseek',
        'providerLabel' => 'DeepSeek',
    ];
}
function docs_generate_ai_brief_from_ocr_text(string $ocrText, array $config): array
{
    if (trim((string) ($config['apiKey'] ?? '')) === '') {
        $providerLabel = sanitize_text_field((string) ($config['providerLabel'] ?? 'ИИ'), 80);
        return [
            'ok' => false,
            'status' => 503,
            'error' => 'Для провайдера «' . $providerLabel . '» не задан API-ключ в .env.',
        ];
    }
    $sourceText = mb_substr(trim($ocrText), 0, DOCS_AI_BRIEF_MAX_SOURCE_CHARS, 'UTF-8');
    if ($sourceText === '') {
        return ['ok' => false, 'status' => 422, 'error' => 'OCR не вернул текст для анализа.'];
    }
    $request = docs_ai_task_search_request_json(
        $config,
        'Ты анализируешь деловой документ. Верни только JSON {"summary":"..."}. '
            . 'Кратко и конкретно опиши: о чем документ, кто кому пишет, что требуется сделать, сроки, суммы и риски, если они есть. '
            . 'Не выдумывай отсутствующие факты. Ответ на русском языке, не более 1800 символов.',
        ['ocrText' => $sourceText],
        'ИИ не вернул корректный краткий вывод.',
        0.1
    );
    if (empty($request['ok'])) {
        return $request;
    }
    $summary = sanitize_text_field(
        (string) (($request['parsed']['summary'] ?? ($request['parsed']['response'] ?? ''))),
        DOCS_AI_BRIEF_MAX_SUMMARY_CHARS
    );
    if ($summary === '') {
        return ['ok' => false, 'status' => 502, 'error' => 'ИИ вернул пустой краткий вывод.'];
    }
    return [
        'ok' => true,
        'summary' => $summary,
        'model' => sanitize_text_field((string) ($config['model'] ?? ''), 120),
        'provider' => docs_normalize_ai_brief_provider($config['provider'] ?? 'default'),
    ];
}
function docs_live_ocr_queue_path(string $folder): string
{
    return ensure_organization_directory($folder) . '/' . DOCS_LIVE_OCR_QUEUE_FILENAME;
}
function docs_live_ocr_queue_lock_path(string $folder): string
{
    return ensure_organization_directory($folder) . '/' . DOCS_LIVE_OCR_QUEUE_LOCK_FILENAME;
}
function docs_live_ocr_worker_lock_path(string $folder): string
{
    return ensure_organization_directory($folder) . '/' . DOCS_LIVE_OCR_WORKER_LOCK_FILENAME;
}
function docs_ocr_runtime_path(string $filename): string
{
    if (!is_dir(DOCS_SERVER_LOG_DIRECTORY)) {
        @mkdir(DOCS_SERVER_LOG_DIRECTORY, 0775, true);
    }
    return DOCS_SERVER_LOG_DIRECTORY . '/' . ltrim($filename, '/');
}
function docs_read_json_array_file_with_backup(string $path): ?array
{
    foreach ([$path, $path . '.bak'] as $candidate) {
        $raw = is_file($candidate) && is_readable($candidate) ? @file_get_contents($candidate) : false;
        if (!is_string($raw) || trim($raw) === '') {
            continue;
        }
        $decoded = json_decode($raw, true);
        if (!is_array($decoded)) {
            continue;
        }
        if ($candidate !== $path) {
            log_docs_event('JSON backup loaded', [
                'path' => $path,
                'backupPath' => $candidate,
            ]);
        }
        return $decoded;
    }
    return null;
}
function docs_replace_json_content_atomically(
    string $path,
    string $content,
    int $defaultMode = 0664,
    bool $contentValidated = false
): bool
{
    $directory = dirname($path);
    if (!is_dir($directory) && !@mkdir($directory, 0775, true) && !is_dir($directory)) {
        return false;
    }
    if (trim($content) === '' || (!$contentValidated && !is_array(json_decode($content, true)))) {
        return false;
    }
    $tempPath = tempnam($directory, '.documents_json_');
    if (!is_string($tempPath) || $tempPath === '') {
        return false;
    }
    try {
        $handle = @fopen($tempPath, 'wb');
        if ($handle === false) {
            return false;
        }
        $length = strlen($content);
        $offset = 0;
        $written = @fwrite($handle, $content);
        if ($written === false || $written < 1) {
            fclose($handle);
            return false;
        }
        $offset = $written;
        while ($offset < $length) {
            $written = @fwrite($handle, substr($content, $offset));
            if ($written === false || $written < 1) {
                fclose($handle);
                return false;
            }
            $offset += $written;
        }
        $flushed = @fflush($handle);
        $synced = !function_exists('fsync') || @fsync($handle);
        fclose($handle);
        if (!$flushed || !$synced) {
            return false;
        }
        $mode = is_file($path) ? ((int) @fileperms($path) & 0777) : $defaultMode;
        @chmod($tempPath, $mode > 0 ? $mode : $defaultMode);
        return @rename($tempPath, $path);
    } finally {
        if (is_file($tempPath)) {
            @unlink($tempPath);
        }
    }
}
function docs_write_json_content_atomically(string $path, string $content, bool $preserveBackup = true): bool
{
    $directory = dirname($path);
    if (!is_dir($directory) && !@mkdir($directory, 0775, true) && !is_dir($directory)) {
        return false;
    }
    $lockHandle = @fopen($path . '.write.lock', 'c+');
    if ($lockHandle === false || !@flock($lockHandle, LOCK_EX)) {
        if (is_resource($lockHandle)) {
            fclose($lockHandle);
        }
        return false;
    }
    try {
        if ($preserveBackup) {
            $current = is_file($path) && is_readable($path) ? @file_get_contents($path) : false;
            if (is_string($current) && trim($current) !== '' && is_array(json_decode($current, true))) {
                $currentMode = ((int) @fileperms($path) & 0777) ?: 0664;
                if (!docs_replace_json_content_atomically($path . '.bak', $current, $currentMode)) {
                    return false;
                }
            } elseif (is_file($path)) {
                $backup = docs_read_json_array_file_with_backup($path . '.bak');
                if (!is_array($backup)) {
                    return false;
                }
            }
        }
        return docs_replace_json_content_atomically($path, $content);
    } finally {
        @flock($lockHandle, LOCK_UN);
        fclose($lockHandle);
    }
}
function docs_write_json_file_atomically(string $path, array $payload): bool
{
    $json = json_encode(
        $payload,
        JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE
    );
    return is_string($json) && docs_write_json_content_atomically($path, $json);
}
function docs_acquire_global_ocr_slot()
{
    $handle = @fopen(docs_ocr_runtime_path(DOCS_OCR_GLOBAL_LOCK_FILENAME), 'c+');
    if ($handle === false || !@flock($handle, LOCK_EX | LOCK_NB)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return null;
    }
    return $handle;
}
function docs_release_global_ocr_slot($handle): void
{
    if (!is_resource($handle)) {
        return;
    }
    @flock($handle, LOCK_UN);
    fclose($handle);
}
function docs_ocr_active_job_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_ACTIVE_JOB_FILENAME);
}
function docs_default_ocr_active_job(): array
{
    return [
        'version' => 1,
        'ownerKey' => '',
        'source' => '',
        'runId' => '',
        'folder' => '',
        'itemKey' => '',
        'idempotencyKey' => '',
        'jobId' => '',
        'phase' => '',
        'updatedAt' => date('c'),
    ];
}
function docs_load_ocr_active_job_unlocked(): array
{
    $path = docs_ocr_active_job_path();
    $decoded = docs_read_json_array_file_with_backup($path);
    if (!is_array($decoded) || (int) ($decoded['version'] ?? 0) !== 1) {
        return docs_default_ocr_active_job();
    }
    return array_replace(docs_default_ocr_active_job(), $decoded);
}
function docs_save_ocr_active_job_unlocked(array $activeJob): bool
{
    $activeJob = array_replace(docs_default_ocr_active_job(), $activeJob, [
        'version' => 1,
        'updatedAt' => date('c'),
    ]);
    return docs_write_json_file_atomically(docs_ocr_active_job_path(), $activeJob);
}
function docs_build_ocr_item_owner_key(string $folder, array $item): string
{
    $source = sanitize_text_field((string) ($item['source'] ?? 'live_upload'), 80);
    $runId = sanitize_text_field((string) ($item['runId'] ?? ''), 120);
    $itemKey = sanitize_text_field((string) ($item['key'] ?? ''), 160);
    if ($itemKey === '') {
        $itemKey = hash('sha256', implode("\0", [
            (string) ($item['documentField'] ?? 'id'),
            (string) ($item['documentValue'] ?? ($item['documentId'] ?? '')),
            (string) ($item['storedName'] ?? ''),
        ]));
    }
    return hash('sha256', implode("\0", [
        $source,
        $runId,
        sanitize_folder_name($folder),
        $itemKey,
    ]));
}
function docs_clear_ocr_active_job_for_owner_unlocked(string $ownerKey): bool
{
    $activeJob = docs_load_ocr_active_job_unlocked();
    $activeOwnerKey = sanitize_text_field((string) ($activeJob['ownerKey'] ?? ''), 80);
    if ($activeOwnerKey !== '' && !hash_equals($activeOwnerKey, $ownerKey)) {
        return false;
    }
    return docs_save_ocr_active_job_unlocked(docs_default_ocr_active_job());
}
function docs_gate_ocr_active_job_unlocked(string $ownerKey): array
{
    $activeJob = docs_load_ocr_active_job_unlocked();
    $activeOwnerKey = sanitize_text_field((string) ($activeJob['ownerKey'] ?? ''), 80);
    if ($activeOwnerKey === '' || hash_equals($activeOwnerKey, $ownerKey)) {
        return ['ok' => true, 'activeJob' => $activeJob];
    }
    $jobId = sanitize_text_field((string) ($activeJob['jobId'] ?? ''), 160);
    if ($jobId === '') {
        return [
            'ok' => false,
            'busy' => true,
            'remoteUnresolved' => true,
            'activeJob' => $activeJob,
            'error' => 'Предыдущая отправка OCR ещё не подтверждена сервером.',
        ];
    }
    $status = docs_fetch_private_ocr_job_status($jobId);
    $remoteStatus = strtolower((string) ($status['status'] ?? ''));
    $remoteMissing = empty($status['ok'])
        && in_array((int) ($status['httpStatus'] ?? 0), [404, 410], true);
    if ($remoteMissing || (!empty($status['ok']) && in_array($remoteStatus, ['succeeded', 'failed', 'cancelled'], true))) {
        if (!docs_save_ocr_active_job_unlocked(docs_default_ocr_active_job())) {
            return [
                'ok' => false,
                'busy' => true,
                'remoteUnresolved' => true,
                'activeJob' => $activeJob,
                'error' => 'Не удалось освободить подтверждённо завершённый OCR job.',
            ];
        }
        return ['ok' => true, 'activeJob' => docs_default_ocr_active_job()];
    }
    return [
        'ok' => false,
        'busy' => true,
        'remoteUnresolved' => empty($status['ok']),
        'activeJob' => $activeJob,
        'error' => !empty($status['ok'])
            ? 'Предыдущий OCR job ещё выполняется.'
            : 'Статус предыдущего OCR job не подтверждён: '
                . sanitize_text_field((string) ($status['error'] ?? 'нет ответа OCR-сервера'), 360),
    ];
}
function docs_build_ocr_document_reference(array $record, string $folder = ''): array
{
    foreach (['id', 'entryNumber', 'registryNumber', 'documentNumber'] as $field) {
        $value = sanitize_text_field((string) ($record[$field] ?? ''), 200);
        if ($value !== '') {
            return ['field' => $field, 'value' => $value];
        }
    }
    $record['documentFolder'] = sanitize_folder_name($folder);
    $taskKey = docs_task_snapshot_key($record);
    return $taskKey !== ''
        ? ['field' => 'taskKey', 'value' => $taskKey]
        : ['field' => '', 'value' => ''];
}
function docs_normalize_ocr_document_field(string $field): string
{
    return in_array($field, ['id', 'entryNumber', 'registryNumber', 'documentNumber', 'taskKey'], true)
        ? $field
        : 'id';
}
function docs_sanitize_ocr_document_value(string $field, string $value): string
{
    return sanitize_text_field($value, $field === 'taskKey' ? 500 : 200);
}
function docs_ocr_record_matches_reference(
    array $record,
    string $field,
    string $value,
    string $folder = ''
): bool
{
    $field = docs_normalize_ocr_document_field($field);
    $value = docs_sanitize_ocr_document_value($field, $value);
    if ($field === 'taskKey') {
        $record['documentFolder'] = sanitize_folder_name($folder);
        return $value !== '' && hash_equals($value, docs_task_snapshot_key($record));
    }
    return $value !== '' && sanitize_text_field((string) ($record[$field] ?? ''), 200) === $value;
}
function docs_default_live_ocr_queue(string $folder): array
{
    return [
        'version' => 1,
        'folder' => $folder,
        'updatedAt' => date('c'),
        'items' => [],
        'recent' => [],
    ];
}
function docs_load_live_ocr_queue_unlocked(string $folder): array
{
    $path = docs_live_ocr_queue_path($folder);
    $decoded = docs_read_json_array_file_with_backup($path);
    if (!is_array($decoded) || (int) ($decoded['version'] ?? 0) !== 1) {
        return docs_default_live_ocr_queue($folder);
    }
    $decoded['folder'] = $folder;
    $decoded['items'] = isset($decoded['items']) && is_array($decoded['items']) ? $decoded['items'] : [];
    $decoded['recent'] = isset($decoded['recent']) && is_array($decoded['recent']) ? $decoded['recent'] : [];
    return $decoded;
}
function docs_save_live_ocr_queue_unlocked(string $folder, array $state): bool
{
    $path = docs_live_ocr_queue_path($folder);
    $state['version'] = 1;
    $state['folder'] = $folder;
    $state['updatedAt'] = date('c');
    $state['items'] = array_values(isset($state['items']) && is_array($state['items']) ? $state['items'] : []);
    $state['recent'] = array_slice(
        array_values(isset($state['recent']) && is_array($state['recent']) ? $state['recent'] : []),
        -30
    );
    return docs_write_json_file_atomically($path, $state);
}
function docs_mutate_live_ocr_queue(string $folder, callable $callback): array
{
    $folder = sanitize_folder_name($folder);
    if ($folder === '') {
        return ['ok' => false, 'error' => 'Не указана организация OCR-очереди.'];
    }
    $handle = @fopen(docs_live_ocr_queue_lock_path($folder), 'c+');
    if ($handle === false || !@flock($handle, LOCK_EX)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return ['ok' => false, 'error' => 'Не удалось заблокировать OCR-очередь.'];
    }
    try {
        $state = docs_load_live_ocr_queue_unlocked($folder);
        $result = $callback($state);
        if (!docs_save_live_ocr_queue_unlocked($folder, $state)) {
            return ['ok' => false, 'error' => 'Не удалось сохранить OCR-очередь.'];
        }
        return is_array($result) ? array_merge(['ok' => true], $result) : ['ok' => true];
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_live_ocr_item_key(string $documentId, string $storedName): string
{
    return hash('sha256', $documentId . "\0" . $storedName);
}
function docs_enqueue_live_ocr_uploads(string $folder, string $documentId, array $uploads): array
{
    $documentId = sanitize_text_field($documentId, 200);
    $newItems = [];
    foreach ($uploads as $upload) {
        $file = isset($upload['file']) && is_array($upload['file']) ? $upload['file'] : null;
        if (!is_array($file) || !docs_is_live_ocr_supported_file($file)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        if ($storedName === '' || $documentId === '') {
            continue;
        }
        $key = docs_live_ocr_item_key($documentId, $storedName);
        $newItems[$key] = [
            'key' => $key,
            'documentId' => $documentId,
            'documentField' => 'id',
            'documentValue' => $documentId,
            'storedName' => $storedName,
            'originalName' => sanitize_text_field((string) ($file['originalName'] ?? $storedName), 255),
            'source' => 'live_upload',
            'status' => 'pending',
            'jobId' => '',
            'attempts' => 0,
            'nextAttemptAt' => '',
            'error' => '',
            'queuedAt' => date('c'),
        ];
    }
    if (empty($newItems)) {
        return ['ok' => true, 'queued' => 0];
    }
    return docs_mutate_live_ocr_queue($folder, static function (array &$state) use ($newItems): array {
        $items = isset($state['items']) && is_array($state['items']) ? $state['items'] : [];
        $indexByKey = [];
        foreach ($items as $index => $item) {
            if (is_array($item) && isset($item['key'])) {
                $indexByKey[(string) $item['key']] = $index;
            }
        }
        $queued = 0;
        foreach ($newItems as $key => $item) {
            if (isset($indexByKey[$key])) {
                $existing = is_array($items[$indexByKey[$key]] ?? null) ? $items[$indexByKey[$key]] : [];
                if (!in_array((string) ($existing['status'] ?? ''), ['completed', 'failed', 'skipped'], true)) {
                    continue;
                }
                $items[$indexByKey[$key]] = $item;
            } else {
                $items[] = $item;
            }
            $queued++;
        }
        $state['items'] = array_values($items);
        return ['queued' => $queued];
    });
}
function docs_get_live_ocr_queue_item(string $folder): array
{
    $handle = @fopen(docs_live_ocr_queue_lock_path($folder), 'c+');
    if ($handle === false || !@flock($handle, LOCK_SH)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return ['item' => null, 'nextAttemptAt' => 0];
    }
    try {
        $state = docs_load_live_ocr_queue_unlocked($folder);
        $nextAttemptAt = 0;
        foreach ($state['items'] as $item) {
            if (!is_array($item) || in_array((string) ($item['status'] ?? ''), ['completed', 'failed', 'skipped'], true)) {
                continue;
            }
            $itemNextAttemptAt = strtotime((string) ($item['nextAttemptAt'] ?? '')) ?: 0;
            if ($itemNextAttemptAt <= time()) {
                return ['item' => $item, 'nextAttemptAt' => 0];
            }
            if ($nextAttemptAt === 0 || $itemNextAttemptAt < $nextAttemptAt) {
                $nextAttemptAt = $itemNextAttemptAt;
            }
        }
        return ['item' => null, 'nextAttemptAt' => $nextAttemptAt];
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_update_live_ocr_queue_item(string $folder, string $key, array $changes): bool
{
    $result = docs_mutate_live_ocr_queue($folder, static function (array &$state) use ($key, $changes): array {
        foreach ($state['items'] as &$item) {
            if (!is_array($item) || (string) ($item['key'] ?? '') !== $key) {
                continue;
            }
            $item = array_replace($item, $changes, ['updatedAt' => date('c')]);
            unset($item);
            return ['updated' => true];
        }
        unset($item);
        return ['updated' => false];
    });
    return !empty($result['ok']) && !empty($result['updated']);
}
function docs_finish_live_ocr_queue_item(string $folder, array $item, string $status, string $error = ''): void
{
    $key = (string) ($item['key'] ?? '');
    docs_mutate_live_ocr_queue($folder, static function (array &$state) use ($key, $item, $status, $error): array {
        $state['items'] = array_values(array_filter(
            $state['items'],
            static fn($candidate): bool => !is_array($candidate) || (string) ($candidate['key'] ?? '') !== $key
        ));
        $state['recent'][] = [
            'documentId' => (string) ($item['documentId'] ?? ''),
            'storedName' => (string) ($item['storedName'] ?? ''),
            'status' => $status,
            'error' => sanitize_text_field($error, 500),
            'finishedAt' => date('c'),
        ];
        return ['removed' => true];
    });
}
function docs_find_live_ocr_record_file(
    string $folder,
    string $documentId,
    string $storedName,
    string $documentField = 'id'
): array
{
    foreach (load_registry($folder) as $record) {
        if (!is_array($record) || !docs_ocr_record_matches_reference($record, $documentField, $documentId, $folder)) {
            continue;
        }
        foreach (isset($record['files']) && is_array($record['files']) ? $record['files'] : [] as $file) {
            if (is_array($file) && (string) ($file['storedName'] ?? '') === $storedName) {
                return ['record' => $record, 'file' => $file];
            }
        }
        return ['record' => $record, 'file' => null];
    }
    return ['record' => null, 'file' => null];
}
function docs_resolve_live_ocr_local_path(string $folder, array $file): string
{
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName === '') {
        return '';
    }
    $directory = ensure_organization_directory($folder);
    $candidates = [$directory . '/' . $storedName];
    foreach (docs_file_public_relative_candidates($folder, $file, $storedName) as $relativePath) {
        $relativePath = docs_normalize_cold_storage_relative_path($relativePath);
        if ($relativePath !== '') {
            $candidates[] = $directory . '/' . $relativePath;
        }
    }
    return docs_resolve_file_path_with_cold_storage($folder, $file, array_values(array_unique($candidates)), microtime(true) + 120);
}
function docs_cleanup_live_ocr_temp_source(string $path): void
{
    if ($path === '' || strpos(basename($path), 'docs_s3_') !== 0) {
        return;
    }
    $tempDirectory = realpath(sys_get_temp_dir());
    $sourceDirectory = realpath(dirname($path));
    if ($tempDirectory === false || $sourceDirectory === false || !hash_equals($tempDirectory, $sourceDirectory)) {
        return;
    }
    if (is_file($path)) {
        @unlink($path);
    }
}
function docs_update_live_ocr_registry_file(
    string $folder,
    string $documentId,
    string $storedName,
    array $ocr,
    ?string $ocrText = null,
    string $documentField = 'id'
): array {
    [$handle, $records] = docs_lock_registry($folder);
    if ($handle === null) {
        return ['ok' => false, 'error' => 'Реестр занят другим процессом.'];
    }
    $updatedRecord = null;
    $found = false;
    try {
        foreach ($records as &$record) {
            if (!is_array($record) || !docs_ocr_record_matches_reference($record, $documentField, $documentId, $folder)) {
                continue;
            }
            if (!isset($record['files']) || !is_array($record['files'])) {
                continue;
            }
            foreach ($record['files'] as &$file) {
                if (!is_array($file) || (string) ($file['storedName'] ?? '') !== $storedName) {
                    continue;
                }
                $file['ocr'] = $ocr;
                if ($ocrText !== null && trim($ocrText) !== '') {
                    unset($file['ocrText']);
                    $file['ocrTextLength'] = mb_strlen($ocrText, 'UTF-8');
                }
                $found = true;
                break;
            }
            unset($file);
            $updatedRecord = $record;
            break;
        }
        unset($record);
        if (!$found || !is_array($updatedRecord)) {
            return ['ok' => false, 'missing' => true, 'error' => 'Задача или файл уже удалены.'];
        }
        if ($ocrText !== null && trim($ocrText) !== '') {
            foreach ($updatedRecord['files'] as &$snapshotFile) {
                if (!is_array($snapshotFile) || (string) ($snapshotFile['storedName'] ?? '') !== $storedName) {
                    continue;
                }
                $snapshotFile['ocrText'] = $ocrText;
                $snapshotFile['ocrTextLength'] = mb_strlen($ocrText, 'UTF-8');
                break;
            }
            unset($snapshotFile);
        }
        if (!docs_save_registry_locked($handle, $records)) {
            return ['ok' => false, 'error' => 'Не удалось сохранить OCR-результат в registry.json.'];
        }
    } finally {
        docs_unlock_registry($handle);
    }
    docs_run_pending_registry_s3_backups();
    return ['ok' => true, 'record' => $updatedRecord];
}
function docs_sync_live_ocr_participant_snapshots(
    array $record,
    string $folder,
    string $storedName = '',
    string $expectedText = ''
): array
{
    $record['documentFolder'] = sanitize_folder_name($folder);
    $telegramIds = docs_collect_record_telegram_ids($record, $folder);
    $errors = [];
    $saved = 0;
    $verified = 0;
    $deliveries = [];
    foreach ($telegramIds as $telegramId) {
        $result = docs_rebuild_mini_app_user_tasks_snapshot((string) $telegramId, $record);
        if (empty($result['saved'])) {
            $error = sanitize_text_field(
                (string) ($result['error'] ?? ($result['reason'] ?? 'S3-ошибка')),
                500
            );
            $errors[] = $error;
            $deliveries[] = [
                'telegramId' => (string) $telegramId,
                'key' => (string) ($result['key'] ?? ''),
                'status' => 'error',
                'hasText' => false,
                'textLength' => 0,
                'error' => $error,
            ];
            continue;
        }
        $saved++;
        if ($storedName === '' || trim($expectedText) === '') {
            $deliveries[] = [
                'telegramId' => (string) $telegramId,
                'key' => (string) ($result['key'] ?? ''),
                'status' => 'saved',
                'hasText' => false,
                'textLength' => 0,
                'error' => '',
            ];
            continue;
        }
        $verification = docs_verify_task_file_ocr_in_user_s3_snapshot(
            (string) $telegramId,
            $record,
            $folder,
            $storedName,
            $expectedText
        );
        if (empty($verification['ok'])) {
            $error = sanitize_text_field(
                (string) ($verification['error'] ?? 'OCR-текст не подтверждён в Telegram JSON пользователя.'),
                500
            );
            $errors[] = $error;
            $deliveries[] = [
                'telegramId' => (string) $telegramId,
                'key' => (string) ($verification['key'] ?? ($result['key'] ?? '')),
                'status' => 'error',
                'hasText' => false,
                'textLength' => 0,
                'error' => $error,
            ];
            continue;
        }
        $verified++;
        $deliveries[] = [
            'telegramId' => (string) $telegramId,
            'key' => (string) ($verification['key'] ?? ($result['key'] ?? '')),
            'status' => 'verified',
            'hasText' => true,
            'textLength' => (int) ($verification['textLength'] ?? 0),
            'verifiedAt' => (string) ($verification['verifiedAt'] ?? date('c')),
            'error' => '',
        ];
    }
    return [
        'ok' => empty($errors)
            && ($storedName === '' || trim($expectedText) === '' || $verified === count($telegramIds)),
        'participants' => count($telegramIds),
        'saved' => $saved,
        'verified' => $verified,
        'allPresent' => empty($errors)
            && ($storedName === '' || trim($expectedText) === '' || $verified === count($telegramIds)),
        'deliveries' => $deliveries,
        'error' => !empty($errors) ? implode('; ', array_slice(array_unique($errors), 0, 3)) : '',
    ];
}
function docs_process_ocr_queue_item(
    string $folder,
    array $item,
    float $workerDeadline,
    callable $progressCallback,
    ?callable $resourceGuard = null
): array {
    $slotHandle = docs_acquire_global_ocr_slot();
    if ($slotHandle === null) {
        return [
            'done' => false,
            'retry' => true,
            'busy' => true,
            'stage' => 'waiting_slot',
            'error' => 'Ожидается завершение другого OCR-файла.',
        ];
    }
    try {
        if ($resourceGuard !== null) {
            $guard = $resourceGuard();
            if (is_array($guard) && empty($guard['ok'])) {
                return [
                    'done' => false,
                    'retry' => true,
                    'abortWorker' => true,
                    'stage' => 'resource_guard',
                    'error' => docs_format_ocr_backfill_memory_guard_error($guard),
                ];
            }
        }
        $ownerKey = docs_build_ocr_item_owner_key($folder, $item);
        $source = sanitize_text_field((string) ($item['source'] ?? 'live_upload'), 80);
        if ($source === 'legacy_backfill') {
            $protectedJob = docs_load_ocr_active_job_unlocked();
            $protectedOwnerKey = sanitize_text_field((string) ($protectedJob['ownerKey'] ?? ''), 80);
            $protectedItemKey = sanitize_text_field((string) ($protectedJob['itemKey'] ?? ''), 160);
            $currentItemKey = sanitize_text_field((string) ($item['key'] ?? ''), 160);
            if ($protectedOwnerKey !== ''
                && !hash_equals($protectedOwnerKey, $ownerKey)
                && (string) ($protectedJob['source'] ?? '') === 'legacy_backfill'
                && sanitize_folder_name((string) ($protectedJob['folder'] ?? '')) === sanitize_folder_name($folder)
                && $protectedItemKey !== ''
                && hash_equals($protectedItemKey, $currentItemKey)
            ) {
                $protectedJob['ownerKey'] = $ownerKey;
                $protectedJob['runId'] = sanitize_text_field((string) ($item['runId'] ?? ''), 120);
                docs_save_ocr_active_job_unlocked($protectedJob);
            }
        }
        $activeGate = docs_gate_ocr_active_job_unlocked($ownerKey);
        if (empty($activeGate['ok'])) {
            return [
                'done' => false,
                'retry' => true,
                'busy' => true,
                'remoteUnresolved' => !empty($activeGate['remoteUnresolved']),
                'stage' => 'waiting_slot',
                'error' => (string) ($activeGate['error'] ?? 'Ожидается завершение предыдущего OCR job.'),
            ];
        }
        $activeJob = isset($activeGate['activeJob']) && is_array($activeGate['activeJob'])
            ? $activeGate['activeJob']
            : docs_default_ocr_active_job();
        $documentField = docs_normalize_ocr_document_field(
            (string) ($item['documentField'] ?? 'id')
        );
        $documentValue = docs_sanitize_ocr_document_value(
            $documentField,
            (string) ($item['documentValue'] ?? ($item['documentId'] ?? ''))
        );
        $storedName = sanitize_text_field((string) ($item['storedName'] ?? ''), 255);
        $progressCallback([
            'status' => 'processing',
            'stage' => 'resolving_file',
            'gateAttempts' => 0,
            'error' => '',
            'heartbeatAt' => date('c'),
        ]);
        $located = docs_find_live_ocr_record_file(
            $folder,
            $documentValue,
            $storedName,
            $documentField
        );
        if (!is_array($located['record'] ?? null) || !is_array($located['file'] ?? null)) {
            return ['done' => true, 'status' => 'skipped', 'error' => 'Задача или файл удалены.'];
        }
        $record = $located['record'];
        $file = $located['file'];
        $record['documentFolder'] = sanitize_folder_name($folder);
        $itemArchiveHash = strtolower(sanitize_text_field(
            (string) ($item['ocrTextSha256'] ?? ''),
            80
        ));
        $itemArchiveConfirmed = $source === 'legacy_backfill'
            && trim((string) ($item['archiveKey'] ?? '')) !== ''
            && (int) ($item['ocrTextLength'] ?? 0) > 0
            && preg_match('/^[a-f0-9]{64}$/', $itemArchiveHash) === 1;
        $legacyNeedsFreshOcr = $source === 'legacy_backfill' && !$itemArchiveConfirmed;
        $existingText = !$legacyNeedsFreshOcr && isset($file['ocrText']) && is_string($file['ocrText'])
            ? trim($file['ocrText'])
            : '';
        if (!$legacyNeedsFreshOcr && $existingText === '') {
            $archiveFile = $file;
            if ($itemArchiveConfirmed) {
                $archiveFile['ocr'] = array_replace(
                    isset($archiveFile['ocr']) && is_array($archiveFile['ocr'])
                        ? $archiveFile['ocr']
                        : [],
                    [
                        'archiveRelativePath' => docs_build_ocr_text_archive_relative_path(
                            $folder,
                            $documentField,
                            $documentValue,
                            $storedName
                        ),
                        'archiveKey' => (string) $item['archiveKey'],
                        'archiveTextLength' => (int) $item['ocrTextLength'],
                        'archiveTextSha256' => $itemArchiveHash,
                        'archiveFolder' => sanitize_folder_name($folder),
                        'archiveDocumentField' => $documentField,
                        'archiveDocumentValue' => $documentValue,
                    ]
                );
            }
            $archive = docs_load_ocr_text_archive($archiveFile);
            if (!empty($archive['ok']) && isset($archive['text']) && is_string($archive['text'])) {
                $existingText = trim($archive['text']);
            } elseif ($itemArchiveConfirmed) {
                return [
                    'done' => false,
                    'retry' => true,
                    'stage' => 'archive',
                    'error' => (string) ($archive['error'] ?? 'Подтверждённый OCR-архив временно не прочитан из S3.'),
                ];
            }
        }
        if (!$legacyNeedsFreshOcr
            && $existingText === ''
            && isset($file['ocr'])
            && is_array($file['ocr'])
            && strtolower((string) ($file['ocr']['status'] ?? '')) === 'completed'
        ) {
            $hydrated = docs_hydrate_task_ocr_from_participant_snapshots(
                $record,
                docs_collect_record_telegram_ids($record, $folder)
            );
            foreach ((array) ($hydrated['files'] ?? []) as $hydratedFile) {
                if (!is_array($hydratedFile)
                    || sanitize_text_field((string) ($hydratedFile['storedName'] ?? ''), 255) !== $storedName
                ) {
                    continue;
                }
                $existingText = isset($hydratedFile['ocrText']) && is_string($hydratedFile['ocrText'])
                    ? trim($hydratedFile['ocrText'])
                    : '';
                break;
            }
        }
        $jobId = sanitize_text_field((string) ($item['jobId'] ?? ''), 160);
        $activeOwnerKey = sanitize_text_field((string) ($activeJob['ownerKey'] ?? ''), 80);
        if ($activeOwnerKey !== '' && hash_equals($activeOwnerKey, $ownerKey)) {
            $activeJobId = sanitize_text_field((string) ($activeJob['jobId'] ?? ''), 160);
            if ($activeJobId !== '') {
                $jobId = $activeJobId;
            }
        }
        $idempotencyKey = sanitize_text_field((string) ($item['idempotencyKey'] ?? ''), 240);
        if ($activeOwnerKey !== '' && hash_equals($activeOwnerKey, $ownerKey)) {
            $activeIdempotencyKey = sanitize_text_field(
                (string) ($activeJob['idempotencyKey'] ?? ''),
                240
            );
            if ($activeIdempotencyKey !== '') {
                $idempotencyKey = $activeIdempotencyKey;
            }
        }
        $pagesCount = max(0, (int) ($item['pagesCount'] ?? 0));
        $textTruncated = !empty($item['textTruncated']);
        $lastJobStatus = strtolower(sanitize_text_field((string) ($item['jobStatus'] ?? ''), 40));
        $lastJobProgress = max(0, min(100, (int) ($item['progress'] ?? 0)));
        $lastCurrentPage = max(0, (int) ($item['currentPage'] ?? 0));
        $lastTotalPages = max(0, (int) ($item['totalPages'] ?? 0));
        $progressChangedAt = strtotime((string) ($item['progressChangedAt'] ?? ''))
            ?: (strtotime((string) ($item['startedAt'] ?? '')) ?: time());
        if ($existingText === '') {
            if ($jobId === '') {
                $localPath = docs_resolve_live_ocr_local_path($folder, $file);
                if ($localPath === '') {
                    return [
                        'done' => false,
                        'retry' => true,
                        'stage' => 'source',
                        'error' => 'Исходный файл недоступен локально и в S3.',
                    ];
                }
                if ($idempotencyKey === '') {
                    $idempotencyKey = docs_private_ocr_idempotency_key($localPath);
                }
                $progressCallback([
                    'stage' => 'creating_job',
                    'progress' => 0,
                    'idempotencyKey' => $idempotencyKey,
                    'heartbeatAt' => date('c'),
                ]);
                $activeJob = [
                    'version' => 1,
                    'ownerKey' => $ownerKey,
                    'source' => $source,
                    'runId' => sanitize_text_field((string) ($item['runId'] ?? ''), 120),
                    'folder' => sanitize_folder_name($folder),
                    'itemKey' => sanitize_text_field((string) ($item['key'] ?? ''), 160),
                    'idempotencyKey' => $idempotencyKey,
                    'jobId' => '',
                    'phase' => 'submitting',
                ];
                if (!docs_save_ocr_active_job_unlocked($activeJob)) {
                    docs_cleanup_live_ocr_temp_source($localPath);
                    return [
                        'done' => false,
                        'retry' => true,
                        'stage' => 'state',
                        'error' => 'Не удалось сохранить защитное состояние до отправки OCR.',
                    ];
                }
                try {
                    $created = docs_create_private_ocr_job(
                        $localPath,
                        (string) ($file['originalName'] ?? $storedName),
                        $idempotencyKey
                    );
                } finally {
                    docs_cleanup_live_ocr_temp_source($localPath);
                }
                if (empty($created['ok'])) {
                    $httpStatus = (int) ($created['httpStatus'] ?? 0);
                    $definitiveRejection = $httpStatus >= 400 && $httpStatus < 500;
                    if ($definitiveRejection) {
                        docs_clear_ocr_active_job_for_owner_unlocked($ownerKey);
                    }
                    return [
                        'done' => false,
                        'retry' => true,
                        'remoteUnresolved' => !$definitiveRejection,
                        'stage' => 'ocr',
                        'error' => (string) ($created['error'] ?? 'Не удалось создать OCR-задание.'),
                    ];
                }
                $jobId = (string) $created['jobId'];
                $lastJobStatus = strtolower(sanitize_text_field((string) ($created['status'] ?? 'queued'), 40));
                $lastJobProgress = max(0, min(100, (int) ($created['progress'] ?? 0)));
                $lastCurrentPage = 0;
                $lastTotalPages = 0;
                $progressChangedAt = time();
                $activeJob['jobId'] = $jobId;
                $activeJob['phase'] = 'running';
                if (!docs_save_ocr_active_job_unlocked($activeJob)) {
                    return [
                        'done' => false,
                        'retry' => true,
                        'remoteUnresolved' => true,
                        'stage' => 'state',
                        'error' => 'OCR job создан, но его защитное состояние не удалось подтвердить.',
                    ];
                }
                $progressCallback([
                    'status' => 'processing',
                    'stage' => 'ocr',
                    'jobId' => $jobId,
                    'idempotencyKey' => $idempotencyKey,
                    'jobStatus' => $lastJobStatus,
                    'progressChangedAt' => date('c', $progressChangedAt),
                    'startedAt' => (string) ($item['startedAt'] ?? date('c')),
                    'error' => '',
                    'heartbeatAt' => date('c'),
                ]);
            } else {
                $activeJob = [
                    'version' => 1,
                    'ownerKey' => $ownerKey,
                    'source' => $source,
                    'runId' => sanitize_text_field((string) ($item['runId'] ?? ''), 120),
                    'folder' => sanitize_folder_name($folder),
                    'itemKey' => sanitize_text_field((string) ($item['key'] ?? ''), 160),
                    'idempotencyKey' => $idempotencyKey,
                    'jobId' => $jobId,
                    'phase' => 'running',
                ];
                if (!docs_save_ocr_active_job_unlocked($activeJob)) {
                    return [
                        'done' => false,
                        'retry' => true,
                        'remoteUnresolved' => true,
                        'stage' => 'state',
                        'error' => 'Не удалось подтвердить активный OCR job перед опросом.',
                    ];
                }
            }
            $statusErrors = 0;
            while (microtime(true) < $workerDeadline) {
                if ($resourceGuard !== null) {
                    $guard = $resourceGuard();
                    if (is_array($guard) && empty($guard['ok'])) {
                        return [
                            'done' => false,
                            'retry' => true,
                            'abortWorker' => true,
                            'stage' => 'resource_guard',
                            'jobId' => $jobId,
                            'error' => docs_format_ocr_backfill_memory_guard_error($guard),
                        ];
                    }
                }
                $status = docs_fetch_private_ocr_job_status($jobId);
                if (empty($status['ok'])) {
                    $statusErrors++;
                    if ($statusErrors >= 3) {
                        $remoteMissing = in_array((int) ($status['httpStatus'] ?? 0), [404, 410], true);
                        if ($remoteMissing) {
                            docs_clear_ocr_active_job_for_owner_unlocked($ownerKey);
                            $progressCallback([
                                'jobId' => '',
                                'idempotencyKey' => '',
                                'jobStatus' => 'expired',
                                'heartbeatAt' => date('c'),
                            ]);
                        }
                        return [
                            'done' => false,
                            'retry' => true,
                            'remoteUnresolved' => !$remoteMissing,
                            'staleJob' => $remoteMissing,
                            'stage' => 'ocr',
                            'error' => (string) ($status['error'] ?? 'OCR-сервер временно недоступен.'),
                        ];
                    }
                    sleep(DOCS_LIVE_OCR_POLL_INTERVAL_SECONDS);
                    continue;
                }
                $statusErrors = 0;
                $remoteJobStatus = strtolower(sanitize_text_field((string) ($status['status'] ?? ''), 40));
                $remoteProgress = max(0, min(100, (int) ($status['progress'] ?? 0)));
                $remoteCurrentPage = max(0, (int) ($status['currentPage'] ?? 0));
                $remoteTotalPages = max(0, (int) ($status['totalPages'] ?? 0));
                if ($remoteJobStatus !== $lastJobStatus
                    || $remoteProgress !== $lastJobProgress
                    || $remoteCurrentPage !== $lastCurrentPage
                    || $remoteTotalPages !== $lastTotalPages
                ) {
                    $lastJobStatus = $remoteJobStatus;
                    $lastJobProgress = $remoteProgress;
                    $lastCurrentPage = $remoteCurrentPage;
                    $lastTotalPages = $remoteTotalPages;
                    $progressChangedAt = time();
                }
                $progressCallback([
                    'status' => 'processing',
                    'stage' => 'ocr',
                    'jobStatus' => $remoteJobStatus,
                    'progress' => $remoteProgress,
                    'currentPage' => $remoteCurrentPage,
                    'totalPages' => $remoteTotalPages,
                    'progressChangedAt' => date('c', $progressChangedAt),
                    'heartbeatAt' => date('c'),
                ]);
                if (in_array($remoteJobStatus, ['queued', 'running'], true)) {
                    if ($source === 'legacy_backfill'
                        && time() - $progressChangedAt >= DOCS_OCR_BACKFILL_MAX_STALLED_SECONDS
                    ) {
                        return [
                            'done' => false,
                            'retry' => true,
                            'remoteUnresolved' => true,
                            'stalled' => true,
                            'stage' => 'ocr',
                            'jobId' => $jobId,
                            'error' => 'OCR job не меняет статус, процент или страницу более 30 минут. Удалённое задание сохранено.',
                        ];
                    }
                    sleep(DOCS_LIVE_OCR_POLL_INTERVAL_SECONDS);
                    continue;
                }
                if (in_array($remoteJobStatus, ['failed', 'cancelled'], true)) {
                    docs_clear_ocr_active_job_for_owner_unlocked($ownerKey);
                    $remoteJobError = sanitize_text_field((string) ($status['error'] ?? ''), 500);
                    return [
                        'done' => false,
                        'terminal' => true,
                        'stage' => 'ocr',
                        'error' => $remoteJobError !== ''
                            ? $remoteJobError
                            : 'OCR завершён со статусом ' . $remoteJobStatus . '.',
                    ];
                }
                if ($resourceGuard !== null) {
                    $guard = $resourceGuard();
                    if (is_array($guard) && empty($guard['ok'])) {
                        return [
                            'done' => false,
                            'retry' => true,
                            'abortWorker' => true,
                            'stage' => 'resource_guard',
                            'jobId' => $jobId,
                            'error' => docs_format_ocr_backfill_memory_guard_error($guard),
                        ];
                    }
                }
                $result = docs_fetch_private_ocr_job_result($jobId);
                if (empty($result['ok'])) {
                    $remoteMissing = in_array((int) ($result['httpStatus'] ?? 0), [404, 410], true);
                    $emptyResult = !empty($result['emptyResult']);
                    if ($remoteMissing || $emptyResult) {
                        docs_clear_ocr_active_job_for_owner_unlocked($ownerKey);
                        $progressCallback([
                            'jobId' => '',
                            'idempotencyKey' => '',
                            'jobStatus' => $remoteMissing ? 'expired' : 'empty',
                            'heartbeatAt' => date('c'),
                        ]);
                    }
                    return [
                        'done' => false,
                        'retry' => true,
                        'remoteUnresolved' => !$remoteMissing && !$emptyResult,
                        'staleJob' => $remoteMissing,
                        'emptyResult' => $emptyResult,
                        'pagesCount' => max(0, (int) ($result['pagesCount'] ?? 0)),
                        'stage' => 'ocr',
                        'error' => (string) ($result['error'] ?? 'Не удалось получить OCR-текст.'),
                    ];
                }
                $existingText = trim((string) $result['text']);
                $pagesCount = (int) ($result['pagesCount'] ?? 0);
                $textTruncated = !empty($result['textTruncated']);
                docs_clear_ocr_active_job_for_owner_unlocked($ownerKey);
                break;
            }
            if ($existingText === '') {
                return [
                    'done' => false,
                    'retry' => true,
                    'remoteUnresolved' => $jobId !== '',
                    'stage' => 'ocr',
                    'error' => microtime(true) >= $workerDeadline
                        ? 'Истекло время рабочего цикла OCR.'
                        : 'OCR завершён без текста.',
                ];
            }
        }
        if ($resourceGuard !== null) {
            $guard = $resourceGuard();
            if (is_array($guard) && empty($guard['ok'])) {
                return [
                    'done' => false,
                    'retry' => true,
                    'abortWorker' => true,
                    'stage' => 'resource_guard',
                    'jobId' => $jobId,
                    'error' => docs_format_ocr_backfill_memory_guard_error($guard),
                ];
            }
        }
        $progressCallback([
            'stage' => 'archive',
            'progress' => 100,
            'heartbeatAt' => date('c'),
        ]);
        $archive = docs_write_ocr_text_archive(
            $folder,
            $documentField,
            $documentValue,
            $file,
            $existingText
        );
        if (empty($archive['ok'])) {
            return [
                'done' => false,
                'retry' => true,
                'stage' => 'archive',
                'error' => (string) ($archive['error'] ?? 'Не удалось подтвердить OCR-текст в S3-архиве.'),
            ];
        }
        $progressCallback([
            'stage' => 'archive',
            'archiveKey' => (string) ($archive['key'] ?? ''),
            'ocrTextLength' => (int) ($archive['textLength'] ?? 0),
            'ocrTextSha256' => (string) ($archive['textSha256'] ?? ''),
            'heartbeatAt' => date('c'),
        ]);
        $progressCallback(['stage' => 'registry', 'heartbeatAt' => date('c')]);
        $registryUpdate = docs_update_live_ocr_registry_file(
            $folder,
            $documentValue,
            $storedName,
            [
                'status' => 'completed',
                'engine' => $jobId !== '' ? 'n8n_jobs' : 's3_archive',
                'source' => $source !== '' ? $source : 'live_upload',
                'jobId' => $jobId,
                'jobStatus' => $jobId !== '' ? 'succeeded' : 'reused_text',
                'progress' => 100,
                'pagesCount' => $pagesCount,
                'textTruncated' => $textTruncated,
                'archiveRelativePath' => (string) ($archive['relativePath'] ?? ''),
                'archiveKey' => (string) ($archive['key'] ?? ''),
                'archiveTextLength' => (int) ($archive['textLength'] ?? 0),
                'archiveTextSha256' => (string) ($archive['textSha256'] ?? ''),
                'archiveFolder' => sanitize_folder_name($folder),
                'archiveDocumentField' => $documentField,
                'archiveDocumentValue' => $documentValue,
                'archiveVerifiedAt' => (string) ($archive['savedAt'] ?? date('c')),
                'completedAt' => date('c'),
            ],
            $existingText,
            $documentField
        );
        if (empty($registryUpdate['ok'])) {
            if (!empty($registryUpdate['missing'])) {
                return ['done' => true, 'status' => 'skipped', 'error' => (string) ($registryUpdate['error'] ?? '')];
            }
            return [
                'done' => false,
                'retry' => true,
                'stage' => 'registry',
                'error' => (string) ($registryUpdate['error'] ?? 'Не удалось сохранить OCR-метаданные.'),
            ];
        }
        $progressCallback(['stage' => 'delivery', 'heartbeatAt' => date('c')]);
        $delivery = docs_sync_live_ocr_participant_snapshots(
            (array) $registryUpdate['record'],
            $folder,
            $storedName,
            $existingText
        );
        $progressCallback([
            'stage' => 'delivery',
            'participants' => (int) ($delivery['participants'] ?? 0),
            'delivered' => (int) ($delivery['verified'] ?? 0),
            'allPresent' => !empty($delivery['allPresent']),
            'deliveries' => (array) ($delivery['deliveries'] ?? []),
            'heartbeatAt' => date('c'),
        ]);
        if (empty($delivery['ok'])) {
            return [
                'done' => false,
                'retry' => true,
                'stage' => 'delivery',
                'deliveries' => (array) ($delivery['deliveries'] ?? []),
                'error' => (string) ($delivery['error'] ?? 'Не удалось подтвердить Telegram JSON в S3.'),
            ];
        }
        return [
            'done' => true,
            'status' => 'completed',
            'archiveKey' => (string) ($archive['key'] ?? ''),
            'ocrTextLength' => mb_strlen($existingText, 'UTF-8'),
            'ocrTextSha256' => hash('sha256', $existingText),
            'participants' => (int) ($delivery['participants'] ?? 0),
            'delivered' => (int) ($delivery['verified'] ?? 0),
            'allPresent' => !empty($delivery['allPresent']),
            'deliveries' => (array) ($delivery['deliveries'] ?? []),
        ];
    } finally {
        docs_release_global_ocr_slot($slotHandle);
    }
}
function docs_process_live_ocr_queue_item(string $folder, array $item, float $workerDeadline): array
{
    $key = (string) ($item['key'] ?? '');
    return docs_process_ocr_queue_item(
        $folder,
        $item,
        $workerDeadline,
        static function (array $changes) use ($folder, $key): void {
            docs_update_live_ocr_queue_item($folder, $key, $changes);
        }
    );
}
function docs_run_live_ocr_worker(string $folder): array
{
    $folder = sanitize_folder_name($folder);
    if ($folder === '') {
        return ['ok' => false, 'reason' => 'folder_missing'];
    }
    $workerLock = @fopen(docs_live_ocr_worker_lock_path($folder), 'c+');
    if ($workerLock === false || !@flock($workerLock, LOCK_EX | LOCK_NB)) {
        if (is_resource($workerLock)) {
            fclose($workerLock);
        }
        return ['ok' => true, 'worked' => false, 'reason' => 'worker_already_running'];
    }
    if (function_exists('set_time_limit')) {
        @set_time_limit(0);
    }
    $deadline = microtime(true) + DOCS_LIVE_OCR_MAX_WORKER_SECONDS;
    $completed = 0;
    $failed = 0;
    $restartNeeded = false;
    try {
        while (microtime(true) < $deadline) {
            $selected = docs_get_live_ocr_queue_item($folder);
            $item = $selected['item'] ?? null;
            if (!is_array($item)) {
                $nextAttemptAt = (int) ($selected['nextAttemptAt'] ?? 0);
                if ($nextAttemptAt <= 0) {
                    break;
                }
                sleep(max(1, min(30, $nextAttemptAt - time())));
                continue;
            }
            $outcome = docs_process_live_ocr_queue_item($folder, $item, $deadline);
            if (!empty($outcome['busy'])) {
                docs_update_live_ocr_queue_item($folder, (string) ($item['key'] ?? ''), [
                    'status' => 'pending',
                    'stage' => 'waiting_slot',
                    'nextAttemptAt' => date('c', time() + DOCS_LIVE_OCR_POLL_INTERVAL_SECONDS),
                    'error' => '',
                ]);
                sleep(DOCS_LIVE_OCR_POLL_INTERVAL_SECONDS);
                continue;
            }
            if (!empty($outcome['done'])) {
                docs_finish_live_ocr_queue_item(
                    $folder,
                    $item,
                    (string) ($outcome['status'] ?? 'completed'),
                    (string) ($outcome['error'] ?? '')
                );
                $completed++;
                continue;
            }
            $attempts = max(0, (int) ($item['attempts'] ?? 0)) + 1;
            $stage = (string) ($outcome['stage'] ?? 'ocr');
            $error = sanitize_text_field((string) ($outcome['error'] ?? 'Неизвестная ошибка OCR.'), 500);
            $terminal = !empty($outcome['terminal'])
                || (empty($outcome['remoteUnresolved']) && $attempts >= DOCS_LIVE_OCR_MAX_ATTEMPTS);
            if ($terminal) {
                $documentField = docs_normalize_ocr_document_field(
                    (string) ($item['documentField'] ?? 'id')
                );
                $documentValue = (string) ($item['documentValue'] ?? ($item['documentId'] ?? ''));
                $located = docs_find_live_ocr_record_file(
                    $folder,
                    $documentValue,
                    (string) ($item['storedName'] ?? ''),
                    $documentField
                );
                if (is_array($located['file'] ?? null)) {
                    $existingOcr = isset($located['file']['ocr']) && is_array($located['file']['ocr'])
                        ? $located['file']['ocr']
                        : [];
                    $extractionAlreadyCompleted = $stage === 'delivery'
                        && strtolower((string) ($existingOcr['status'] ?? '')) === 'completed'
                        && trim((string) ($existingOcr['archiveRelativePath'] ?? '')) !== ''
                        && trim((string) ($existingOcr['archiveTextSha256'] ?? '')) !== '';
                    $terminalOcr = $extractionAlreadyCompleted
                        ? array_replace($existingOcr, [
                            'deliveryStatus' => 'error',
                            'deliveryError' => $error,
                            'deliveryFailedAt' => date('c'),
                        ])
                        : array_replace($existingOcr, [
                            'status' => 'error',
                            'engine' => 'n8n_jobs',
                            'source' => sanitize_text_field((string) ($item['source'] ?? 'live_upload'), 80),
                            'jobId' => (string) ($item['jobId'] ?? ''),
                            'error' => $error,
                            'failedAt' => date('c'),
                        ]);
                    $registryUpdate = docs_update_live_ocr_registry_file(
                        $folder,
                        $documentValue,
                        (string) ($item['storedName'] ?? ''),
                        $terminalOcr,
                        null,
                        $documentField
                    );
                    if (!$extractionAlreadyCompleted
                        && !empty($registryUpdate['ok'])
                        && is_array($registryUpdate['record'] ?? null)
                    ) {
                        docs_sync_live_ocr_participant_snapshots($registryUpdate['record'], $folder);
                    }
                }
                docs_finish_live_ocr_queue_item($folder, $item, 'failed', $error);
                $failed++;
                continue;
            }
            $delay = min(300, DOCS_LIVE_OCR_RETRY_DELAY_SECONDS * max(1, $attempts));
            docs_update_live_ocr_queue_item($folder, (string) ($item['key'] ?? ''), [
                'status' => 'retry',
                'attempts' => $attempts,
                'nextAttemptAt' => date('c', time() + $delay),
                'error' => $error,
            ]);
        }
        if (microtime(true) >= $deadline) {
            $queue = docs_load_live_ocr_queue_unlocked($folder);
            foreach ((array) ($queue['items'] ?? []) as $pendingItem) {
                if (is_array($pendingItem)
                    && !in_array((string) ($pendingItem['status'] ?? ''), ['completed', 'failed', 'skipped'], true)
                ) {
                    $restartNeeded = true;
                    break;
                }
            }
        }
    } finally {
        @flock($workerLock, LOCK_UN);
        fclose($workerLock);
    }
    if ($restartNeeded) {
        docs_start_live_ocr_worker($folder);
    }
    return [
        'ok' => true,
        'worked' => ($completed + $failed) > 0,
        'completed' => $completed,
        'failed' => $failed,
        'reason' => $restartNeeded
            ? 'worker_restarted'
            : (microtime(true) >= $deadline ? 'worker_window_finished' : 'queue_empty'),
    ];
}
function docs_live_ocr_php_binary(): string
{
    foreach (array_values(array_unique([
        rtrim((string) PHP_BINDIR, '/') . '/php',
        PHP_BINARY,
        '/usr/bin/php',
        '/usr/local/bin/php',
        '/opt/homebrew/bin/php',
    ])) as $candidate) {
        $candidate = trim((string) $candidate);
        if ($candidate !== '' && is_file($candidate) && is_executable($candidate) && preg_match('/^php(?:[0-9.]+)?$/i', basename($candidate))) {
            return $candidate;
        }
    }
    return '';
}
function docs_start_live_ocr_worker(string $folder): array
{
    $folder = sanitize_folder_name($folder);
    $phpBinary = docs_live_ocr_php_binary();
    if ($folder === '' || $phpBinary === '' || !function_exists('proc_open')) {
        return ['ok' => false, 'error' => 'Фоновый PHP worker недоступен.'];
    }
    if (!is_dir(DOCS_SERVER_LOG_DIRECTORY)) {
        @mkdir(DOCS_SERVER_LOG_DIRECTORY, 0775, true);
    }
    $logPath = DOCS_SERVER_LOG_DIRECTORY . '/' . DOCS_LIVE_OCR_WORKER_LOG_FILENAME;
    $command = 'nohup '
        . escapeshellarg($phpBinary) . ' '
        . escapeshellarg(__FILE__) . ' '
        . escapeshellarg(DOCS_LIVE_OCR_WORKER_COMMAND) . ' '
        . escapeshellarg($folder) . ' >> '
        . escapeshellarg($logPath) . ' 2>&1 < /dev/null &';
    $started = docs_run_process_with_timeout(['/bin/sh', '-c', $command], 5);
    return [
        'ok' => !empty($started['ok']),
        'error' => !empty($started['ok']) ? '' : sanitize_text_field((string) ($started['error'] ?? 'Не удалось запустить OCR worker.'), 500),
    ];
}
function docs_activate_live_ocr_worker(string $folder): void
{
    $started = docs_start_live_ocr_worker($folder);
    if (!empty($started['ok'])) {
        return;
    }
    docs_write_response_log('Не удалось запустить отдельный OCR worker; используется фоновый PHP-запрос', [
        'folder' => $folder,
        'error' => (string) ($started['error'] ?? ''),
    ]);
    docs_run_live_ocr_worker($folder);
}
function docs_ocr_backfill_state_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_BACKFILL_STATE_FILENAME);
}
function docs_ocr_backfill_state_lock_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_BACKFILL_STATE_LOCK_FILENAME);
}
function docs_ocr_backfill_worker_lock_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_BACKFILL_WORKER_LOCK_FILENAME);
}
function docs_ocr_backfill_memory_stop_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_BACKFILL_MEMORY_STOP_FILENAME);
}
function docs_is_ocr_backfill_worker_process(): bool
{
    $arguments = isset($_SERVER['argv']) && is_array($_SERVER['argv'])
        ? $_SERVER['argv']
        : [];
    return PHP_SAPI === 'cli'
        && isset($arguments[1])
        && trim((string) $arguments[1]) === DOCS_OCR_BACKFILL_WORKER_COMMAND;
}
function docs_apply_task_snapshot_memory_limit(): void
{
    @ini_set(
        'memory_limit',
        docs_is_ocr_backfill_worker_process()
            ? DOCS_OCR_BACKFILL_PROCESS_MEMORY_LIMIT
            : DOCS_TASK_SNAPSHOT_READ_MEMORY_LIMIT
    );
}
function docs_ocr_backfill_resource_guard(): array
{
    $path = '/proc/meminfo';
    if (!is_file($path) || !is_readable($path)) {
        return [
            'ok' => true,
            'monitored' => false,
            'totalBytes' => 0,
            'availableBytes' => 0,
            'requiredBytes' => DOCS_OCR_BACKFILL_MIN_AVAILABLE_MEMORY_BYTES,
        ];
    }
    $raw = @file_get_contents($path, false, null, 0, 65536);
    if (!is_string($raw)
        || preg_match('/^MemTotal:\s+(\d+)\s+kB$/mi', $raw, $totalMatch) !== 1
        || preg_match('/^MemAvailable:\s+(\d+)\s+kB$/mi', $raw, $availableMatch) !== 1
    ) {
        return [
            'ok' => true,
            'monitored' => false,
            'totalBytes' => 0,
            'availableBytes' => 0,
            'requiredBytes' => DOCS_OCR_BACKFILL_MIN_AVAILABLE_MEMORY_BYTES,
        ];
    }
    $totalBytes = max(0, (int) $totalMatch[1]) * 1024;
    $availableBytes = max(0, (int) $availableMatch[1]) * 1024;
    $requiredBytes = max(
        DOCS_OCR_BACKFILL_MIN_AVAILABLE_MEMORY_BYTES,
        (int) ceil($totalBytes * DOCS_OCR_BACKFILL_MIN_AVAILABLE_MEMORY_RATIO)
    );
    return [
        'ok' => $availableBytes >= $requiredBytes,
        'monitored' => true,
        'totalBytes' => $totalBytes,
        'availableBytes' => $availableBytes,
        'requiredBytes' => $requiredBytes,
    ];
}
function docs_format_ocr_backfill_memory_guard_error(array $guard): string
{
    $availableMb = (int) floor(max(0, (int) ($guard['availableBytes'] ?? 0)) / 1048576);
    $requiredMb = (int) ceil(max(0, (int) ($guard['requiredBytes'] ?? 0)) / 1048576);
    return 'OCR старых файлов остановлен защитой памяти: доступно '
        . $availableMb . ' МБ, для сайта зарезервировано минимум ' . $requiredMb
        . ' МБ. Освободите RAM и продолжите проход вручную.';
}
function docs_is_ocr_backfill_worker_active(): bool
{
    $handle = @fopen(docs_ocr_backfill_worker_lock_path(), 'c+');
    if ($handle === false) {
        return false;
    }
    $acquired = @flock($handle, LOCK_EX | LOCK_NB);
    if ($acquired) {
        @flock($handle, LOCK_UN);
    }
    fclose($handle);
    return !$acquired;
}
function docs_default_ocr_backfill_final_audit(): array
{
    return [
        'status' => 'pending',
        'ok' => false,
        'checkedAt' => '',
        'users' => 0,
        'expectedFiles' => 0,
        'verifiedFiles' => 0,
        'archiveFiles' => 0,
        'archiveFilesRechecked' => 0,
        'error' => '',
        'errors' => [],
    ];
}
function docs_default_ocr_backfill_state(): array
{
    return [
        'version' => 1,
        'runId' => '',
        'status' => 'idle',
        'stopRequested' => false,
        'createdAt' => '',
        'startedAt' => '',
        'completedAt' => '',
        'updatedAt' => date('c'),
        'heartbeatAt' => '',
        'workerError' => '',
        'currentKey' => '',
        'finalAudit' => docs_default_ocr_backfill_final_audit(),
        'scan' => [
            'organizations' => 0,
            'tasks' => 0,
            'files' => 0,
            'supported' => 0,
            'unsupported' => 0,
            'ambiguousTaskReferences' => 0,
            'ambiguousStoredNames' => 0,
        ],
        'items' => [],
    ];
}
function docs_load_ocr_backfill_state_unlocked(): array
{
    $path = docs_ocr_backfill_state_path();
    $decoded = docs_read_json_array_file_with_backup($path);
    if (!is_array($decoded) || (int) ($decoded['version'] ?? 0) !== 1) {
        return docs_default_ocr_backfill_state();
    }
    $decoded['items'] = isset($decoded['items']) && is_array($decoded['items'])
        ? array_values($decoded['items'])
        : [];
    $decoded['scan'] = isset($decoded['scan']) && is_array($decoded['scan'])
        ? $decoded['scan']
        : docs_default_ocr_backfill_state()['scan'];
    $decoded['finalAudit'] = isset($decoded['finalAudit']) && is_array($decoded['finalAudit'])
        ? array_replace(docs_default_ocr_backfill_final_audit(), $decoded['finalAudit'])
        : docs_default_ocr_backfill_final_audit();
    return array_replace(docs_default_ocr_backfill_state(), $decoded);
}
function docs_load_ocr_backfill_state(): array
{
    $handle = @fopen(docs_ocr_backfill_state_lock_path(), 'c+');
    if ($handle === false || !@flock($handle, LOCK_SH)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return docs_default_ocr_backfill_state();
    }
    try {
        return docs_load_ocr_backfill_state_unlocked();
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_save_ocr_backfill_state_unlocked(array $state): bool
{
    $state['version'] = 1;
    $state['updatedAt'] = date('c');
    $state['items'] = isset($state['items']) && is_array($state['items'])
        ? array_values($state['items'])
        : [];
    return docs_write_json_file_atomically(docs_ocr_backfill_state_path(), $state);
}
function docs_mutate_ocr_backfill_state(callable $callback): array
{
    $handle = @fopen(docs_ocr_backfill_state_lock_path(), 'c+');
    if ($handle === false || !@flock($handle, LOCK_EX)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return ['ok' => false, 'error' => 'Не удалось заблокировать очередь старых OCR-файлов.'];
    }
    try {
        $state = docs_load_ocr_backfill_state_unlocked();
        $result = $callback($state);
        if (!docs_save_ocr_backfill_state_unlocked($state)) {
            return ['ok' => false, 'error' => 'Не удалось сохранить очередь старых OCR-файлов.'];
        }
        return is_array($result) ? array_merge(['ok' => true], $result) : ['ok' => true];
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_ocr_backfill_task_label(array $record): string
{
    foreach (['registryNumber', 'entryNumber', 'documentNumber', 'id'] as $field) {
        $value = sanitize_text_field((string) ($record[$field] ?? ''), 200);
        if ($value !== '') {
            return $value;
        }
    }
    return 'Задача без номера';
}
function docs_create_ocr_backfill_state(): array
{
    try {
        $runId = date('YmdHis') . '-' . bin2hex(random_bytes(6));
    } catch (Throwable $error) {
        $runId = date('YmdHis') . '-' . str_replace('.', '', uniqid('', true));
    }
    $state = docs_default_ocr_backfill_state();
    $state['runId'] = $runId;
    $state['status'] = 'running';
    $state['createdAt'] = date('c');
    $state['startedAt'] = date('c');
    $state['heartbeatAt'] = date('c');
    $items = [];
    $seenKeys = [];
    $organizationsCount = 0;
    $tasksCount = 0;
    $filesCount = 0;
    $supportedCount = 0;
    $unsupportedCount = 0;
    $ambiguousTaskReferencesCount = 0;
    $ambiguousStoredNamesCount = 0;
    foreach (load_organizations() as $organization) {
        if (!is_string($organization) || trim($organization) === '') {
            continue;
        }
        $folder = sanitize_folder_name($organization);
        if ($folder === '' || !is_dir(DOCUMENTS_ROOT . '/' . $folder)) {
            continue;
        }
        $organizationsCount++;
        $directoryEntries = docs_load_telegram_participant_directory_entries($folder);
        $registry = load_registry($folder);
        $referenceCounts = [];
        foreach ($registry as $record) {
            if (!is_array($record)) {
                continue;
            }
            $reference = docs_build_ocr_document_reference($record, $folder);
            $referenceKey = (string) ($reference['field'] ?? '') . "\0" . (string) ($reference['value'] ?? '');
            if ($referenceKey !== "\0") {
                $referenceCounts[$referenceKey] = ($referenceCounts[$referenceKey] ?? 0) + 1;
            }
        }
        foreach ($registry as $record) {
            if (!is_array($record)) {
                continue;
            }
            $tasksCount++;
            $reference = docs_build_ocr_document_reference($record, $folder);
            $documentField = (string) ($reference['field'] ?? '');
            $documentValue = (string) ($reference['value'] ?? '');
            $snapshotRecord = $record;
            $snapshotRecord['documentFolder'] = $folder;
            $taskKey = docs_task_snapshot_key($snapshotRecord);
            $referenceKey = $documentField . "\0" . $documentValue;
            $ambiguousTaskReference = $referenceKey !== "\0"
                && (int) ($referenceCounts[$referenceKey] ?? 0) > 1;
            $telegramIds = [];
            foreach (docs_collect_record_telegram_participation($record, $folder, $directoryEntries) as $participant) {
                if (!is_array($participant)) {
                    continue;
                }
                $telegramId = normalize_identifier_value($participant['telegramId'] ?? '');
                if ($telegramId !== '') {
                    $telegramIds[$telegramId] = true;
                }
            }
            $telegramIds = array_keys($telegramIds);
            $storedNameCounts = [];
            foreach (isset($record['files']) && is_array($record['files']) ? $record['files'] : [] as $recordFile) {
                if (!is_array($recordFile)) {
                    continue;
                }
                $recordStoredName = sanitize_text_field((string) ($recordFile['storedName'] ?? ''), 255);
                if ($recordStoredName !== '') {
                    $storedNameCounts[$recordStoredName] = ($storedNameCounts[$recordStoredName] ?? 0) + 1;
                }
            }
            foreach (isset($record['files']) && is_array($record['files']) ? $record['files'] : [] as $fileIndex => $file) {
                if (!is_array($file)) {
                    continue;
                }
                $filesCount++;
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                $originalName = sanitize_text_field(
                    (string) ($file['originalName'] ?? ($file['name'] ?? $storedName)),
                    255
                );
                $supported = docs_is_live_ocr_supported_file($file);
                $ambiguousStoredName = $storedName !== ''
                    && (int) ($storedNameCounts[$storedName] ?? 0) > 1;
                $key = hash(
                    'sha256',
                    $folder . "\0" . $documentField . "\0" . $documentValue . "\0" . $storedName . "\0" . (string) $fileIndex
                );
                if (isset($seenKeys[$key])) {
                    continue;
                }
                $seenKeys[$key] = true;
                $status = 'pending';
                $error = '';
                $retryable = true;
                if (!$supported) {
                    $status = 'unsupported';
                    $error = 'Формат файла не поддерживается текущим OCR.';
                    $retryable = false;
                    $unsupportedCount++;
                } elseif ($storedName === '' || $documentField === '' || $documentValue === '') {
                    $status = 'failed';
                    $error = 'У старого файла отсутствует устойчивый идентификатор задачи или имя хранения.';
                    $retryable = false;
                    $supportedCount++;
                } elseif ($ambiguousTaskReference) {
                    $status = 'failed';
                    $error = 'В реестре есть несколько старых задач с одинаковым идентификатором. OCR не запущен, чтобы не записать текст в чужую задачу.';
                    $retryable = false;
                    $supportedCount++;
                    $ambiguousTaskReferencesCount++;
                } elseif ($ambiguousStoredName) {
                    $status = 'failed';
                    $error = 'В одной старой задаче повторяется storedName файла. OCR не запущен, пока нельзя однозначно выбрать вложение.';
                    $retryable = false;
                    $supportedCount++;
                    $ambiguousStoredNamesCount++;
                } else {
                    $supportedCount++;
                }
                $items[] = [
                    'key' => $key,
                    'organization' => sanitize_text_field($organization, 200),
                    'folder' => $folder,
                    'documentField' => $documentField,
                    'documentValue' => $documentValue,
                    'documentId' => $documentField === 'id' ? $documentValue : '',
                    'taskKey' => $taskKey,
                    'taskLabel' => docs_ocr_backfill_task_label($record),
                    'storedName' => $storedName,
                    'originalName' => $originalName !== '' ? $originalName : ($storedName !== '' ? $storedName : 'Файл без имени'),
                    'source' => 'legacy_backfill',
                    'status' => $status,
                    'retryable' => $retryable,
                    'stage' => $status === 'pending' ? 'waiting' : $status,
                    'progress' => 0,
                    'currentPage' => 0,
                    'totalPages' => 0,
                    'jobId' => '',
                    'jobStatus' => '',
                    'attempts' => 0,
                    'gateAttempts' => 0,
                    'staleJobResets' => 0,
                    'emptyResultResets' => 0,
                    'progressChangedAt' => '',
                    'retryGeneration' => 0,
                    'idempotencyKey' => '',
                    'nextAttemptAt' => '',
                    'participants' => count($telegramIds),
                    'telegramIds' => $telegramIds,
                    'delivered' => 0,
                    'allPresent' => count($telegramIds) === 0,
                    'deliveries' => [],
                    'archiveKey' => '',
                    'ocrTextLength' => 0,
                    'ocrTextSha256' => '',
                    'error' => $error,
                    'queuedAt' => date('c'),
                    'updatedAt' => date('c'),
                ];
            }
        }
    }
    $state['scan'] = [
        'organizations' => $organizationsCount,
        'tasks' => $tasksCount,
        'files' => $filesCount,
        'supported' => $supportedCount,
        'unsupported' => $unsupportedCount,
        'ambiguousTaskReferences' => $ambiguousTaskReferencesCount,
        'ambiguousStoredNames' => $ambiguousStoredNamesCount,
    ];
    $state['items'] = $items;
    if ($supportedCount === 0) {
        $state['status'] = 'completed';
        $state['completedAt'] = date('c');
        $state['currentKey'] = '';
        $state['finalAudit'] = array_replace(docs_default_ocr_backfill_final_audit(), [
            'status' => 'completed',
            'ok' => true,
            'checkedAt' => date('c'),
        ]);
    }
    return $state;
}
function docs_update_ocr_backfill_item(string $key, array $changes): bool
{
    $result = docs_mutate_ocr_backfill_state(static function (array &$state) use ($key, $changes): array {
        foreach ($state['items'] as &$item) {
            if (!is_array($item) || (string) ($item['key'] ?? '') !== $key) {
                continue;
            }
            $item = array_replace($item, $changes, ['updatedAt' => date('c')]);
            $state['heartbeatAt'] = date('c');
            if ((string) ($item['status'] ?? '') === 'processing') {
                $state['currentKey'] = $key;
            }
            unset($item);
            return ['updated' => true];
        }
        unset($item);
        return ['updated' => false];
    });
    return !empty($result['ok']) && !empty($result['updated']);
}
function docs_verify_ocr_backfill_final_manifest(array $state): array
{
    $expectedByUser = [];
    $archiveFiles = 0;
    $archiveFilesRechecked = 0;
    $manifestErrors = [];
    $registriesByFolder = [];
    $currentTasks = [];
    foreach (isset($state['items']) && is_array($state['items']) ? $state['items'] : [] as $item) {
        if (!is_array($item) || (string) ($item['status'] ?? '') !== 'completed') {
            continue;
        }
        $folder = sanitize_folder_name((string) ($item['folder'] ?? ''));
        $documentField = docs_normalize_ocr_document_field((string) ($item['documentField'] ?? 'id'));
        $documentValue = docs_sanitize_ocr_document_value(
            $documentField,
            (string) ($item['documentValue'] ?? ($item['documentId'] ?? ''))
        );
        $storedName = sanitize_text_field((string) ($item['storedName'] ?? ''), 255);
        $archiveKey = sanitize_text_field((string) ($item['archiveKey'] ?? ''), 1000);
        $textLength = max(0, (int) ($item['ocrTextLength'] ?? 0));
        $textSha256 = strtolower(sanitize_text_field((string) ($item['ocrTextSha256'] ?? ''), 80));
        $currentTaskCacheKey = hash('sha256', $folder . "\0" . $documentField . "\0" . $documentValue);
        if (!array_key_exists($currentTaskCacheKey, $currentTasks)) {
            if (!array_key_exists($folder, $registriesByFolder)) {
                $registriesByFolder[$folder] = load_registry($folder);
            }
            $currentRecord = null;
            foreach ($registriesByFolder[$folder] as $registryRecord) {
                if (is_array($registryRecord)
                    && docs_ocr_record_matches_reference(
                        $registryRecord,
                        $documentField,
                        $documentValue,
                        $folder
                    )
                ) {
                    $currentRecord = $registryRecord;
                    break;
                }
            }
            if (is_array($currentRecord)) {
                $currentRecord['documentFolder'] = $folder;
                $currentTasks[$currentTaskCacheKey] = [
                    'record' => $currentRecord,
                    'taskKey' => docs_task_snapshot_key($currentRecord),
                    'telegramIds' => docs_collect_record_telegram_ids($currentRecord, $folder),
                ];
            } else {
                $currentTasks[$currentTaskCacheKey] = null;
            }
        }
        $currentTask = isset($currentTasks[$currentTaskCacheKey])
            && is_array($currentTasks[$currentTaskCacheKey])
            ? $currentTasks[$currentTaskCacheKey]
            : null;
        $taskKey = is_array($currentTask)
            ? sanitize_text_field((string) ($currentTask['taskKey'] ?? ''), 500)
            : '';
        $currentFile = null;
        foreach (is_array($currentTask) ? (array) ($currentTask['record']['files'] ?? []) : [] as $recordFile) {
            if (is_array($recordFile)
                && sanitize_text_field((string) ($recordFile['storedName'] ?? ''), 255) === $storedName
            ) {
                $currentFile = $recordFile;
                break;
            }
        }
        $currentOcr = is_array($currentFile)
            && isset($currentFile['ocr'])
            && is_array($currentFile['ocr'])
            ? $currentFile['ocr']
            : [];
        if (!is_array($currentTask)
            || !is_array($currentFile)
            || $taskKey === ''
            || $storedName === ''
            || $archiveKey === ''
            || $textLength <= 0
            || preg_match('/^[a-f0-9]{64}$/', $textSha256) !== 1
            || strtolower((string) ($currentOcr['status'] ?? '')) !== 'completed'
            || (string) ($currentOcr['archiveKey'] ?? '') !== $archiveKey
            || (int) ($currentOcr['archiveTextLength'] ?? 0) !== $textLength
            || !hash_equals((string) ($currentOcr['archiveTextSha256'] ?? ''), $textSha256)
        ) {
            $manifestErrors[] = 'Для файла «'
                . sanitize_text_field((string) ($item['originalName'] ?? $storedName), 180)
                . '» текущий registry.json не подтвердил OCR-архив или задача изменилась.';
            continue;
        }
        $archiveFiles++;
        $telegramIds = [];
        foreach ((array) ($currentTask['telegramIds'] ?? []) as $telegramId) {
            $telegramId = normalize_identifier_value($telegramId);
            if ($telegramId !== '') {
                $telegramIds[$telegramId] = true;
            }
        }
        if (empty($telegramIds)) {
            $archive = docs_load_ocr_text_archive($currentFile);
            if (empty($archive['ok'])
                || (int) ($archive['textLength'] ?? 0) !== $textLength
                || !hash_equals($textSha256, (string) ($archive['textSha256'] ?? ''))
            ) {
                $manifestErrors[] = 'Для файла «'
                    . sanitize_text_field((string) ($item['originalName'] ?? $storedName), 180)
                    . '» без Telegram-получателей конечный OCR-архив не прошёл повторное чтение S3.';
                continue;
            }
            $archiveFilesRechecked++;
        }
        foreach (array_keys($telegramIds) as $telegramId) {
            $manifestKey = hash('sha256', $taskKey . "\0" . $storedName);
            $expected = [
                'taskKey' => $taskKey,
                'storedName' => $storedName,
                'originalName' => sanitize_text_field(
                    (string) ($item['originalName'] ?? $storedName),
                    255
                ),
                'textLength' => $textLength,
                'textSha256' => $textSha256,
            ];
            if (isset($expectedByUser[$telegramId][$manifestKey])
                && ((int) $expectedByUser[$telegramId][$manifestKey]['textLength'] !== $textLength
                    || !hash_equals(
                        (string) $expectedByUser[$telegramId][$manifestKey]['textSha256'],
                        $textSha256
                    ))
            ) {
                $manifestErrors[] = 'Для Telegram ID ' . $telegramId
                    . ' обнаружены противоречивые OCR-версии одного файла.';
                continue;
            }
            $expectedByUser[$telegramId][$manifestKey] = $expected;
        }
    }
    if (!empty($manifestErrors)) {
        $manifestErrors = array_slice(array_values(array_unique($manifestErrors)), 0, 50);
        return [
            'status' => 'failed',
            'ok' => false,
            'checkedAt' => date('c'),
            'users' => count($expectedByUser),
            'expectedFiles' => $archiveFiles,
            'verifiedFiles' => 0,
            'archiveFiles' => $archiveFiles,
            'archiveFilesRechecked' => $archiveFilesRechecked,
            'error' => sanitize_text_field(implode(' ', array_slice($manifestErrors, 0, 3)), 500),
            'errors' => $manifestErrors,
        ];
    }
    $verifiedFiles = 0;
    $errors = [];
    foreach ($expectedByUser as $telegramId => $expectedFiles) {
        $loaded = docs_load_mini_app_user_tasks_snapshot((string) $telegramId);
        if (empty($loaded['ok']) || !is_array($loaded['snapshot'] ?? null)) {
            $error = 'Telegram JSON ' . $telegramId . ' не прочитан из S3: '
                . sanitize_text_field((string) ($loaded['message'] ?? 'объект недоступен'), 300);
            $errors[] = $error;
            docs_mark_ocr_s3_user_index_error((string) $telegramId, $error);
            continue;
        }
        $identity = docs_validate_mini_app_user_tasks_snapshot_identity(
            (array) $loaded['snapshot'],
            (string) $telegramId
        );
        if (empty($identity['ok'])) {
            $error = 'Telegram JSON ' . $telegramId . ': '
                . sanitize_text_field((string) ($identity['error'] ?? 'не прошёл проверку'), 400);
            $errors[] = $error;
            docs_mark_ocr_s3_user_index_error((string) $telegramId, $error);
            continue;
        }
        $actualFiles = [];
        foreach ((array) ($loaded['snapshot']['tasks'] ?? []) as $task) {
            if (!is_array($task)) {
                continue;
            }
            $actualTaskKey = docs_task_snapshot_key($task);
            if ($actualTaskKey === '') {
                continue;
            }
            foreach ((array) ($task['files'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                $actualStoredName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                if ($actualStoredName === '') {
                    continue;
                }
                $manifestKey = hash('sha256', $actualTaskKey . "\0" . $actualStoredName);
                if (!isset($expectedFiles[$manifestKey]) || isset($actualFiles[$manifestKey])) {
                    continue;
                }
                $actualFiles[$manifestKey] = docs_validate_ocr_text_in_user_snapshot_file($file);
            }
        }
        $userErrors = [];
        foreach ($expectedFiles as $manifestKey => $expected) {
            $actual = isset($actualFiles[$manifestKey]) && is_array($actualFiles[$manifestKey])
                ? $actualFiles[$manifestKey]
                : [];
            if (empty($actual['ok'])) {
                $userErrors[] = 'нет текста файла «' . (string) $expected['originalName'] . '»';
                continue;
            }
            $actualHash = (string) ($actual['textSha256'] ?? '');
            $actualLength = (int) ($actual['textLength'] ?? 0);
            if ($actualHash === ''
                || !hash_equals((string) $expected['textSha256'], $actualHash)
                || $actualLength !== (int) $expected['textLength']
            ) {
                $userErrors[] = 'не совпал текст файла «' . (string) $expected['originalName'] . '»';
                continue;
            }
            $verifiedFiles++;
        }
        $summary = docs_summarize_ocr_user_snapshot(
            (string) $telegramId,
            (array) $loaded['snapshot'],
            (string) ($loaded['key'] ?? '')
        );
        if (empty($summary['allOcrPresent'])) {
            $userErrors[] = 'в конечном JSON остались другие OCR-пропуски или ошибки целостности';
        }
        if (!empty($userErrors)) {
            $error = 'Telegram JSON ' . $telegramId . ': ' . implode('; ', array_slice($userErrors, 0, 5)) . '.';
            $errors[] = $error;
            docs_mark_ocr_s3_user_index_error((string) $telegramId, $error);
            continue;
        }
        docs_update_ocr_s3_user_index_from_snapshot(
            (string) $telegramId,
            (array) $loaded['snapshot'],
            (string) ($loaded['key'] ?? '')
        );
        if (!docs_task_rag_invalidate_sync_cache((string) $telegramId)) {
            $error = 'Telegram JSON ' . $telegramId
                . ': не удалось пометить поисковый индекс как устаревший.';
            $errors[] = $error;
            docs_mark_ocr_s3_user_index_error((string) $telegramId, $error);
        }
    }
    $errors = array_slice(array_values(array_unique($errors)), 0, 50);
    return [
        'status' => empty($errors) ? 'completed' : 'failed',
        'ok' => empty($errors),
        'checkedAt' => date('c'),
        'users' => count($expectedByUser),
        'expectedFiles' => array_sum(array_map('count', $expectedByUser)),
        'verifiedFiles' => $verifiedFiles,
        'archiveFiles' => $archiveFiles,
        'archiveFilesRechecked' => $archiveFilesRechecked,
        'error' => empty($errors)
            ? ''
            : sanitize_text_field(implode(' ', array_slice($errors, 0, 3)), 500),
        'errors' => $errors,
    ];
}
function docs_ocr_backfill_summary(array $state): array
{
    $summary = [
        'total' => 0,
        'eligible' => 0,
        'completed' => 0,
        'pending' => 0,
        'processing' => 0,
        'retry' => 0,
        'failed' => 0,
        'skipped' => 0,
        'unsupported' => 0,
        'participants' => 0,
        'delivered' => 0,
        'noRecipients' => 0,
        'remaining' => 0,
        'percent' => 0,
        'filesPassedBeforeFinalAudit' => false,
        'finalAuditPassed' => false,
        'allFilesPassed' => false,
    ];
    foreach (isset($state['items']) && is_array($state['items']) ? $state['items'] : [] as $item) {
        if (!is_array($item)) {
            continue;
        }
        $summary['total']++;
        $status = (string) ($item['status'] ?? 'pending');
        if (array_key_exists($status, $summary)) {
            $summary[$status]++;
        }
        if ($status !== 'unsupported') {
            $summary['eligible']++;
        }
        if (in_array($status, ['pending', 'processing', 'retry'], true)) {
            $summary['remaining']++;
        }
        if ($status === 'completed') {
            $participants = max(0, (int) ($item['participants'] ?? 0));
            $summary['participants'] += $participants;
            $summary['delivered'] += max(0, (int) ($item['delivered'] ?? 0));
            if ($participants === 0) {
                $summary['noRecipients']++;
            }
        }
    }
    if ($summary['eligible'] > 0) {
        $summary['percent'] = max(0, min(100, (int) floor(
            ($summary['completed'] / $summary['eligible']) * 100
        )));
    } elseif ($summary['total'] > 0) {
        $summary['percent'] = 100;
    }
    $summary['filesPassedBeforeFinalAudit'] = trim((string) ($state['runId'] ?? '')) !== ''
        && $summary['eligible'] === $summary['completed']
        && $summary['failed'] === 0
        && $summary['skipped'] === 0
        && $summary['remaining'] === 0;
    $finalAudit = isset($state['finalAudit']) && is_array($state['finalAudit'])
        ? $state['finalAudit']
        : [];
    $summary['finalAuditPassed'] = (string) ($finalAudit['status'] ?? '') === 'completed'
        && !empty($finalAudit['ok']);
    $summary['allFilesPassed'] = $summary['filesPassedBeforeFinalAudit']
        && $summary['finalAuditPassed'];
    return $summary;
}
function docs_find_ocr_backfill_current_item(array $state): ?array
{
    $currentKey = (string) ($state['currentKey'] ?? '');
    if ($currentKey === '') {
        return null;
    }
    foreach (isset($state['items']) && is_array($state['items']) ? $state['items'] : [] as $item) {
        if (is_array($item) && (string) ($item['key'] ?? '') === $currentKey) {
            return $item;
        }
    }
    return null;
}
function docs_prepare_ocr_backfill_response(
    array $state,
    int $page = 1,
    int $pageSize = DOCS_OCR_BACKFILL_ITEMS_PAGE_SIZE,
    string $query = '',
    string $statusFilter = ''
): array {
    $page = max(1, $page);
    $pageSize = max(1, min(DOCS_OCR_BACKFILL_ITEMS_MAX_PAGE_SIZE, $pageSize));
    $query = mb_strtolower(sanitize_text_field($query, 200), 'UTF-8');
    $allowedStatuses = ['pending', 'processing', 'retry', 'completed', 'failed', 'skipped', 'unsupported'];
    $statusFilter = in_array($statusFilter, $allowedStatuses, true) ? $statusFilter : '';
    $filtered = [];
    foreach (isset($state['items']) && is_array($state['items']) ? $state['items'] : [] as $item) {
        if (!is_array($item)) {
            continue;
        }
        if ($statusFilter !== '' && (string) ($item['status'] ?? '') !== $statusFilter) {
            continue;
        }
        if ($query !== '') {
            $haystack = mb_strtolower(implode(' ', [
                (string) ($item['organization'] ?? ''),
                (string) ($item['taskLabel'] ?? ''),
                (string) ($item['originalName'] ?? ''),
                (string) ($item['storedName'] ?? ''),
                (string) ($item['error'] ?? ''),
                implode(' ', isset($item['telegramIds']) && is_array($item['telegramIds']) ? $item['telegramIds'] : []),
            ]), 'UTF-8');
            if (mb_strpos($haystack, $query, 0, 'UTF-8') === false) {
                continue;
            }
        }
        $filtered[] = $item;
    }
    $total = count($filtered);
    $pages = max(1, (int) ceil($total / $pageSize));
    $page = min($page, $pages);
    $items = array_slice($filtered, ($page - 1) * $pageSize, $pageSize);
    return [
        'runId' => sanitize_text_field((string) ($state['runId'] ?? ''), 120),
        'status' => sanitize_text_field((string) ($state['status'] ?? 'idle'), 40),
        'stopRequested' => !empty($state['stopRequested']),
        'createdAt' => sanitize_text_field((string) ($state['createdAt'] ?? ''), 80),
        'startedAt' => sanitize_text_field((string) ($state['startedAt'] ?? ''), 80),
        'completedAt' => sanitize_text_field((string) ($state['completedAt'] ?? ''), 80),
        'updatedAt' => sanitize_text_field((string) ($state['updatedAt'] ?? ''), 80),
        'heartbeatAt' => sanitize_text_field((string) ($state['heartbeatAt'] ?? ''), 80),
        'workerError' => sanitize_text_field((string) ($state['workerError'] ?? ''), 500),
        'finalAudit' => isset($state['finalAudit']) && is_array($state['finalAudit'])
            ? array_replace(docs_default_ocr_backfill_final_audit(), $state['finalAudit'])
            : docs_default_ocr_backfill_final_audit(),
        'workerActive' => (string) ($state['status'] ?? '') === 'running'
            && docs_is_ocr_backfill_worker_active(),
        'scan' => (array) ($state['scan'] ?? []),
        'summary' => docs_ocr_backfill_summary($state),
        'current' => docs_find_ocr_backfill_current_item($state),
        'items' => array_values($items),
        'pagination' => [
            'page' => $page,
            'pageSize' => $pageSize,
            'total' => $total,
            'pages' => $pages,
        ],
    ];
}
function docs_get_next_ocr_backfill_item(array $state): array
{
    $activeJob = docs_load_ocr_active_job_unlocked();
    $activeSource = sanitize_text_field((string) ($activeJob['source'] ?? ''), 80);
    $activeRunId = sanitize_text_field((string) ($activeJob['runId'] ?? ''), 120);
    $stateRunId = sanitize_text_field((string) ($state['runId'] ?? ''), 120);
    $activeItemKey = sanitize_text_field((string) ($activeJob['itemKey'] ?? ''), 160);
    if ($activeSource === 'legacy_backfill'
        && $activeRunId !== ''
        && hash_equals($stateRunId, $activeRunId)
        && $activeItemKey !== ''
    ) {
        foreach (isset($state['items']) && is_array($state['items']) ? $state['items'] : [] as $activeItem) {
            if (!is_array($activeItem)
                || (string) ($activeItem['key'] ?? '') !== $activeItemKey
                || !in_array((string) ($activeItem['status'] ?? ''), ['pending', 'processing', 'retry'], true)
            ) {
                continue;
            }
            $activeNextAttemptAt = strtotime((string) ($activeItem['nextAttemptAt'] ?? '')) ?: 0;
            return $activeNextAttemptAt <= time()
                ? ['item' => $activeItem, 'nextAttemptAt' => 0]
                : ['item' => null, 'nextAttemptAt' => $activeNextAttemptAt];
        }
    }
    $nextAttemptAt = 0;
    foreach (isset($state['items']) && is_array($state['items']) ? $state['items'] : [] as $item) {
        if (!is_array($item)
            || !in_array((string) ($item['status'] ?? ''), ['pending', 'processing', 'retry'], true)
        ) {
            continue;
        }
        $itemNextAttemptAt = strtotime((string) ($item['nextAttemptAt'] ?? '')) ?: 0;
        if ($itemNextAttemptAt <= time()) {
            return ['item' => $item, 'nextAttemptAt' => 0];
        }
        if ($nextAttemptAt === 0 || $itemNextAttemptAt < $nextAttemptAt) {
            $nextAttemptAt = $itemNextAttemptAt;
        }
    }
    return ['item' => null, 'nextAttemptAt' => $nextAttemptAt];
}
function docs_run_ocr_backfill_worker(): array
{
    $workerLock = @fopen(docs_ocr_backfill_worker_lock_path(), 'c+');
    if ($workerLock === false || !@flock($workerLock, LOCK_EX | LOCK_NB)) {
        if (is_resource($workerLock)) {
            fclose($workerLock);
        }
        return ['ok' => true, 'worked' => false, 'reason' => 'worker_already_running'];
    }
    if (function_exists('set_time_limit')) {
        @set_time_limit(0);
    }
    @ini_set('memory_limit', DOCS_OCR_BACKFILL_PROCESS_MEMORY_LIMIT);
    if (function_exists('proc_nice')) {
        @proc_nice(19);
    }
    $shutdownCompleted = false;
    $shutdownReserve = '';
    register_shutdown_function(static function () use (&$shutdownCompleted, &$shutdownReserve): void {
        $shutdownReserve = '';
        if ($shutdownCompleted) {
            return;
        }
        $lastError = error_get_last();
        $message = is_array($lastError) ? (string) ($lastError['message'] ?? '') : '';
        if ($message === '' || preg_match('/allowed memory size|out of memory/i', $message) !== 1) {
            return;
        }
        @file_put_contents(docs_ocr_backfill_memory_stop_path(), date('c') . PHP_EOL, LOCK_EX);
    });
    $shutdownReserve = str_repeat('R', DOCS_OCR_BACKFILL_SHUTDOWN_RESERVE_BYTES);
    $deadline = microtime(true) + DOCS_OCR_BACKFILL_MAX_WORKER_SECONDS;
    $completed = 0;
    $failed = 0;
    $processedItems = 0;
    $restartNeeded = false;
    $workerError = '';
    $workerStopReason = '';
    try {
        while (microtime(true) < $deadline) {
            $resourceGuard = docs_ocr_backfill_resource_guard();
            if (empty($resourceGuard['ok'])) {
                $workerError = docs_format_ocr_backfill_memory_guard_error($resourceGuard);
                $workerStopReason = 'resource_guard_stopped';
                break;
            }
            $state = docs_load_ocr_backfill_state();
            if ((string) ($state['status'] ?? '') !== 'running') {
                break;
            }
            if ((string) ($state['workerError'] ?? '') !== '') {
                docs_mutate_ocr_backfill_state(static function (array &$current): array {
                    $current['workerError'] = '';
                    $current['heartbeatAt'] = date('c');
                    return ['workerRecovered' => true];
                });
            }
            if (!empty($state['stopRequested'])) {
                docs_mutate_ocr_backfill_state(static function (array &$current): array {
                    $current['status'] = 'paused';
                    $current['stopRequested'] = false;
                    $current['currentKey'] = '';
                    $current['heartbeatAt'] = date('c');
                    return ['paused' => true];
                });
                break;
            }
            $selected = docs_get_next_ocr_backfill_item($state);
            $item = $selected['item'] ?? null;
            if (!is_array($item)) {
                $nextAttemptAt = (int) ($selected['nextAttemptAt'] ?? 0);
                if ($nextAttemptAt > time()) {
                    sleep(max(1, min(30, $nextAttemptAt - time())));
                    continue;
                }
                $summaryBeforeAudit = docs_ocr_backfill_summary($state);
                $canRunFinalAudit = !empty($summaryBeforeAudit['filesPassedBeforeFinalAudit']);
                $finalAudit = $canRunFinalAudit
                    ? docs_verify_ocr_backfill_final_manifest($state)
                    : array_replace(docs_default_ocr_backfill_final_audit(), [
                        'status' => 'not_run',
                        'checkedAt' => date('c'),
                        'error' => 'Итоговая проверка Telegram JSON не запущена: в очереди есть ошибки файлов.',
                    ]);
                $stateRunId = sanitize_text_field((string) ($state['runId'] ?? ''), 120);
                $finished = docs_mutate_ocr_backfill_state(static function (array &$current) use (
                    $finalAudit,
                    $stateRunId
                ): array {
                    $currentSummary = docs_ocr_backfill_summary($current);
                    if ((string) ($current['status'] ?? '') !== 'running'
                        || sanitize_text_field((string) ($current['runId'] ?? ''), 120) !== $stateRunId
                        || (int) ($currentSummary['remaining'] ?? 0) > 0
                    ) {
                        return ['finished' => false];
                    }
                    $filesPassed = !empty($currentSummary['filesPassedBeforeFinalAudit']);
                    $current['finalAudit'] = $filesPassed
                        ? $finalAudit
                        : array_replace(docs_default_ocr_backfill_final_audit(), [
                            'status' => 'not_run',
                            'checkedAt' => date('c'),
                            'error' => 'Итоговая проверка Telegram JSON не запущена: в очереди есть ошибки файлов.',
                        ]);
                    $auditPassed = $filesPassed
                        && (string) ($current['finalAudit']['status'] ?? '') === 'completed'
                        && !empty($current['finalAudit']['ok']);
                    $current['status'] = $auditPassed ? 'completed' : 'attention';
                    $current['completedAt'] = date('c');
                    $current['currentKey'] = '';
                    $current['workerError'] = $filesPassed && !$auditPassed
                        ? sanitize_text_field(
                            (string) ($current['finalAudit']['error'] ?? 'Конечный Telegram JSON не прошёл проверку.'),
                            500
                        )
                        : '';
                    $current['heartbeatAt'] = date('c');
                    return ['finished' => true];
                });
                if (!empty($finished['finished'])) {
                    break;
                }
                continue;
            }
            $key = (string) ($item['key'] ?? '');
            $previousAttempts = max(0, (int) ($item['attempts'] ?? 0));
            $attempts = $previousAttempts;
            if ((string) ($item['status'] ?? '') !== 'processing' || $attempts === 0) {
                $attempts++;
            }
            $runId = sanitize_text_field((string) ($state['runId'] ?? ''), 120);
            $retryGeneration = max(0, (int) ($item['retryGeneration'] ?? 0));
            $idempotencyKey = sanitize_text_field((string) ($item['idempotencyKey'] ?? ''), 240);
            if ($idempotencyKey === '') {
                $idempotencyKey = 'documents-ocr-backfill-' . substr(hash(
                    'sha256',
                    $runId . "\0" . $key . "\0" . (string) $retryGeneration . "\0" . (string) $attempts
                ), 0, 48);
            }
            $workingItem = array_replace($item, [
                'runId' => $runId,
                'status' => 'processing',
                'stage' => 'waiting_slot',
                'attempts' => $attempts,
                'idempotencyKey' => $idempotencyKey,
                'startedAt' => (string) ($item['startedAt'] ?? '') !== ''
                    ? (string) $item['startedAt']
                    : date('c'),
                'nextAttemptAt' => '',
                'error' => '',
            ]);
            if (!docs_update_ocr_backfill_item($key, $workingItem)) {
                $workerError = 'Не удалось сохранить состояние файла до отправки в OCR.';
                $workerStopReason = 'state_persistence_failed';
                break;
            }
            unset($state, $selected, $item);
            $outcome = docs_process_ocr_queue_item(
                sanitize_folder_name((string) ($workingItem['folder'] ?? '')),
                $workingItem,
                $deadline,
                static function (array $changes) use ($key): void {
                    docs_update_ocr_backfill_item($key, $changes);
                },
                static function (): array {
                    return docs_ocr_backfill_resource_guard();
                }
            );
            if (!empty($outcome['abortWorker'])) {
                $workerError = sanitize_text_field(
                    (string) ($outcome['error'] ?? 'OCR старых файлов остановлен защитой ресурсов.'),
                    500
                );
                $workerStopReason = 'resource_guard_stopped';
                $outcomeJobId = sanitize_text_field(
                    (string) ($outcome['jobId'] ?? ($workingItem['jobId'] ?? '')),
                    160
                );
                docs_update_ocr_backfill_item($key, [
                    'status' => 'retry',
                    'stage' => 'resource_guard',
                    'jobId' => $outcomeJobId,
                    'jobStatus' => (string) ($workingItem['jobStatus'] ?? ''),
                    'idempotencyKey' => (string) ($workingItem['idempotencyKey'] ?? ''),
                    'retryGeneration' => max(0, (int) ($workingItem['retryGeneration'] ?? 0)),
                    'nextAttemptAt' => '',
                    'error' => $workerError,
                ]);
                break;
            }
            if (!empty($outcome['busy'])) {
                $busyError = sanitize_text_field(
                    (string) ($outcome['error'] ?? 'Ожидается завершение другого OCR-файла.'),
                    500
                );
                $gateAttempts = !empty($outcome['remoteUnresolved'])
                    ? max(0, (int) ($workingItem['gateAttempts'] ?? 0)) + 1
                    : 0;
                if (!empty($outcome['remoteUnresolved'])
                    && $gateAttempts >= DOCS_LIVE_OCR_MAX_ATTEMPTS
                ) {
                    $workerError = 'Не удалось подтвердить состояние предыдущего OCR job после '
                        . $gateAttempts
                        . ' проверок. Проход поставлен на паузу без сброса задания. '
                        . $busyError;
                    $workerStopReason = 'active_job_unresolved';
                    docs_update_ocr_backfill_item($key, [
                        'status' => 'retry',
                        'stage' => 'waiting_slot',
                        'attempts' => $previousAttempts,
                        'gateAttempts' => $gateAttempts,
                        'nextAttemptAt' => '',
                        'error' => sanitize_text_field($workerError, 500),
                    ]);
                    break;
                }
                $busyDelay = !empty($outcome['remoteUnresolved'])
                    ? min(300, DOCS_LIVE_OCR_RETRY_DELAY_SECONDS * max(1, $gateAttempts))
                    : DOCS_LIVE_OCR_POLL_INTERVAL_SECONDS;
                $busySaved = docs_update_ocr_backfill_item($key, [
                    'status' => !empty($outcome['remoteUnresolved']) ? 'retry' : 'pending',
                    'stage' => 'waiting_slot',
                    'attempts' => $previousAttempts,
                    'gateAttempts' => $gateAttempts,
                    'nextAttemptAt' => date('c', time() + $busyDelay),
                    'error' => $busyError,
                ]);
                if (!$busySaved) {
                    $workerError = 'Не удалось сохранить ожидание OCR job. Проход остановлен без запуска нового файла.';
                    $workerStopReason = 'state_persistence_failed';
                    break;
                }
                sleep($busyDelay);
                continue;
            }
            if (!empty($outcome['done'])) {
                $finalStatus = (string) ($outcome['status'] ?? 'completed');
                $completedSaved = docs_update_ocr_backfill_item($key, [
                    'status' => $finalStatus,
                    'stage' => $finalStatus,
                    'progress' => $finalStatus === 'completed' ? 100 : (int) ($workingItem['progress'] ?? 0),
                    'archiveKey' => (string) ($outcome['archiveKey'] ?? ''),
                    'ocrTextLength' => (int) ($outcome['ocrTextLength'] ?? 0),
                    'ocrTextSha256' => sanitize_text_field(
                        (string) ($outcome['ocrTextSha256'] ?? ''),
                        80
                    ),
                    'participants' => (int) ($outcome['participants'] ?? ($workingItem['participants'] ?? 0)),
                    'delivered' => (int) ($outcome['delivered'] ?? 0),
                    'allPresent' => !empty($outcome['allPresent']),
                    'deliveries' => (array) ($outcome['deliveries'] ?? []),
                    'finishedAt' => date('c'),
                    'error' => sanitize_text_field((string) ($outcome['error'] ?? ''), 500),
                ]);
                if (!$completedSaved) {
                    $workerError = 'Файл обработан, но не удалось сохранить его итоговое состояние. Проход остановлен.';
                    $workerStopReason = 'state_persistence_failed';
                    break;
                }
                docs_mutate_ocr_backfill_state(static function (array &$current): array {
                    $current['currentKey'] = '';
                    $current['heartbeatAt'] = date('c');
                    return ['updated' => true];
                });
                if ($finalStatus === 'completed') {
                    $completed++;
                } else {
                    $failed++;
                }
                $processedItems++;
                if ($processedItems >= DOCS_OCR_BACKFILL_MAX_FILES_PER_PROCESS) {
                    $restartNeeded = true;
                    break;
                }
                continue;
            }
            $error = sanitize_text_field(
                (string) ($outcome['error'] ?? 'Неизвестная ошибка OCR.'),
                500
            );
            $remoteUnresolved = !empty($outcome['remoteUnresolved']);
            $staleJobResets = max(0, (int) ($workingItem['staleJobResets'] ?? 0));
            if (!empty($outcome['staleJob']) && $staleJobResets < 1) {
                $staleSaved = docs_update_ocr_backfill_item($key, [
                    'status' => 'retry',
                    'stage' => 'ocr',
                    'progress' => 0,
                    'currentPage' => 0,
                    'totalPages' => 0,
                    'jobId' => '',
                    'jobStatus' => 'expired',
                    'attempts' => 0,
                    'staleJobResets' => $staleJobResets + 1,
                    'progressChangedAt' => '',
                    'retryGeneration' => max(0, (int) ($workingItem['retryGeneration'] ?? 0)) + 1,
                    'idempotencyKey' => '',
                    'nextAttemptAt' => '',
                    'error' => 'Предыдущий OCR job не найден. Файл будет один раз повторно отправлен с новым ключом.',
                ]);
                if (!$staleSaved) {
                    $workerError = 'Не удалось сохранить безопасный повтор после потери OCR job.';
                    $workerStopReason = 'state_persistence_failed';
                    break;
                }
                docs_mutate_ocr_backfill_state(static function (array &$current): array {
                    $current['currentKey'] = '';
                    $current['heartbeatAt'] = date('c');
                    return ['staleJobReset' => true];
                });
                $restartNeeded = true;
                break;
            }
            $emptyResultResets = max(0, (int) ($workingItem['emptyResultResets'] ?? 0));
            if (!empty($outcome['emptyResult']) && $emptyResultResets < 1) {
                $emptyResultSaved = docs_update_ocr_backfill_item($key, [
                    'status' => 'retry',
                    'stage' => 'ocr',
                    'progress' => 0,
                    'currentPage' => 0,
                    'totalPages' => max(0, (int) ($outcome['pagesCount'] ?? 0)),
                    'jobId' => '',
                    'jobStatus' => 'empty',
                    'attempts' => 0,
                    'emptyResultResets' => $emptyResultResets + 1,
                    'progressChangedAt' => '',
                    'retryGeneration' => max(0, (int) ($workingItem['retryGeneration'] ?? 0)) + 1,
                    'idempotencyKey' => '',
                    'nextAttemptAt' => '',
                    'error' => 'Первый OCR job завершён без текста. Файл будет один раз повторно отправлен с новым ключом.',
                ]);
                if (!$emptyResultSaved) {
                    $workerError = 'Не удалось сохранить безопасный повтор после пустого OCR-результа.';
                    $workerStopReason = 'state_persistence_failed';
                    break;
                }
                docs_mutate_ocr_backfill_state(static function (array &$current): array {
                    $current['currentKey'] = '';
                    $current['heartbeatAt'] = date('c');
                    return ['emptyResultReset' => true];
                });
                $restartNeeded = true;
                break;
            }
            if ($remoteUnresolved
                && (!empty($outcome['stalled']) || $attempts >= DOCS_LIVE_OCR_MAX_ATTEMPTS)
            ) {
                $workerError = !empty($outcome['stalled'])
                    ? $error . ' Проход поставлен на паузу; после проверки OCR-сервера нажмите «Продолжить».'
                    : 'Приватный OCR не подтвердил состояние задания после '
                        . $attempts
                        . ' попыток. Проход остановлен, текущий OCR job сохранён; после восстановления OCR-сервера нажмите «Продолжить». '
                        . $error;
                $workerStopReason = 'remote_job_unresolved';
                docs_update_ocr_backfill_item($key, [
                    'status' => 'retry',
                    'stage' => sanitize_text_field((string) ($outcome['stage'] ?? 'ocr'), 80),
                    'nextAttemptAt' => '',
                    'deliveries' => (array) ($outcome['deliveries'] ?? ($workingItem['deliveries'] ?? [])),
                    'error' => sanitize_text_field($workerError, 500),
                ]);
                break;
            }
            $terminal = !empty($outcome['terminal'])
                || !empty($outcome['staleJob'])
                || !empty($outcome['emptyResult'])
                || (!$remoteUnresolved && $attempts >= DOCS_LIVE_OCR_MAX_ATTEMPTS);
            $delay = min(300, DOCS_LIVE_OCR_RETRY_DELAY_SECONDS * max(1, $attempts));
            $retrySaved = docs_update_ocr_backfill_item($key, [
                'status' => $terminal ? 'failed' : 'retry',
                'stage' => sanitize_text_field((string) ($outcome['stage'] ?? 'ocr'), 80),
                'nextAttemptAt' => $terminal ? '' : date('c', time() + $delay),
                'deliveries' => (array) ($outcome['deliveries'] ?? ($workingItem['deliveries'] ?? [])),
                'finishedAt' => $terminal ? date('c') : '',
                'error' => $error,
            ]);
            if (!$retrySaved) {
                $workerError = 'Не удалось сохранить состояние ошибки OCR. Проход остановлен.';
                $workerStopReason = 'state_persistence_failed';
                break;
            }
            docs_mutate_ocr_backfill_state(static function (array &$current): array {
                $current['currentKey'] = '';
                $current['heartbeatAt'] = date('c');
                return ['updated' => true];
            });
            if ($terminal) {
                $failed++;
            }
            $processedItems++;
            if ($processedItems >= DOCS_OCR_BACKFILL_MAX_FILES_PER_PROCESS) {
                $restartNeeded = true;
                break;
            }
        }
        if (microtime(true) >= $deadline) {
            $state = docs_load_ocr_backfill_state();
            $restartNeeded = (string) ($state['status'] ?? '') === 'running';
        }
    } catch (Throwable $error) {
        $workerError = 'OCR worker остановлен внутренней ошибкой: '
            . sanitize_text_field($error->getMessage(), 420);
        $workerStopReason = 'worker_exception';
    } finally {
        @flock($workerLock, LOCK_UN);
        fclose($workerLock);
    }
    if ($workerError !== '') {
        docs_mutate_ocr_backfill_state(static function (array &$current) use ($workerError): array {
            if ((string) ($current['status'] ?? '') === 'running') {
                $current['status'] = 'paused';
            }
            $current['stopRequested'] = false;
            $current['currentKey'] = '';
            $current['workerError'] = $workerError;
            $current['heartbeatAt'] = date('c');
            return ['workerFailed' => true];
        });
    }
    if ($restartNeeded && $workerError === '') {
        $restarted = docs_start_ocr_backfill_worker();
        if (empty($restarted['ok'])) {
            $workerError = sanitize_text_field(
                (string) ($restarted['error'] ?? 'Не удалось запустить OCR worker для следующего файла.'),
                500
            );
            $workerStopReason = 'worker_restart_failed';
            docs_mutate_ocr_backfill_state(static function (array &$current) use ($workerError): array {
                if ((string) ($current['status'] ?? '') === 'running') {
                    $current['status'] = 'paused';
                }
                $current['stopRequested'] = false;
                $current['currentKey'] = '';
                $current['workerError'] = $workerError;
                $current['heartbeatAt'] = date('c');
                return ['workerRestartFailed' => true];
            });
        }
    }
    $shutdownCompleted = true;
    return [
        'ok' => $workerError === '',
        'worked' => ($completed + $failed) > 0,
        'completed' => $completed,
        'failed' => $failed,
        'reason' => $workerError !== ''
            ? ($workerStopReason !== '' ? $workerStopReason : 'worker_failed')
            : ($restartNeeded ? 'worker_restarted' : 'worker_finished'),
        'error' => $workerError,
    ];
}
function docs_start_ocr_backfill_worker(): array
{
    if (is_file(docs_ocr_backfill_memory_stop_path())) {
        return [
            'ok' => false,
            'error' => 'OCR старых файлов аварийно остановлен лимитом памяти. Сайт оставлен в приоритете; после освобождения RAM продолжите проход вручную.',
        ];
    }
    $phpBinary = docs_live_ocr_php_binary();
    if ($phpBinary === '' || !function_exists('proc_open')) {
        return ['ok' => false, 'error' => 'Фоновый PHP worker недоступен.'];
    }
    $logPath = docs_ocr_runtime_path(DOCS_OCR_BACKFILL_WORKER_LOG_FILENAME);
    $command = 'nohup '
        . escapeshellarg($phpBinary) . ' '
        . escapeshellarg(__FILE__) . ' '
        . escapeshellarg(DOCS_OCR_BACKFILL_WORKER_COMMAND) . ' >> '
        . escapeshellarg($logPath) . ' 2>&1 < /dev/null &';
    $started = docs_run_process_with_timeout(['/bin/sh', '-c', $command], 5);
    return [
        'ok' => !empty($started['ok']),
        'error' => !empty($started['ok'])
            ? ''
            : sanitize_text_field((string) ($started['error'] ?? 'Не удалось запустить OCR backfill worker.'), 500),
    ];
}
function docs_start_new_ocr_backfill(): array
{
    $handle = @fopen(docs_ocr_backfill_state_lock_path(), 'c+');
    if ($handle === false || !@flock($handle, LOCK_EX)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return ['ok' => false, 'error' => 'Не удалось заблокировать OCR backfill.'];
    }
    try {
        $current = docs_load_ocr_backfill_state_unlocked();
        if (in_array((string) ($current['status'] ?? ''), ['running', 'paused'], true)
            && docs_ocr_backfill_summary($current)['remaining'] > 0
        ) {
            return ['ok' => true, 'alreadyExists' => true, 'state' => $current];
        }
        $state = docs_create_ocr_backfill_state();
        if (!docs_save_ocr_backfill_state_unlocked($state)) {
            return ['ok' => false, 'error' => 'Не удалось сохранить новую очередь OCR.'];
        }
        return ['ok' => true, 'alreadyExists' => false, 'state' => $state];
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_control_ocr_backfill(string $operation): array
{
    if (in_array($operation, ['start', 'resume'], true)) {
        $resourceGuard = docs_ocr_backfill_resource_guard();
        if (empty($resourceGuard['ok'])) {
            return [
                'ok' => false,
                'error' => docs_format_ocr_backfill_memory_guard_error($resourceGuard),
                'state' => docs_load_ocr_backfill_state(),
            ];
        }
        $memoryStopPath = docs_ocr_backfill_memory_stop_path();
        if (is_file($memoryStopPath)) {
            @unlink($memoryStopPath);
        }
    }
    if ($operation === 'start') {
        $created = docs_start_new_ocr_backfill();
        if (empty($created['ok'])) {
            return $created;
        }
        $state = (array) ($created['state'] ?? docs_load_ocr_backfill_state());
        if ((string) ($state['status'] ?? '') === 'paused') {
            docs_mutate_ocr_backfill_state(static function (array &$current): array {
                $current['status'] = 'running';
                $current['stopRequested'] = false;
                $current['completedAt'] = '';
                $current['workerError'] = '';
                $current['heartbeatAt'] = date('c');
                return ['resumed' => true];
            });
        }
    } elseif ($operation === 'resume') {
        $changed = docs_mutate_ocr_backfill_state(static function (array &$state): array {
            if (docs_ocr_backfill_summary($state)['remaining'] <= 0) {
                return ['resumed' => false];
            }
            $state['status'] = 'running';
            $state['stopRequested'] = false;
            $state['completedAt'] = '';
            $state['workerError'] = '';
            $state['heartbeatAt'] = date('c');
            return ['resumed' => true];
        });
        if (empty($changed['ok'])) {
            return $changed;
        }
    } elseif ($operation === 'stop_after_current') {
        return docs_mutate_ocr_backfill_state(static function (array &$state): array {
            if ((string) ($state['status'] ?? '') === 'running') {
                $state['stopRequested'] = true;
            }
            return ['stopRequested' => !empty($state['stopRequested'])];
        });
    } elseif ($operation === 'retry_failed') {
        $changed = docs_mutate_ocr_backfill_state(static function (array &$state): array {
            $retried = 0;
            foreach ($state['items'] as &$item) {
                if (!is_array($item)
                    || !in_array((string) ($item['status'] ?? ''), ['failed', 'skipped'], true)
                    || (array_key_exists('retryable', $item) && empty($item['retryable']))
                ) {
                    continue;
                }
                $retryGeneration = max(0, (int) ($item['retryGeneration'] ?? 0)) + 1;
                $item = array_replace($item, [
                    'status' => 'pending',
                    'stage' => 'waiting',
                    'progress' => 0,
                    'currentPage' => 0,
                    'totalPages' => 0,
                    'jobId' => '',
                    'jobStatus' => '',
                    'attempts' => 0,
                    'gateAttempts' => 0,
                    'staleJobResets' => 0,
                    'emptyResultResets' => 0,
                    'progressChangedAt' => '',
                    'retryGeneration' => $retryGeneration,
                    'idempotencyKey' => '',
                    'nextAttemptAt' => '',
                    'delivered' => 0,
                    'allPresent' => false,
                    'deliveries' => [],
                    'error' => '',
                    'finishedAt' => '',
                    'updatedAt' => date('c'),
                ]);
                $retried++;
            }
            unset($item);
            $retryFinalAudit = $retried === 0
                && (string) ($state['status'] ?? '') === 'attention'
                && (string) ($state['finalAudit']['status'] ?? '') === 'failed';
            if ($retried > 0 || $retryFinalAudit) {
                $state['status'] = 'running';
                $state['stopRequested'] = false;
                $state['completedAt'] = '';
                $state['workerError'] = '';
                $state['finalAudit'] = docs_default_ocr_backfill_final_audit();
                $state['heartbeatAt'] = date('c');
            }
            return ['retried' => $retried, 'finalAuditRetried' => $retryFinalAudit];
        });
        if (empty($changed['ok'])) {
            return $changed;
        }
    } else {
        return ['ok' => false, 'error' => 'Неизвестная операция OCR backfill.'];
    }
    $state = docs_load_ocr_backfill_state();
    if ((string) ($state['status'] ?? '') === 'running') {
        $started = docs_start_ocr_backfill_worker();
        if (empty($started['ok'])) {
            $workerError = sanitize_text_field(
                (string) ($started['error'] ?? 'Не удалось запустить OCR backfill worker.'),
                500
            );
            docs_mutate_ocr_backfill_state(static function (array &$current) use ($workerError): array {
                if ((string) ($current['status'] ?? '') === 'running') {
                    $current['status'] = 'paused';
                }
                $current['stopRequested'] = false;
                $current['workerError'] = $workerError;
                $current['heartbeatAt'] = date('c');
                return ['workerStartFailed' => true];
            });
            return [
                'ok' => false,
                'error' => $workerError,
                'state' => docs_load_ocr_backfill_state(),
            ];
        }
    }
    return ['ok' => true, 'state' => docs_load_ocr_backfill_state()];
}
function docs_sync_uploaded_files_to_cold_storage(string $folder, array $uploads): void
{
    if (empty($uploads)) {
        return;
    }
    $resultsByStoredName = [];
    foreach ($uploads as $upload) {
        if (!is_array($upload) || !isset($upload['file']) || !is_array($upload['file'])) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($upload['file']['storedName'] ?? ''), 255);
        $localPath = (string) ($upload['localPath'] ?? '');
        $relativePath = docs_normalize_cold_storage_relative_path((string) ($upload['relativePath'] ?? ''));
        if ($storedName === '' || $localPath === '' || $relativePath === '') {
            continue;
        }
        $resultsByStoredName[$storedName] = [
            'relativePath' => $relativePath,
            'result' => docs_upload_file_to_cold_storage($localPath, $folder, $relativePath),
        ];
    }
    if (empty($resultsByStoredName)) {
        return;
    }
    [$handle, $records] = docs_lock_registry($folder);
    if ($handle === null) {
        docs_write_response_log('Не удалось обновить S3-статус новых вложений: реестр заблокирован', [
            'folder' => $folder,
            'filesCount' => count($resultsByStoredName),
        ]);
        return;
    }
    $changed = false;
    try {
        foreach ($records as &$record) {
            if (!is_array($record) || !isset($record['files']) || !is_array($record['files'])) {
                continue;
            }
            foreach ($record['files'] as &$file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                if ($storedName === '' || !isset($resultsByStoredName[$storedName])) {
                    continue;
                }
                $entry = $resultsByStoredName[$storedName];
                $result = is_array($entry['result'] ?? null) ? $entry['result'] : [];
                $file = docs_apply_cold_storage_state(
                    $file,
                    $folder,
                    (string) ($entry['relativePath'] ?? ''),
                    !empty($result['ok']) ? 'synced' : 'local_fallback',
                    $result
                );
                $changed = true;
            }
            unset($file);
        }
        unset($record);
        if ($changed && !docs_save_registry_locked($handle, $records)) {
            docs_write_response_log('Не удалось сохранить S3-статус новых вложений', [
                'folder' => $folder,
                'filesCount' => count($resultsByStoredName),
            ]);
        }
    } finally {
        docs_unlock_registry($handle);
    }
}
function docs_apply_cold_storage_state(
    array $file,
    string $folder,
    string $relativePath,
    string $status,
    array $upload = []
): array
{
    if (!in_array($status, ['pending', 'synced', 'local_fallback'], true)) {
        $status = 'local_fallback';
    }
    $key = sanitize_text_field((string) ($upload['key'] ?? ''), 1000);
    if ($key === '') {
        $key = docs_build_cold_storage_key($folder, $relativePath);
    }
    $file['storageProvider'] = $status === 'synced' ? DOCS_COLD_STORAGE_PROVIDER : 'local';
    $file['coldStorage'] = [
        'provider' => DOCS_COLD_STORAGE_PROVIDER,
        'remote' => docs_rclone_remote(),
        'key' => $key,
        'status' => $status,
        'localFallback' => true,
        'updatedAt' => date('c'),
    ];
    if ($status === 'synced') {
        unset($file['storageWarning']);
        return $file;
    }
    if ($status === 'pending') {
        $error = sanitize_text_field((string) ($upload['error'] ?? ''), 500);
        if ($error !== '') {
            $file['coldStorage']['error'] = $error;
        }
        docs_mark_cold_storage_queue_pending($folder);
        $file['storageWarning'] = 'S3-копия создаётся в фоне.';
        return $file;
    }
    $error = sanitize_text_field((string) ($upload['error'] ?? 'S3-копия не создана.'), 500);
    if ($error !== '') {
        $file['coldStorage']['error'] = $error;
    }
    $file['storageWarning'] = 'S3 недоступен, файл сохранён локально.';
    return $file;
}
function docs_prepare_cold_storage_file_payload(array $file): array
{
    $payload = [];
    $storageProvider = sanitize_text_field((string) ($file['storageProvider'] ?? ''), 80);
    if ($storageProvider !== '') {
        $payload['storageProvider'] = $storageProvider;
    }
    if (isset($file['coldStorage']) && is_array($file['coldStorage'])) {
        $coldStorage = array_filter([
            'provider' => sanitize_text_field((string) ($file['coldStorage']['provider'] ?? DOCS_COLD_STORAGE_PROVIDER), 80),
            'remote' => sanitize_text_field((string) ($file['coldStorage']['remote'] ?? docs_rclone_remote()), 160),
            'key' => sanitize_text_field((string) ($file['coldStorage']['key'] ?? ''), 1000),
            'status' => sanitize_text_field((string) ($file['coldStorage']['status'] ?? ''), 80),
            'updatedAt' => docs_normalize_datetime_iso(isset($file['coldStorage']['updatedAt']) ? (string) $file['coldStorage']['updatedAt'] : null) ?? '',
            'error' => sanitize_text_field((string) ($file['coldStorage']['error'] ?? ''), 500),
        ], static function ($item) {
            return $item !== '' && $item !== 0;
        });
        if (array_key_exists('localFallback', $file['coldStorage'])) {
            $coldStorage['localFallback'] = !empty($file['coldStorage']['localFallback']);
        }
        if (!empty($coldStorage['key'])) {
            $payload['coldStorage'] = $coldStorage;
        }
    }
    $storageWarning = sanitize_text_field((string) ($file['storageWarning'] ?? ''), 500);
    if ($storageWarning !== '') {
        $payload['storageWarning'] = $storageWarning;
    }
    return $payload;
}
function docs_download_cold_storage_to_temp(array $file, ?float $deadline = null): string
{
    $key = docs_extract_cold_storage_key($file);
    if ($key === '') {
        return '';
    }
    $tempPath = tempnam(sys_get_temp_dir(), 'docs_s3_');
    if (!is_string($tempPath) || $tempPath === '') {
        return '';
    }
    $timeoutSeconds = 60;
    if ($deadline !== null) {
        $timeoutSeconds = min($timeoutSeconds, (int) floor($deadline - microtime(true)));
        if ($timeoutSeconds < 2) {
            @unlink($tempPath);
            return '';
        }
    }
    $result = docs_run_rclone_command(['copyto', docs_cold_storage_remote_path($key), $tempPath], $timeoutSeconds);
    clearstatcache(true, $tempPath);
    if (empty($result['ok']) || !is_file($tempPath) || (int) @filesize($tempPath) < 1) {
        @unlink($tempPath);
        return '';
    }
    register_shutdown_function(static function () use ($tempPath): void {
        if (is_file($tempPath)) {
            @unlink($tempPath);
        }
    });
    return $tempPath;
}
function docs_delete_cold_storage_file(array $file): void
{
    $key = docs_extract_cold_storage_key($file);
    if ($key === '') {
        return;
    }
    docs_run_rclone_command(['deletefile', docs_cold_storage_remote_path($key)], 25);
}
function docs_resolve_file_path_with_cold_storage(
    string $folder,
    array $file,
    array $pathCandidates,
    ?float $deadline = null
): string
{
    foreach ($pathCandidates as $pathCandidate) {
        if (is_string($pathCandidate) && is_file($pathCandidate) && is_readable($pathCandidate)) {
            return $pathCandidate;
        }
    }
    return docs_download_cold_storage_to_temp($file, $deadline);
}
function docs_extract_public_relative_path(string $rawPath, string $folder): string
{
    $path = parse_url($rawPath, PHP_URL_PATH);
    if (!is_string($path) || $path === '') {
        $path = $rawPath;
    }
    $path = rawurldecode(str_replace('\\', '/', ltrim($path, '/')));
    $marker = 'documents/' . $folder . '/';
    if (strpos($path, $marker) === 0) {
        return docs_normalize_cold_storage_relative_path(substr($path, strlen($marker)));
    }
    return '';
}
function docs_file_public_relative_candidates(string $folder, array $file, string $fallbackRelative = ''): array
{
    $candidates = [];
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName !== '') {
        $candidates[] = $storedName;
    }
    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $relative = docs_extract_public_relative_path($url, $folder);
        if ($relative !== '') {
            $candidates[] = $relative;
        }
    }
    if ($fallbackRelative !== '') {
        $candidates[] = docs_normalize_cold_storage_relative_path($fallbackRelative);
    }
    return array_values(array_unique(array_filter($candidates, static function ($candidate): bool {
        return is_string($candidate) && $candidate !== '';
    })));
}
function docs_file_matches_public_relative(string $folder, array $file, string $relativePath, string $fallbackRelative = ''): bool
{
    $relativePath = docs_normalize_cold_storage_relative_path($relativePath);
    if ($relativePath === '') {
        return false;
    }
    foreach (docs_file_public_relative_candidates($folder, $file, $fallbackRelative) as $candidate) {
        if ($candidate === $relativePath) {
            return true;
        }
    }
    return false;
}
function docs_find_cold_storage_file_by_public_path(string $rawPath): ?array
{
    $path = parse_url($rawPath, PHP_URL_PATH);
    if (!is_string($path) || $path === '') {
        $path = $rawPath;
    }
    $path = rawurldecode(str_replace('\\', '/', ltrim($path, '/')));
    if (stripos($path, 'documents/') !== 0) {
        return null;
    }
    $segments = preg_split('#/+#', substr($path, strlen('documents/')), -1, PREG_SPLIT_NO_EMPTY);
    if (!is_array($segments) || count($segments) < 2) {
        return null;
    }
    $folder = sanitize_folder_name((string) $segments[0]);
    $relativePath = docs_normalize_cold_storage_relative_path(implode('/', array_slice($segments, 1)));
    if ($folder === '' || $relativePath === '') {
        return null;
    }
    foreach (load_registry($folder) as $record) {
        if (!is_array($record)) {
            continue;
        }
        foreach (($record['files'] ?? []) as $file) {
            if (is_array($file) && docs_file_matches_public_relative($folder, $file, $relativePath)) {
                return [
                    'folder' => $folder,
                    'file' => $file,
                    'paths' => docs_get_document_file_path_candidates($folder, $file),
                ];
            }
        }
        $documentId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
        foreach (($record['responses'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
            $fallback = $documentId !== '' && $storedName !== ''
                ? 'Ответы/' . $documentId . '/' . $storedName
                : '';
            if (docs_file_matches_public_relative($folder, $file, $relativePath, $fallback)) {
                $paths = [];
                if ($fallback !== '') {
                    $paths[] = ensure_organization_directory($folder) . '/' . $fallback;
                }
                return [
                    'folder' => $folder,
                    'file' => $file,
                    'paths' => $paths,
                ];
            }
        }
    }
    foreach (docs_load_outgoing_registry($folder) as $record) {
        if (!is_array($record)) {
            continue;
        }
        foreach (($record['files'] ?? []) as $file) {
            if (is_array($file) && docs_file_matches_public_relative($folder, $file, $relativePath)) {
                return [
                    'folder' => $folder,
                    'file' => $file,
                    'paths' => docs_get_outgoing_file_path_candidates($folder, $file),
                ];
            }
        }
    }
    foreach (['orders', 'directives', 'disciplinary'] as $journalType) {
        $meta = docs_get_orders_journal_meta($journalType);
        foreach (docs_load_orders_registry($folder, $journalType) as $record) {
            if (!is_array($record)) {
                continue;
            }
            foreach (($record['files'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                $fallback = $storedName !== '' ? $meta['directory'] . '/' . $storedName : '';
                if (docs_file_matches_public_relative($folder, $file, $relativePath, $fallback)) {
                    return [
                        'folder' => $folder,
                        'file' => $file,
                        'paths' => docs_get_order_file_path_candidates($folder, $file, $journalType),
                    ];
                }
            }
        }
    }
    return null;
}
function docs_collect_storage_file_state(string $folder, array $file, array $pathCandidates): array
{
    $localExists = false;
    $localBytes = 0;
    foreach ($pathCandidates as $pathCandidate) {
        if (is_string($pathCandidate) && is_file($pathCandidate)) {
            $localExists = true;
            $localBytes = max($localBytes, (int) (@filesize($pathCandidate) ?: 0));
        }
    }
    $cold = isset($file['coldStorage']) && is_array($file['coldStorage']) ? $file['coldStorage'] : [];
    $coldKey = docs_extract_cold_storage_key($file);
    $coldStatus = sanitize_text_field((string) ($cold['status'] ?? ''), 60);
    $coldSynced = $coldKey !== '' && $coldStatus === 'synced';
    $coldPending = $coldKey !== '' && $coldStatus === 'pending';
    $size = (int) ($file['size'] ?? 0);
    return [
        'localExists' => $localExists,
        'localBytes' => $localBytes,
        'bytes' => $size > 0 ? $size : $localBytes,
        'coldKey' => $coldKey,
        'coldSynced' => $coldSynced,
        'coldPending' => $coldPending,
        'storageProvider' => sanitize_text_field((string) ($file['storageProvider'] ?? ''), 80),
    ];
}
function docs_run_cold_storage_self_test(string $folder): array
{
    $folder = sanitize_folder_name($folder);
    $tempPath = tempnam(sys_get_temp_dir(), 'docs_s3_test_');
    if (!is_string($tempPath) || $tempPath === '') {
        return [
            'ok' => false,
            'message' => 'Не удалось создать временный файл для теста.',
        ];
    }
    $body = 'documents-api rclone test ' . date('c') . "\n";
    @file_put_contents($tempPath, $body);
    try {
        $suffix = bin2hex(random_bytes(4));
    } catch (Throwable $error) {
        $suffix = str_replace('.', '', uniqid('', true));
    }
    $relativePath = '.s3-test/test-' . date('Ymd-His') . '-' . $suffix . '.txt';
    $upload = docs_upload_file_to_cold_storage($tempPath, $folder, $relativePath);
    @unlink($tempPath);
    if (empty($upload['ok'])) {
        return [
            'ok' => false,
            'message' => (string) ($upload['error'] ?? 'Тестовая загрузка в S3 не выполнена.'),
            'key' => (string) ($upload['key'] ?? ''),
        ];
    }
    docs_run_rclone_command(['deletefile', docs_cold_storage_remote_path((string) $upload['key'])], 25);
    return [
        'ok' => true,
        'message' => 'Тестовая загрузка в S3 прошла успешно, тестовый файл удалён.',
        'key' => (string) $upload['key'],
    ];
}
function docs_cold_storage_queue_relative_path(string $folder, array $file): string
{
    $key = docs_extract_cold_storage_key($file);
    $folderPrefix = docs_build_cold_storage_key($folder, '');
    if ($key === '' || $folderPrefix === '') {
        return '';
    }
    $prefix = rtrim($folderPrefix, '/') . '/';
    if (strpos($key, $prefix) !== 0) {
        return '';
    }
    return docs_normalize_cold_storage_relative_path(substr($key, strlen($prefix)));
}
function docs_cold_storage_queue_local_path(array $pathCandidates): string
{
    foreach ($pathCandidates as $pathCandidate) {
        if (!is_string($pathCandidate) || !is_file($pathCandidate) || !is_readable($pathCandidate)) {
            continue;
        }
        clearstatcache(true, $pathCandidate);
        if ((int) (@filesize($pathCandidate) ?: 0) > 0) {
            return $pathCandidate;
        }
    }
    return '';
}
function docs_build_cold_storage_queue_entry(
    string $folder,
    string $registry,
    string $collection,
    array $file,
    array $pathCandidates,
    string $journalType = ''
): ?array {
    $cold = isset($file['coldStorage']) && is_array($file['coldStorage']) ? $file['coldStorage'] : [];
    $status = sanitize_text_field((string) ($cold['status'] ?? ''), 60);
    $key = docs_extract_cold_storage_key($file);
    if ($status !== 'pending' || $key === '') {
        return null;
    }
    return [
        'registry' => $registry,
        'collection' => $collection,
        'journalType' => $journalType,
        'key' => $key,
        'relativePath' => docs_cold_storage_queue_relative_path($folder, $file),
        'file' => $file,
        'pathCandidates' => array_values($pathCandidates),
    ];
}
function docs_collect_pending_cold_storage_queue_entries(string $folder, int $limit): array
{
    $folder = sanitize_folder_name($folder);
    $limit = max(1, min($limit, DOCS_COLD_STORAGE_QUEUE_BATCH_SIZE));
    $entries = [];
    $append = static function (?array $entry) use (&$entries, $limit): bool {
        if (is_array($entry)) {
            $entries[] = $entry;
        }
        return count($entries) >= $limit;
    };
    foreach (load_registry($folder) as $record) {
        if (!is_array($record)) {
            continue;
        }
        foreach (($record['files'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            if ($append(docs_build_cold_storage_queue_entry(
                $folder,
                'main',
                'files',
                $file,
                docs_get_document_file_path_candidates($folder, $file)
            ))) {
                return $entries;
            }
        }
        $documentId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
        foreach (($record['responses'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
            $paths = [];
            if ($documentId !== '' && $storedName !== '') {
                $paths[] = docs_get_document_responses_dir($folder, $documentId, false) . '/' . $storedName;
            }
            if ($append(docs_build_cold_storage_queue_entry(
                $folder,
                'main',
                'responses',
                $file,
                $paths
            ))) {
                return $entries;
            }
        }
    }
    foreach (docs_load_outgoing_registry($folder) as $record) {
        if (!is_array($record)) {
            continue;
        }
        foreach (($record['files'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            if ($append(docs_build_cold_storage_queue_entry(
                $folder,
                'outgoing',
                'files',
                $file,
                docs_get_outgoing_file_path_candidates($folder, $file)
            ))) {
                return $entries;
            }
        }
    }
    foreach (['orders', 'directives', 'disciplinary'] as $journalType) {
        foreach (docs_load_orders_registry($folder, $journalType) as $record) {
            if (!is_array($record)) {
                continue;
            }
            foreach (($record['files'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                if ($append(docs_build_cold_storage_queue_entry(
                    $folder,
                    'orders',
                    'files',
                    $file,
                    docs_get_order_file_path_candidates($folder, $file, $journalType),
                    $journalType
                ))) {
                    return $entries;
                }
            }
        }
    }
    return $entries;
}
function docs_process_pending_cold_storage_queue_entry(string $folder, array $entry): array
{
    $file = isset($entry['file']) && is_array($entry['file']) ? $entry['file'] : [];
    $key = sanitize_text_field((string) ($entry['key'] ?? ''), 1000);
    $relativePath = docs_normalize_cold_storage_relative_path((string) ($entry['relativePath'] ?? ''));
    $localPath = docs_cold_storage_queue_local_path(
        isset($entry['pathCandidates']) && is_array($entry['pathCandidates'])
            ? $entry['pathCandidates']
            : []
    );
    $expectedBytes = max(0, (int) ($file['size'] ?? 0));
    if ($expectedBytes < 1 && $localPath !== '') {
        clearstatcache(true, $localPath);
        $expectedBytes = max(0, (int) (@filesize($localPath) ?: 0));
    }
    if ($key !== '' && $expectedBytes > 0) {
        $verification = docs_verify_cold_storage_file_size($key, $expectedBytes);
        if (!empty($verification['ok'])) {
            return [
                'ok' => true,
                'status' => 'synced',
                'source' => 'existing',
                'key' => $key,
                'bytes' => $expectedBytes,
                'error' => '',
            ];
        }
    }
    if ($localPath === '') {
        return [
            'ok' => false,
            'status' => 'pending',
            'source' => 'missing_local',
            'key' => $key,
            'bytes' => $expectedBytes,
            'error' => 'S3-файл не подтверждён, локальная копия недоступна.',
        ];
    }
    if ($relativePath === '') {
        return [
            'ok' => false,
            'status' => 'pending',
            'source' => 'invalid_key',
            'key' => $key,
            'bytes' => $expectedBytes,
            'error' => 'Не удалось определить относительный путь S3 из сохранённого ключа.',
        ];
    }
    $upload = docs_upload_file_to_cold_storage($localPath, $folder, $relativePath);
    if (empty($upload['ok'])) {
        return [
            'ok' => false,
            'status' => 'pending',
            'source' => 'upload_failed',
            'key' => (string) ($upload['key'] ?? $key),
            'bytes' => $expectedBytes,
            'error' => (string) ($upload['error'] ?? 'Повторная загрузка в S3 не выполнена.'),
        ];
    }
    return [
        'ok' => true,
        'status' => 'synced',
        'source' => 'uploaded',
        'key' => (string) ($upload['key'] ?? $key),
        'bytes' => (int) ($upload['bytes'] ?? $expectedBytes),
        'error' => '',
    ];
}
function docs_update_pending_cold_storage_queue_entry(string $folder, array $entry, array $result): bool
{
    $registry = (string) ($entry['registry'] ?? '');
    $collection = (string) ($entry['collection'] ?? 'files');
    $journalType = (string) ($entry['journalType'] ?? '');
    $key = sanitize_text_field((string) ($entry['key'] ?? ''), 1000);
    $relativePath = docs_normalize_cold_storage_relative_path((string) ($entry['relativePath'] ?? ''));
    if ($key === '' || !in_array($collection, ['files', 'responses'], true)) {
        return false;
    }
    if ($registry === 'main') {
        [$handle, $records] = docs_lock_registry($folder);
        $save = static function ($lockedHandle, array $lockedRecords): bool {
            return docs_save_registry_locked($lockedHandle, $lockedRecords);
        };
        $unlock = static function ($lockedHandle): void {
            docs_unlock_registry($lockedHandle);
        };
    } elseif ($registry === 'outgoing') {
        [$handle, $records] = docs_lock_outgoing_registry($folder);
        $save = static function ($lockedHandle, array $lockedRecords): bool {
            return docs_save_outgoing_registry_locked($lockedHandle, $lockedRecords);
        };
        $unlock = static function ($lockedHandle): void {
            docs_unlock_outgoing_registry($lockedHandle);
        };
    } elseif ($registry === 'orders' && in_array($journalType, ['orders', 'directives', 'disciplinary'], true)) {
        [$handle, $records] = docs_lock_orders_registry($folder, $journalType);
        $save = static function ($lockedHandle, array $lockedRecords) use ($journalType): bool {
            return docs_save_orders_registry_locked($lockedHandle, $lockedRecords, $journalType);
        };
        $unlock = static function ($lockedHandle): void {
            docs_unlock_orders_registry($lockedHandle);
        };
    } else {
        return false;
    }
    if ($handle === null) {
        return false;
    }
    $changed = false;
    $alreadySynced = false;
    try {
        foreach ($records as &$record) {
            if (!is_array($record) || !isset($record[$collection]) || !is_array($record[$collection])) {
                continue;
            }
            foreach ($record[$collection] as &$file) {
                if (!is_array($file) || docs_extract_cold_storage_key($file) !== $key) {
                    continue;
                }
                $cold = isset($file['coldStorage']) && is_array($file['coldStorage']) ? $file['coldStorage'] : [];
                if ((string) ($cold['status'] ?? '') !== 'pending') {
                    $alreadySynced = (string) ($cold['status'] ?? '') === 'synced';
                    if ($alreadySynced) {
                        break 2;
                    }
                    continue;
                }
                $resolvedBytes = max(0, (int) ($result['bytes'] ?? 0));
                if (!empty($result['ok']) && $resolvedBytes > 0) {
                    $file['size'] = $resolvedBytes;
                }
                $file = docs_apply_cold_storage_state(
                    $file,
                    $folder,
                    $relativePath,
                    !empty($result['ok']) ? 'synced' : 'local_fallback',
                    [
                        'key' => (string) ($result['key'] ?? $key),
                        'bytes' => $resolvedBytes,
                        'error' => (string) ($result['error'] ?? ''),
                    ]
                );
                $changed = true;
                break 2;
            }
            unset($file);
        }
        unset($file);
        unset($record);
        return $alreadySynced || ($changed && $save($handle, $records));
    } finally {
        $unlock($handle);
    }
}
function docs_cold_storage_queue_state_path(string $folder): string
{
    return ensure_organization_directory($folder) . '/' . DOCS_COLD_STORAGE_QUEUE_STATE_FILENAME;
}
function docs_read_cold_storage_queue_state(string $folder): array
{
    $path = docs_cold_storage_queue_state_path($folder);
    if (!is_file($path) || !is_readable($path)) {
        return [];
    }
    $raw = @file_get_contents($path);
    $decoded = is_string($raw) && trim($raw) !== '' ? json_decode($raw, true) : null;
    return is_array($decoded) ? $decoded : [];
}
function docs_write_cold_storage_queue_state(string $folder, array $state): bool
{
    $json = json_encode(
        $state,
        JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
    );
    if (!is_string($json)) {
        return false;
    }
    return docs_write_json_content_atomically(
        docs_cold_storage_queue_state_path($folder),
        $json,
        false
    );
}
function docs_mark_cold_storage_queue_pending(string $folder): void
{
    $folder = sanitize_folder_name($folder);
    if ($folder === '') {
        return;
    }
    $state = docs_read_cold_storage_queue_state($folder);
    $state['pending'] = true;
    $state['updatedAt'] = date('c');
    unset($state['nextAttemptAt']);
    docs_write_cold_storage_queue_state($folder, $state);
}
function docs_should_run_cold_storage_queue(string $folder): bool
{
    $folder = sanitize_folder_name($folder);
    if ($folder === '') {
        return false;
    }
    $state = docs_read_cold_storage_queue_state($folder);
    if (empty($state)) {
        // Первый обычный запрос после публикации обнаружит старые pending-записи.
        return true;
    }
    if (!empty($state['pending'])) {
        $nextAttemptAt = strtotime((string) ($state['nextAttemptAt'] ?? '')) ?: 0;
        return $nextAttemptAt <= time();
    }
    $lastCheckedAt = strtotime((string) ($state['checkedAt'] ?? '')) ?: 0;
    return $lastCheckedAt < time() - DOCS_COLD_STORAGE_QUEUE_DISCOVERY_INTERVAL_SECONDS;
}
function docs_cold_storage_queue_request_folder(array $responsePayload = []): string
{
    $requestPayload = [];
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
        $requestPayload = load_json_payload();
    }
    $sessionAuth = docs_get_session_auth();
    $candidates = [
        $responsePayload['organization'] ?? '',
        $requestPayload['organization'] ?? '',
        $_POST['organization'] ?? '',
        $_GET['organization'] ?? '',
        is_array($sessionAuth) ? ($sessionAuth['organization'] ?? '') : '',
    ];
    foreach ($candidates as $candidate) {
        if (!is_string($candidate) && !is_int($candidate)) {
            continue;
        }
        $folder = sanitize_folder_name((string) $candidate);
        if ($folder !== '') {
            return $folder;
        }
    }
    return '';
}
function docs_acquire_cold_storage_queue_lock(string $folder)
{
    $path = ensure_organization_directory($folder) . '/' . DOCS_COLD_STORAGE_QUEUE_LOCK_FILENAME;
    $handle = @fopen($path, 'c+');
    if ($handle === false) {
        return null;
    }
    if (!flock($handle, LOCK_EX | LOCK_NB)) {
        fclose($handle);
        return null;
    }
    return $handle;
}
function docs_release_cold_storage_queue_lock($handle): void
{
    if (!is_resource($handle)) {
        return;
    }
    flock($handle, LOCK_UN);
    fclose($handle);
}
function docs_run_automatic_cold_storage_queue_step(string $folder): array
{
    $folder = sanitize_folder_name($folder);
    $lockHandle = docs_acquire_cold_storage_queue_lock($folder);
    if ($lockHandle === null) {
        return [
            'ok' => false,
            'reason' => 'queue_busy',
            'message' => 'Для этой организации уже обрабатывается очередь S3.',
        ];
    }
    $coldStorage = docs_cold_storage_base_status();
    if (empty($coldStorage['available'])) {
        docs_release_cold_storage_queue_lock($lockHandle);
        docs_write_cold_storage_queue_state($folder, [
            'pending' => true,
            'checkedAt' => date('c'),
            'nextAttemptAt' => date('c', time() + 300),
            'error' => sanitize_text_field((string) ($coldStorage['message'] ?? 'S3 недоступен.'), 500),
        ]);
        return [
            'ok' => false,
            'worked' => false,
            'queuePending' => true,
            'reason' => 'cold_storage_unavailable',
            'error' => (string) ($coldStorage['message'] ?? 'S3 недоступен.'),
        ];
    }
    $startedAt = microtime(true);
    $attemptedCount = 0;
    $syncedCount = 0;
    $verifiedCount = 0;
    $uploadedCount = 0;
    $failedCount = 0;
    $stateSaveFailedCount = 0;
    $errors = [];
    $entries = [];
    try {
        $entries = docs_collect_pending_cold_storage_queue_entries(
            $folder,
            DOCS_COLD_STORAGE_QUEUE_BATCH_SIZE
        );
        foreach ($entries as $entry) {
            if ($attemptedCount > 0
                && microtime(true) - $startedAt >= DOCS_COLD_STORAGE_QUEUE_BATCH_MAX_SECONDS
            ) {
                break;
            }
            $result = docs_process_pending_cold_storage_queue_entry($folder, $entry);
            $attemptedCount++;
            if (!docs_update_pending_cold_storage_queue_entry($folder, $entry, $result)) {
                $failedCount++;
                $stateSaveFailedCount++;
                $errors[] = 'Не удалось сохранить новый S3-статус файла.';
                continue;
            }
            if (!empty($result['ok'])) {
                $syncedCount++;
                if (($result['source'] ?? '') === 'existing') {
                    $verifiedCount++;
                } elseif (($result['source'] ?? '') === 'uploaded') {
                    $uploadedCount++;
                }
                continue;
            }
            $failedCount++;
            $error = sanitize_text_field((string) ($result['error'] ?? ''), 500);
            if ($error !== '') {
                $errors[] = $error;
            }
        }
    } finally {
        docs_release_cold_storage_queue_lock($lockHandle);
    }
    $queuePending = $stateSaveFailedCount > 0
        || $attemptedCount < count($entries)
        || count($entries) >= DOCS_COLD_STORAGE_QUEUE_BATCH_SIZE;
    docs_write_cold_storage_queue_state($folder, [
        'pending' => $queuePending,
        'checkedAt' => date('c'),
        'attemptedCount' => $attemptedCount,
        'syncedCount' => $syncedCount,
        'verifiedCount' => $verifiedCount,
        'uploadedCount' => $uploadedCount,
        'failedCount' => $failedCount,
        'errors' => array_slice($errors, 0, 5),
    ]);
    if ($attemptedCount > 0 || $failedCount > 0) {
        docs_write_response_log('Автоматическая обработка очереди S3', [
            'folder' => $folder,
            'attemptedCount' => $attemptedCount,
            'syncedCount' => $syncedCount,
            'verifiedCount' => $verifiedCount,
            'uploadedCount' => $uploadedCount,
            'failedCount' => $failedCount,
            'queuePending' => $queuePending,
            'errors' => array_slice($errors, 0, 5),
        ]);
    }
    return [
        'ok' => $failedCount === 0,
        'worked' => $attemptedCount > 0,
        'queuePending' => $queuePending,
        'attemptedCount' => $attemptedCount,
        'syncedCount' => $syncedCount,
        'verifiedCount' => $verifiedCount,
        'uploadedCount' => $uploadedCount,
        'failedCount' => $failedCount,
        'errors' => array_slice($errors, 0, 5),
    ];
}
function docs_sanitize_cold_storage_browser_path($value): string
{
    $path = is_string($value) ? trim($value) : '';
    if ($path === '') {
        return '';
    }
    return docs_normalize_cold_storage_relative_path($path);
}
function docs_cold_storage_parent_browser_path(string $path): string
{
    $path = docs_normalize_cold_storage_relative_path($path);
    if ($path === '') {
        return '';
    }
    $parts = explode('/', $path);
    array_pop($parts);
    return implode('/', $parts);
}
function docs_list_cold_storage_objects(string $folder, string $browserPath = ''): array
{
    $folder = trim($folder) !== '' ? sanitize_folder_name($folder) : '';
    $browserPath = docs_sanitize_cold_storage_browser_path($browserPath);
    $key = docs_build_cold_storage_key($folder, $browserPath);
    $remotePath = docs_cold_storage_remote_path($key);
    $result = docs_run_rclone_command(['lsjson', '--max-depth', '1', $remotePath], 25);
    $items = [];
    $totalBytes = 0;
    $directoriesCount = 0;
    $filesCount = 0;
    if (empty($result['ok'])) {
        return [
            'ok' => false,
            'path' => $browserPath,
            'parentPath' => docs_cold_storage_parent_browser_path($browserPath),
            'key' => $key,
            'remotePath' => $remotePath,
            'items' => [],
            'filesCount' => 0,
            'directoriesCount' => 0,
            'bytes' => 0,
            'label' => docs_format_file_size(0),
            'message' => (string) ($result['error'] ?? 'Не удалось получить список S3.'),
        ];
    }
    if (!empty($result['outputTruncated'])) {
        return [
            'ok' => false,
            'path' => $browserPath,
            'parentPath' => docs_cold_storage_parent_browser_path($browserPath),
            'key' => $key,
            'remotePath' => $remotePath,
            'items' => [],
            'filesCount' => 0,
            'directoriesCount' => 0,
            'bytes' => 0,
            'label' => docs_format_file_size(0),
            'message' => 'Список S3 превысил безопасный размер ответа и не был показан частично.',
        ];
    }
    $decoded = json_decode((string) ($result['output'] ?? ''), true);
    if (!is_array($decoded)) {
        $decoded = [];
    }
    foreach ($decoded as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $name = sanitize_text_field((string) ($entry['Name'] ?? ''), 255);
        if ($name === '') {
            continue;
        }
        $isDir = !empty($entry['IsDir']);
        $size = $isDir ? 0 : max(0, (int) ($entry['Size'] ?? 0));
        $childPath = $browserPath !== '' ? $browserPath . '/' . $name : $name;
        $childPath = docs_normalize_cold_storage_relative_path($childPath);
        $childKey = docs_build_cold_storage_key($folder, $childPath);
        $items[] = [
            'name' => $name,
            'path' => $childPath,
            'type' => $isDir ? 'directory' : 'file',
            'size' => $size,
            'sizeLabel' => $isDir ? '' : docs_format_file_size($size),
            'modifiedAt' => sanitize_text_field((string) ($entry['ModTime'] ?? ''), 80),
            'remoteKey' => $childKey,
            'remotePath' => docs_cold_storage_remote_path($childKey),
        ];
        if ($isDir) {
            $directoriesCount++;
        } else {
            $filesCount++;
            $totalBytes += $size;
        }
    }
    usort($items, static function (array $left, array $right): int {
        if (($left['type'] ?? '') !== ($right['type'] ?? '')) {
            return ($left['type'] ?? '') === 'directory' ? -1 : 1;
        }
        return strnatcasecmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''));
    });
    return [
        'ok' => true,
        'path' => $browserPath,
        'parentPath' => docs_cold_storage_parent_browser_path($browserPath),
        'key' => $key,
        'remotePath' => $remotePath,
        'items' => $items,
        'filesCount' => $filesCount,
        'directoriesCount' => $directoriesCount,
        'bytes' => $totalBytes,
        'label' => docs_format_file_size($totalBytes),
        'message' => '',
    ];
}
function docs_normalize_cold_storage_browser_object_type($value): string
{
    $type = is_string($value) ? mb_strtolower(trim($value), 'UTF-8') : '';
    return $type === 'directory' ? 'directory' : 'file';
}
function docs_delete_cold_storage_browser_object(string $folder, string $browserPath, string $type): array
{
    $folder = trim($folder) !== '' ? sanitize_folder_name($folder) : '';
    $browserPath = docs_sanitize_cold_storage_browser_path($browserPath);
    $type = docs_normalize_cold_storage_browser_object_type($type);
    if ($browserPath === '') {
        return [
            'ok' => false,
            'path' => '',
            'type' => $type,
            'key' => '',
            'remotePath' => '',
            'message' => 'Корень S3 удалить нельзя.',
        ];
    }
    $key = docs_build_cold_storage_key($folder, $browserPath);
    $remotePath = docs_cold_storage_remote_path($key);
    $result = $type === 'directory'
        ? docs_run_rclone_command(['purge', $remotePath], 60)
        : docs_run_rclone_command(['deletefile', $remotePath], 30);
    return [
        'ok' => !empty($result['ok']),
        'path' => $browserPath,
        'type' => $type,
        'key' => $key,
        'remotePath' => $remotePath,
        'message' => !empty($result['ok'])
            ? ($type === 'directory' ? 'Папка удалена из S3.' : 'Файл удалён из S3.')
            : (string) ($result['error'] ?? 'Не удалось удалить объект из S3.'),
        'exitCode' => $result['exitCode'] ?? null,
    ];
}
function docs_read_cold_storage_browser_file(string $folder, string $browserPath): array
{
    $folder = trim($folder) !== '' ? sanitize_folder_name($folder) : '';
    $browserPath = docs_sanitize_cold_storage_browser_path($browserPath);
    if ($browserPath === '') {
        return [
            'ok' => false,
            'path' => '',
            'key' => '',
            'remotePath' => '',
            'message' => 'Файл S3 не выбран.',
        ];
    }
    $key = docs_build_cold_storage_key($folder, $browserPath);
    $remotePath = docs_cold_storage_remote_path($key);
    $tempPath = tempnam(sys_get_temp_dir(), 'docs_s3_read_');
    if (!is_string($tempPath) || $tempPath === '') {
        return [
            'ok' => false,
            'path' => $browserPath,
            'key' => $key,
            'remotePath' => $remotePath,
            'message' => 'Не удалось создать временный файл для чтения S3.',
        ];
    }
    try {
        $result = docs_run_rclone_command(['copyto', $remotePath, $tempPath], 60);
        if (empty($result['ok'])) {
            return [
                'ok' => false,
                'path' => $browserPath,
                'key' => $key,
                'remotePath' => $remotePath,
                'message' => (string) ($result['error'] ?? 'Не удалось скачать файл из S3.'),
                'exitCode' => $result['exitCode'] ?? null,
            ];
        }
        $bytes = is_file($tempPath) ? (int) (@filesize($tempPath) ?: 0) : 0;
        if ($bytes > DOCS_S3_READ_MAX_BYTES) {
            return [
                'ok' => false,
                'path' => $browserPath,
                'key' => $key,
                'remotePath' => $remotePath,
                'bytes' => $bytes,
                'label' => docs_format_file_size($bytes),
                'message' => 'Файл слишком большой для чтения в модальном окне. Лимит: ' . docs_format_file_size(DOCS_S3_READ_MAX_BYTES) . '.',
            ];
        }
        $raw = @file_get_contents($tempPath);
        if (!is_string($raw)) {
            return [
                'ok' => false,
                'path' => $browserPath,
                'key' => $key,
                'remotePath' => $remotePath,
                'bytes' => $bytes,
                'label' => docs_format_file_size($bytes),
                'message' => 'Не удалось прочитать временный файл S3.',
            ];
        }
        if ($raw !== '' && preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F]/', $raw)) {
            return [
                'ok' => false,
                'path' => $browserPath,
                'key' => $key,
                'remotePath' => $remotePath,
                'bytes' => $bytes,
                'label' => docs_format_file_size($bytes),
                'message' => 'Файл похож на бинарный. В модальном окне читаются только текстовые файлы.',
            ];
        }
        if ($raw !== '' && function_exists('mb_check_encoding') && !mb_check_encoding($raw, 'UTF-8')) {
            $converted = @mb_convert_encoding($raw, 'UTF-8', 'Windows-1251,ISO-8859-1,UTF-8');
            if (is_string($converted) && $converted !== '') {
                $raw = $converted;
            }
        }
        return [
            'ok' => true,
            'path' => $browserPath,
            'name' => basename($browserPath),
            'key' => $key,
            'remotePath' => $remotePath,
            'bytes' => $bytes,
            'label' => docs_format_file_size($bytes),
            'text' => $raw,
            'message' => 'Файл прочитан из S3.',
        ];
    } finally {
        @unlink($tempPath);
    }
}
function docs_normalize_cold_storage_listing_scope($value): string
{
    $scope = is_string($value) ? mb_strtolower(trim($value), 'UTF-8') : '';
    return in_array($scope, ['all', 'root', 'project'], true) ? 'all' : 'organization';
}
function docs_collect_storage_size_summary(?string $requestedOrganization = null): array
{
    $folder = '';
    if (is_string($requestedOrganization) && trim($requestedOrganization) !== '') {
        $folder = sanitize_folder_name($requestedOrganization);
    }
    $folders = [];
    if ($folder !== '') {
        $folders[] = $folder;
    } else {
        foreach (load_organizations() as $organization) {
            $candidate = sanitize_folder_name((string) $organization);
            if ($candidate !== '') {
                $folders[$candidate] = $candidate;
            }
        }
        $folders = array_values($folders);
    }
    $registryFiles = [
        REGISTRY_FILENAME,
        OUTGOING_REGISTRY_FILENAME,
        ORDERS_REGISTRY_FILENAME,
        DIRECTIVES_REGISTRY_FILENAME,
        DISCIPLINARY_REGISTRY_FILENAME,
        SETTINGS_FILENAME,
    ];
    $registryBytes = 0;
    $attachmentsCount = 0;
    $responsesCount = 0;
    $ordersAttachmentsCount = 0;
    $recordsCount = 0;
    $localFilesCount = 0;
    $localBytes = 0;
    $coldSyncedCount = 0;
    $coldPendingCount = 0;
    $coldFallbackCount = 0;
    $missingFilesCount = 0;
    $coldBytes = 0;
    foreach ($folders as $currentFolder) {
        $directory = DOCUMENTS_ROOT . '/' . $currentFolder;
        foreach ($registryFiles as $registryFile) {
            $path = $directory . '/' . $registryFile;
            if (is_file($path)) {
                $registryBytes += max(0, (int) (@filesize($path) ?: 0));
            }
        }
        foreach (load_registry($currentFolder) as $record) {
            if (!is_array($record)) {
                continue;
            }
            $recordsCount++;
            if (isset($record['files']) && is_array($record['files'])) {
                $attachmentsCount += count($record['files']);
                foreach ($record['files'] as $file) {
                    if (!is_array($file)) {
                        continue;
                    }
                    $fileState = docs_collect_storage_file_state(
                        $currentFolder,
                        $file,
                        docs_get_document_file_path_candidates($currentFolder, $file)
                    );
                    if (!empty($fileState['localExists'])) {
                        $localFilesCount++;
                        $localBytes += (int) $fileState['localBytes'];
                    }
                    if (!empty($fileState['coldSynced'])) {
                        $coldSyncedCount++;
                        $coldBytes += (int) $fileState['bytes'];
                    } elseif (!empty($fileState['coldPending'])) {
                        $coldPendingCount++;
                    } elseif (!empty($fileState['coldKey']) || ($fileState['storageProvider'] ?? '') === 'local') {
                        $coldFallbackCount++;
                    }
                    if (empty($fileState['localExists']) && empty($fileState['coldSynced'])) {
                        $missingFilesCount++;
                    }
                }
            }
            if (isset($record['responses']) && is_array($record['responses'])) {
                $responsesCount += count($record['responses']);
                $documentId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
                foreach ($record['responses'] as $file) {
                    if (!is_array($file)) {
                        continue;
                    }
                    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                    $paths = [];
                    if ($documentId !== '' && $storedName !== '') {
                        $paths[] = ensure_organization_directory($currentFolder) . '/Ответы/' . $documentId . '/' . $storedName;
                    }
                    $fileState = docs_collect_storage_file_state($currentFolder, $file, $paths);
                    if (!empty($fileState['localExists'])) {
                        $localFilesCount++;
                        $localBytes += (int) $fileState['localBytes'];
                    }
                    if (!empty($fileState['coldSynced'])) {
                        $coldSyncedCount++;
                        $coldBytes += (int) $fileState['bytes'];
                    } elseif (!empty($fileState['coldPending'])) {
                        $coldPendingCount++;
                    } elseif (!empty($fileState['coldKey']) || ($fileState['storageProvider'] ?? '') === 'local') {
                        $coldFallbackCount++;
                    }
                    if (empty($fileState['localExists']) && empty($fileState['coldSynced'])) {
                        $missingFilesCount++;
                    }
                }
            }
        }
        foreach (docs_load_outgoing_registry($currentFolder) as $record) {
            if (!is_array($record)) {
                continue;
            }
            $recordsCount++;
            if (isset($record['files']) && is_array($record['files'])) {
                $attachmentsCount += count($record['files']);
                foreach ($record['files'] as $file) {
                    if (!is_array($file)) {
                        continue;
                    }
                    $fileState = docs_collect_storage_file_state(
                        $currentFolder,
                        $file,
                        docs_get_outgoing_file_path_candidates($currentFolder, $file)
                    );
                    if (!empty($fileState['localExists'])) {
                        $localFilesCount++;
                        $localBytes += (int) $fileState['localBytes'];
                    }
                    if (!empty($fileState['coldSynced'])) {
                        $coldSyncedCount++;
                        $coldBytes += (int) $fileState['bytes'];
                    } elseif (!empty($fileState['coldPending'])) {
                        $coldPendingCount++;
                    } elseif (!empty($fileState['coldKey']) || ($fileState['storageProvider'] ?? '') === 'local') {
                        $coldFallbackCount++;
                    }
                    if (empty($fileState['localExists']) && empty($fileState['coldSynced'])) {
                        $missingFilesCount++;
                    }
                }
            }
        }
        foreach (['orders', 'directives', 'disciplinary'] as $journalType) {
            foreach (docs_load_orders_registry($currentFolder, $journalType) as $record) {
                if (!is_array($record)) {
                    continue;
                }
                $recordsCount++;
                if (isset($record['files']) && is_array($record['files'])) {
                    $ordersAttachmentsCount += count($record['files']);
                    foreach ($record['files'] as $file) {
                        if (!is_array($file)) {
                            continue;
                        }
                        $fileState = docs_collect_storage_file_state(
                            $currentFolder,
                            $file,
                            docs_get_order_file_path_candidates($currentFolder, $file, $journalType)
                        );
                        if (!empty($fileState['localExists'])) {
                            $localFilesCount++;
                            $localBytes += (int) $fileState['localBytes'];
                        }
                        if (!empty($fileState['coldSynced'])) {
                            $coldSyncedCount++;
                            $coldBytes += (int) $fileState['bytes'];
                        } elseif (!empty($fileState['coldPending'])) {
                            $coldPendingCount++;
                        } elseif (!empty($fileState['coldKey']) || ($fileState['storageProvider'] ?? '') === 'local') {
                            $coldFallbackCount++;
                        }
                        if (empty($fileState['localExists']) && empty($fileState['coldSynced'])) {
                            $missingFilesCount++;
                        }
                    }
                }
            }
        }
    }
    $trackedFiles = $attachmentsCount + $responsesCount + $ordersAttachmentsCount;
    return [
        'bytes' => $registryBytes + $localBytes,
        'files' => $trackedFiles,
        'directories' => count($folders),
        'extensions' => [],
        'topDirectories' => [],
        'largestFiles' => [],
        'registryBytes' => $registryBytes,
        'localBytes' => $localBytes,
        'coldBytes' => $coldBytes,
        'label' => docs_format_file_size($registryBytes + $localBytes),
        'registryLabel' => docs_format_file_size($registryBytes),
        'localLabel' => docs_format_file_size($localBytes),
        'coldLabel' => docs_format_file_size($coldBytes),
        'path' => $folder !== '' ? 'documents/' . $folder : 'documents',
        'organization' => $folder !== '' ? $requestedOrganization : null,
        'checkedAt' => date('c'),
        'mode' => 'registry_and_s3_metadata',
        'recordsCount' => $recordsCount,
        'attachmentsCount' => $attachmentsCount,
        'responsesCount' => $responsesCount,
        'ordersAttachmentsCount' => $ordersAttachmentsCount,
        'localFilesCount' => $localFilesCount,
        'coldSyncedCount' => $coldSyncedCount,
        'coldPendingCount' => $coldPendingCount,
        'coldFallbackCount' => $coldFallbackCount,
        'missingFilesCount' => $missingFilesCount,
        'coldStorage' => docs_cold_storage_base_status(),
    ];
}
function docs_validate_uploaded_attachment(string $originalName, int $size): ?string
{
    if ($size <= 0) {
        return 'Файл «' . $originalName . '» пустой или повреждён.';
    }
    if ($size > DOCS_ATTACHMENT_MAX_FILE_SIZE) {
        return 'Файл «' . $originalName . '» слишком большой: ' . docs_format_file_size($size)
            . '. Максимум для одного файла — ' . docs_format_file_size(DOCS_ATTACHMENT_MAX_FILE_SIZE) . '.';
    }
    $extension = strtolower((string) pathinfo($originalName, PATHINFO_EXTENSION));
    if ($extension !== '' && isset(DOCS_ATTACHMENT_BLOCKED_EXTENSIONS[$extension])) {
        return 'Файл «' . $originalName . '» не похож на документ. Загрузите PDF, изображение, DOCX/XLSX или архив.';
    }
    return null;
}
function docs_optimize_uploaded_attachment_file(string $path, string $originalName, int $originalSize = 0): array
{
    $result = [
        'optimized' => false,
        'size' => is_file($path) ? (int) (@filesize($path) ?: 0) : 0,
        'originalSize' => max(0, $originalSize),
    ];
    $actualSize = (int) (@filesize($path) ?: 0);
    if ($actualSize <= 0) {
        return $result;
    }
    $result['size'] = $actualSize;
    if ($result['originalSize'] <= 0) {
        $result['originalSize'] = $actualSize;
    }
    return $result;
}
function sanitize_status(?string $value, bool $useDefault = false): string
{
    $value = sanitize_text_field($value, 80);
    if ($value === '') {
        return $useDefault ? 'Принято в работу' : '';
    }
    $normalized = mb_strtolower($value);
    $map = [
        'в работе'        => 'Принято в работу',
        'принято в работу'=> 'Принято в работу',
        'принято вработу' => 'Принято в работу',
        'принято в работ' => 'Принято в работу',
        'распределено'    => 'Распределено',
        'распределен'     => 'Распределено',
        'распределена'    => 'Распределено',
        'распределены'    => 'Распределено',
        'на контроле'     => 'На проверке',
        'на проверке'     => 'На проверке',
        'на проверку'     => 'На проверке',
        'завершено'       => 'Выполнено',
        'выполнено'       => 'Выполнено',
        'отменено'        => 'Отменено',
    ];
    if (isset($map[$normalized])) {
        return $map[$normalized];
    }
    return mb_convert_case($normalized, MB_CASE_TITLE, 'UTF-8');
}
function docs_init_status_counters(): array
{
    return [
        'distributed' => 0,
        'accepted' => 0,
        'review' => 0,
        'done' => 0,
        'cancelled' => 0,
    ];
}
function docs_status_key_from_status($status): ?string
{
    if ($status === null) {
        return null;
    }
    $raw = trim((string) $status);
    if ($raw === '') {
        return null;
    }
    $sanitized = sanitize_status($raw);
    $normalized = mb_strtolower($sanitized, 'UTF-8');
    switch ($normalized) {
        case 'распределено':
            return 'distributed';
        case 'принято в работу':
            return 'accepted';
        case 'на проверке':
            return 'review';
        case 'выполнено':
            return 'done';
        case 'отменено':
            return 'cancelled';
        default:
            return null;
    }
}
function docs_normalize_datetime_iso(?string $value): ?string
{
    if ($value === null) {
        return null;
    }
    $raw = trim((string) $value);
    if ($raw === '') {
        return null;
    }
    try {
        $date = new DateTime($raw);
        return $date->format(DateTime::ATOM);
    } catch (Exception $exception) {
        return null;
    }
}
function docs_sanitize_filename(string $name, string $default = 'document.pdf'): string
{
    $candidate = trim($name);
    if ($candidate === '') {
        $candidate = $default;
    }
    $candidate = preg_replace('/[\x00-\x1F\x7F]+/u', '', $candidate);
    $candidate = str_replace(['\\', '/', ':', '*', '?', '"', '<', '>', '|'], '_', $candidate);
    $candidate = preg_replace('/\s+/u', '_', $candidate);
    if ($candidate === '' || $candidate === '_') {
        $candidate = $default;
    }
    if (mb_strlen($candidate, 'UTF-8') > 200) {
        $candidate = mb_substr($candidate, 0, 200, 'UTF-8');
    }
    return $candidate;
}
function docs_get_pdf_cache_directory(): string
{
    static $ensured = false;
    if (!is_dir(MINI_APP_PDF_CACHE_DIRECTORY)) {
        $created = @mkdir(MINI_APP_PDF_CACHE_DIRECTORY, 0775, true);
        if (!$created) {
            log_docs_event('Mini app PDF cache directory unavailable', [
                'directory' => MINI_APP_PDF_CACHE_DIRECTORY,
                'exists' => is_dir(MINI_APP_PDF_CACHE_DIRECTORY),
                'writable' => is_writable(dirname(MINI_APP_PDF_CACHE_DIRECTORY)),
            ]);
        }
    }
    if (!$ensured && is_dir(MINI_APP_PDF_CACHE_DIRECTORY)) {
        $ensured = true;
        log_docs_event('Mini app PDF cache directory ready', [
            'directory' => MINI_APP_PDF_CACHE_DIRECTORY,
        ]);
    }
    return MINI_APP_PDF_CACHE_DIRECTORY;
}
function docs_cleanup_pdf_cache(string $directory, int $maxAge = MINI_APP_PDF_CACHE_TTL): void
{
    if (!is_dir($directory)) {
        return;
    }
    $now = time();
    $handle = @opendir($directory);
    if ($handle === false) {
        return;
    }
    while (($entry = readdir($handle)) !== false) {
        if ($entry === '.' || $entry === '..') {
            continue;
        }
        $path = $directory . '/' . $entry;
        if (!is_file($path)) {
            continue;
        }
        $mtime = @filemtime($path);
        if ($mtime === false) {
            continue;
        }
        if ($now - $mtime > $maxAge) {
            @unlink($path);
        }
    }
    closedir($handle);
}
function docs_build_public_pdf_url(string $fileName): string
{
    $safeName = ltrim($fileName, '/');
    return '/cache/miniapp_pdf/' . rawurlencode($safeName);
}
function docs_build_public_pdf_delivery_url(string $storedFileName, string $fileName): string
{
    $safeStoredName = basename(ltrim($storedFileName, '/'));
    $safeFileName = docs_sanitize_filename($fileName, 'document.pdf');
    return '/docs.php?' . http_build_query([
        'action' => 'mini_app_cached_pdf',
        'file' => $safeStoredName,
        'name' => $safeFileName,
        'disposition' => 'inline',
    ], '', '&', PHP_QUERY_RFC3986);
}
function docs_handle_mini_app_cached_pdf(string $method): void
{
    $method = strtoupper($method);
    if ($method !== 'GET' && $method !== 'HEAD') {
        respond_error('Некорректный метод запроса.', 405, ['allowedMethod' => 'GET']);
    }
    $storedFileName = isset($_GET['file']) && is_string($_GET['file'])
        ? basename(sanitize_text_field($_GET['file'], 255))
        : '';
    if ($storedFileName === '' || !preg_match('/^miniapp_\d{8}_\d{6}_[a-f0-9]{16}\.pdf$/i', $storedFileName)) {
        respond_error('Файл не найден.', 404);
    }
    $cacheDirectory = docs_get_pdf_cache_directory();
    $cacheRoot = realpath($cacheDirectory);
    if (!is_string($cacheRoot) || $cacheRoot === '') {
        respond_error('Файл не найден.', 404);
    }
    $filePath = rtrim($cacheRoot, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $storedFileName;
    $realPath = realpath($filePath);
    $rootPrefix = rtrim($cacheRoot, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;
    if (!is_string($realPath) || !is_file($realPath) || strpos($realPath, $rootPrefix) !== 0) {
        respond_error('Файл не найден.', 404);
    }
    $fileName = isset($_GET['name']) && is_string($_GET['name'])
        ? docs_sanitize_filename($_GET['name'], 'document.pdf')
        : 'document.pdf';
    if ($fileName === '') {
        $fileName = 'document.pdf';
    }
    $disposition = isset($_GET['disposition']) && is_string($_GET['disposition'])
        ? $_GET['disposition']
        : 'inline';
    $disposition = strtolower(trim($disposition)) === 'attachment' ? 'attachment' : 'inline';
    docs_stream_file_response($realPath, $fileName, $disposition, $method);
}
function sanitize_folder_name(string $name): string
{
    $candidate = preg_replace('/[^\p{L}\p{N}\s._-]/u', '', $name);
    $candidate = preg_replace('/\s+/u', '_', trim((string) $candidate));
    if ($candidate === '') {
        $candidate = 'organization_' . substr(sha1($name), 0, 8);
    }
    return $candidate;
}
function get_registry_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . REGISTRY_FILENAME;
}
function docs_build_registry_meta(string $folder, string $organization): array
{
    $path = get_registry_path($folder);
    $exists = is_file($path);
    $mtime = $exists ? @filemtime($path) : false;
    $size = $exists ? @filesize($path) : false;
    $mtimeValue = $mtime === false ? 0 : (int) $mtime;
    $sizeValue = $size === false ? 0 : (int) $size;
    return [
        'exists' => $exists,
        'mtime' => $mtimeValue,
        'size' => $sizeValue,
        'signature' => $organization . '|' . $mtimeValue . '|' . $sizeValue,
    ];
}
function get_outgoing_registry_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . OUTGOING_REGISTRY_FILENAME;
}
function docs_normalize_orders_journal_type($value): string
{
