function docs_normalize_outgoing_save_payload(array $payload): array
{
    foreach (['payload', 'fields', 'record', 'data'] as $field) {
        if (!isset($payload[$field])) {
            continue;
        }
        $nested = $payload[$field];
        if (is_string($nested)) {
            $decoded = json_decode($nested, true);
            $nested = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($nested) || empty($nested)) {
            continue;
        }
        unset($payload[$field]);
        foreach ($nested as $key => $value) {
            if (!is_string($key) && !is_int($key)) {
                continue;
            }
            $key = (string) $key;
            $currentValue = $payload[$key] ?? null;
            $currentIsEmpty = $currentValue === null
                || (is_string($currentValue) && trim($currentValue) === '')
                || (is_array($currentValue) && empty($currentValue));
            $nestedArrayShouldWin = is_array($value)
                && in_array($key, ['filesToDelete', 'filesRemaining'], true);
            if ($nestedArrayShouldWin || !array_key_exists($key, $payload) || $currentIsEmpty) {
                $payload[$key] = $value;
            }
        }
    }
    return $payload;
}
function docs_payload_first_scalar_text(array $payload, array $fields, int $maxLength = 220): string
{
    foreach ($fields as $field) {
        if (!is_string($field) || $field === '' || !array_key_exists($field, $payload)) {
            continue;
        }
        $value = $payload[$field];
        if (is_array($value)) {
            $value = reset($value);
        }
        if (is_object($value) || is_array($value)) {
            continue;
        }
        $value = sanitize_text_field((string) $value, $maxLength);
        if ($value !== '') {
            return $value;
        }
    }
    return '';
}
function docs_payload_has_any_field(array $payload, array $fields): bool
{
    foreach ($fields as $field) {
        if (is_string($field) && $field !== '' && array_key_exists($field, $payload)) {
            return true;
        }
    }
    return false;
}
function docs_create_outgoing_record_id(): string
{
    try {
        return 'outgoing_' . bin2hex(random_bytes(8));
    } catch (Throwable $exception) {
        return 'outgoing_' . str_replace('.', '', uniqid('', true));
    }
}
function docs_prepare_outgoing_files_payload($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $files = [];
    foreach ($value as $file) {
        if (!is_array($file)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
        if ($storedName === '' && $url === '') {
            continue;
        }
        $visibility = docs_normalize_outgoing_file_visibility($file['visibility'] ?? '');
        $preparedFile = array_filter([
            'originalName' => sanitize_text_field((string) ($file['originalName'] ?? ($file['name'] ?? $storedName)), 255),
            'storedName' => $storedName,
            'size' => isset($file['size']) ? max(0, (int) $file['size']) : 0,
            'uploadedAt' => docs_normalize_datetime_iso(isset($file['uploadedAt']) ? (string) $file['uploadedAt'] : null) ?? '',
            'url' => $url,
            'accessKey' => sanitize_text_field((string) ($file['accessKey'] ?? ''), 200),
            'visibility' => $visibility,
            'uploadedBy' => sanitize_text_field((string) ($file['uploadedBy'] ?? ''), 220),
            'uploadedByKey' => sanitize_text_field((string) ($file['uploadedByKey'] ?? ''), 200),
        ], static function ($item) {
            return $item !== '' && $item !== 0;
        });
        $preparedFile = array_merge($preparedFile, docs_prepare_cold_storage_file_payload($file));
        $files[] = $preparedFile;
    }
    return $files;
}
function docs_normalize_outgoing_file_visibility($value): string
{
    $normalized = mb_strtolower(trim((string) $value), 'UTF-8');
    if (in_array($normalized, ['private', 'privat', '1', 'true', 'yes', 'on', 'приватный', 'личный'], true)) {
        return 'private';
    }
    return 'public';
}
function docs_payload_requests_private_outgoing_files(array $payload): bool
{
    foreach (['outgoingFilesPrivate', 'filesPrivate', 'privateFiles', 'isPrivate'] as $key) {
        if (!array_key_exists($key, $payload)) {
            continue;
        }
        $value = is_array($payload[$key]) ? reset($payload[$key]) : $payload[$key];
        $normalized = mb_strtolower(trim((string) $value), 'UTF-8');
        if (in_array($normalized, ['1', 'true', 'yes', 'on', 'private', 'приватный'], true)) {
            return true;
        }
    }
    $visibility = docs_normalize_outgoing_file_visibility($payload['filesVisibility'] ?? ($payload['visibility'] ?? ''));
    return $visibility === 'private';
}
function docs_is_outgoing_file_private(array $file): bool
{
    return docs_normalize_outgoing_file_visibility($file['visibility'] ?? '') === 'private';
}
function docs_normalize_outgoing_user_key(string $value): string
{
    $value = sanitize_text_field($value, 200);
    $value = trim($value);
    return $value !== '' ? mb_strtolower($value, 'UTF-8') : '';
}
function docs_normalize_outgoing_user_keys($value): array
{
    $values = is_array($value) ? $value : [$value];
    $keys = [];
    foreach ($values as $item) {
        if (is_array($item)) {
            foreach (docs_normalize_outgoing_user_keys($item) as $nestedKey) {
                $keys[$nestedKey] = true;
            }
            continue;
        }
        $key = docs_normalize_outgoing_user_key((string) $item);
        if ($key !== '') {
            $keys[$key] = true;
        }
    }
    return array_keys($keys);
}
function docs_outgoing_file_user_can_access(array $file, bool $canManageOutgoing, $currentUserKeys): bool
{
    if (!docs_is_outgoing_file_private($file)) {
        return true;
    }
    if ($canManageOutgoing) {
        return true;
    }
    $ownerKey = docs_normalize_outgoing_user_key((string) ($file['uploadedByKey'] ?? ''));
    if ($ownerKey === '') {
        return false;
    }
    foreach (docs_normalize_outgoing_user_keys($currentUserKeys) as $viewerKey) {
        if (hash_equals($ownerKey, $viewerKey)) {
            return true;
        }
    }
    return false;
}
function docs_outgoing_record_user_can_edit(array $record, bool $_canManageOutgoing, $currentUserKeys): bool
{
    $ownerKey = docs_normalize_outgoing_user_key((string) ($record['createdByKey'] ?? ''));
    if ($ownerKey === '') {
        return false;
    }
    foreach (docs_normalize_outgoing_user_keys($currentUserKeys) as $userKey) {
        if (hash_equals($ownerKey, $userKey)) {
            return true;
        }
    }
    return false;
}
function docs_normalize_outgoing_owner_label($value): string
{
    $label = sanitize_text_field((string) $value, 220);
    $label = preg_replace('/\s+/u', ' ', trim($label));
    if (!is_string($label) || $label === '') {
        return '';
    }
    return mb_strtolower($label, 'UTF-8');
}
function docs_outgoing_file_has_inherited_private_owner(array $file, array $record): bool
{
    if (!docs_is_outgoing_file_private($file)) {
        return false;
    }
    $ownerKey = docs_normalize_outgoing_user_key((string) ($file['uploadedByKey'] ?? ''));
    $uploaderLabel = docs_normalize_outgoing_owner_label($file['uploadedBy'] ?? '');
    if ($ownerKey === '' || $uploaderLabel === '') {
        return false;
    }
    $recordOwners = [
        [
            'key' => $record['createdByKey'] ?? '',
            'label' => $record['createdBy'] ?? '',
        ],
        [
            'key' => $record['updatedByKey'] ?? '',
            'label' => $record['updatedBy'] ?? '',
        ],
    ];
    foreach ($recordOwners as $recordOwner) {
        $recordKey = docs_normalize_outgoing_user_key((string) ($recordOwner['key'] ?? ''));
        if ($recordKey === '' || !hash_equals($ownerKey, $recordKey)) {
            continue;
        }
        $recordLabel = docs_normalize_outgoing_owner_label($recordOwner['label'] ?? '');
        if ($recordLabel !== '' && !hash_equals($uploaderLabel, $recordLabel)) {
            return true;
        }
    }
    return false;
}
function docs_ensure_private_outgoing_storage_guard(string $directory): void
{
    if ($directory === '' || !is_dir($directory)) {
        return;
    }
    $htaccessPath = rtrim($directory, '/\\') . '/.htaccess';
    if (!is_file($htaccessPath)) {
        @file_put_contents($htaccessPath, "Require all denied\nDeny from all\n", LOCK_EX);
        @chmod($htaccessPath, 0644);
    }
    $indexPath = rtrim($directory, '/\\') . '/index.html';
    if (!is_file($indexPath)) {
        @file_put_contents($indexPath, '', LOCK_EX);
        @chmod($indexPath, 0644);
    }
}
function docs_build_private_outgoing_file_url(string $folder, string $recordId, string $fileKey): string
{
    $params = [
        'action' => 'outgoing_file',
        'organization' => $folder,
        'record_id' => $recordId,
        'file' => $fileKey,
    ];
    return '/docs.php?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
}
function docs_create_outgoing_private_file_access_key(): string
{
    try {
        return 'opf_' . bin2hex(random_bytes(16));
    } catch (Throwable $exception) {
        return 'opf_' . str_replace('.', '', uniqid('', true));
    }
}
function docs_outgoing_file_key_is_signed_access(array $file, string $fileKey): bool
{
    if (!docs_is_outgoing_file_private($file)) {
        return false;
    }
    $accessKey = sanitize_text_field((string) ($file['accessKey'] ?? ''), 200);
    if ($accessKey === '' || $fileKey === '') {
        return false;
    }
    return hash_equals($accessKey, $fileKey);
}
function docs_prepare_outgoing_record_response(array $record, bool $canManageOutgoing = false, $currentUserKeys = '', string $folder = ''): array
{
    $prepared = docs_prepare_outgoing_record($record);
    $recordId = sanitize_text_field((string) ($prepared['id'] ?? ''), 160);
    $canEditRecord = docs_outgoing_record_user_can_edit($prepared, $canManageOutgoing, $currentUserKeys);
    $visibleFiles = [];
    foreach (($prepared['files'] ?? []) as $file) {
        if (!is_array($file)) {
            continue;
        }
        if (docs_is_outgoing_file_private($file)) {
            $hasInheritedOwner = docs_outgoing_file_has_inherited_private_owner($file, $record);
            if (($hasInheritedOwner && !$canManageOutgoing) || !docs_outgoing_file_user_can_access($file, $canManageOutgoing, $currentUserKeys)) {
                $visibleFiles[] = array_filter([
                    'originalName' => 'Приватный файл',
                    'visibility' => 'private',
                    'accessDenied' => true,
                    'restricted' => true,
                    'uploadedBy' => sanitize_text_field((string) ($file['uploadedBy'] ?? ''), 220),
                    'uploadedAt' => sanitize_text_field((string) ($file['uploadedAt'] ?? ''), 80),
                    'size' => isset($file['size']) ? max(0, (int) $file['size']) : 0,
                ], static function ($item) {
                    return $item !== '' && $item !== 0;
                });
                continue;
            }
            $fileKey = sanitize_text_field((string) ($file['accessKey'] ?? ''), 200);
            if ($fileKey === '') {
                $fileKey = sanitize_text_field((string) ($file['storedName'] ?? ($file['originalName'] ?? '')), 255);
            }
            if ($folder !== '' && $recordId !== '' && $fileKey !== '') {
                $file['url'] = docs_build_private_outgoing_file_url($folder, $recordId, $fileKey);
            }
        }
        $visibleFiles[] = $file;
    }
    $prepared['files'] = $visibleFiles;
    $prepared['filesCount'] = count($visibleFiles);
    $fileNames = [];
    foreach ($visibleFiles as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }
    $prepared['filesLabel'] = !empty($fileNames) ? sanitize_text_field(implode(', ', $fileNames), 500) : '';
    $prepared['canEdit'] = $canEditRecord;
    $prepared['canAttach'] = true;
    $prepared['canDelete'] = $canManageOutgoing;
    return $prepared;
}
function docs_decode_outgoing_file_key_list($value): array
{
    if (is_string($value)) {
        $decoded = json_decode($value, true);
        if (is_array($decoded)) {
            $value = $decoded;
        } elseif (trim($value) !== '') {
            $value = [$value];
        } else {
            $value = [];
        }
    }
    if (!is_array($value)) {
        return [];
    }
    $keys = [];
    foreach ($value as $item) {
        if (is_array($item)) {
            foreach (docs_collect_outgoing_file_keys($item) as $key) {
                $keys[$key] = true;
            }
            continue;
        }
        $key = sanitize_text_field((string) $item, 500);
        if ($key !== '') {
            $keys[$key] = true;
        }
    }
    return array_keys($keys);
}
function docs_collect_outgoing_file_keys(array $file): array
{
    $candidates = [
        $file['accessKey'] ?? '',
        $file['storedName'] ?? '',
        $file['originalName'] ?? '',
        $file['url'] ?? '',
    ];
    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $basename = rawurldecode((string) basename($path));
            if ($basename !== '') {
                $candidates[] = $basename;
            }
        }
    }
    $keys = [];
    foreach ($candidates as $candidate) {
        $key = sanitize_text_field((string) $candidate, 500);
        if ($key !== '') {
            $keys[$key] = true;
        }
    }
    return array_keys($keys);
}
function docs_outgoing_file_matches_keys(array $file, array $lookup): bool
{
    if (empty($lookup)) {
        return false;
    }
    foreach (docs_collect_outgoing_file_keys($file) as $key) {
        if (isset($lookup[$key])) {
            return true;
        }
    }
    return false;
}
function docs_get_outgoing_file_path_candidates(string $folder, array $file): array
{
    $paths = [];
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName !== '') {
        $paths[] = docs_get_outgoing_files_root($folder, false, true) . '/' . $storedName;
        $paths[] = ensure_organization_directory($folder) . '/' . $storedName;
        $paths[] = ensure_organization_directory($folder) . '/Исходящие/' . $storedName;
    }
    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $decodedPath = rawurldecode($path);
            $marker = '/documents/' . $folder . '/';
            $position = strpos($decodedPath, $marker);
            if ($position !== false) {
                $relative = substr($decodedPath, $position + strlen($marker));
                $relative = str_replace(['../', '..\\'], '', ltrim($relative, '/\\'));
                if ($relative !== '') {
                    $paths[] = ensure_organization_directory($folder) . '/' . $relative;
                }
            }
        }
    }
    return array_values(array_unique(array_filter($paths, static function ($path): bool {
        return is_string($path) && $path !== '';
    })));
}
function docs_find_private_outgoing_file_by_real_path(string $folder, string $realPath): ?array
{
    $folder = sanitize_folder_name($folder);
    $targetPath = realpath($realPath);
    if ($folder === '' || !is_string($targetPath) || $targetPath === '') {
        return null;
    }
    foreach (docs_load_outgoing_registry($folder) as $record) {
        if (!is_array($record) || empty($record['files']) || !is_array($record['files'])) {
            continue;
        }
        foreach ($record['files'] as $file) {
            if (!is_array($file) || !docs_is_outgoing_file_private($file)) {
                continue;
            }
            foreach (docs_get_outgoing_file_path_candidates($folder, $file) as $pathCandidate) {
                $candidateRealPath = realpath($pathCandidate);
                if (is_string($candidateRealPath) && $candidateRealPath !== '' && hash_equals($targetPath, $candidateRealPath)) {
                    return [
                        'record' => $record,
                        'file' => $file,
                    ];
                }
            }
        }
    }
    return null;
}
function docs_delete_outgoing_file_from_storage(string $folder, array $file): void
{
    foreach (docs_get_outgoing_file_path_candidates($folder, $file) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
    docs_delete_cold_storage_file($file);
}
function docs_get_document_file_path_candidates(string $folder, array $file): array
{
    $paths = [];
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName !== '') {
        $paths[] = ensure_organization_directory($folder) . '/' . $storedName;
    }
    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $decodedPath = rawurldecode($path);
            $marker = '/documents/' . $folder . '/';
            $position = strpos($decodedPath, $marker);
            if ($position !== false) {
                $relative = substr($decodedPath, $position + strlen($marker));
                $relative = str_replace(['../', '..\\'], '', ltrim($relative, '/\\'));
                if ($relative !== '') {
                    $paths[] = ensure_organization_directory($folder) . '/' . $relative;
                }
            }
        }
    }
    return array_values(array_unique(array_filter($paths, static function ($path): bool {
        return is_string($path) && $path !== '';
    })));
}
function docs_delete_document_file_from_storage(string $folder, array $file): void
{
    foreach (docs_get_document_file_path_candidates($folder, $file) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
    docs_delete_cold_storage_file($file);
}
function docs_resolve_unique_storage_target(string $directory, string $storedName): array
{
    $storedName = docs_sanitize_filename($storedName, 'attachment');
    $target = rtrim($directory, '/\\') . '/' . $storedName;
    $duplicateIndex = 2;
    while (is_file($target)) {
        $pathInfo = pathinfo($storedName);
        $extension = isset($pathInfo['extension']) && $pathInfo['extension'] !== '' ? '.' . $pathInfo['extension'] : '';
        $filename = $pathInfo['filename'] ?? $storedName;
        $storedName = $filename . '_' . $duplicateIndex . $extension;
        $target = rtrim($directory, '/\\') . '/' . $storedName;
        $duplicateIndex++;
    }
    return [$storedName, $target];
}
function docs_user_can_manage_outgoing_records(array $accessContext, ?array $sessionAuth = null): bool
{
    if (!is_array($sessionAuth)) {
        return false;
    }
    $role = docs_normalize_assignment_role((string) ($sessionAuth['role'] ?? ''));
    if ($role === 'admin') {
        return true;
    }
    $responsibleRole = docs_normalize_assignment_role((string) ($sessionAuth['responsibleRole'] ?? ''));
    return $responsibleRole === 'admin';
}
function docs_load_outgoing_registry(string $folder): array
{
    $file = get_outgoing_registry_path($folder);
    $decoded = docs_read_json_array_file_with_backup($file);
    if (!is_array($decoded)) {
        if (is_file($file) || is_file($file . '.bak')) {
            log_docs_event('Outgoing registry decode error', [
                'folder' => $folder,
                'path' => $file,
            ]);
        }
        return [];
    }
    $records = [];
    foreach ($decoded as $record) {
        if (is_array($record)) {
            $records[] = docs_prepare_outgoing_record($record);
        }
    }
    return $records;
}
function docs_save_outgoing_registry(string $folder, array $records): void
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . OUTGOING_REGISTRY_FILENAME;
    $json = docs_encode_outgoing_registry_records($records);
    if ($json === null) {
        return;
    }
    if (!docs_write_json_content_atomically($file, $json)) {
        log_docs_event('Outgoing registry write failed', [
            'folder' => $folder,
            'path' => $file,
        ]);
    }
}
function docs_encode_outgoing_registry_records(array $records): ?string
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_outgoing_record($record, 'outgoing', true);
        }
    }
    $json = json_encode(array_values($prepared), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        return null;
    }
    return $json;
}
function docs_lock_outgoing_registry(string $folder): array
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . OUTGOING_REGISTRY_FILENAME;
    $lockFile = $file . '.lock';
    $handle = @fopen($lockFile, 'c+');
    if ($handle === false) {
        log_docs_event('Outgoing registry file open failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        return [null, []];
    }
    if (!flock($handle, LOCK_EX)) {
        log_docs_event('Outgoing registry file lock failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        fclose($handle);
        return [null, []];
    }
    $decoded = docs_read_json_array_file_with_backup($file);
    if (!is_array($decoded) && !is_file($file) && !is_file($file . '.bak')) {
        $records = [];
    } elseif (!is_array($decoded)) {
        log_docs_event('Outgoing registry decode error (locked)', [
            'file' => $file,
            'folder' => $folder,
        ]);
        flock($handle, LOCK_UN);
        fclose($handle);
        return [null, []];
    } else {
        $records = [];
        foreach ($decoded as $record) {
            if (is_array($record)) {
                $records[] = docs_prepare_outgoing_record($record, 'outgoing', true);
            }
        }
    }
    register_shutdown_function(function () use ($handle) {
        if (is_resource($handle)) {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    });
    return [$handle, $records];
}
function docs_save_outgoing_registry_locked($handle, array $records): bool
{
    if (!is_resource($handle)) {
        return false;
    }
    $json = docs_encode_outgoing_registry_records($records);
    if ($json === null) {
        return false;
    }
    $metadata = stream_get_meta_data($handle);
    $lockPath = isset($metadata['uri']) && is_string($metadata['uri']) ? $metadata['uri'] : '';
    if ($lockPath === '' || substr($lockPath, -5) !== '.lock') {
        return false;
    }
    $file = substr($lockPath, 0, -5);
    return docs_write_json_content_atomically($file, $json);
}
function docs_unlock_outgoing_registry($handle): void
{
    if (!is_resource($handle)) {
        return;
    }
    flock($handle, LOCK_UN);
    fclose($handle);
}
function docs_normalize_outgoing_number_for_unique(string $value): string
{
    $normalized = sanitize_text_field($value, 160);
    $normalized = preg_replace('/\s+/u', ' ', trim($normalized));
    if (!is_string($normalized) || $normalized === '') {
        return '';
    }
    return function_exists('mb_strtolower') ? mb_strtolower($normalized, 'UTF-8') : strtolower($normalized);
}
function docs_outgoing_number_exists(array $records, string $outgoingNumber, string $excludeId = ''): bool
{
    $normalizedNumber = docs_normalize_outgoing_number_for_unique($outgoingNumber);
    if ($normalizedNumber === '') {
        return false;
    }
    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }
        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        if ($excludeId !== '' && $recordId === $excludeId) {
            continue;
        }
        $candidate = docs_normalize_outgoing_number_for_unique((string) ($record['outgoingNumber'] ?? ''));
        if ($candidate !== '' && $candidate === $normalizedNumber) {
            return true;
        }
    }
    return false;
}
function docs_prepare_outgoing_records_response(array $records, bool $canManageOutgoing = false, $currentUserKeys = '', string $folder = ''): array
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_outgoing_record_response($record, $canManageOutgoing, $currentUserKeys, $folder);
        }
    }
    return $prepared;
}
function docs_prepare_outgoing_edit_lock($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $token = sanitize_text_field((string) ($value['token'] ?? ''), 120);
    $userLabel = sanitize_text_field((string) ($value['userLabel'] ?? ''), 220);
    $userKey = sanitize_text_field((string) ($value['userKey'] ?? ''), 200);
    $lockedAt = docs_normalize_datetime_iso(isset($value['lockedAt']) ? (string) $value['lockedAt'] : null) ?? '';
    $expiresAt = isset($value['expiresAt']) ? (int) $value['expiresAt'] : 0;
    if ($token === '' || $userKey === '' || $expiresAt <= 0) {
        return [];
    }
    return array_filter([
        'token' => $token,
        'userLabel' => $userLabel !== '' ? $userLabel : 'другой пользователь',
        'userKey' => $userKey,
        'lockedAt' => $lockedAt,
        'expiresAt' => $expiresAt,
    ], static function ($item) {
        return $item !== '';
    });
}
function docs_create_outgoing_edit_lock_token(): string
{
    try {
        return bin2hex(random_bytes(16));
    } catch (Throwable $exception) {
        return str_replace('.', '', uniqid('', true));
    }
}
function docs_outgoing_edit_lock_is_active(array $lock): bool
{
    $prepared = docs_prepare_outgoing_edit_lock($lock);
    return !empty($prepared) && (int) ($prepared['expiresAt'] ?? 0) > time();
}
function docs_outgoing_edit_lock_matches(array $lock, string $token): bool
{
    $prepared = docs_prepare_outgoing_edit_lock($lock);
    if ($token === '' || empty($prepared) || !docs_outgoing_edit_lock_is_active($prepared)) {
        return false;
    }
    return hash_equals((string) ($prepared['token'] ?? ''), $token);
}
function docs_acquire_outgoing_record_edit_lock(
    string $folder,
    string $recordId,
    string $userLabel,
    string $userKey,
    bool $canManageOutgoing = false,
    $currentUserKeys = ''
): array
{
    [$handle, $records] = docs_lock_outgoing_registry($folder);
    if ($handle === null) {
        return [
            'ok' => false,
            'status' => 503,
            'message' => 'Не удалось проверить блокировку записи. Повторите действие.',
            'reason' => 'outgoing_registry_lock_failed',
        ];
    }
    $recordIndex = null;
    foreach ($records as $index => $record) {
        if (is_array($record) && (string) ($record['id'] ?? '') === $recordId) {
            $recordIndex = $index;
            break;
        }
    }
    if ($recordIndex === null) {
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 404,
            'message' => 'Запись исходящей корреспонденции не найдена.',
            'reason' => 'outgoing_record_not_found',
        ];
    }
    if (!docs_outgoing_record_user_can_edit($records[$recordIndex], $canManageOutgoing, $currentUserKeys)) {
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 403,
            'message' => 'Редактировать можно только записи, которые вы добавили.',
            'reason' => 'outgoing_update_forbidden',
        ];
    }
    $existingLock = docs_prepare_outgoing_edit_lock($records[$recordIndex]['editLock'] ?? null);
    if (!empty($existingLock) && docs_outgoing_edit_lock_is_active($existingLock)) {
        $normalizedExistingUserKey = mb_strtolower(trim((string) ($existingLock['userKey'] ?? '')), 'UTF-8');
        $normalizedUserKey = mb_strtolower(trim($userKey), 'UTF-8');
        if ($normalizedExistingUserKey !== '' && $normalizedExistingUserKey === $normalizedUserKey) {
            $records[$recordIndex]['editLock']['expiresAt'] = time() + DOCS_OUTGOING_EDIT_LOCK_TTL;
            docs_save_outgoing_registry_locked($handle, $records);
            docs_unlock_outgoing_registry($handle);
            return [
                'ok' => true,
                'token' => (string) ($existingLock['token'] ?? ''),
                'expiresAt' => $records[$recordIndex]['editLock']['expiresAt'],
            ];
        }
        $lockedBy = sanitize_text_field((string) ($existingLock['userLabel'] ?? 'другой пользователь'), 220);
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 409,
            'message' => 'Эту строку сейчас редактирует ' . $lockedBy . '. Подождите.',
            'reason' => 'outgoing_record_locked',
            'lockedBy' => $lockedBy,
        ];
    }
    $now = time();
    $token = docs_create_outgoing_edit_lock_token();
    $records[$recordIndex]['editLock'] = [
        'token' => $token,
        'userLabel' => $userLabel,
        'userKey' => $userKey,
        'lockedAt' => date('c', $now),
        'expiresAt' => $now + DOCS_OUTGOING_EDIT_LOCK_TTL,
    ];
    if (!docs_save_outgoing_registry_locked($handle, $records)) {
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 500,
            'message' => 'Не удалось заблокировать запись для редактирования. Повторите действие.',
            'reason' => 'outgoing_registry_save_failed',
        ];
    }
    docs_unlock_outgoing_registry($handle);
    return [
        'ok' => true,
        'token' => $token,
        'expiresAt' => $records[$recordIndex]['editLock']['expiresAt'],
    ];
}
function docs_release_outgoing_record_edit_lock(string $folder, string $recordId, string $token): void
{
    if ($recordId === '' || $token === '') {
        return;
    }
    [$handle, $records] = docs_lock_outgoing_registry($folder);
    if ($handle === null) {
        return;
    }
    foreach ($records as $index => $record) {
        if (!is_array($record) || (string) ($record['id'] ?? '') !== $recordId) {
            continue;
        }
        if (docs_outgoing_edit_lock_matches($record['editLock'] ?? [], $token)) {
            unset($records[$index]['editLock']);
            docs_save_outgoing_registry_locked($handle, $records);
        }
        break;
    }
    docs_unlock_outgoing_registry($handle);
}
function docs_build_outgoing_number_sort_key(string $value): array
{
    $normalized = docs_normalize_outgoing_number_for_unique($value);
    if ($normalized === '') {
        return [
            'hasNumber' => false,
            'base' => 0,
            'hasSuffix' => false,
            'suffix' => 0,
            'text' => '',
        ];
    }
    if (preg_match('/^(\d+)(?:\D+(\d+))?/u', $normalized, $matches) === 1) {
        $suffix = isset($matches[2]) && $matches[2] !== '' ? (int) $matches[2] : 0;
        return [
            'hasNumber' => true,
            'base' => (int) $matches[1],
            'hasSuffix' => isset($matches[2]) && $matches[2] !== '',
            'suffix' => $suffix,
            'text' => $normalized,
        ];
    }
    return [
        'hasNumber' => false,
        'base' => 0,
        'hasSuffix' => false,
        'suffix' => 0,
        'text' => $normalized,
    ];
}
function docs_compare_outgoing_numbers_desc(string $left, string $right): int
{
    $leftKey = docs_build_outgoing_number_sort_key($left);
    $rightKey = docs_build_outgoing_number_sort_key($right);
    if ($leftKey['hasNumber'] !== $rightKey['hasNumber']) {
        return $leftKey['hasNumber'] ? -1 : 1;
    }
    if ($leftKey['hasNumber'] && $rightKey['hasNumber']) {
        $baseCompare = $rightKey['base'] <=> $leftKey['base'];
        if ($baseCompare !== 0) {
            return $baseCompare;
        }
        if ($leftKey['hasSuffix'] !== $rightKey['hasSuffix']) {
            return $leftKey['hasSuffix'] ? 1 : -1;
        }
        $suffixCompare = $leftKey['suffix'] <=> $rightKey['suffix'];
        if ($suffixCompare !== 0) {
            return $suffixCompare;
        }
    }
    return strcmp((string) $rightKey['text'], (string) $leftKey['text']);
}
function docs_sort_outgoing_records(array $records): array
{
    usort($records, static function (array $a, array $b): int {
        $numberCompare = docs_compare_outgoing_numbers_desc(
            (string) ($a['outgoingNumber'] ?? ''),
            (string) ($b['outgoingNumber'] ?? '')
        );
        if ($numberCompare !== 0) {
            return $numberCompare;
        }
        $dateA = !empty($a['registeredAt']) ? (string) $a['registeredAt'] : (string) ($a['sendingDate'] ?? '');
        $dateB = !empty($b['registeredAt']) ? (string) $b['registeredAt'] : (string) ($b['sendingDate'] ?? '');
        return strcmp($dateB, $dateA);
    });
    return $records;
}
function docs_sanitize_outgoing_record_payload(array $payload, ?array $existing, string $authorLabel, string $authorKey): array
{
    $now = date('c');
    $base = is_array($existing) ? $existing : [];
    $isNew = empty($base['id']);
    $outgoingNumberFields = ['registryNumber', 'registry_number', 'outgoingNumber', 'outgoing_number'];
    $sendingDateFields = ['registrationDate', 'registration_date', 'sendingDate'];
    $documentIndexFields = ['documentNumber', 'document_number', 'documentIndexNumber', 'document_index_number'];
    $addresseeFields = ['addressee', 'correspondent', 'sender', 'recipient', 'adresat', 'address'];
    $summaryFields = ['summary', 'content', 'description'];
    $executorFields = ['executor'];
    $noteFields = ['note'];
    $record = [
        'id' => $isNew ? docs_create_outgoing_record_id() : sanitize_text_field((string) $base['id'], 160),
        'source' => 'outgoing',
        'outgoingNumber' => docs_payload_first_scalar_text($payload, $outgoingNumberFields, 160),
        'sendingDate' => docs_payload_first_date($payload, $sendingDateFields),
        'documentIndexNumber' => docs_payload_first_scalar_text($payload, $documentIndexFields, 220),
        'documentType' => 'Исходящий',
        'addressee' => docs_payload_first_scalar_text($payload, $addresseeFields, 260),
        'summary' => docs_payload_first_scalar_text($payload, $summaryFields, 1000),
        'files' => docs_prepare_outgoing_files_payload($base['files'] ?? []),
        'executor' => docs_payload_first_scalar_text($payload, $executorFields, 220),
        'note' => docs_payload_first_scalar_text($payload, $noteFields, 500),
        'registeredBy' => $base['registeredBy'] ?? $authorLabel,
        'registeredAt' => $base['registeredAt'] ?? $now,
        'createdBy' => $base['createdBy'] ?? $authorLabel,
        'createdByKey' => $base['createdByKey'] ?? $authorKey,
        'createdAt' => $base['createdAt'] ?? $now,
        'updatedBy' => $authorLabel,
        'updatedByKey' => $authorKey,
        'updatedAt' => $now,
        'deleted' => false,
    ];
    if (!$isNew) {
        $fallbackFields = [
            'outgoingNumber' => [$outgoingNumberFields, 160],
            'sendingDate' => [$sendingDateFields, 0],
            'documentIndexNumber' => [$documentIndexFields, 220],
            'addressee' => [$addresseeFields, 260],
            'summary' => [$summaryFields, 1000],
            'executor' => [$executorFields, 220],
            'note' => [$noteFields, 500],
        ];
        foreach ($fallbackFields as $recordField => $config) {
            [$fields, $maxLength] = $config;
            if (!docs_payload_has_any_field($payload, $fields) && array_key_exists($recordField, $base)) {
                $record[$recordField] = $recordField === 'sendingDate'
                    ? sanitize_date_field((string) $base[$recordField])
                    : sanitize_text_field((string) $base[$recordField], (int) $maxLength);
            }
        }
    }
    return docs_prepare_outgoing_record($record);
}
function docs_validate_outgoing_record(array $record): ?string
{
    if (sanitize_text_field((string) ($record['outgoingNumber'] ?? ''), 160) === '') {
        return 'Поле «Исходящий номер» обязательно для заполнения.';
    }
    if (sanitize_date_field((string) ($record['sendingDate'] ?? '')) === '') {
        return 'Поле «Дата регистрации» обязательно для заполнения.';
    }
    if (sanitize_text_field((string) ($record['addressee'] ?? ''), 260) === '') {
        return 'Поле «Адресат» обязательно для заполнения.';
    }
    return null;
}
function docs_outgoing_validation_reason(string $message): string
{
    if (strpos($message, 'Исходящий номер') !== false) {
        return 'outgoing_number_required';
    }
    if (strpos($message, 'Дата регистрации') !== false) {
        return 'outgoing_sending_date_required';
    }
    if (strpos($message, 'Адресат') !== false) {
        return 'outgoing_addressee_required';
    }
    return 'outgoing_validation_failed';
}
function docs_get_outgoing_files_root(string $folder, bool $create = true, bool $private = false): string
{
    $dir = ensure_organization_directory($folder);
    if ($private) {
        $dir .= '/.outgoing-private';
    }
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }
    if ($private && $create) {
        docs_ensure_private_outgoing_storage_guard($dir);
    }
    return $dir;
}
function docs_build_outgoing_file_public_path(string $folder, string $storedName): string
{
    return build_public_path($folder, $storedName);
}
function docs_normalize_outgoing_file_name(string $originalName, array $record, int $sequence, string $folder = ''): string
{
    return normalize_file_name($originalName, [
        'organization' => (string) ($record['organization'] ?? $folder),
        'registryNumber' => (string) ($record['outgoingNumber'] ?? $record['id'] ?? 'outgoing'),
        'registrationDate' => (string) ($record['sendingDate'] ?? ''),
        'createdAt' => (string) ($record['createdAt'] ?? ''),
    ], $sequence);
}
function docs_apply_outgoing_file_mutation(array &$record, string $folder, array $payload, ?array &$filesPendingDeletion = null): void
{
    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }
    $deleteKeys = docs_decode_outgoing_file_key_list($payload['filesToDelete'] ?? []);
    $hasRemainingPayload = array_key_exists('filesRemaining', $payload);
    $remainingKeys = docs_decode_outgoing_file_key_list($payload['filesRemaining'] ?? []);
    if (empty($deleteKeys) && !$hasRemainingPayload) {
        return;
    }
    $deleteLookup = array_fill_keys($deleteKeys, true);
    $remainingLookup = array_fill_keys($remainingKeys, true);
    $nextFiles = [];
    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }
        $shouldDelete = docs_outgoing_file_matches_keys($file, $deleteLookup);
        if ($hasRemainingPayload && !docs_outgoing_file_matches_keys($file, $remainingLookup)) {
            $shouldDelete = true;
        }
        if ($shouldDelete) {
            if (is_array($filesPendingDeletion)) {
                $filesPendingDeletion[] = $file;
            } else {
                docs_delete_outgoing_file_from_storage($folder, $file);
            }
            continue;
        }
        $nextFiles[] = $file;
    }
    $record['files'] = $nextFiles;
}
function docs_attach_uploaded_outgoing_files_to_record(array &$record, string $folder, string $errorPrefix, string $authorLabel = '', string $authorKey = '', bool $privateFiles = false): void
{
    if (empty($_FILES['attachments']) || !isset($_FILES['attachments']['name'])) {
        return;
    }
    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }
    if ($privateFiles && docs_normalize_outgoing_user_key($authorKey) === '') {
        respond_error('Приватные файлы нельзя сохранить без идентификатора пользователя.', 403, [
            'reason' => 'outgoing_private_owner_required',
        ]);
    }
    $dir = docs_get_outgoing_files_root($folder, true, $privateFiles);
    $names = $_FILES['attachments']['name'];
    $tmpNames = $_FILES['attachments']['tmp_name'];
    $errors = $_FILES['attachments']['error'];
    $sizes = $_FILES['attachments']['size'];
    $createdUploadTargets = [];
    $failUpload = static function (string $message, int $status = 500, array $details = []) use (&$createdUploadTargets): void {
        foreach ($createdUploadTargets as $createdUploadTarget) {
            if (is_string($createdUploadTarget) && $createdUploadTarget !== '' && is_file($createdUploadTarget)) {
                @unlink($createdUploadTarget);
            }
        }
        respond_error($message, $status, $details);
    };
    $storeFile = static function (string $originalName, string $tmpPath, int $size) use (&$record, $folder, $dir, &$createdUploadTargets, $failUpload, $errorPrefix, $authorLabel, $authorKey, $privateFiles): void {
        $validationError = docs_validate_uploaded_attachment($originalName, $size);
        if ($validationError !== null) {
            $failUpload($errorPrefix . ': ' . $validationError, 422, ['reason' => 'invalid_attachment']);
        }
        if (!is_uploaded_file($tmpPath)) {
            $failUpload(
                $errorPrefix . ': сервер не получил файл «' . $originalName . '». Повторите сохранение.',
                500,
                ['reason' => 'upload_tmp_missing']
            );
        }
        [$storedName, $target] = docs_resolve_unique_storage_target(
            $dir,
            docs_normalize_outgoing_file_name($originalName, $record, count($record['files']) + 1, $folder)
        );
        if (!move_uploaded_file($tmpPath, $target)) {
            $failUpload(
                $errorPrefix . ': не удалось сохранить файл «' . $originalName . '» в хранилище.',
                500,
                ['reason' => 'upload_move_failed']
            );
        }
        $createdUploadTargets[] = $target;
        $fileOptimization = docs_optimize_uploaded_attachment_file($target, $originalName, $size);
        $visibility = $privateFiles ? 'private' : 'public';
        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        $accessKey = $privateFiles ? docs_create_outgoing_private_file_access_key() : '';
        $fileEntry = [
            'originalName' => $originalName,
            'storedName' => $storedName,
            'size' => (int) ($fileOptimization['size'] ?? ($size > 0 ? $size : (filesize($target) ?: 0))),
            'uploadedAt' => date('c'),
            'url' => $privateFiles && $recordId !== ''
                ? docs_build_private_outgoing_file_url($folder, $recordId, $accessKey)
                : docs_build_outgoing_file_public_path($folder, $storedName),
            'accessKey' => $accessKey,
            'visibility' => $visibility,
            'uploadedBy' => $authorLabel !== '' ? $authorLabel : sanitize_text_field((string) ($record['updatedBy'] ?? ($record['createdBy'] ?? '')), 220),
            'uploadedByKey' => $privateFiles ? $authorKey : ($authorKey !== '' ? $authorKey : sanitize_text_field((string) ($record['updatedByKey'] ?? ($record['createdByKey'] ?? '')), 200)),
        ];
        $relativePath = ($privateFiles ? '.outgoing-private/' : '') . $storedName;
        $record['files'][] = docs_apply_cold_storage_metadata($fileEntry, $folder, $relativePath, $target);
    };
    if (is_array($names)) {
        $count = count($names);
        for ($i = 0; $i < $count; $i++) {
            $uploadError = isset($errors[$i]) ? (int) $errors[$i] : UPLOAD_ERR_NO_FILE;
            $uploadName = isset($names[$i]) ? docs_normalize_uploaded_filename((string) $names[$i]) : 'Файл';
            if ($uploadError !== UPLOAD_ERR_OK) {
                if ($uploadError === UPLOAD_ERR_NO_FILE && trim((string) ($names[$i] ?? '')) === '') {
                    continue;
                }
                $failUpload(
                    $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
                    500,
                    ['reason' => 'upload_error', 'uploadError' => $uploadError]
                );
            }
            $storeFile($uploadName, (string) ($tmpNames[$i] ?? ''), (int) ($sizes[$i] ?? 0));
        }
        return;
    }
    $uploadError = (int) $errors;
    $uploadName = is_string($names) && trim($names) !== ''
        ? docs_normalize_uploaded_filename($names)
        : 'Файл';
    if ($uploadError === UPLOAD_ERR_NO_FILE && (!is_string($names) || trim($names) === '')) {
        return;
    }
    if ($uploadError !== UPLOAD_ERR_OK) {
        $failUpload(
            $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
            500,
            ['reason' => 'upload_error', 'uploadError' => $uploadError]
        );
    }
    $storeFile($uploadName, (string) $tmpNames, (int) $sizes);
}
function docs_delete_outgoing_record_files(string $folder, array $record): void
{
    if (empty($record['files']) || !is_array($record['files'])) {
        return;
    }
    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }
        docs_delete_outgoing_file_from_storage($folder, $file);
    }
}
function docs_user_can_manage_orders(array $accessContext, ?array $sessionAuth = null): bool
{
    return docs_user_can_manage_outgoing_records($accessContext, $sessionAuth);
}
function docs_create_order_record_id(): string
{
    try {
        return 'order_' . bin2hex(random_bytes(8));
    } catch (Throwable $exception) {
        return 'order_' . str_replace('.', '', uniqid('', true));
    }
}
function docs_build_order_file_url(string $folder, string $recordId, string $fileKey, string $journalType = 'orders'): string
{
    $params = [
        'action' => 'orders_file',
        'organization' => $folder,
        'record_id' => $recordId,
        'file' => $fileKey,
    ];
    $type = docs_normalize_orders_journal_type($journalType);
    if ($type !== 'orders') {
        $params['journal_type'] = $type;
    }
    return '/docs.php?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
}
function docs_prepare_order_files_payload($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $files = [];
    foreach ($value as $file) {
        if (!is_array($file)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
        if ($storedName === '' && $url === '') {
            continue;
        }
        $preparedFile = array_filter([
            'originalName' => sanitize_text_field((string) ($file['originalName'] ?? ($file['name'] ?? $storedName)), 255),
            'storedName' => $storedName,
            'size' => isset($file['size']) ? max(0, (int) $file['size']) : 0,
            'uploadedAt' => docs_normalize_datetime_iso(isset($file['uploadedAt']) ? (string) $file['uploadedAt'] : null) ?? '',
            'url' => $url,
            'uploadedBy' => sanitize_text_field((string) ($file['uploadedBy'] ?? ''), 220),
            'uploadedByKey' => sanitize_text_field((string) ($file['uploadedByKey'] ?? ''), 200),
        ], static function ($item) {
            return $item !== '' && $item !== 0;
        });
        foreach (docs_prepare_cold_storage_file_payload($file) as $key => $item) {
            $preparedFile[$key] = $item;
        }
        $files[] = $preparedFile;
    }
    return $files;
}
function docs_prepare_order_record(array $record, bool $includeInternal = false, string $journalType = 'orders'): array
{
    $type = docs_normalize_orders_journal_type($journalType);
    $files = docs_prepare_order_files_payload($record['files'] ?? []);
    $fileNames = [];
    foreach ($files as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }
    $prepared = [
        'id' => sanitize_text_field((string) ($record['id'] ?? ''), 160),
        'source' => $type,
        'orderNumber' => sanitize_text_field((string) ($record['orderNumber'] ?? ''), 160),
        'orderDate' => sanitize_date_field(isset($record['orderDate']) ? (string) $record['orderDate'] : ''),
        'summary' => sanitize_text_field((string) ($record['summary'] ?? ''), 1000),
        'executor' => sanitize_text_field((string) ($record['executor'] ?? ''), 220),
        'files' => $files,
        'filesLabel' => !empty($fileNames)
            ? sanitize_text_field(implode(', ', $fileNames), 500)
            : sanitize_text_field((string) ($record['filesLabel'] ?? ''), 500),
        'filesCount' => count($files),
        'createdBy' => sanitize_text_field((string) ($record['createdBy'] ?? ''), 220),
        'createdByKey' => sanitize_text_field((string) ($record['createdByKey'] ?? ''), 200),
        'createdAt' => docs_normalize_datetime_iso(isset($record['createdAt']) ? (string) $record['createdAt'] : null) ?? '',
        'updatedBy' => sanitize_text_field((string) ($record['updatedBy'] ?? ''), 220),
        'updatedByKey' => sanitize_text_field((string) ($record['updatedByKey'] ?? ''), 200),
        'updatedAt' => docs_normalize_datetime_iso(isset($record['updatedAt']) ? (string) $record['updatedAt'] : null) ?? '',
        'deleted' => !empty($record['deleted']),
    ];
    if ($prepared['id'] === '') {
        $prepared['id'] = docs_create_order_record_id();
    }
    if ($includeInternal && isset($record['editLock']) && is_array($record['editLock'])) {
        $prepared['editLock'] = $record['editLock'];
    }
    return $prepared;
}
function docs_prepare_order_record_response(array $record, bool $canManageOrders, string $folder = '', string $journalType = 'orders'): array
{
    $prepared = docs_prepare_order_record($record, false, $journalType);
    $recordId = sanitize_text_field((string) ($prepared['id'] ?? ''), 160);
    $visibleFiles = [];
    foreach (($prepared['files'] ?? []) as $file) {
        if (!is_array($file)) {
            continue;
        }
        $fileKey = sanitize_text_field((string) ($file['storedName'] ?? ($file['originalName'] ?? '')), 255);
        if ($folder !== '' && $recordId !== '' && $fileKey !== '') {
            $file['url'] = docs_build_order_file_url($folder, $recordId, $fileKey, $journalType);
        }
        $file['visibility'] = 'public';
        $visibleFiles[] = $file;
    }
    $prepared['files'] = $visibleFiles;
    $prepared['filesCount'] = count($visibleFiles);
    $fileNames = [];
    foreach ($visibleFiles as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }
    $prepared['filesLabel'] = !empty($fileNames) ? sanitize_text_field(implode(', ', $fileNames), 500) : '';
    $prepared['canEdit'] = $canManageOrders;
    $prepared['canAttach'] = $canManageOrders;
    $prepared['canDelete'] = $canManageOrders;
    return $prepared;
}
function docs_prepare_order_records_response(array $records, bool $canManageOrders, string $folder = '', string $journalType = 'orders'): array
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_order_record_response($record, $canManageOrders, $folder, $journalType);
        }
    }
    return $prepared;
}
function docs_load_orders_registry(string $folder, string $journalType = 'orders'): array
{
    $file = get_orders_registry_path($folder, $journalType);
    $decoded = docs_read_json_array_file_with_backup($file);
    if (!is_array($decoded)) {
        if (is_file($file) || is_file($file . '.bak')) {
            log_docs_event('Orders registry decode error', [
                'folder' => $folder,
                'path' => $file,
            ]);
        }
        return [];
    }
    $records = [];
    foreach ($decoded as $record) {
        if (is_array($record)) {
            $records[] = docs_prepare_order_record($record, false, $journalType);
        }
    }
    return $records;
}
function docs_encode_orders_registry_records(array $records, string $journalType = 'orders'): ?string
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_order_record($record, true, $journalType);
        }
    }
    $json = json_encode(array_values($prepared), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    return $json === false ? null : $json;
}
function docs_lock_orders_registry(string $folder, string $journalType = 'orders'): array
{
    ensure_organization_directory($folder);
    $file = get_orders_registry_path($folder, $journalType);
    $lockFile = $file . '.lock';
    $handle = @fopen($lockFile, 'c+');
    if ($handle === false) {
        log_docs_event('Orders registry file open failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        return [null, []];
    }
    if (!flock($handle, LOCK_EX)) {
        log_docs_event('Orders registry file lock failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        fclose($handle);
        return [null, []];
    }
    $decoded = docs_read_json_array_file_with_backup($file);
    if (!is_array($decoded) && !is_file($file) && !is_file($file . '.bak')) {
        $records = [];
    } elseif (!is_array($decoded)) {
        log_docs_event('Orders registry decode error (locked)', [
            'file' => $file,
            'folder' => $folder,
        ]);
        flock($handle, LOCK_UN);
        fclose($handle);
        return [null, []];
    } else {
        $records = [];
        foreach ($decoded as $record) {
            if (is_array($record)) {
                $records[] = docs_prepare_order_record($record, true, $journalType);
            }
        }
    }
    register_shutdown_function(function () use ($handle) {
        if (is_resource($handle)) {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    });
    return [$handle, $records];
}
function docs_save_orders_registry_locked($handle, array $records, string $journalType = 'orders'): bool
{
    if (!is_resource($handle)) {
        return false;
    }
    $json = docs_encode_orders_registry_records($records, $journalType);
    if ($json === null) {
        return false;
    }
    $metadata = stream_get_meta_data($handle);
    $lockPath = isset($metadata['uri']) && is_string($metadata['uri']) ? $metadata['uri'] : '';
    if ($lockPath === '' || substr($lockPath, -5) !== '.lock') {
        return false;
    }
    $file = substr($lockPath, 0, -5);
    return docs_write_json_content_atomically($file, $json);
}
function docs_unlock_orders_registry($handle): void
{
    if (!is_resource($handle)) {
        return;
    }
    flock($handle, LOCK_UN);
    fclose($handle);
}
function docs_normalize_order_number_for_unique(string $value): string
{
    $normalized = sanitize_text_field($value, 160);
    $normalized = preg_replace('/\s+/u', ' ', trim($normalized));
    if (!is_string($normalized) || $normalized === '') {
        return '';
    }
    return function_exists('mb_strtolower') ? mb_strtolower($normalized, 'UTF-8') : strtolower($normalized);
}
function docs_order_number_exists(array $records, string $orderNumber, string $excludeId = ''): bool
{
    $normalizedNumber = docs_normalize_order_number_for_unique($orderNumber);
    if ($normalizedNumber === '') {
        return false;
    }
    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }
        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        if ($excludeId !== '' && $recordId === $excludeId) {
            continue;
        }
        $candidate = docs_normalize_order_number_for_unique((string) ($record['orderNumber'] ?? ''));
        if ($candidate !== '' && $candidate === $normalizedNumber) {
            return true;
        }
    }
    return false;
}
function docs_build_order_number_sort_key(string $value): array
{
    $normalized = docs_normalize_order_number_for_unique($value);
    if ($normalized === '') {
        return [
            'hasNumber' => false,
            'base' => 0,
            'suffix' => 0,
            'text' => '',
        ];
    }
    if (preg_match('/^(\d+)(?:\D+(\d+))?/u', $normalized, $matches) === 1) {
        return [
            'hasNumber' => true,
            'base' => (int) $matches[1],
            'suffix' => isset($matches[2]) && $matches[2] !== '' ? (int) $matches[2] : 0,
            'text' => $normalized,
        ];
    }
    return [
        'hasNumber' => false,
        'base' => 0,
        'suffix' => 0,
        'text' => $normalized,
    ];
}
function docs_generate_next_order_number(array $records): string
{
    $maxNumber = 0;
    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }
        $key = docs_build_order_number_sort_key((string) ($record['orderNumber'] ?? ''));
        if (!empty($key['hasNumber']) && (int) ($key['base'] ?? 0) > $maxNumber) {
            $maxNumber = (int) $key['base'];
        }
    }
    return (string) ($maxNumber + 1);
}
function docs_compare_order_numbers_desc(string $left, string $right): int
{
    $leftKey = docs_build_order_number_sort_key($left);
    $rightKey = docs_build_order_number_sort_key($right);
    if ($leftKey['hasNumber'] !== $rightKey['hasNumber']) {
        return $leftKey['hasNumber'] ? -1 : 1;
    }
    if ($leftKey['hasNumber'] && $rightKey['hasNumber']) {
        $baseCompare = $rightKey['base'] <=> $leftKey['base'];
        if ($baseCompare !== 0) {
            return $baseCompare;
        }
        $suffixCompare = $rightKey['suffix'] <=> $leftKey['suffix'];
        if ($suffixCompare !== 0) {
            return $suffixCompare;
        }
    }
    return strcmp((string) $rightKey['text'], (string) $leftKey['text']);
}
function docs_sort_order_records(array $records): array
{
    usort($records, static function (array $a, array $b): int {
        $dateCompare = strcmp((string) ($b['orderDate'] ?? ''), (string) ($a['orderDate'] ?? ''));
        if ($dateCompare !== 0) {
            return $dateCompare;
        }
        return docs_compare_order_numbers_desc(
            (string) ($a['orderNumber'] ?? ''),
            (string) ($b['orderNumber'] ?? '')
        );
    });
    return $records;
}
function docs_sanitize_order_record_payload(array $payload, ?array $existing, string $authorLabel, string $authorKey, string $journalType = 'orders'): array
{
    $type = docs_normalize_orders_journal_type($journalType);
    $now = date('c');
    $base = is_array($existing) ? $existing : [];
    $isNew = empty($base['id']);
    $orderNumberFields = ['orderNumber', 'order_number', 'registryNumber', 'number'];
    $orderDateFields = ['orderDate', 'order_date', 'registrationDate', 'date'];
    $summaryFields = ['summary', 'content', 'description'];
    $executorFields = ['executor'];
    $record = [
        'id' => $isNew ? docs_create_order_record_id() : sanitize_text_field((string) $base['id'], 160),
        'source' => $type,
        'orderNumber' => docs_payload_first_scalar_text($payload, $orderNumberFields, 160),
        'orderDate' => docs_payload_first_date($payload, $orderDateFields),
        'summary' => docs_payload_first_scalar_text($payload, $summaryFields, 1000),
        'executor' => docs_payload_first_scalar_text($payload, $executorFields, 220),
        'files' => docs_prepare_order_files_payload($base['files'] ?? []),
        'createdBy' => $base['createdBy'] ?? $authorLabel,
        'createdByKey' => $base['createdByKey'] ?? $authorKey,
        'createdAt' => $base['createdAt'] ?? $now,
        'updatedBy' => $authorLabel,
        'updatedByKey' => $authorKey,
        'updatedAt' => $now,
        'deleted' => false,
    ];
    if (!$isNew) {
        $fallbackFields = [
            'orderNumber' => [$orderNumberFields, 160],
            'orderDate' => [$orderDateFields, 0],
            'summary' => [$summaryFields, 1000],
            'executor' => [$executorFields, 220],
        ];
        foreach ($fallbackFields as $recordField => $config) {
            [$fields, $maxLength] = $config;
            if (!docs_payload_has_any_field($payload, $fields) && array_key_exists($recordField, $base)) {
                $record[$recordField] = $recordField === 'orderDate'
                    ? sanitize_date_field((string) $base[$recordField])
                    : sanitize_text_field((string) $base[$recordField], (int) $maxLength);
            }
        }
    }
    return docs_prepare_order_record($record, false, $type);
}
function docs_validate_order_record(array $record, string $journalType = 'orders'): ?string
{
    $meta = docs_get_orders_journal_meta($journalType);
    if (sanitize_text_field((string) ($record['orderNumber'] ?? ''), 160) === '') {
        return 'Поле «' . $meta['numberLabel'] . '» обязательно для заполнения.';
    }
    if (sanitize_date_field((string) ($record['orderDate'] ?? '')) === '') {
        return 'Поле «Дата» обязательно для заполнения.';
    }
    if (sanitize_text_field((string) ($record['summary'] ?? ''), 1000) === '') {
        return 'Поле «Краткое содержание» обязательно для заполнения.';
    }
    return null;
}
function docs_order_validation_reason(string $message): string
{
    if (strpos($message, '№ приказа') !== false
        || strpos($message, '№ распоряжения') !== false
        || strpos($message, '№ взыскания') !== false) {
        return 'order_number_required';
    }
    if (strpos($message, 'Дата') !== false) {
        return 'order_date_required';
    }
    if (strpos($message, 'Краткое содержание') !== false) {
        return 'order_summary_required';
    }
    return 'order_validation_failed';
}
function docs_get_order_files_root(string $folder, bool $create = true, string $journalType = 'orders'): string
{
    $meta = docs_get_orders_journal_meta($journalType);
    $dir = ensure_organization_directory($folder) . '/' . $meta['directory'];
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }
    return $dir;
}
function docs_build_order_file_public_path(string $folder, string $storedName, string $journalType = 'orders'): string
{
    $meta = docs_get_orders_journal_meta($journalType);
    return build_public_path($folder, $meta['directory'] . '/' . $storedName);
}
function docs_normalize_order_file_name(string $originalName, array $record, int $sequence, string $folder = ''): string
{
    return normalize_file_name($originalName, [
        'organization' => (string) ($record['organization'] ?? $folder),
        'registryNumber' => (string) ($record['orderNumber'] ?? $record['id'] ?? 'order'),
        'registrationDate' => (string) ($record['orderDate'] ?? ''),
        'createdAt' => (string) ($record['createdAt'] ?? ''),
    ], $sequence);
}
function docs_get_order_file_path_candidates(string $folder, array $file, string $journalType = 'orders'): array
{
    $paths = [];
    $meta = docs_get_orders_journal_meta($journalType);
    $organizationDir = ensure_organization_directory($folder);
    $fileNames = [];
    $fileNameCandidates = [
        $file['storedName'] ?? '',
        $file['originalName'] ?? '',
        $file['name'] ?? '',
    ];
    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $basename = rawurldecode((string) basename($path));
            if ($basename !== '') {
                $fileNameCandidates[] = $basename;
            }
        }
    }
    foreach ($fileNameCandidates as $candidate) {
        $name = sanitize_text_field((string) $candidate, 255);
        if ($name !== '') {
            $fileNames[$name] = true;
        }
    }
    $directories = [
        docs_get_order_files_root($folder, false, $journalType),
        $organizationDir . '/' . $meta['directory'],
        $organizationDir,
        $organizationDir . '/Приказы',
        $organizationDir . '/Распоряжения',
        $organizationDir . '/Дисциплинарные взыскания',
    ];
    foreach (array_keys($fileNames) as $fileName) {
        foreach ($directories as $directory) {
            $paths[] = rtrim($directory, '/\\') . '/' . $fileName;
        }
    }
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $decodedPath = rawurldecode($path);
            $marker = '/documents/' . $folder . '/';
            $position = strpos($decodedPath, $marker);
            if ($position !== false) {
                $relative = substr($decodedPath, $position + strlen($marker));
                $relative = str_replace(['../', '..\\'], '', ltrim($relative, '/\\'));
                if ($relative !== '') {
                    $paths[] = $organizationDir . '/' . $relative;
                }
            }
        }
    }
    return array_values(array_unique(array_filter($paths, static function ($path): bool {
        return is_string($path) && $path !== '';
    })));
}
function docs_delete_order_file_from_storage(string $folder, array $file, string $journalType = 'orders'): void
{
    foreach (docs_get_order_file_path_candidates($folder, $file, $journalType) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
    docs_delete_cold_storage_file($file);
}
function docs_delete_order_file_local_copies(string $folder, array $file, string $journalType = 'orders'): void
{
    foreach (docs_get_order_file_path_candidates($folder, $file, $journalType) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
}
function docs_delete_order_record_files(string $folder, array $record, string $journalType = 'orders'): void
{
    if (empty($record['files']) || !is_array($record['files'])) {
        return;
    }
    foreach ($record['files'] as $file) {
        if (is_array($file)) {
            docs_delete_order_file_from_storage($folder, $file, $journalType);
        }
    }
}
function docs_apply_order_file_mutation(array &$record, string $folder, array $payload, ?array &$filesPendingDeletion = null, string $journalType = 'orders'): void
{
    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }
    $deleteKeys = docs_decode_outgoing_file_key_list($payload['filesToDelete'] ?? []);
    $hasRemainingPayload = array_key_exists('filesRemaining', $payload);
    $remainingKeys = docs_decode_outgoing_file_key_list($payload['filesRemaining'] ?? []);
    if (empty($deleteKeys) && !$hasRemainingPayload) {
        return;
    }
    $deleteLookup = array_fill_keys($deleteKeys, true);
    $remainingLookup = array_fill_keys($remainingKeys, true);
    $nextFiles = [];
    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }
        $shouldDelete = docs_outgoing_file_matches_keys($file, $deleteLookup);
        if ($hasRemainingPayload && !docs_outgoing_file_matches_keys($file, $remainingLookup)) {
            $shouldDelete = true;
        }
        if ($shouldDelete) {
            if (is_array($filesPendingDeletion)) {
                $filesPendingDeletion[] = $file;
            } else {
                docs_delete_order_file_from_storage($folder, $file, $journalType);
            }
            continue;
        }
        $nextFiles[] = $file;
    }
    $record['files'] = $nextFiles;
}
function docs_attach_uploaded_order_files_to_record(
    array &$record,
    string $folder,
    string $errorPrefix,
    string $authorLabel = '',
    string $authorKey = '',
    string $journalType = 'orders',
    ?array &$createdFiles = null,
    ?array &$coldStorageUploads = null
): void
{
    if (empty($_FILES['attachments']) || !isset($_FILES['attachments']['name'])) {
        return;
    }
    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }
    $dir = docs_get_order_files_root($folder, true, $journalType);
    $names = $_FILES['attachments']['name'];
    $tmpNames = $_FILES['attachments']['tmp_name'];
    $errors = $_FILES['attachments']['error'];
    $sizes = $_FILES['attachments']['size'];
    $createdUploadTargets = [];
    $failUpload = static function (string $message, int $status = 500, array $details = []) use (&$createdUploadTargets): void {
        foreach ($createdUploadTargets as $createdUploadTarget) {
            if (is_string($createdUploadTarget) && $createdUploadTarget !== '' && is_file($createdUploadTarget)) {
                @unlink($createdUploadTarget);
            }
        }
        respond_error($message, $status, $details);
    };
    $storeFile = static function (string $originalName, string $tmpPath, int $size) use (&$record, $folder, $dir, &$createdUploadTargets, &$createdFiles, &$coldStorageUploads, $failUpload, $errorPrefix, $authorLabel, $authorKey, $journalType): void {
        $validationError = docs_validate_uploaded_attachment($originalName, $size);
        if ($validationError !== null) {
            $failUpload($errorPrefix . ': ' . $validationError, 422, ['reason' => 'invalid_attachment']);
        }
        if (!is_uploaded_file($tmpPath)) {
            $failUpload(
                $errorPrefix . ': сервер не получил файл «' . $originalName . '». Повторите сохранение.',
                500,
                ['reason' => 'upload_tmp_missing']
            );
        }
        [$storedName, $target] = docs_resolve_unique_storage_target(
            $dir,
            docs_normalize_order_file_name($originalName, $record, count($record['files']) + 1, $folder)
        );
        if (!move_uploaded_file($tmpPath, $target)) {
            $failUpload(
                $errorPrefix . ': не удалось сохранить файл «' . $originalName . '» в хранилище.',
                500,
                ['reason' => 'upload_move_failed']
            );
        }
        $createdUploadTargets[] = $target;
        $fileOptimization = docs_optimize_uploaded_attachment_file($target, $originalName, $size);
        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        $fileEntry = [
            'originalName' => $originalName,
            'storedName' => $storedName,
            'size' => (int) ($fileOptimization['size'] ?? ($size > 0 ? $size : (filesize($target) ?: 0))),
            'uploadedAt' => date('c'),
            'url' => $recordId !== ''
                ? docs_build_order_file_url($folder, $recordId, $storedName, $journalType)
                : docs_build_order_file_public_path($folder, $storedName, $journalType),
            'uploadedBy' => $authorLabel !== '' ? $authorLabel : sanitize_text_field((string) ($record['updatedBy'] ?? ($record['createdBy'] ?? '')), 220),
            'uploadedByKey' => $authorKey !== '' ? $authorKey : sanitize_text_field((string) ($record['updatedByKey'] ?? ($record['createdByKey'] ?? '')), 200),
        ];
        $relativePath = docs_get_orders_journal_meta($journalType)['directory'] . '/' . $storedName;
        $fileEntry = docs_apply_cold_storage_state($fileEntry, $folder, $relativePath, 'pending');
        if (is_array($createdFiles)) {
            $createdFiles[] = $fileEntry;
        }
        if (is_array($coldStorageUploads)) {
            $coldStorageUploads[] = [
                'recordId' => $recordId,
                'storedName' => $storedName,
                'localPath' => $target,
                'relativePath' => $relativePath,
            ];
        }
        $record['files'][] = $fileEntry;
    };
    if (is_array($names)) {
        $count = count($names);
        for ($i = 0; $i < $count; $i++) {
            $uploadError = isset($errors[$i]) ? (int) $errors[$i] : UPLOAD_ERR_NO_FILE;
            $uploadName = isset($names[$i]) ? docs_normalize_uploaded_filename((string) $names[$i]) : 'Файл';
            if ($uploadError !== UPLOAD_ERR_OK) {
                if ($uploadError === UPLOAD_ERR_NO_FILE && trim((string) ($names[$i] ?? '')) === '') {
                    continue;
                }
                $failUpload(
                    $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
                    500,
                    ['reason' => 'upload_error', 'uploadError' => $uploadError]
                );
            }
            $storeFile($uploadName, (string) ($tmpNames[$i] ?? ''), (int) ($sizes[$i] ?? 0));
        }
        return;
    }
    $uploadError = (int) $errors;
    $uploadName = is_string($names) && trim($names) !== ''
        ? docs_normalize_uploaded_filename($names)
        : 'Файл';
    if ($uploadError === UPLOAD_ERR_NO_FILE && (!is_string($names) || trim($names) === '')) {
        return;
    }
    if ($uploadError !== UPLOAD_ERR_OK) {
        $failUpload(
            $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
            500,
            ['reason' => 'upload_error', 'uploadError' => $uploadError]
        );
    }
    $storeFile($uploadName, (string) $tmpNames, (int) $sizes);
}
function docs_sync_order_files_to_cold_storage(string $folder, string $journalType, array $uploads): void
{
    if (empty($uploads)) {
        return;
    }
    $resultsByFile = [];
    foreach ($uploads as $upload) {
        if (!is_array($upload)) {
            continue;
        }
        $recordId = sanitize_text_field((string) ($upload['recordId'] ?? ''), 160);
        $storedName = sanitize_text_field((string) ($upload['storedName'] ?? ''), 255);
        $localPath = (string) ($upload['localPath'] ?? '');
        $relativePath = docs_normalize_cold_storage_relative_path((string) ($upload['relativePath'] ?? ''));
        if ($recordId === '' || $storedName === '' || $localPath === '' || $relativePath === '') {
            continue;
        }
        $result = docs_upload_file_to_cold_storage($localPath, $folder, $relativePath);
        $resultsByFile[$recordId . "\n" . $storedName] = [
            'recordId' => $recordId,
            'storedName' => $storedName,
            'localPath' => $localPath,
            'relativePath' => $relativePath,
            'result' => $result,
        ];
    }
    if (empty($resultsByFile)) {
        return;
    }
    [$handle, $records] = docs_lock_orders_registry($folder, $journalType);
    if ($handle === null) {
        docs_write_response_log('Не удалось обновить S3-статус файлов журнала: реестр заблокирован', [
            'folder' => $folder,
            'journalType' => $journalType,
            'filesCount' => count($resultsByFile),
        ]);
        return;
    }
    $changed = false;
    try {
        foreach ($records as &$record) {
            if (!is_array($record)) {
                continue;
            }
            $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
            if ($recordId === '' || empty($record['files']) || !is_array($record['files'])) {
                continue;
            }
            foreach ($record['files'] as &$file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                if ($storedName === '') {
                    continue;
                }
                $resultKey = $recordId . "\n" . $storedName;
                if (!isset($resultsByFile[$resultKey])) {
                    continue;
                }
                $resultEntry = $resultsByFile[$resultKey];
                $result = is_array($resultEntry['result'] ?? null) ? $resultEntry['result'] : [];
                $file = docs_apply_cold_storage_state(
                    $file,
                    $folder,
                    (string) ($resultEntry['relativePath'] ?? ''),
                    !empty($result['ok']) ? 'synced' : 'local_fallback',
                    $result
                );
                if (!empty($result['ok'])) {
                    docs_delete_order_file_local_copies($folder, $file, $journalType);
                }
                $changed = true;
            }
            unset($file);
        }
        unset($record);
        if ($changed && !docs_save_orders_registry_locked($handle, $records, $journalType)) {
            docs_write_response_log('Не удалось сохранить S3-статус файлов журнала', [
                'folder' => $folder,
                'journalType' => $journalType,
                'filesCount' => count($resultsByFile),
            ]);
        }
    } finally {
        docs_unlock_orders_registry($handle);
    }
}
function docs_respond_orders_success_with_cold_storage(
    array $payload,
    string $folder,
    string $journalType,
    array $uploads
): void
{
    if (empty($uploads)) {
        respond_success($payload);
    }
    $backgroundTask = static function () use ($folder, $journalType, $uploads): void {
        docs_sync_order_files_to_cold_storage($folder, $journalType, $uploads);
    };
    respond_success_with_background_fallback($payload, $backgroundTask);
}
function docs_get_organization_template_filename(string $folder): string
{
    return $folder . '_template.docx';
}
function docs_get_organization_template_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . docs_get_organization_template_filename($folder);
}
function docs_build_organization_template_file_url(string $organization, string $version = '', string $disposition = 'inline'): string
{
    $params = [
        'action' => 'organization_template_file',
        'organization' => $organization,
        'disposition' => strtolower(trim($disposition)) === 'attachment' ? 'attachment' : 'inline',
    ];
    if ($version !== '') {
        $params['v'] = $version;
    }
    return '/docs.php?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
}
function docs_get_organization_template_descriptor(string $organization): array
{
    $folder = sanitize_folder_name($organization);
    $templateName = docs_get_organization_template_filename($folder);
    $templatePath = docs_get_organization_template_path($folder);
    $localExists = is_file($templatePath) && is_readable($templatePath);
    $localSize = $localExists ? (int) (@filesize($templatePath) ?: 0) : 0;
    $localMtime = $localExists ? (int) (@filemtime($templatePath) ?: time()) : 0;
    $exists = $localExists;
    $cacheStamp = $localMtime;
    if ($cacheStamp <= 0) {
        $cacheStamp = time();
    }
    $templateUrl = $exists
        ? docs_build_organization_template_file_url($organization, (string) $cacheStamp, 'inline')
        : '';
    $viewerUrl = $exists && $templateUrl !== ''
        ? 'https://view.officeapps.live.com/op/view.aspx?src='
            . rawurlencode(docs_resolve_application_base_url() . $templateUrl)
        : '';
    return [
        'exists' => $exists,
        'fileName' => $templateName,
        'templateUrl' => $templateUrl,
        'viewerUrl' => $viewerUrl,
        'size' => $localSize,
        'updatedAt' => $localMtime > 0 ? date('c', $localMtime) : '',
    ];
}
function docs_resolve_organization_template_stream_path(string $folder, string $templateName): string
{
    $templatePath = docs_get_organization_template_path($folder);
    if (is_file($templatePath) && is_readable($templatePath)) {
        return $templatePath;
    }
    return '';
}
function docs_sanitize_admin_object_name(string $organization): string
{
    $sanitized = preg_replace('/[^a-zA-Z0-9А-Яа-яЁё._-]/u', '_', $organization);
    if (!is_string($sanitized) || $sanitized === '') {
        $sanitized = sanitize_folder_name($organization);
    }
    return $sanitized;
}
function ensure_organization_directory(string $folder): string
{
    $dir = DOCUMENTS_ROOT . '/' . $folder;
    if (!is_dir($dir)) {
        mkdir($dir, 0775, true);
    }
    return $dir;
}
function docs_get_responses_root(string $folder, bool $create = true): string
{
    $dir = ensure_organization_directory($folder) . '/Ответы';
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }
    return $dir;
}
function docs_get_document_responses_dir(string $folder, string $documentId, bool $create = true): string
{
    $safeDocumentId = preg_replace('/[^A-Za-z0-9._-]/', '_', trim($documentId));
    if (!is_string($safeDocumentId) || $safeDocumentId === '') {
        $safeDocumentId = 'document';
    }
    $dir = docs_get_responses_root($folder, $create) . '/' . $safeDocumentId;
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }
    return $dir;
}
function docs_delete_directory_recursive(string $path): void
{
    if ($path === '' || !file_exists($path)) {
        return;
    }
    if (is_file($path) || is_link($path)) {
        @unlink($path);
        return;
    }
    $items = @scandir($path);
    if (is_array($items)) {
        foreach ($items as $item) {
            if ($item === '.' || $item === '..') {
                continue;
            }
            docs_delete_directory_recursive($path . '/' . $item);
        }
    }
    @rmdir($path);
}
function docs_resolve_current_user_key(array $requestContext, ?array $sessionAuth = null): string
{
    $user = isset($requestContext['user']) && is_array($requestContext['user']) ? $requestContext['user'] : [];
    $candidates = [
        ['id', $user['id'] ?? ($requestContext['primaryId'] ?? null)],
        ['login', $user['login'] ?? ($sessionAuth['login'] ?? null)],
        ['username', $user['username'] ?? null],
        ['name', $user['fullName'] ?? ($sessionAuth['fullName'] ?? null)],
    ];
    foreach ($candidates as [$prefix, $value]) {
        if ($value === null) {
            continue;
        }
        $normalized = trim((string) $value);
        if ($normalized !== '') {
            return $prefix . ':' . mb_strtolower($normalized, 'UTF-8');
        }
    }
    return '';
}
function docs_resolve_outgoing_private_user_key(array $requestContext, ?array $sessionAuth = null): string
{
    if (is_array($sessionAuth)) {
        $sessionCandidates = [
            ['login', $sessionAuth['login'] ?? null],
            ['id', $sessionAuth['telegramId'] ?? ($sessionAuth['telegram'] ?? ($sessionAuth['chatId'] ?? null))],
            ['name', $sessionAuth['fullName'] ?? null],
        ];
        foreach ($sessionCandidates as [$prefix, $value]) {
            if ($value === null) {
                continue;
            }
            $normalized = trim((string) $value);
            if ($normalized !== '') {
                return $prefix . ':' . mb_strtolower($normalized, 'UTF-8');
            }
        }
    }
    return docs_resolve_current_user_key($requestContext, null);
}
function docs_resolve_outgoing_private_user_keys(array $requestContext, ?array $sessionAuth = null): array
{
    $keys = [];
    $pushKey = static function (string $prefix, $value) use (&$keys): void {
        if ($value === null) {
            return;
        }
        $normalized = trim((string) $value);
        if ($normalized !== '') {
            $keys[] = $prefix . ':' . mb_strtolower($normalized, 'UTF-8');
        }
    };
    if (is_array($sessionAuth)) {
        $pushKey('login', $sessionAuth['login'] ?? null);
        $pushKey('id', $sessionAuth['telegramId'] ?? null);
        $pushKey('id', $sessionAuth['telegram'] ?? null);
        $pushKey('id', $sessionAuth['chatId'] ?? null);
        $pushKey('name', $sessionAuth['fullName'] ?? null);
    }
    $user = isset($requestContext['user']) && is_array($requestContext['user']) ? $requestContext['user'] : [];
    $pushKey('id', $user['id'] ?? ($requestContext['primaryId'] ?? null));
    $pushKey('username', $user['username'] ?? null);
    $pushKey('name', $user['fullName'] ?? null);
    $pushKey('login', $user['login'] ?? null);
    $primaryKey = docs_resolve_outgoing_private_user_key($requestContext, $sessionAuth);
    if ($primaryKey !== '') {
        $keys[] = $primaryKey;
    }
    return docs_normalize_outgoing_user_keys($keys);
}
function docs_resolve_site_user_identity_for_responses(string $folder, array $requestContext, ?array $sessionAuth = null): array
{
    $telegramUserId = normalize_identifier_value($requestContext['raw']['telegram_user_id'] ?? '');
    if ($telegramUserId === '') {
        $telegramUserId = normalize_identifier_value($requestContext['primaryId'] ?? '');
    }
    if ($telegramUserId === '' && isset($requestContext['user']) && is_array($requestContext['user'])) {
        $telegramUserId = normalize_identifier_value($requestContext['user']['id'] ?? '');
    }
    if ($telegramUserId !== '') {
        $settings = load_admin_settings($folder);
        $searchPools = [];
        if (isset($settings['block3']) && is_array($settings['block3'])) {
            $searchPools[] = $settings['block3'];
        }
        if (isset($settings['responsibles']) && is_array($settings['responsibles'])) {
            $searchPools[] = $settings['responsibles'];
        }
        foreach ($searchPools as $pool) {
            foreach ($pool as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $entryTelegramId = normalize_identifier_value($entry['telegram_user_id'] ?? ($entry['telegram'] ?? ($entry['chatId'] ?? '')));
                if ($entryTelegramId === '' || $entryTelegramId !== $telegramUserId) {
                    continue;
                }
                $label = sanitize_text_field((string) ($entry['subordinate'] ?? ($entry['responsible'] ?? ($entry['name'] ?? ''))), 200);
                if ($label === '') {
                    continue;
                }
                return [
                    'label' => $label,
                    'key' => 'name:' . mb_strtolower($label, 'UTF-8'),
                    'source' => 'settingsdocs',
                ];
            }
        }
    }
    $fallbackLabel = docs_resolve_current_user_label($requestContext, $sessionAuth);
    if ($fallbackLabel === '') {
        $fallbackLabel = 'Пользователь';
    }
    $fallbackKey = docs_resolve_current_user_key($requestContext, $sessionAuth);
    return [
        'label' => $fallbackLabel,
        'key' => $fallbackKey !== '' ? $fallbackKey : ('name:' . mb_strtolower($fallbackLabel, 'UTF-8')),
        'source' => 'fallback',
    ];
}
function docs_is_current_user_response_owner(array $response, string $folder, array $requestContext, ?array $sessionAuth = null): bool
{
    $siteIdentity = docs_resolve_site_user_identity_for_responses($folder, $requestContext, $sessionAuth);
    $siteKeyNormalized = mb_strtolower(trim((string) ($siteIdentity['key'] ?? '')), 'UTF-8');
    $siteLabelNormalized = docs_normalize_name_candidate_value($siteIdentity['label'] ?? '');
    $ownerKey = sanitize_text_field((string) ($response['uploadedByKey'] ?? ''), 200);
    $ownerKeyNormalized = $ownerKey !== '' ? mb_strtolower(trim($ownerKey), 'UTF-8') : '';
    if ($ownerKeyNormalized !== '' && $siteKeyNormalized !== '' && $ownerKeyNormalized === $siteKeyNormalized) {
        return true;
    }
    $ownerName = docs_normalize_name_candidate_value($response['uploadedBy'] ?? '');
    return $ownerName !== '' && $siteLabelNormalized !== '' && $ownerName === $siteLabelNormalized;
}
function docs_resolve_current_user_label(array $requestContext, ?array $sessionAuth = null): string
{
    $user = isset($requestContext['user']) && is_array($requestContext['user']) ? $requestContext['user'] : [];
    $candidates = [
        $user['fullName'] ?? null,
        $sessionAuth['fullName'] ?? null,
        $user['login'] ?? null,
        $sessionAuth['login'] ?? null,
        $user['username'] ?? null,
        $requestContext['primaryId'] ?? null,
    ];
    foreach ($candidates as $candidate) {
        $value = trim((string) ($candidate ?? ''));
        if ($value !== '') {
            return sanitize_text_field($value, 200);
        }
    }
    return 'Пользователь';
}
