        }
        if (isset($settings['responsibles']) && is_array($settings['responsibles'])) {
            $searchPools[] = $settings['responsibles'];
        }
        foreach ($searchPools as $pool) {
            foreach ($pool as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $entryTelegramId = normalize_identifier_value($entry['telegram_user_id'] ?? ($entry['telegram'] ?? ($entry['chatId'] ?? '')));
                if ($entryTelegramId === '' || $entryTelegramId !== $telegramUserId) {
                    continue;
                }
                $responsible = sanitize_text_field((string) ($entry['subordinate'] ?? ($entry['responsible'] ?? ($entry['name'] ?? ''))), 200);
                if ($responsible === '') {
                    continue;
                }
                return [
                    'label' => $responsible,
                    'key' => 'name:' . mb_strtolower($responsible, 'UTF-8'),
                    'source' => 'settingsdocs',
                    'telegramUserId' => $telegramUserId,
                    'matchedResponsible' => $responsible,
                ];
            }
        }
    }
    if ($fallbackLabel === '') {
        $fallbackLabel = 'Пользователь';
    }
    return [
        'label' => $fallbackLabel,
        'key' => $fallbackKey !== '' ? $fallbackKey : ('name:' . mb_strtolower($fallbackLabel, 'UTF-8')),
        'source' => 'fallback',
        'telegramUserId' => $telegramUserId,
        'matchedResponsible' => null,
    ];
}
function docs_normalize_response_file_name(string $original, array $record, int $sequence = 1): string
{
    $base = normalize_file_name($original, $record, $sequence);
    return 'answer.' . $base;
}
function docs_is_text_response_file(string $fileName): bool
{
    $extension = mb_strtolower((string) pathinfo($fileName, PATHINFO_EXTENSION), 'UTF-8');
    return $extension === 'txt';
}
function docs_extract_pure_response_text(string $rawText): string
{
    $normalized = str_replace("\r\n", "\n", str_replace("\r", "\n", $rawText));
    $normalized = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', '', $normalized) ?? '';
    if ($normalized === '') {
        return '';
    }
    $trimmed = trim($normalized);
    if ($trimmed === '') {
        return '';
    }
    $parts = preg_split('/\nОтвет к задаче\s*\n/u', "\n" . $trimmed, -1, PREG_SPLIT_NO_EMPTY);
    $candidate = is_array($parts) && !empty($parts)
        ? (string) $parts[count($parts) - 1]
        : $trimmed;
    $candidate = preg_replace('/^\s*Ответ к задаче\s*\n/u', '', $candidate) ?? $candidate;
    $candidate = preg_replace('/^\s*Дата:\s*.*\n/u', '', $candidate) ?? $candidate;
    $candidate = preg_replace('/^\s*Пользователь:\s*.*\n/u', '', $candidate) ?? $candidate;
    $candidate = preg_replace('/^\s*-{3,}\s*\n/u', '', $candidate) ?? $candidate;
    $candidate = trim((string) $candidate);
    return $candidate !== '' ? $candidate : $trimmed;
}
function docs_read_response_text_content(string $folder, string $documentId, string $storedName): string
{
    if ($documentId === '' || $storedName === '' || !docs_is_text_response_file($storedName)) {
        return '';
    }
    $path = docs_get_document_responses_dir($folder, $documentId, false) . '/' . $storedName;
    if (!is_file($path)) {
        return '';
    }
    $maxBytes = 262144;
    $raw = @file_get_contents($path, false, null, 0, $maxBytes);
    if (!is_string($raw) || $raw === '') {
        return '';
    }
    $clean = docs_extract_pure_response_text($raw);
    if ($clean === '') {
        return '';
    }
    if (mb_strlen($clean, 'UTF-8') > 12000) {
        $clean = mb_substr($clean, 0, 12000, 'UTF-8');
    }
    return $clean;
}
function docs_prepare_responses_for_record(array &$record, string $folder): void
{
    if (!isset($record['responses']) || !is_array($record['responses'])) {
        $record['responses'] = [];
        return;
    }
    $documentId = isset($record['id']) ? trim((string) $record['id']) : '';
    $prepared = [];
    foreach ($record['responses'] as $response) {
        if (!is_array($response)) {
            continue;
        }
        $storedName = isset($response['storedName']) ? sanitize_text_field((string) $response['storedName'], 255) : '';
        if ($storedName === '') {
            continue;
        }
        $item = [
            'originalName' => sanitize_text_field((string) ($response['originalName'] ?? $storedName), 255),
            'storedName' => $storedName,
            'size' => isset($response['size']) ? (int) $response['size'] : 0,
            'uploadedAt' => isset($response['uploadedAt']) ? (string) $response['uploadedAt'] : '',
            'url' => sanitize_text_field((string) ($response['url'] ?? ''), 500),
            'uploadedBy' => sanitize_text_field((string) ($response['uploadedBy'] ?? ''), 200),
            'uploadedByKey' => sanitize_text_field((string) ($response['uploadedByKey'] ?? ''), 200),
            'uploadedByName' => sanitize_text_field((string) ($response['uploadedByName'] ?? ($response['uploadedBy'] ?? '')), 200),
            'uploadedByTelegram' => sanitize_text_field((string) ($response['uploadedByTelegram'] ?? ''), 120),
            'uploadedById' => sanitize_text_field((string) ($response['uploadedById'] ?? ''), 120),
            'uploadedByLogin' => sanitize_text_field((string) ($response['uploadedByLogin'] ?? ''), 120),
        ];
        $item = array_merge($item, docs_prepare_cold_storage_file_payload($response));
        if ($documentId !== '') {
            if (empty($item['url'])) {
                $item['url'] = build_public_path($folder, 'Ответы/' . $documentId . '/' . $storedName);
            }
        }
        if (docs_is_text_response_file($storedName)) {
            $item['isTextFile'] = true;
            $item['textContent'] = docs_read_response_text_content($folder, $documentId, $storedName);
        }
        $prepared[] = $item;
    }
    $record['responses'] = array_values($prepared);
}
function docs_get_mini_app_user_log_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . MINI_APP_USER_LOG_FILENAME;
}
function docs_load_mini_app_user_log(string $folder): array
{
    $path = docs_get_mini_app_user_log_path($folder);
    $entries = [];
    $updatedAt = null;
    $decoded = docs_read_json_array_file_with_backup($path);
    if (is_array($decoded)) {
        foreach ($decoded as $entry) {
            if (!is_array($entry)) {
                continue;
            }
            $id = normalize_identifier_value($entry['id'] ?? '');
            if ($id === '') {
                continue;
            }
            $entries[] = array_filter([
                'id' => $id,
                'fullName' => sanitize_text_field($entry['fullName'] ?? '', 200),
                'username' => sanitize_text_field($entry['username'] ?? '', 100),
                'lastSeen' => isset($entry['lastSeen']) ? (string) $entry['lastSeen'] : '',
            ], static function ($value) {
                return $value !== '';
            });
        }
    }
    if (is_file($path)) {
        $mtime = @filemtime($path);
        if ($mtime !== false) {
            $updatedAt = date('c', $mtime);
        }
    }
    return [
        'entries' => $entries,
        'updatedAt' => $updatedAt,
        'path' => $path,
    ];
}
function docs_write_mini_app_user_log(string $folder, array $entries): void
{
    $directory = ensure_organization_directory($folder);
    $path = rtrim($directory, '/\\') . '/' . MINI_APP_USER_LOG_FILENAME;
    $encoded = json_encode($entries, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT);
    if ($encoded === false) {
        return;
    }
    if (!docs_write_json_content_atomically($path, $encoded)) {
        log_docs_event('Mini app user log write failed', ['folder' => $folder, 'path' => $path]);
    }
}
function docs_register_mini_app_user_visit(string $organizationName, string $folder, array $requestContext): void
{
    $userId = '';
    $fullName = '';
    $username = '';
    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $userId = normalize_identifier_value($requestContext['user']['id'] ?? '');
        $fullName = sanitize_text_field($requestContext['user']['fullName'] ?? '', 200);
        $firstName = sanitize_text_field($requestContext['user']['firstName'] ?? '', 120);
        $lastName = sanitize_text_field($requestContext['user']['lastName'] ?? '', 120);
        if ($fullName === '' && ($firstName !== '' || $lastName !== '')) {
            $parts = array_filter([$lastName, $firstName], static function ($value): bool {
                return $value !== '';
            });
            $fullName = implode(' ', $parts);
        }
        $username = sanitize_text_field($requestContext['user']['username'] ?? '', 120);
    }
    if ($userId === '' && !empty($requestContext['primaryId'])) {
        $userId = normalize_identifier_value((string) $requestContext['primaryId']);
    }
    if ($fullName === '' && isset($requestContext['raw']['telegram_full_name'])) {
        $fullName = sanitize_text_field((string) $requestContext['raw']['telegram_full_name'], 200);
    }
    if ($username === '' && isset($requestContext['raw']['telegram_username'])) {
        $username = sanitize_text_field((string) $requestContext['raw']['telegram_username'], 120);
    }
    if ($userId === '') {
        return;
    }
    if ($fullName === '') {
        $fullName = 'Без имени';
    }
    $log = docs_load_mini_app_user_log($folder);
    $entries = [];
    foreach ($log['entries'] as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $entryId = normalize_identifier_value($entry['id'] ?? '');
        if ($entryId === '') {
            continue;
        }
        $existing = ['id' => $entryId];
        $existingName = sanitize_text_field($entry['fullName'] ?? '', 200);
        if ($existingName !== '') {
            $existing['fullName'] = $existingName;
        }
        $existingUsername = sanitize_text_field($entry['username'] ?? '', 120);
        if ($existingUsername !== '') {
            $existing['username'] = ltrim($existingUsername, '@');
        }
        if (!empty($entry['lastSeen'])) {
            $existing['lastSeen'] = (string) $entry['lastSeen'];
        }
        $entries[$entryId] = $existing;
    }
    $now = date('c');
    $current = $entries[$userId] ?? ['id' => $userId];
    if ($fullName !== '' && $fullName !== 'Без имени') {
        $current['fullName'] = $fullName;
    } elseif (empty($current['fullName'])) {
        $current['fullName'] = 'Без имени';
    }
    if ($username !== '') {
        $current['username'] = ltrim($username, '@');
    } elseif (isset($current['username']) && $current['username'] === '') {
        unset($current['username']);
    }
    $current['lastSeen'] = $now;
    $entries[$userId] = $current;
    $sorted = array_values($entries);
    usort($sorted, static function (array $a, array $b): int {
        $nameA = mb_strtolower((string) ($a['fullName'] ?? ''), 'UTF-8');
        $nameB = mb_strtolower((string) ($b['fullName'] ?? ''), 'UTF-8');
        if ($nameA === $nameB) {
            return strcmp((string) ($a['id'] ?? ''), (string) ($b['id'] ?? ''));
        }
        if ($nameA === '') {
            return 1;
        }
        if ($nameB === '') {
            return -1;
        }
        return strcmp($nameA, $nameB);
    });
    docs_write_mini_app_user_log($folder, $sorted);
    log_docs_event('Mini app user visit recorded', [
        'organization' => $organizationName,
        'folder' => $folder,
        'userId' => $userId,
        'fullName' => $fullName,
        'username' => $username,
        'entriesCount' => count($sorted),
    ]);
}
function docs_sanitize_mini_app_user_tasks_snapshot_id(string $telegramUserId): string
{
    $normalized = normalize_identifier_value($telegramUserId);
    if ($normalized === '') {
        $normalized = trim($telegramUserId);
    }
    $safe = preg_replace('/[^A-Za-z0-9._@-]+/', '_', $normalized);
    if (!is_string($safe) || trim($safe, '._-') === '') {
        $safe = 'user_' . substr(sha1($telegramUserId), 0, 16);
    }
    if (strlen($safe) > 120) {
        $safe = substr($safe, 0, 120);
    }
    return $safe;
}
function docs_build_mini_app_user_tasks_snapshot_relative_path(string $safeTelegramUserId): string
{
    return MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_DIRECTORY . '/' . $safeTelegramUserId . '.json';
}
function docs_mini_app_user_tasks_snapshot_lock_path(string $safeTelegramUserId): string
{
    return sys_get_temp_dir() . '/docs_tasks_snapshot_' . sha1($safeTelegramUserId) . '.lock';
}
function docs_upload_mini_app_user_tasks_snapshot_to_cold_storage(string $localPath, string $relativePath): array
{
    $key = docs_build_cold_storage_key(MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_FOLDER, $relativePath);
    if ($key === '') {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Не удалось построить путь JSON-снимка в S3.',
        ];
    }
    if (!is_file($localPath) || !is_readable($localPath)) {
        return [
            'ok' => false,
            'key' => $key,
            'error' => 'Временный JSON-снимок задач недоступен для отправки в S3.',
        ];
    }
    clearstatcache(true, $localPath);
    $localBytes = @filesize($localPath);
    if ($localBytes === false || $localBytes < 1) {
        return [
            'ok' => false,
            'key' => $key,
            'error' => 'Пустой JSON-снимок нельзя отправлять в S3.',
        ];
    }
    $result = docs_run_rclone_command(['copyto', $localPath, docs_cold_storage_remote_path($key)], 15);
    if (empty($result['ok'])) {
        return [
            'ok' => false,
            'key' => $key,
            'error' => (string) ($result['error'] ?? 'Не удалось отправить JSON-снимок задач в S3.'),
        ];
    }
    $verification = docs_verify_cold_storage_file_size($key, (int) $localBytes, 15);
    if (empty($verification['ok'])) {
        return [
            'ok' => false,
            'key' => $key,
            'error' => (string) ($verification['error'] ?? 'JSON-снимок в S3 не прошёл проверку размера.'),
        ];
    }
    return [
        'ok' => true,
        'key' => $key,
        'bytes' => (int) $localBytes,
        'error' => '',
    ];
}
function docs_write_mini_app_tasks_snapshot_payload(array $payload, string $relativePath): array
{
    if ($relativePath === '') {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Не указан S3-путь JSON-снимка задач.',
        ];
    }
    $encoded = json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($encoded === false) {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Не удалось закодировать JSON-снимок задач.',
        ];
    }
    $tempPath = tempnam(sys_get_temp_dir(), 'docs_tasks_snapshot_');
    if (!is_string($tempPath) || $tempPath === '') {
        return [
            'ok' => false,
            'key' => '',
            'error' => 'Не удалось создать временный JSON-снимок задач.',
        ];
    }
    try {
        if (!docs_replace_json_content_atomically($tempPath, $encoded)) {
            return [
                'ok' => false,
                'key' => '',
                'error' => 'Не удалось записать временный JSON-снимок задач.',
            ];
        }
        return docs_upload_mini_app_user_tasks_snapshot_to_cold_storage($tempPath, $relativePath);
    } finally {
        @unlink($tempPath);
    }
}
function docs_build_ocr_text_archive_relative_path(
    string $folder,
    string $documentField,
    string $documentValue,
    string $storedName
): string {
    $identity = sanitize_folder_name($folder)
        . "\0" . sanitize_text_field($documentField, 40)
        . "\0" . docs_sanitize_ocr_document_value($documentField, $documentValue)
        . "\0" . sanitize_text_field($storedName, 255);
    $digest = hash('sha256', $identity);
    return DOCS_OCR_TEXT_ARCHIVE_STORAGE_DIRECTORY
        . '/' . substr($digest, 0, 2)
        . '/' . $digest . '.json';
}
function docs_write_ocr_text_archive(
    string $folder,
    string $documentField,
    string $documentValue,
    array $file,
    string $ocrText
): array {
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    $ocrText = trim($ocrText);
    if ($storedName === '' || $ocrText === '') {
        return ['ok' => false, 'error' => 'Не указан файл или OCR-текст для S3-архива.'];
    }
    $relativePath = docs_build_ocr_text_archive_relative_path(
        $folder,
        $documentField,
        $documentValue,
        $storedName
    );
    $payload = [
        'version' => 1,
        'source' => 'documents_ocr_text_archive',
        'organizationFolder' => sanitize_folder_name($folder),
        'documentField' => sanitize_text_field($documentField, 40),
        'documentValue' => docs_sanitize_ocr_document_value($documentField, $documentValue),
        'storedName' => $storedName,
        'originalName' => sanitize_text_field(
            (string) ($file['originalName'] ?? ($file['name'] ?? $storedName)),
            255
        ),
        'ocrText' => $ocrText,
        'ocrTextLength' => mb_strlen($ocrText, 'UTF-8'),
        'ocrTextSha256' => hash('sha256', $ocrText),
        'savedAt' => date('c'),
    ];
    $upload = docs_write_mini_app_tasks_snapshot_payload($payload, $relativePath);
    if (empty($upload['ok'])) {
        return [
            'ok' => false,
            'relativePath' => $relativePath,
            'key' => (string) ($upload['key'] ?? ''),
            'error' => sanitize_text_field(
                (string) ($upload['error'] ?? 'Не удалось сохранить OCR-текст в S3-архив.'),
                500
            ),
        ];
    }
    $readBack = docs_load_mini_app_tasks_snapshot_from_relative_path($relativePath, 20);
    $savedPayload = isset($readBack['snapshot']) && is_array($readBack['snapshot'])
        ? $readBack['snapshot']
        : [];
    $savedText = isset($savedPayload['ocrText']) && is_string($savedPayload['ocrText'])
        ? trim($savedPayload['ocrText'])
        : '';
    $savedTextHash = hash('sha256', $savedText);
    $savedTextLength = mb_strlen($savedText, 'UTF-8');
    if (empty($readBack['ok'])
        || (string) ($savedPayload['source'] ?? '') !== 'documents_ocr_text_archive'
        || sanitize_folder_name((string) ($savedPayload['organizationFolder'] ?? ''))
            !== sanitize_folder_name($folder)
        || (string) ($savedPayload['documentField'] ?? '') !== sanitize_text_field($documentField, 40)
        || (string) ($savedPayload['documentValue'] ?? '')
            !== docs_sanitize_ocr_document_value($documentField, $documentValue)
        || sanitize_text_field((string) ($savedPayload['storedName'] ?? ''), 255) !== $storedName
        || $savedText === ''
        || (int) ($savedPayload['ocrTextLength'] ?? -1) !== $savedTextLength
        || !hash_equals((string) ($savedPayload['ocrTextSha256'] ?? ''), $savedTextHash)
        || !hash_equals(hash('sha256', $ocrText), $savedTextHash)
    ) {
        return [
            'ok' => false,
            'relativePath' => $relativePath,
            'key' => (string) ($upload['key'] ?? ''),
            'error' => empty($readBack['ok'])
                ? sanitize_text_field(
                    (string) ($readBack['message'] ?? 'S3-архив OCR не прочитан после записи.'),
                    500
                )
                : 'S3-архив OCR не подтвердил записанный текст.',
        ];
    }
    return [
        'ok' => true,
        'relativePath' => $relativePath,
        'key' => (string) ($upload['key'] ?? docs_build_cold_storage_key(
            DOCS_OCR_TEXT_ARCHIVE_STORAGE_FOLDER,
            $relativePath
        )),
        'textLength' => mb_strlen($ocrText, 'UTF-8'),
        'textSha256' => hash('sha256', $ocrText),
        'savedAt' => (string) $payload['savedAt'],
    ];
}
function docs_load_ocr_text_archive(array $file, int $timeoutSeconds = 20): array
{
    $ocr = isset($file['ocr']) && is_array($file['ocr']) ? $file['ocr'] : [];
    $relativePath = docs_normalize_cold_storage_relative_path(
        (string) ($ocr['archiveRelativePath'] ?? '')
    );
    $archivePrefix = DOCS_OCR_TEXT_ARCHIVE_STORAGE_DIRECTORY . '/';
    if ($relativePath === '' || strpos($relativePath, $archivePrefix) !== 0) {
        return ['ok' => false, 'notFound' => true, 'error' => 'ocr_archive_missing'];
    }
    $loaded = docs_load_mini_app_tasks_snapshot_from_relative_path($relativePath, $timeoutSeconds);
    if (empty($loaded['ok']) || !is_array($loaded['snapshot'] ?? null)) {
        return [
            'ok' => false,
            'notFound' => !empty($loaded['notFound']),
            'error' => sanitize_text_field(
                (string) ($loaded['message'] ?? 'S3-архив OCR недоступен.'),
                500
            ),
        ];
    }
    $payload = $loaded['snapshot'];
    if ((string) ($payload['source'] ?? '') !== 'documents_ocr_text_archive') {
        return ['ok' => false, 'notFound' => false, 'error' => 'S3-архив OCR имеет неизвестный формат.'];
    }
    $text = isset($payload['ocrText']) && is_string($payload['ocrText'])
        ? trim($payload['ocrText'])
        : '';
    if ($text === '') {
        return ['ok' => false, 'notFound' => false, 'error' => 'S3-архив OCR не содержит текст.'];
    }
    $actualHash = hash('sha256', $text);
    $payloadHash = sanitize_text_field((string) ($payload['ocrTextSha256'] ?? ''), 80);
    $expectedHash = sanitize_text_field((string) ($ocr['archiveTextSha256'] ?? ''), 80);
    $payloadLength = (int) ($payload['ocrTextLength'] ?? -1);
    $actualLength = mb_strlen($text, 'UTF-8');
    $expectedLength = max(0, (int) ($ocr['archiveTextLength'] ?? 0));
    $expectedStoredName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($payloadLength !== $actualLength
        || ($expectedLength > 0 && $expectedLength !== $actualLength)
        || preg_match('/^[a-f0-9]{64}$/', $payloadHash) !== 1
        || !hash_equals($payloadHash, $actualHash)
        || ($expectedHash !== '' && !hash_equals($expectedHash, $actualHash))
        || ($expectedStoredName !== ''
            && sanitize_text_field((string) ($payload['storedName'] ?? ''), 255) !== $expectedStoredName)
        || (!empty($ocr['archiveFolder'])
            && sanitize_folder_name((string) ($payload['organizationFolder'] ?? ''))
                !== sanitize_folder_name((string) $ocr['archiveFolder']))
        || (!empty($ocr['archiveDocumentField'])
            && (string) ($payload['documentField'] ?? '') !== (string) $ocr['archiveDocumentField'])
        || (!empty($ocr['archiveDocumentValue'])
            && (string) ($payload['documentValue'] ?? '') !== (string) $ocr['archiveDocumentValue'])
    ) {
        return ['ok' => false, 'notFound' => false, 'error' => 'S3-архив OCR не прошёл проверку целостности.'];
    }
    return [
        'ok' => true,
        'text' => $text,
        'textLength' => mb_strlen($text, 'UTF-8'),
        'textSha256' => $actualHash,
        'relativePath' => $relativePath,
        'key' => (string) ($loaded['key'] ?? ''),
        'savedAt' => sanitize_text_field((string) ($payload['savedAt'] ?? ''), 80),
    ];
}
function docs_prepare_mini_app_user_tasks_snapshot_organizations(array $organizationSummaries): array
{
    $prepared = [];
    foreach ($organizationSummaries as $summary) {
        if (!is_array($summary)) {
            continue;
        }
        $name = sanitize_text_field((string) ($summary['name'] ?? ''), 200);
        if ($name === '') {
            continue;
        }
        $prepared[] = [
            'name' => $name,
            'count' => max(0, (int) ($summary['count'] ?? 0)),
            'canManageInstructions' => !empty($summary['canManageInstructions']),
            'responsiblesCount' => isset($summary['responsibles']) && is_array($summary['responsibles']) ? count($summary['responsibles']) : 0,
            'subordinatesCount' => isset($summary['subordinates']) && is_array($summary['subordinates']) ? count($summary['subordinates']) : 0,
            'directorsCount' => isset($summary['directors']) && is_array($summary['directors']) ? count($summary['directors']) : 0,
        ];
    }
    return $prepared;
}
function docs_save_mini_app_user_tasks_snapshot(
    string $telegramUserId,
    array $tasks,
    array $organizationSummaries,
    array $stats,
    ?array $userInfo,
    ?array $filter,
    array $directorModeSummary
): array {
    docs_apply_task_snapshot_memory_limit();
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId === '' || preg_match('/^-?\d{4,20}$/D', $telegramUserId) !== 1) {
        return [
            'saved' => false,
            'status' => 'skipped',
            'reason' => 'telegram_user_id_invalid',
        ];
    }
    $safeTelegramUserId = docs_sanitize_mini_app_user_tasks_snapshot_id($telegramUserId);
    $lockHandle = @fopen(docs_mini_app_user_tasks_snapshot_lock_path($safeTelegramUserId), 'c+');
    if ($lockHandle === false || !@flock($lockHandle, LOCK_EX)) {
        if (is_resource($lockHandle)) {
            fclose($lockHandle);
        }
        return [
            'saved' => false,
            'status' => 'lock_failed',
            'reason' => 'snapshot_lock_failed',
        ];
    }
    try {
        $generatedAt = date('c');
        $tasks = array_values($tasks);
        $relativePath = docs_build_mini_app_user_tasks_snapshot_relative_path($safeTelegramUserId);
        $existingSnapshot = docs_load_mini_app_user_tasks_snapshot($telegramUserId);
        if (empty($existingSnapshot['ok']) && empty($existingSnapshot['notFound'])) {
            return [
                'saved' => false,
                'status' => 's3_read_failed',
                'reason' => 'snapshot_read_failed',
                'error' => sanitize_text_field(
                    (string) ($existingSnapshot['message'] ?? 'Не удалось прочитать Telegram JSON пользователя.'),
                    500
                ),
            ];
        }
        $existingSnapshotPayload = null;
        if (!empty($existingSnapshot['ok'])
            && isset($existingSnapshot['snapshot'])
            && is_array($existingSnapshot['snapshot'])) {
            $identity = docs_validate_mini_app_user_tasks_snapshot_identity(
                $existingSnapshot['snapshot'],
                $telegramUserId
            );
            if (empty($identity['ok'])) {
                return [
                    'saved' => false,
                    'status' => 'snapshot_identity_failed',
                    'reason' => 'snapshot_identity_failed',
                    'error' => sanitize_text_field(
                        (string) ($identity['error'] ?? 'Telegram JSON не прошёл проверку целостности.'),
                        500
                    ),
                ];
            }
            $existingSnapshotPayload = $existingSnapshot['snapshot'];
            $tasks = docs_merge_task_rag_ocr_snapshot($tasks, $existingSnapshotPayload);
        }
        $currentPayload = [
            'version' => 2,
            'source' => 'mini_app_tasks',
            'telegramUserId' => $telegramUserId,
            'user' => $userInfo,
            'generatedAt' => $generatedAt,
            'tasksCount' => count($tasks),
            'organizations' => docs_prepare_mini_app_user_tasks_snapshot_organizations($organizationSummaries),
            'stats' => $stats,
            'filter' => summarize_assignee_filter_for_log($filter),
            'directorMode' => $directorModeSummary,
            'tasks' => $tasks,
        ];
        $payload = is_array($existingSnapshotPayload)
            ? array_replace($existingSnapshotPayload, $currentPayload)
            : $currentPayload;
        $upload = docs_write_mini_app_tasks_snapshot_payload($payload, $relativePath);
        $saved = !empty($upload['ok']);
        $result = [
            'saved' => $saved,
            'status' => $saved ? 'synced' : 's3_failed',
            'storageProvider' => DOCS_COLD_STORAGE_PROVIDER,
            'key' => (string) ($upload['key'] ?? docs_build_cold_storage_key(
                MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_FOLDER,
                $relativePath
            )),
            'relativePath' => $relativePath,
            'generatedAt' => $generatedAt,
            'tasksCount' => count($tasks),
        ];
        if (!$saved) {
            $result['error'] = sanitize_text_field(
                (string) ($upload['error'] ?? 'Не удалось сохранить Telegram JSON пользователя в S3.'),
                500
            );
        }
        return $result;
    } finally {
        @flock($lockHandle, LOCK_UN);
        fclose($lockHandle);
    }
}
function docs_build_mini_app_user_tasks_snapshot_pending_result(string $telegramUserId, int $tasksCount): array
{
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId === '') {
        return [
            'saved' => false,
            'status' => 'skipped',
            'reason' => 'telegram_user_id_missing',
        ];
    }
    $safeTelegramUserId = docs_sanitize_mini_app_user_tasks_snapshot_id($telegramUserId);
    $relativePath = docs_build_mini_app_user_tasks_snapshot_relative_path($safeTelegramUserId);
    return [
        'saved' => false,
        'status' => 'queued',
        'storageProvider' => DOCS_COLD_STORAGE_PROVIDER,
        'key' => docs_build_cold_storage_key(MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_FOLDER, $relativePath),
        'relativePath' => $relativePath,
        'generatedAt' => date('c'),
        'tasksCount' => max(0, $tasksCount),
    ];
}
function docs_read_mini_app_user_tasks_snapshot_json(string $path): ?array
{
    if ($path === '' || !is_file($path) || !is_readable($path)) {
        return null;
    }
    $raw = @file_get_contents($path);
    if (!is_string($raw) || trim($raw) === '') {
        return null;
    }
    $decoded = json_decode($raw, true);
    return is_array($decoded) ? $decoded : null;
}
function docs_rclone_error_is_missing_object(string $error): bool
{
    $error = mb_strtolower(trim($error), 'UTF-8');
    if ($error === '') {
        return false;
    }
    foreach ([
        'object not found',
        'directory not found',
        'file not found',
        'path not found',
        'no such file',
        'does not exist',
        "doesn't exist",
        'specified key does not exist',
    ] as $marker) {
        if (strpos($error, $marker) !== false) {
            return true;
        }
    }
    return false;
}
function docs_load_mini_app_tasks_snapshot_from_relative_path(
    string $relativePath,
    int $timeoutSeconds = 20
): array {
    $relativePath = docs_normalize_cold_storage_relative_path($relativePath);
    $key = docs_build_cold_storage_key(MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_FOLDER, $relativePath);
    if ($relativePath === '' || $key === '') {
        return [
            'ok' => false,
            'error' => 'snapshot_path_missing',
            'message' => 'Не удалось построить путь JSON-снимка задач.',
        ];
    }
    $tempPath = tempnam(sys_get_temp_dir(), 'docs_tasks_');
    if (!is_string($tempPath) || $tempPath === '') {
        return [
            'ok' => false,
            'error' => 'temp_file_failed',
            'message' => 'Не удалось создать временный файл для JSON-снимка.',
        ];
    }
    $download = docs_run_rclone_command(
        ['copyto', docs_cold_storage_remote_path($key), $tempPath],
        max(1, min(20, $timeoutSeconds))
    );
    if (empty($download['ok'])) {
        @unlink($tempPath);
        $downloadError = (string) ($download['error'] ?? 'JSON-снимок задач в S3 недоступен.');
        return [
            'ok' => false,
            'error' => 's3_snapshot_unavailable',
            'message' => $downloadError,
            'notFound' => docs_rclone_error_is_missing_object($downloadError),
            'timedOut' => !empty($download['timedOut']),
            'exitCode' => (int) ($download['exitCode'] ?? 0),
            'relativePath' => $relativePath,
            'key' => $key,
        ];
    }
    $snapshot = docs_read_mini_app_user_tasks_snapshot_json($tempPath);
    @unlink($tempPath);
    if (!is_array($snapshot)) {
        return [
            'ok' => false,
            'error' => 'snapshot_decode_failed',
            'message' => 'JSON-снимок задач повреждён или пуст.',
            'notFound' => false,
            'relativePath' => $relativePath,
            'key' => $key,
        ];
    }
    return [
        'ok' => true,
        'source' => 's3',
        'remotePath' => docs_cold_storage_remote_path($key),
        'relativePath' => $relativePath,
        'key' => $key,
        'snapshot' => $snapshot,
    ];
}
function docs_load_mini_app_user_tasks_snapshot(string $telegramUserId, int $timeoutSeconds = 20): array
{
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId === '') {
        return [
            'ok' => false,
            'error' => 'telegram_user_id_missing',
            'message' => 'Не удалось определить Telegram ID.',
        ];
    }
    $safeTelegramUserId = docs_sanitize_mini_app_user_tasks_snapshot_id($telegramUserId);
    $relativePath = docs_build_mini_app_user_tasks_snapshot_relative_path($safeTelegramUserId);
    return docs_load_mini_app_tasks_snapshot_from_relative_path($relativePath, $timeoutSeconds);
}
function docs_task_snapshot_key(array $task): string
{
    $folder = '';
    if (isset($task['documentFolder']) && is_scalar($task['documentFolder'])) {
        $folder = sanitize_folder_name(trim((string) $task['documentFolder']));
    }
    if ($folder === '' && isset($task['organization']) && is_scalar($task['organization'])) {
        $folder = sanitize_folder_name(trim((string) $task['organization']));
    }
    $parts = [$folder];
    foreach (['id', 'entryNumber', 'registryNumber', 'documentNumber'] as $field) {
        $value = sanitize_text_field((string) ($task[$field] ?? ''), 200);
        if ($value !== '') {
            $parts[] = $field . ':' . $value;
            break;
        }
    }
    if (count($parts) === 1) {
        $summaryText = '';
        foreach (['summary', 'contentCompact', 'content', 'description', 'text'] as $summaryField) {
            $summaryText = sanitize_text_field((string) ($task[$summaryField] ?? ''), 500);
            if ($summaryText !== '') {
                break;
            }
        }
        $summary = [
            'summary' => $summaryText,
            'correspondent' => sanitize_text_field((string) ($task['correspondent'] ?? ''), 300),
            'documentType' => sanitize_text_field((string) ($task['documentType'] ?? ''), 160),
            'documentDate' => sanitize_date_field((string) ($task['documentDate'] ?? '')),
            'registrationDate' => sanitize_date_field((string) ($task['registrationDate'] ?? '')),
            'createdAt' => sanitize_text_field((string) ($task['createdAt'] ?? ''), 80),
        ];
        $encoded = json_encode($summary, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        $parts[] = 'hash:' . sha1(is_string($encoded) ? $encoded : serialize($summary));
    }
    return implode('|', $parts);
}
function docs_load_telegram_participant_directory_entries(string $folder): array
{
    if ($folder === '') {
        return [];
    }
    $settings = load_admin_settings($folder);
    $directoryEntries = [];
    foreach (['responsibles', 'block2', 'block3'] as $group) {
        if (isset($settings[$group]) && is_array($settings[$group])) {
            $directoryEntries = array_merge($directoryEntries, $settings[$group]);
        }
    }
    return $directoryEntries;
}
function docs_collect_admin_settings_telegram_ids(array $settings): array
{
    $telegramIds = [];
    foreach (['responsibles', 'block2', 'block3'] as $group) {
        foreach (isset($settings[$group]) && is_array($settings[$group]) ? $settings[$group] : [] as $entry) {
            if (!is_array($entry)) {
                continue;
            }
            $telegramId = normalize_identifier_value(
                docs_resolve_telegram_chat_id_from_assignee($entry)
            );
            if ($telegramId !== '' && preg_match('/^-?\d{4,}$/', $telegramId)) {
                $telegramIds[$telegramId] = true;
            }
        }
    }
    $result = array_keys($telegramIds);
    sort($result, SORT_NATURAL);
    return $result;
}
function docs_resolve_explicit_telegram_id_from_participant(array $participant): ?string
{
    foreach (['telegram', 'telegramId', 'telegram_id', 'chatId', 'chat_id'] as $field) {
        if (!array_key_exists($field, $participant)) {
            continue;
        }
        $telegramId = normalize_identifier_value($participant[$field]);
        if ($telegramId !== '' && preg_match('/^-?\d{4,}$/', $telegramId)) {
            return $telegramId;
        }
    }
    return null;
}
function docs_resolve_participant_telegram_id(array $participant, array $directoryEntries = []): ?string
{
    $telegramId = docs_resolve_explicit_telegram_id_from_participant($participant);
    if ($telegramId !== null) {
        return (string) $telegramId;
    }
    foreach (['id', 'userId', 'login', 'username', 'email', 'name', 'responsible', 'fio', 'fullName'] as $field) {
        $candidate = sanitize_text_field((string) ($participant[$field] ?? ''), 200);
        if ($candidate === '') {
            continue;
        }
        $directoryEntry = docs_find_responsible_by_candidate($directoryEntries, $candidate);
        if (!is_array($directoryEntry)) {
            continue;
        }
        $telegramId = docs_resolve_telegram_chat_id_from_assignee($directoryEntry);
        if ($telegramId !== null) {
            return (string) $telegramId;
        }
    }
    // Старые записи могли хранить Telegram ID только в userId/id. Используем
    // этот вариант последним, чтобы внутренний числовой ID не подменил
    // Telegram ID, который доступен в справочнике организации.
    return docs_resolve_telegram_chat_id_from_assignee($participant);
}
function docs_collect_record_telegram_participation(
    array $record,
    string $folder = '',
    ?array $directoryEntries = null
): array {
    if ($directoryEntries === null) {
        $directoryEntries = docs_load_telegram_participant_directory_entries($folder);
    }
    $participation = [];
    foreach (['responsible', 'subordinate', 'director'] as $role) {
        foreach (docs_collect_record_role_participants($record, $role) as $participant) {
            if (!is_array($participant)) {
                continue;
            }
            $telegramId = docs_resolve_participant_telegram_id($participant, $directoryEntries);
            if ($telegramId === null || $telegramId === '') {
                continue;
            }
            $key = 'telegram:' . $telegramId;
            if (!isset($participation[$key])) {
                $participation[$key] = [
                    'telegramId' => $telegramId,
                    'roles' => [],
                ];
            }
            if (!in_array($role, $participation[$key]['roles'], true)) {
                $participation[$key]['roles'][] = $role;
            }
        }
    }
    return array_values($participation);
}
function docs_collect_record_telegram_ids(array $record, string $folder = ''): array
{
    return array_values(array_map(static function (array $participant): string {
        return (string) ($participant['telegramId'] ?? '');
    }, docs_collect_record_telegram_participation($record, $folder)));
}
function docs_ocr_s3_users_index_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_S3_USERS_INDEX_FILENAME);
}
function docs_ocr_s3_users_index_lock_path(): string
{
    return docs_ocr_runtime_path(DOCS_OCR_S3_USERS_INDEX_LOCK_FILENAME);
}
function docs_default_ocr_s3_users_index(): array
{
    return [
        'version' => 1,
        'updatedAt' => date('c'),
        'users' => [],
    ];
}
function docs_load_ocr_s3_users_index_unlocked(): array
{
    $path = docs_ocr_s3_users_index_path();
    $decoded = docs_read_json_array_file_with_backup($path);
    if (!is_array($decoded) || (int) ($decoded['version'] ?? 0) !== 1) {
        return docs_default_ocr_s3_users_index();
    }
    $decoded['users'] = isset($decoded['users']) && is_array($decoded['users'])
        ? $decoded['users']
        : [];
    return $decoded;
}
function docs_load_ocr_s3_users_index(): array
{
    $handle = @fopen(docs_ocr_s3_users_index_lock_path(), 'c+');
    if ($handle === false || !@flock($handle, LOCK_SH)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return docs_default_ocr_s3_users_index();
    }
    try {
        return docs_load_ocr_s3_users_index_unlocked();
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_mutate_ocr_s3_users_index(callable $callback): array
{
    $handle = @fopen(docs_ocr_s3_users_index_lock_path(), 'c+');
    if ($handle === false || !@flock($handle, LOCK_EX)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return ['ok' => false, 'error' => 'Не удалось заблокировать индекс OCR-пользователей.'];
    }
    try {
        $state = docs_load_ocr_s3_users_index_unlocked();
        $result = $callback($state);
        $state['version'] = 1;
        $state['updatedAt'] = date('c');
        if (!docs_write_json_file_atomically(docs_ocr_s3_users_index_path(), $state)) {
            return ['ok' => false, 'error' => 'Не удалось сохранить индекс OCR-пользователей.'];
        }
        return is_array($result) ? array_merge(['ok' => true], $result) : ['ok' => true];
    } finally {
        @flock($handle, LOCK_UN);
        fclose($handle);
    }
}
function docs_resolve_ocr_snapshot_user_name(array $snapshot): string
{
    $user = isset($snapshot['user']) && is_array($snapshot['user']) ? $snapshot['user'] : [];
    foreach (['fullName', 'name', 'displayName', 'username'] as $field) {
        $value = sanitize_text_field((string) ($user[$field] ?? ''), 200);
        if ($value !== '') {
            return $value;
        }
    }
    $parts = array_values(array_filter([
        sanitize_text_field((string) ($user['first_name'] ?? ($user['firstName'] ?? '')), 100),
        sanitize_text_field((string) ($user['last_name'] ?? ($user['lastName'] ?? '')), 100),
    ]));
    return trim(implode(' ', $parts));
}
function docs_validate_mini_app_user_tasks_snapshot_identity(array $snapshot, string $telegramId): array
{
    $telegramId = normalize_identifier_value($telegramId);
    if ($telegramId === '' || preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1) {
        return ['ok' => false, 'error' => 'Некорректный Telegram ID.'];
    }
    if ((int) ($snapshot['version'] ?? 0) !== 2
        || (string) ($snapshot['source'] ?? '') !== 'mini_app_tasks'
        || !isset($snapshot['tasks'])
        || !is_array($snapshot['tasks'])
    ) {
        return ['ok' => false, 'error' => 'Telegram JSON имеет неизвестный или повреждённый формат.'];
    }
    $snapshotTelegramId = normalize_identifier_value($snapshot['telegramUserId'] ?? '');
    if ($snapshotTelegramId === '' || !hash_equals($telegramId, $snapshotTelegramId)) {
        return ['ok' => false, 'error' => 'Telegram ID внутри S3-снимка не совпал с его путём.'];
    }
    if (array_key_exists('tasksCount', $snapshot)
        && (int) $snapshot['tasksCount'] !== count($snapshot['tasks'])
    ) {
        return ['ok' => false, 'error' => 'Счётчик задач в Telegram JSON не совпал с массивом tasks.'];
    }
    return ['ok' => true, 'error' => ''];
}
function docs_validate_ocr_text_in_user_snapshot_file(array $file): array
{
    $text = isset($file['ocrText']) && is_string($file['ocrText'])
        ? trim($file['ocrText'])
        : '';
    if ($text === '') {
        return ['ok' => false, 'text' => '', 'textLength' => 0, 'textSha256' => '', 'error' => 'ocr_text_missing'];
    }
    $textLength = mb_strlen($text, 'UTF-8');
    $textSha256 = hash('sha256', $text);
    $declaredLength = array_key_exists('ocrTextLength', $file)
        ? (int) $file['ocrTextLength']
        : null;
    $ocr = isset($file['ocr']) && is_array($file['ocr']) ? $file['ocr'] : [];
    $archiveLength = array_key_exists('archiveTextLength', $ocr)
        ? (int) $ocr['archiveTextLength']
        : null;
    $archiveHash = sanitize_text_field((string) ($ocr['archiveTextSha256'] ?? ''), 80);
    if (($declaredLength !== null && $declaredLength !== $textLength)
        || ($archiveLength !== null && $archiveLength > 0 && $archiveLength !== $textLength)
        || ($archiveHash !== '' && (
            preg_match('/^[a-f0-9]{64}$/', $archiveHash) !== 1
            || !hash_equals($archiveHash, $textSha256)
        ))
    ) {
        return [
            'ok' => false,
            'text' => '',
            'textLength' => $textLength,
            'textSha256' => $textSha256,
            'error' => 'ocr_text_integrity_failed',
        ];
    }
    return [
        'ok' => true,
        'text' => $text,
        'textLength' => $textLength,
        'textSha256' => $textSha256,
        'error' => '',
    ];
}
function docs_summarize_ocr_user_snapshot(string $telegramId, array $snapshot, string $key): array
{
    $tasksCount = 0;
    $tasksWithOcr = 0;
    $filesCount = 0;
    $eligibleFiles = 0;
    $filesWithOcr = 0;
    $ocrTextCharacters = 0;
    $integrityErrors = 0;
    foreach (isset($snapshot['tasks']) && is_array($snapshot['tasks']) ? $snapshot['tasks'] : [] as $task) {
        if (!is_array($task)) {
            continue;
        }
        $tasksCount++;
        $taskHasOcr = false;
        foreach (isset($task['files']) && is_array($task['files']) ? $task['files'] : [] as $file) {
            if (!is_array($file)) {
                continue;
            }
            $filesCount++;
            $supported = docs_is_live_ocr_supported_file($file);
            if ($supported) {
                $eligibleFiles++;
            }
            $textCheck = docs_validate_ocr_text_in_user_snapshot_file($file);
            if (empty($textCheck['ok'])) {
                if ((string) ($textCheck['error'] ?? '') === 'ocr_text_integrity_failed') {
                    $integrityErrors++;
                }
                continue;
            }
            $taskHasOcr = true;
            if ($supported) {
                $filesWithOcr++;
            }
            $ocrTextCharacters += (int) ($textCheck['textLength'] ?? 0);
        }
        if ($taskHasOcr) {
            $tasksWithOcr++;
        }
    }
    $declaredTasksCount = array_key_exists('tasksCount', $snapshot)
        ? max(0, (int) $snapshot['tasksCount'])
        : $tasksCount;
    $allOcrPresent = $filesWithOcr >= $eligibleFiles
        && $integrityErrors === 0
        && $declaredTasksCount === $tasksCount;
    return [
        'telegramId' => normalize_identifier_value($telegramId),
        'name' => docs_resolve_ocr_snapshot_user_name($snapshot),
        's3Key' => sanitize_text_field($key, 1000),
        's3Status' => $allOcrPresent ? 'complete' : 'incomplete',
        'allOcrPresent' => $allOcrPresent,
        'generatedAt' => sanitize_text_field((string) ($snapshot['generatedAt'] ?? ''), 80),
        'verifiedAt' => date('c'),
        'tasksCount' => $tasksCount,
        'tasksWithOcr' => $tasksWithOcr,
        'filesCount' => $filesCount,
        'eligibleFiles' => $eligibleFiles,
        'filesWithOcr' => $filesWithOcr,
        'missingOcrFiles' => max(0, $eligibleFiles - $filesWithOcr),
        'integrityErrors' => $integrityErrors + ($declaredTasksCount === $tasksCount ? 0 : 1),
        'ocrTextCharacters' => $ocrTextCharacters,
        'error' => '',
    ];
}
function docs_update_ocr_s3_user_index_from_snapshot(
    string $telegramId,
    array $snapshot,
    string $key
): void {
    $telegramId = normalize_identifier_value($telegramId);
    if ($telegramId === '') {
        return;
    }
    $summary = docs_summarize_ocr_user_snapshot($telegramId, $snapshot, $key);
    docs_mutate_ocr_s3_users_index(static function (array &$state) use ($telegramId, $summary): array {
        $state['users'][$telegramId] = $summary;
        return ['updated' => true];
    });
}
function docs_mark_ocr_s3_user_index_error(string $telegramId, string $error): void
{
    $telegramId = normalize_identifier_value($telegramId);
    if ($telegramId === '') {
        return;
    }
    docs_mutate_ocr_s3_users_index(static function (array &$state) use ($telegramId, $error): array {
        $current = isset($state['users'][$telegramId]) && is_array($state['users'][$telegramId])
            ? $state['users'][$telegramId]
            : ['telegramId' => $telegramId];
        $state['users'][$telegramId] = array_replace($current, [
            'telegramId' => $telegramId,
            's3Status' => 'error',
            'verifiedAt' => date('c'),
            'error' => sanitize_text_field($error, 500),
        ]);
        return ['updated' => true];
    });
}
function docs_verify_task_file_ocr_in_user_s3_snapshot(
    string $telegramId,
    array $record,
    string $folder,
    string $storedName,
    string $expectedText
): array {
    $telegramId = normalize_identifier_value($telegramId);
    $storedName = sanitize_text_field($storedName, 255);
    $expectedText = trim($expectedText);
    $record['documentFolder'] = sanitize_folder_name($folder);
    $taskKey = docs_task_snapshot_key($record);
    if (preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1
        || $storedName === ''
        || $expectedText === ''
        || $taskKey === ''
    ) {
        return ['ok' => false, 'error' => 'Недостаточно данных для проверки Telegram JSON в S3.'];
    }
    $loaded = docs_load_mini_app_user_tasks_snapshot($telegramId);
    if (empty($loaded['ok']) || !is_array($loaded['snapshot'] ?? null)) {
        $error = sanitize_text_field(
            (string) ($loaded['message'] ?? 'Telegram JSON пользователя не прочитан из S3.'),
            500
        );
        docs_mark_ocr_s3_user_index_error($telegramId, $error);
        return [
            'ok' => false,
            'telegramId' => $telegramId,
            'key' => (string) ($loaded['key'] ?? ''),
            'error' => $error,
        ];
    }
    $identity = docs_validate_mini_app_user_tasks_snapshot_identity(
        (array) $loaded['snapshot'],
        $telegramId
    );
    if (empty($identity['ok'])) {
        $error = sanitize_text_field((string) ($identity['error'] ?? 'Telegram JSON не прошёл проверку.'), 500);
        docs_mark_ocr_s3_user_index_error($telegramId, $error);
        return [
            'ok' => false,
            'telegramId' => $telegramId,
            'key' => (string) ($loaded['key'] ?? ''),
            'error' => $error,
        ];
    }
    $actualText = '';
    $integrityError = false;
    foreach ((array) ($loaded['snapshot']['tasks'] ?? []) as $task) {
        if (!is_array($task) || docs_task_snapshot_key($task) !== $taskKey) {
            continue;
        }
        foreach ((array) ($task['files'] ?? []) as $file) {
            if (!is_array($file)
                || sanitize_text_field((string) ($file['storedName'] ?? ''), 255) !== $storedName
            ) {
                continue;
            }
            $textCheck = docs_validate_ocr_text_in_user_snapshot_file($file);
            $actualText = !empty($textCheck['ok']) ? (string) ($textCheck['text'] ?? '') : '';
            $integrityError = (string) ($textCheck['error'] ?? '') === 'ocr_text_integrity_failed';
            break;
        }
        break;
    }
    if ($actualText === '' || !hash_equals(hash('sha256', $expectedText), hash('sha256', $actualText))) {
        $error = $actualText === ''
            ? ($integrityError
                ? 'OCR-текст файла в Telegram JSON пользователя не прошёл проверку целостности.'
                : 'В Telegram JSON пользователя в S3 отсутствует OCR-текст файла.')
            : 'OCR-текст в Telegram JSON пользователя не совпал с результатом файла.';
        docs_mark_ocr_s3_user_index_error($telegramId, $error);
        return [
            'ok' => false,
            'telegramId' => $telegramId,
            'key' => (string) ($loaded['key'] ?? ''),
            'error' => $error,
        ];
    }
    docs_update_ocr_s3_user_index_from_snapshot(
        $telegramId,
        (array) $loaded['snapshot'],
        (string) ($loaded['key'] ?? '')
    );
    if (!docs_task_rag_invalidate_sync_cache($telegramId)) {
        $error = 'Не удалось пометить Telegram-поиск как устаревший.';
        docs_mark_ocr_s3_user_index_error($telegramId, $error);
        return [
            'ok' => false,
            'telegramId' => $telegramId,
            'key' => (string) ($loaded['key'] ?? ''),
            'error' => $error,
        ];
    }
    return [
        'ok' => true,
        'telegramId' => $telegramId,
        'key' => (string) ($loaded['key'] ?? ''),
        'textLength' => mb_strlen($actualText, 'UTF-8'),
        'verifiedAt' => date('c'),
        'error' => '',
    ];
}
function docs_resolve_ocr_directory_entry_name(array $entry): string
{
    foreach (['fullName', 'responsible', 'name', 'fio', 'displayName', 'login', 'username'] as $field) {
        $value = sanitize_text_field((string) ($entry[$field] ?? ''), 200);
        if ($value !== '') {
            return $value;
        }
    }
    return '';
}
function docs_collect_ocr_s3_user_directory(): array
{
    $users = [];
    foreach (load_organizations() as $organization) {
        if (!is_string($organization) || trim($organization) === '') {
            continue;
        }
        $folder = sanitize_folder_name($organization);
        if ($folder === '' || !is_dir(DOCUMENTS_ROOT . '/' . $folder)) {
            continue;
        }
        $settings = load_admin_settings($folder);
        foreach (['responsibles', 'block2', 'block3'] as $group) {
            foreach (isset($settings[$group]) && is_array($settings[$group]) ? $settings[$group] : [] as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $telegramId = normalize_identifier_value(
                    docs_resolve_telegram_chat_id_from_assignee($entry)
                );
                if (preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1) {
                    continue;
                }
                if (!isset($users[$telegramId])) {
                    $users[$telegramId] = [
                        'telegramId' => $telegramId,
                        'name' => docs_resolve_ocr_directory_entry_name($entry),
                        'organizations' => [],
                    ];
                } elseif ((string) ($users[$telegramId]['name'] ?? '') === '') {
                    $users[$telegramId]['name'] = docs_resolve_ocr_directory_entry_name($entry);
                }
                if (!in_array($organization, $users[$telegramId]['organizations'], true)) {
                    $users[$telegramId]['organizations'][] = sanitize_text_field($organization, 200);
                }
            }
        }
    }
    return $users;
}
function docs_list_admin_ocr_s3_users(
    int $page,
    int $pageSize,
    string $query,
    string $statusFilter = ''
): array {
    $listing = docs_list_cold_storage_objects(
        DOCS_OCR_TEXT_ARCHIVE_STORAGE_FOLDER,
        MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_DIRECTORY
    );
    if (empty($listing['ok'])) {
        return [
            'ok' => false,
            'error' => sanitize_text_field(
                (string) ($listing['message'] ?? 'Не удалось получить список Telegram JSON из S3.'),
                500
            ),
        ];
    }
    $directory = docs_collect_ocr_s3_user_directory();
    $index = docs_load_ocr_s3_users_index();
    $indexedUsers = isset($index['users']) && is_array($index['users']) ? $index['users'] : [];
    $users = $directory;
    foreach ((array) ($listing['items'] ?? []) as $object) {
        if (!is_array($object) || (string) ($object['type'] ?? '') !== 'file') {
            continue;
        }
        $name = sanitize_text_field((string) ($object['name'] ?? ''), 255);
        if (strtolower((string) pathinfo($name, PATHINFO_EXTENSION)) !== 'json') {
            continue;
        }
        $telegramId = normalize_identifier_value((string) pathinfo($name, PATHINFO_FILENAME));
        if (preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1) {
            continue;
        }
        if (!isset($users[$telegramId])) {
            $users[$telegramId] = [
                'telegramId' => $telegramId,
                'name' => '',
                'organizations' => [],
            ];
        }
        $users[$telegramId]['s3Exists'] = true;
        $users[$telegramId]['s3Key'] = sanitize_text_field((string) ($object['remoteKey'] ?? ''), 1000);
        $users[$telegramId]['s3Size'] = max(0, (int) ($object['size'] ?? 0));
        $users[$telegramId]['s3SizeLabel'] = sanitize_text_field((string) ($object['sizeLabel'] ?? ''), 80);
        $users[$telegramId]['s3ModifiedAt'] = sanitize_text_field((string) ($object['modifiedAt'] ?? ''), 80);
    }
    foreach ($users as $telegramId => &$user) {
        $cached = isset($indexedUsers[$telegramId]) && is_array($indexedUsers[$telegramId])
            ? $indexedUsers[$telegramId]
            : [];
        $directoryName = sanitize_text_field((string) ($user['name'] ?? ''), 200);
        $cachedName = sanitize_text_field((string) ($cached['name'] ?? ''), 200);
        $user = array_replace([
            'telegramId' => $telegramId,
            'name' => '',
            'organizations' => [],
            's3Exists' => false,
            's3Key' => '',
            's3Size' => 0,
            's3SizeLabel' => '',
            's3ModifiedAt' => '',
            's3Status' => 'not_checked',
            'allOcrPresent' => false,
            'generatedAt' => '',
            'verifiedAt' => '',
            'tasksCount' => 0,
            'tasksWithOcr' => 0,
            'filesCount' => 0,
            'eligibleFiles' => 0,
            'filesWithOcr' => 0,
            'missingOcrFiles' => 0,
            'ocrTextCharacters' => 0,
            'error' => '',
        ], $cached, $user);
        $user['name'] = $directoryName !== '' ? $directoryName : $cachedName;
        if (empty($user['s3Exists'])) {
            $user['s3Status'] = 'missing';
            $user['allOcrPresent'] = false;
        } elseif (empty($cached)) {
            $user['s3Status'] = 'not_checked';
        } else {
            $verifiedAt = strtotime((string) ($cached['verifiedAt'] ?? '')) ?: 0;
            $modifiedAt = strtotime((string) ($user['s3ModifiedAt'] ?? '')) ?: 0;
            if ($verifiedAt <= 0 || $modifiedAt <= 0 || $modifiedAt > $verifiedAt) {
                $user['s3Status'] = 'not_checked';
                $user['allOcrPresent'] = false;
                $user['error'] = '';
            }
        }
        $user['organizations'] = array_values(array_unique(array_filter(
            isset($user['organizations']) && is_array($user['organizations']) ? $user['organizations'] : []
        )));
    }
    unset($user);
    $query = mb_strtolower(sanitize_text_field($query, 200), 'UTF-8');
    $allowedStatuses = ['complete', 'incomplete', 'error', 'missing', 'not_checked'];
    $statusFilter = in_array($statusFilter, $allowedStatuses, true) ? $statusFilter : '';
    $filtered = [];
    foreach ($users as $user) {
        if ($statusFilter !== '' && (string) ($user['s3Status'] ?? '') !== $statusFilter) {
            continue;
        }
        if ($query !== '') {
            $haystack = mb_strtolower(implode(' ', [
                (string) ($user['telegramId'] ?? ''),
                (string) ($user['name'] ?? ''),
                implode(' ', (array) ($user['organizations'] ?? [])),
            ]), 'UTF-8');
            if (mb_strpos($haystack, $query, 0, 'UTF-8') === false) {
                continue;
            }
        }
        $filtered[] = $user;
    }
    usort($filtered, static function (array $left, array $right): int {
        $leftName = mb_strtolower((string) ($left['name'] ?? ''), 'UTF-8');
        $rightName = mb_strtolower((string) ($right['name'] ?? ''), 'UTF-8');
        if ($leftName === $rightName) {
            return strnatcasecmp((string) ($left['telegramId'] ?? ''), (string) ($right['telegramId'] ?? ''));
        }
        if ($leftName === '') {
            return 1;
        }
        if ($rightName === '') {
            return -1;
        }
        return strcmp($leftName, $rightName);
    });
    $page = max(1, $page);
    $pageSize = max(1, min(DOCS_OCR_S3_USERS_MAX_PAGE_SIZE, $pageSize));
    $total = count($filtered);
    $pages = max(1, (int) ceil($total / $pageSize));
    $page = min($page, $pages);
    return [
        'ok' => true,
        'items' => array_values(array_slice($filtered, ($page - 1) * $pageSize, $pageSize)),
        'pagination' => [
            'page' => $page,
            'pageSize' => $pageSize,
            'total' => $total,
            'pages' => $pages,
        ],
        's3Path' => MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_DIRECTORY,
        'checkedAt' => date('c'),
    ];
}
function docs_build_ocr_s3_entry_token(string $taskKey, string $storedName): string
{
    return hash('sha256', $taskKey . "\0" . $storedName);
}
function docs_build_ocr_text_preview(string $text, string $query): string
{
    $text = trim($text);
    if ($text === '') {
        return '';
    }
    $start = 0;
    if ($query !== '') {
        $position = mb_stripos($text, $query, 0, 'UTF-8');
        if ($position !== false) {
            $start = max(0, (int) $position - 180);
        }
    }
    $preview = mb_substr($text, $start, DOCS_OCR_S3_TEXT_PREVIEW_LENGTH, 'UTF-8');
    return ($start > 0 ? '…' : '')
        . $preview
        . (mb_strlen($text, 'UTF-8') > $start + DOCS_OCR_S3_TEXT_PREVIEW_LENGTH ? '…' : '');
}
function docs_list_admin_ocr_s3_user_files(
    string $telegramId,
    int $page,
    int $pageSize,
    string $query
): array {
    @ini_set('memory_limit', DOCS_TASK_SNAPSHOT_READ_MEMORY_LIMIT);
    $telegramId = normalize_identifier_value($telegramId);
    if ($telegramId === '' || preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1) {
        return ['ok' => false, 'error' => 'Некорректный Telegram ID пользователя.'];
    }
    $loaded = docs_load_mini_app_user_tasks_snapshot($telegramId);
    if (empty($loaded['ok']) || !is_array($loaded['snapshot'] ?? null)) {
        return [
            'ok' => false,
            'error' => sanitize_text_field(
                (string) ($loaded['message'] ?? 'Telegram JSON пользователя не прочитан из S3.'),
                500
            ),
        ];
    }
    $snapshot = $loaded['snapshot'];
    $identity = docs_validate_mini_app_user_tasks_snapshot_identity($snapshot, $telegramId);
    if (empty($identity['ok'])) {
        return ['ok' => false, 'error' => (string) ($identity['error'] ?? 'Telegram JSON не прошёл проверку.')];
    }
    docs_update_ocr_s3_user_index_from_snapshot(
        $telegramId,
        $snapshot,
        (string) ($loaded['key'] ?? '')
    );
    $query = sanitize_text_field($query, 200);
    $items = [];
    foreach ((array) ($snapshot['tasks'] ?? []) as $task) {
        if (!is_array($task)) {
            continue;
        }
        $taskKey = docs_task_snapshot_key($task);
        $taskLabel = docs_ocr_backfill_task_label($task);
        $organization = sanitize_text_field((string) ($task['organization'] ?? ''), 200);
        foreach ((array) ($task['files'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
            $fileName = sanitize_text_field(
                (string) ($file['originalName'] ?? ($file['name'] ?? $storedName)),
                255
            );
            $textCheck = docs_validate_ocr_text_in_user_snapshot_file($file);
            $text = !empty($textCheck['ok']) ? (string) ($textCheck['text'] ?? '') : '';
            if ($query !== '') {
                $metadata = implode(' ', [$organization, $taskLabel, $taskKey, $fileName, $storedName]);
                if (mb_stripos($metadata, $query, 0, 'UTF-8') === false
                    && ($text === '' || mb_stripos($text, $query, 0, 'UTF-8') === false)
                ) {
                    continue;
                }
            }
            $items[] = [
                'entryToken' => docs_build_ocr_s3_entry_token($taskKey, $storedName),
                'taskKey' => $taskKey,
                'taskLabel' => $taskLabel,
                'organization' => $organization,
                'fileName' => $fileName !== '' ? $fileName : ($storedName !== '' ? $storedName : 'Файл без имени'),
                'storedName' => $storedName,
                'supported' => docs_is_live_ocr_supported_file($file),
                'textPresent' => $text !== '',
                'ocrTextLength' => $text !== '' ? (int) ($textCheck['textLength'] ?? 0) : 0,
                'ocrTextSha256' => $text !== '' ? (string) ($textCheck['textSha256'] ?? '') : '',
                'integrityError' => (string) ($textCheck['error'] ?? '') === 'ocr_text_integrity_failed',
                'textPreview' => docs_build_ocr_text_preview($text, $query),
            ];
        }
    }
    $page = max(1, $page);
    $pageSize = max(1, min(DOCS_OCR_S3_FILES_MAX_PAGE_SIZE, $pageSize));
    $total = count($items);
    $pages = max(1, (int) ceil($total / $pageSize));
    $page = min($page, $pages);
    return [
        'ok' => true,
        'user' => [
            'telegramId' => $telegramId,
            'name' => docs_resolve_ocr_snapshot_user_name($snapshot),
        ],
        'snapshot' => [
            'key' => (string) ($loaded['key'] ?? ''),
            'generatedAt' => sanitize_text_field((string) ($snapshot['generatedAt'] ?? ''), 80),
            'readAt' => date('c'),
        ],
        'summary' => docs_summarize_ocr_user_snapshot(
            $telegramId,
            $snapshot,
            (string) ($loaded['key'] ?? '')
        ),
        'items' => array_values(array_slice($items, ($page - 1) * $pageSize, $pageSize)),
        'pagination' => [
            'page' => $page,
            'pageSize' => $pageSize,
            'total' => $total,
            'pages' => $pages,
        ],
    ];
}
function docs_read_admin_ocr_s3_text(
    string $telegramId,
    string $entryToken,
    int $offset,
    int $limit
): array {
    @ini_set('memory_limit', DOCS_TASK_SNAPSHOT_READ_MEMORY_LIMIT);
    $telegramId = normalize_identifier_value($telegramId);
    $entryToken = sanitize_text_field($entryToken, 80);
    if (preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1
        || preg_match('/^[a-f0-9]{64}$/D', $entryToken) !== 1
    ) {
        return ['ok' => false, 'error' => 'Некорректный пользователь или идентификатор OCR-текста.'];
    }
    $loaded = docs_load_mini_app_user_tasks_snapshot($telegramId);
    if (empty($loaded['ok']) || !is_array($loaded['snapshot'] ?? null)) {
        return [
            'ok' => false,
            'error' => sanitize_text_field(
                (string) ($loaded['message'] ?? 'Telegram JSON пользователя не прочитан из S3.'),
                500
            ),
        ];
    }
    $snapshot = $loaded['snapshot'];
    $identity = docs_validate_mini_app_user_tasks_snapshot_identity($snapshot, $telegramId);
    if (empty($identity['ok'])) {
        return ['ok' => false, 'error' => (string) ($identity['error'] ?? 'Telegram JSON не прошёл проверку.')];
    }
    foreach ((array) ($snapshot['tasks'] ?? []) as $task) {
        if (!is_array($task)) {
            continue;
        }
        $taskKey = docs_task_snapshot_key($task);
        foreach ((array) ($task['files'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
            if (!hash_equals($entryToken, docs_build_ocr_s3_entry_token($taskKey, $storedName))) {
                continue;
            }
            $textCheck = docs_validate_ocr_text_in_user_snapshot_file($file);
            $text = !empty($textCheck['ok']) ? (string) ($textCheck['text'] ?? '') : '';
            if ($text === '') {
                return [
                    'ok' => false,
                    'error' => (string) ($textCheck['error'] ?? '') === 'ocr_text_integrity_failed'
                        ? 'OCR-текст выбранного файла не прошёл проверку целостности.'
                        : 'В выбранном файле S3 отсутствует OCR-текст.',
                ];
            }
            $totalLength = mb_strlen($text, 'UTF-8');
            $offset = max(0, min($offset, $totalLength));
            $limit = max(1, min(50000, $limit));
            $chunk = mb_substr($text, $offset, $limit, 'UTF-8');
            $nextOffset = $offset + mb_strlen($chunk, 'UTF-8');
            return [
                'ok' => true,
                'telegramId' => $telegramId,
                'entryToken' => $entryToken,
                'fileName' => sanitize_text_field(
                    (string) ($file['originalName'] ?? ($file['name'] ?? $storedName)),
                    255
                ),
                'taskLabel' => docs_ocr_backfill_task_label($task),
                'organization' => sanitize_text_field((string) ($task['organization'] ?? ''), 200),
                'ocrText' => $chunk,
                'offset' => $offset,
                'nextOffset' => $nextOffset,
                'totalLength' => $totalLength,
                'hasMore' => $nextOffset < $totalLength,
                'ocrTextSha256' => (string) ($textCheck['textSha256'] ?? hash('sha256', $text)),
                's3Key' => (string) ($loaded['key'] ?? ''),
                'readAt' => date('c'),
            ];
        }
    }
    return ['ok' => false, 'error' => 'OCR-текст с указанным идентификатором не найден в S3.'];
}
function docs_resolve_record_roles_for_telegram_user(
    array $record,
    string $telegramUserId,
    string $folder = '',
    ?array $directoryEntries = null,
    ?array $fallbackFilter = null
): array {
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId !== '') {
        foreach (docs_collect_record_telegram_participation($record, $folder, $directoryEntries) as $participant) {
            if (!is_array($participant)
                || normalize_identifier_value($participant['telegramId'] ?? '') !== $telegramUserId
            ) {
                continue;
            }
            $roles = [];
            foreach (isset($participant['roles']) && is_array($participant['roles']) ? $participant['roles'] : [] as $role) {
                $normalizedRole = docs_normalize_assignment_role((string) $role);
                if ($normalizedRole !== '') {
                    $roles[$normalizedRole] = true;
                }
            }
            return array_keys($roles);
        }
    }
    // Совместимость со старыми задачами, где участник уже записан Telegram ID,
    // username или ФИО непосредственно в самой задаче.
    return docs_resolve_record_roles_for_filter($record, $fallbackFilter);
}
function docs_merge_task_file_ocr_text(array $targetTask, array $sourceTask, bool $overwriteExisting): array
{
    if (!isset($targetTask['files']) || !is_array($targetTask['files'])) {
        return $targetTask;
    }
    $ocrTextByStoredName = [];
    foreach (isset($sourceTask['files']) && is_array($sourceTask['files']) ? $sourceTask['files'] : [] as $sourceFile) {
        if (!is_array($sourceFile)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($sourceFile['storedName'] ?? ''), 255);
        $textCheck = docs_validate_ocr_text_in_user_snapshot_file($sourceFile);
        $ocrText = !empty($textCheck['ok']) ? (string) ($textCheck['text'] ?? '') : '';
        if ($storedName !== '' && $ocrText !== '') {
            $ocrTextByStoredName[$storedName] = $ocrText;
        }
    }
    foreach ($targetTask['files'] as &$targetFile) {
        if (!is_array($targetFile)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($targetFile['storedName'] ?? ''), 255);
        if ($storedName === '' || !isset($ocrTextByStoredName[$storedName])) {
            continue;
        }
        $currentText = isset($targetFile['ocrText']) && is_string($targetFile['ocrText'])
            ? trim($targetFile['ocrText'])
            : '';
        if (!$overwriteExisting && $currentText !== '') {
            continue;
        }
        $targetFile['ocrText'] = $ocrTextByStoredName[$storedName];
        $targetFile['ocrTextLength'] = mb_strlen($ocrTextByStoredName[$storedName], 'UTF-8');
    }
    unset($targetFile);
    return $targetTask;
}
function docs_hydrate_task_ocr_from_participant_snapshots(array $record, array $telegramIds): array
{
    docs_apply_task_snapshot_memory_limit();
    $taskKey = docs_task_snapshot_key($record);
    if ($taskKey === '' || !isset($record['files']) || !is_array($record['files'])) {
        return $record;
    }
    $requiredStoredNames = [];
    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        $ocrStatus = isset($file['ocr']) && is_array($file['ocr'])
            ? strtolower((string) ($file['ocr']['status'] ?? ''))
            : '';
        if ($storedName !== '' && $ocrStatus === 'completed') {
            $requiredStoredNames[$storedName] = true;
        }
    }
    if (empty($requiredStoredNames)) {
        return $record;
    }
    $ocrTextByStoredName = [];
    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        if ($storedName === '' || !isset($requiredStoredNames[$storedName])) {
            continue;
        }
        $archive = docs_load_ocr_text_archive($file);
        if (!empty($archive['ok']) && isset($archive['text']) && is_string($archive['text'])) {
            $ocrTextByStoredName[$storedName] = trim($archive['text']);
        }
    }
    foreach (array_values(array_unique(array_map('strval', $telegramIds))) as $telegramId) {
        $telegramId = normalize_identifier_value($telegramId);
        if (preg_match('/^-?\d{4,20}$/D', $telegramId) !== 1) {
            continue;
        }
        $loaded = docs_load_mini_app_user_tasks_snapshot($telegramId);
        if (empty($loaded['ok']) || !is_array($loaded['snapshot'] ?? null)) {
            continue;
        }
        $identity = docs_validate_mini_app_user_tasks_snapshot_identity(
            (array) $loaded['snapshot'],
            $telegramId
        );
        if (empty($identity['ok'])) {
            continue;
        }
        foreach ((array) ($loaded['snapshot']['tasks'] ?? []) as $task) {
            if (!is_array($task) || docs_task_snapshot_key($task) !== $taskKey) {
                continue;
            }
            foreach ((array) ($task['files'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                if ($storedName === ''
                    || !isset($requiredStoredNames[$storedName])
                    || isset($ocrTextByStoredName[$storedName])
                ) {
                    continue;
                }
                $textCheck = docs_validate_ocr_text_in_user_snapshot_file($file);
                if (!empty($textCheck['ok'])) {
                    $ocrTextByStoredName[$storedName] = (string) ($textCheck['text'] ?? '');
                }
            }
            break;
        }
        if (count($ocrTextByStoredName) === count($requiredStoredNames)) {
            break;
        }
    }
    foreach ($record['files'] as &$file) {
        if (!is_array($file)) {
            continue;
        }
        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        if ($storedName !== '' && isset($ocrTextByStoredName[$storedName])) {
            $file['ocrText'] = $ocrTextByStoredName[$storedName];
            $file['ocrTextLength'] = mb_strlen($ocrTextByStoredName[$storedName], 'UTF-8');
            continue;
        }
        if ($storedName === '' || !isset($requiredStoredNames[$storedName])) {
            continue;
        }
        $jobId = isset($file['ocr']) && is_array($file['ocr'])
            ? sanitize_text_field((string) ($file['ocr']['jobId'] ?? ''), 160)
            : '';
        if ($jobId === '') {
            continue;
        }
        $jobResult = docs_fetch_private_ocr_job_result($jobId);
        if (!empty($jobResult['ok']) && isset($jobResult['text']) && is_string($jobResult['text'])) {
            $file['ocrText'] = $jobResult['text'];
            $file['ocrTextLength'] = mb_strlen($jobResult['text'], 'UTF-8');
        }
    }
    unset($file);
    return $record;
}
function docs_index_telegram_participation(array $participation): array
{
    $index = [];
    foreach ($participation as $participant) {
        if (!is_array($participant)) {
            continue;
        }
        $telegramId = normalize_identifier_value($participant['telegramId'] ?? '');
        if ($telegramId === '') {
            continue;
        }
        $roles = [];
        foreach (isset($participant['roles']) && is_array($participant['roles']) ? $participant['roles'] : [] as $role) {
            $normalizedRole = docs_normalize_assignment_role((string) $role);
            if ($normalizedRole !== '') {
                $roles[$normalizedRole] = true;
            }
        }
        $roleList = array_keys($roles);
        sort($roleList, SORT_STRING);
        $index[$telegramId] = $roleList;
    }
    ksort($index, SORT_STRING);
    return $index;
}
function docs_rebuild_mini_app_user_tasks_snapshot(string $telegramUserId, ?array $ocrTaskOverride = null): array
{
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId === '' || preg_match('/^-?\d{4,20}$/D', $telegramUserId) !== 1) {
        return [
            'saved' => false,
            'status' => 'skipped',
            'reason' => 'telegram_user_id_invalid',
        ];
    }
    $safeTelegramUserId = docs_sanitize_mini_app_user_tasks_snapshot_id($telegramUserId);
    $lockPath = docs_mini_app_user_tasks_snapshot_lock_path($safeTelegramUserId);
    $lockHandle = @fopen($lockPath, 'c+');
    if ($lockHandle === false || !flock($lockHandle, LOCK_EX)) {
        if (is_resource($lockHandle)) {
            fclose($lockHandle);
        }
        return [
            'saved' => false,
            'status' => 'lock_failed',
            'reason' => 'snapshot_lock_failed',
        ];
    }
    try {
        $loaded = docs_load_mini_app_user_tasks_snapshot($telegramUserId);
        if (empty($loaded['ok']) && empty($loaded['notFound'])) {
            return [
                'saved' => false,
                'status' => 's3_read_failed',
                'reason' => 's3_snapshot_read_failed',
                'error' => sanitize_text_field(
                    (string) ($loaded['message'] ?? 'Не удалось прочитать существующий Telegram JSON в S3.'),
                    500
                ),
                'snapshotExisted' => false,
                'expectedTasksCount' => 0,
                'actualTasksBefore' => 0,
                'missingTasksAdded' => 0,
                'staleTasksRemoved' => 0,
            ];
        }
        if (!empty($loaded['ok']) && isset($loaded['snapshot']) && is_array($loaded['snapshot'])) {
            $identity = docs_validate_mini_app_user_tasks_snapshot_identity(
                $loaded['snapshot'],
                $telegramUserId
            );
            if (empty($identity['ok'])) {
                return [
                    'saved' => false,
                    'status' => 'snapshot_identity_failed',
                    'reason' => 'snapshot_identity_failed',
                    'error' => sanitize_text_field(
                        (string) ($identity['error'] ?? 'Telegram JSON не прошёл проверку целостности.'),
                        500
                    ),
                    'snapshotExisted' => true,
                    'expectedTasksCount' => 0,
                    'actualTasksBefore' => 0,
                    'missingTasksAdded' => 0,
                    'staleTasksRemoved' => 0,
                ];
            }
            $snapshot = $loaded['snapshot'];
        } else {
            $snapshot = [
                'version' => 2,
                'source' => 'mini_app_tasks',
                'telegramUserId' => $telegramUserId,
                'user' => null,
                'organizations' => [],
                'stats' => [],
                'filter' => null,
                'directorMode' => [],
                'tasks' => [],
            ];
        }
        $existingTasksByKey = [];
        foreach (isset($snapshot['tasks']) && is_array($snapshot['tasks']) ? $snapshot['tasks'] : [] as $existingTask) {
            if (!is_array($existingTask)) {
                continue;
            }
            $existingKey = docs_task_snapshot_key($existingTask);
            if ($existingKey !== '') {
                $existingTasksByKey[$existingKey] = $existingTask;
            }
        }
        $filter = extract_assignee_filter_from_array([
            'telegram_user_id' => $telegramUserId,
        ]);
        if (!assignee_filter_has_identity($filter)) {
            return [
                'saved' => false,
                'status' => 'filter_failed',
                'reason' => 'telegram_filter_missing',
            ];
        }
        $tasks = [];
        $organizations = [];
        $seenTasks = [];
        foreach (load_organizations() as $organization) {
            if (!is_string($organization) || trim($organization) === '') {
                continue;
            }
            $folder = sanitize_folder_name($organization);
            $organizationTasksCount = 0;
            $directoryEntries = docs_load_telegram_participant_directory_entries($folder);
            $preparedRecords = docs_prepare_records_for_response(load_registry($folder), $organization, $folder);
            foreach ($preparedRecords as $preparedRecord) {
                if (!is_array($preparedRecord)) {
                    continue;
                }
                $preparedRecord['organization'] = $organization;
                $preparedRecord['documentFolder'] = $folder;
                $preparedTaskKey = docs_task_snapshot_key($preparedRecord);
                $roles = [];
                foreach (docs_collect_record_telegram_participation(
                    $preparedRecord,
                    $folder,
                    $directoryEntries
                ) as $participant) {
                    if (!is_array($participant)
                        || (string) ($participant['telegramId'] ?? '') !== $telegramUserId
                    ) {
                        continue;
                    }
                    $roles = isset($participant['roles']) && is_array($participant['roles'])
                        ? array_values($participant['roles'])
                        : [];
                    break;
                }
                if (empty($roles)) {
                    $roles = docs_resolve_record_roles_for_filter($preparedRecord, $filter);
                }
                if (empty($roles)) {
                    continue;
                }
                $preparedRecord['currentUserRoles'] = $roles;
                $taskKey = $preparedTaskKey;
                if ($taskKey === '' || isset($seenTasks[$taskKey])) {
                    continue;
                }
                $seenTasks[$taskKey] = true;
                if (isset($existingTasksByKey[$taskKey])) {
                    $preparedRecord = docs_merge_existing_task_snapshot_data(
                        $preparedRecord,
                        $existingTasksByKey[$taskKey]
                    );
                }
                if (is_array($ocrTaskOverride) && docs_task_snapshot_key($ocrTaskOverride) === $taskKey) {
                    $preparedRecord = docs_merge_task_file_ocr_text($preparedRecord, $ocrTaskOverride, true);
                }
                $preparedRecord['taskKey'] = $taskKey;
                $tasks[] = $preparedRecord;
                $organizationTasksCount++;
            }
            if ($organizationTasksCount > 0) {
                $organizations[] = [
                    'name' => $organization,
                    'count' => $organizationTasksCount,
                ];
            }
        }
        if (is_array($ocrTaskOverride)) {
            $overrideTaskKey = docs_task_snapshot_key($ocrTaskOverride);
            $requiredOcrStoredNames = [];
            foreach ((array) ($ocrTaskOverride['files'] ?? []) as $overrideFile) {
                if (!is_array($overrideFile) || !isset($overrideFile['ocrText']) || !is_string($overrideFile['ocrText'])) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($overrideFile['storedName'] ?? ''), 255);
                if ($storedName !== '' && trim($overrideFile['ocrText']) !== '') {
                    $requiredOcrStoredNames[$storedName] = true;
                }
            }
            if (!empty($requiredOcrStoredNames)) {
                $deliveredOcrStoredNames = [];
                foreach ($tasks as $task) {
                    if (!is_array($task) || docs_task_snapshot_key($task) !== $overrideTaskKey) {
                        continue;
                    }
                    foreach ((array) ($task['files'] ?? []) as $taskFile) {
                        if (!is_array($taskFile) || !isset($taskFile['ocrText']) || !is_string($taskFile['ocrText'])) {
                            continue;
                        }
                        $storedName = sanitize_text_field((string) ($taskFile['storedName'] ?? ''), 255);
                        if ($storedName !== '' && trim($taskFile['ocrText']) !== '') {
                            $deliveredOcrStoredNames[$storedName] = true;
                        }
                    }
                    break;
                }
                $missingOcrStoredNames = array_diff(
                    array_keys($requiredOcrStoredNames),
                    array_keys($deliveredOcrStoredNames)
                );
                if (!empty($missingOcrStoredNames)) {
                    return [
                        'saved' => false,
                        'status' => 'ocr_task_missing',
                        'reason' => 'ocr_task_or_text_missing',
                        'error' => 'OCR-текст не попал в JSON участника: '
                            . implode(', ', array_slice($missingOcrStoredNames, 0, 3)),
                    ];
                }
            }
        }
        $expectedTaskKeys = [];
        foreach ($tasks as $task) {
            if (!is_array($task)) {
                continue;
            }
            $taskKey = docs_task_snapshot_key($task);
            if ($taskKey !== '') {
                $expectedTaskKeys[$taskKey] = true;
            }
        }
        $missingTaskKeys = array_values(array_diff(
            array_keys($expectedTaskKeys),
            array_keys($existingTasksByKey)
        ));
        $staleTaskKeys = array_values(array_diff(
            array_keys($existingTasksByKey),
            array_keys($expectedTaskKeys)
        ));
        $snapshot['version'] = 2;
        $snapshot['source'] = 'mini_app_tasks';
        $snapshot['telegramUserId'] = $telegramUserId;
        $snapshot['generatedAt'] = date('c');
        $snapshot['tasks'] = array_values($tasks);
        $snapshot['tasksCount'] = count($tasks);
        $snapshot['organizations'] = $organizations;
        $relativePath = docs_build_mini_app_user_tasks_snapshot_relative_path($safeTelegramUserId);
        $upload = docs_write_mini_app_tasks_snapshot_payload($snapshot, $relativePath);
        $saved = !empty($upload['ok']);
        return [
            'saved' => $saved,
            'status' => $saved ? 'synced' : 's3_failed',
            'error' => $saved
                ? ''
                : sanitize_text_field(
                    (string) ($upload['error'] ?? 'Не удалось сохранить Telegram JSON пользователя в S3.'),
                    500
                ),
            'key' => (string) ($upload['key'] ?? docs_build_cold_storage_key(
                MINI_APP_USER_TASKS_SNAPSHOT_STORAGE_FOLDER,
                $relativePath
            )),
            'relativePath' => $relativePath,
            'snapshotExisted' => !empty($loaded['ok']),
            'expectedTasksCount' => count($expectedTaskKeys),
            'actualTasksBefore' => count($existingTasksByKey),
            'missingTasksAdded' => count($missingTaskKeys),
            'staleTasksRemoved' => count($staleTaskKeys),
        ];
    } finally {
        flock($lockHandle, LOCK_UN);
        fclose($lockHandle);
    }
}
function docs_sync_task_snapshots_after_participation_change(
    array $record,
    string $folder,
    array $previousParticipation,
    array $currentParticipation
): void {
    $record['documentFolder'] = sanitize_folder_name($folder);
    $previousIndex = docs_index_telegram_participation($previousParticipation);
    $currentIndex = docs_index_telegram_participation($currentParticipation);
    $snapshotRecord = docs_hydrate_task_ocr_from_participant_snapshots(
        $record,
        array_values(array_unique(array_merge(array_keys($previousIndex), array_keys($currentIndex))))
    );
    $telegramIds = array_values(array_unique(array_merge(array_keys($previousIndex), array_keys($currentIndex))));
    foreach ($telegramIds as $telegramId) {
        $result = isset($currentIndex[$telegramId])
            ? docs_rebuild_mini_app_user_tasks_snapshot((string) $telegramId, $snapshotRecord)
            : docs_rebuild_mini_app_user_tasks_snapshot((string) $telegramId);
        if (empty($result['saved'])) {
            docs_write_response_log('Не удалось синхронизировать задачи пользователя в Telegram JSON', [
                'folder' => $folder,
                'documentId' => $record['id'] ?? null,
                'telegramId' => $telegramId,
                'status' => $result['status'] ?? 'unknown',
                'error' => $result['error'] ?? ($result['reason'] ?? ''),
            ]);
        }
    }
}
function docs_read_system_crontab(): array
{
    $result = docs_run_process_with_timeout(['crontab', '-l'], DOCS_SYSTEM_CRONTAB_TIMEOUT_SECONDS);
    $content = (string) ($result['output'] ?? '');
    $error = trim((string) ($result['error'] ?? ''));
    $combinedError = trim($error . "\n" . $content);
    $missingCrontab = empty($result['ok'])
        && ($combinedError === '' || stripos($combinedError, 'no crontab') !== false);
    if (!empty($result['ok']) || $missingCrontab) {
        return [
            'ok' => true,
            'content' => $missingCrontab ? '' : $content,
            'error' => '',
        ];
    }
    return [
        'ok' => false,
        'content' => '',
        'error' => $combinedError !== '' ? sanitize_text_field($combinedError, 500) : 'Команда crontab недоступна.',
    ];
}
function docs_write_system_crontab(array $lines): array
{
    $tempPath = tempnam(sys_get_temp_dir(), '.documents_crontab_');
    if (!is_string($tempPath) || $tempPath === '') {
        return ['ok' => false, 'error' => 'Не удалось создать временный файл crontab.'];
    }
    try {
        $content = !empty($lines) ? implode(PHP_EOL, $lines) . PHP_EOL : '';
        if (@file_put_contents($tempPath, $content, LOCK_EX) === false) {
            return ['ok' => false, 'error' => 'Не удалось подготовить новый crontab.'];
        }
        $result = docs_run_process_with_timeout(['crontab', $tempPath], DOCS_SYSTEM_CRONTAB_TIMEOUT_SECONDS);
        if (empty($result['ok'])) {
            $error = trim((string) ($result['error'] ?? ($result['output'] ?? '')));
            return [
                'ok' => false,
                'error' => $error !== '' ? sanitize_text_field($error, 500) : 'Не удалось обновить crontab.',
            ];
        }
        return ['ok' => true, 'error' => ''];
    } finally {
        @unlink($tempPath);
    }
}
function docs_legacy_ocr_cron_status(): array
{
    $read = docs_read_system_crontab();
    $matches = [];
    if (!empty($read['ok'])) {
        foreach (preg_split('/\r\n|\r|\n/', (string) ($read['content'] ?? '')) ?: [] as $line) {
            $line = trim((string) $line);
            if ($line !== '' && (
                strpos($line, DOCS_LEGACY_OCR_CRON_MARKER) !== false
                || strpos($line, DOCS_LEGACY_OCR_CRON_COMMAND) !== false
            )) {
                $matches[] = $line;
            }
        }
    }
    return [
        'readable' => !empty($read['ok']),
        'installed' => !empty($matches),
        'entries' => $matches,
        'error' => (string) ($read['error'] ?? ''),
        'description' => 'Устаревший cron автоматического OCR. После обновления кода он ничего не вычисляет и может быть удалён.',
    ];
}
function docs_remove_legacy_ocr_cron(): array
{
    $read = docs_read_system_crontab();
    if (empty($read['ok'])) {
        return [
            'ok' => false,
            'error' => (string) ($read['error'] ?? 'Не удалось прочитать crontab.'),
            'cron' => docs_legacy_ocr_cron_status(),
        ];
    }
    $keptLines = [];
    $removed = 0;
    $crontabLines = preg_split('/\r\n|\r|\n/', (string) ($read['content'] ?? '')) ?: [];
    if (!empty($crontabLines) && end($crontabLines) === '') {
        array_pop($crontabLines);
    }
    foreach ($crontabLines as $line) {
        if (strpos((string) $line, DOCS_LEGACY_OCR_CRON_MARKER) !== false
            || strpos((string) $line, DOCS_LEGACY_OCR_CRON_COMMAND) !== false
        ) {
            $removed++;
            continue;
        }
        $keptLines[] = rtrim((string) $line);
    }
    if ($removed > 0) {
        $write = docs_write_system_crontab($keptLines);
        if (empty($write['ok'])) {
            return [
                'ok' => false,
                'error' => (string) ($write['error'] ?? 'Не удалось удалить старый OCR-cron.'),
                'cron' => docs_legacy_ocr_cron_status(),
            ];
        }
    }
    return [
        'ok' => true,
        'removed' => $removed,
        'cron' => docs_legacy_ocr_cron_status(),
    ];
}
function docs_prepare_ai_task_search_client_task(array $task): array
{
    $fieldLimits = [
        'id' => 200,
        'entryNumber' => 80,
        'registryNumber' => 120,
        'documentNumber' => 120,
        'organization' => 200,
        'documentFolder' => 200,
        'folderId' => 120,
    ];
    $prepared = [];
    foreach ($fieldLimits as $field => $maxLength) {
        if (!array_key_exists($field, $task) || !is_scalar($task[$field])) {
            continue;
        }
        $value = sanitize_text_field((string) $task[$field], $maxLength);
        if ($value !== '') {
            $prepared[$field] = $value;
        }
    }
    if (isset($task['folderByUser']) && is_array($task['folderByUser'])) {
        $folderByUser = [];
        foreach ($task['folderByUser'] as $userId => $folderId) {
            if (count($folderByUser) >= 50 || (!is_string($userId) && !is_int($userId)) || !is_scalar($folderId)) {
                break;
            }
            $safeUserId = sanitize_text_field((string) $userId, 80);
            $safeFolderId = sanitize_text_field((string) $folderId, 120);
            if ($safeUserId !== '') {
                $folderByUser[$safeUserId] = $safeFolderId;
            }
        }
        if (!empty($folderByUser)) {
            $prepared['folderByUser'] = $folderByUser;
        }
    }
    return $prepared;
}
function docs_prepare_ai_task_search_client_snapshot($snapshot): array
{
    if (!is_array($snapshot)) {
        return [
            'ok' => false,
            'error' => 'client_snapshot_missing',
        ];
    }
    $rawTasks = isset($snapshot['tasks']) && is_array($snapshot['tasks']) ? $snapshot['tasks'] : [];
    if (empty($rawTasks)) {
        return [
            'ok' => false,
            'error' => 'client_snapshot_empty',
        ];
    }
    $tasks = [];
    foreach ($rawTasks as $task) {
        if (count($tasks) >= DOCS_AI_TASK_SEARCH_CLIENT_SNAPSHOT_MAX_TASKS) {
            break;
        }
        if (!is_array($task)) {
            continue;
        }
        $hasVisibleIdentifier = false;
        foreach (['id', 'entryNumber', 'registryNumber', 'documentNumber', 'organization'] as $field) {
            if (isset($task[$field]) && is_scalar($task[$field]) && trim((string) $task[$field]) !== '') {
                $hasVisibleIdentifier = true;
                break;
            }
        }
        if (!$hasVisibleIdentifier) {
            continue;
        }
        $preparedTask = docs_prepare_ai_task_search_client_task($task);
        if (!empty($preparedTask)) {
            $tasks[] = $preparedTask;
        }
    }
    if (empty($tasks)) {
        return [
            'ok' => false,
            'error' => 'client_snapshot_no_valid_tasks',
        ];
    }
    $generatedAt = sanitize_text_field((string) ($snapshot['generatedAt'] ?? ''), 80);
    if ($generatedAt === '') {
        $generatedAt = date('c');
    }
    return [
        'ok' => true,
        'source' => 'client_current_state',
        'key' => '',
        'snapshot' => [
            'version' => 1,
            'source' => 'client_current_state',
            'generatedAt' => $generatedAt,
            'tasksCount' => count($tasks),
            'tasks' => array_values($tasks),
        ],
    ];
}
function docs_merge_ai_task_search_snapshots(array $storedResult, array $clientResult): array
{
    $storedSnapshot = isset($storedResult['snapshot']) && is_array($storedResult['snapshot'])
        ? $storedResult['snapshot']
        : [];
    $clientSnapshot = isset($clientResult['snapshot']) && is_array($clientResult['snapshot'])
        ? $clientResult['snapshot']
        : [];
    $storedTasks = isset($storedSnapshot['tasks']) && is_array($storedSnapshot['tasks'])
        ? $storedSnapshot['tasks']
        : [];
    $clientTasks = isset($clientSnapshot['tasks']) && is_array($clientSnapshot['tasks'])
        ? $clientSnapshot['tasks']
        : [];
    $clientByKey = [];
    foreach ($clientTasks as $task) {
        if (!is_array($task)) {
            continue;
        }
        $key = docs_task_snapshot_key($task);
        if ($key !== '') {
            $clientByKey[$key] = $task;
        }
    }
    $overlayFields = ['folderId', 'folderByUser'];
    $mergedTasks = [];
    foreach ($storedTasks as $storedTask) {
        if (!is_array($storedTask)) {
            continue;
        }
        $mergedTask = $storedTask;
        $key = docs_task_snapshot_key($storedTask);
        $clientTask = $key !== '' && isset($clientByKey[$key]) && is_array($clientByKey[$key])
            ? $clientByKey[$key]
            : [];
        foreach ($overlayFields as $field) {
            if (array_key_exists($field, $clientTask)) {
                $mergedTask[$field] = $clientTask[$field];
            }
        }
        $mergedTasks[] = $mergedTask;
    }
    $storedSnapshot['tasks'] = $mergedTasks;
    $storedSnapshot['tasksCount'] = count($mergedTasks);
    $storedSnapshot['source'] = 'live_registry_with_client_folders';
    $result = $storedResult;
    $result['source'] = 'live_registry_with_client_folders';
    $result['snapshot'] = $storedSnapshot;
    return $result;
}
function docs_build_live_ai_task_search_snapshot(string $telegramUserId, array $requestContext): array
{
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId === '') {
        return [
            'ok' => false,
            'error' => 'telegram_user_id_missing',
            'message' => 'Не удалось определить Telegram ID.',
        ];
    }
    $identitySource = ['telegram_user_id' => $telegramUserId];
    $telegramInitData = isset($requestContext['telegramInitData']) && is_array($requestContext['telegramInitData'])
        ? $requestContext['telegramInitData']
        : [];
    if (!empty($telegramInitData['valid']) && isset($telegramInitData['source']) && is_array($telegramInitData['source'])) {
        foreach (['telegram_username', 'telegram_full_name'] as $field) {
            if (isset($telegramInitData['source'][$field]) && is_scalar($telegramInitData['source'][$field])) {
                $identitySource[$field] = (string) $telegramInitData['source'][$field];
            }
        }
    }
    $filter = extract_assignee_filter_from_array($identitySource);
    if (!assignee_filter_has_identity($filter)) {
        return [
            'ok' => false,
            'error' => 'verified_filter_missing',
            'message' => 'Не удалось построить подтверждённый фильтр задач.',
        ];
    }
    $accessContext = docs_resolve_access_context(null, true);
    $organizations = isset($accessContext['accessible']) && is_array($accessContext['accessible'])
        ? $accessContext['accessible']
        : [];
    if (empty($organizations)) {
        $organizations = load_organizations();
    }
    $organizations = array_values(array_unique(array_filter($organizations, static function ($value): bool {
        return is_string($value) && trim($value) !== '';
    })));
    $tasks = [];
    $seen = [];
    foreach ($organizations as $organization) {
        $folder = sanitize_folder_name($organization);
        $directoryEntries = docs_load_telegram_participant_directory_entries($folder);
        $prepared = docs_prepare_records_for_response(load_registry($folder), $organization, $folder);
        foreach (is_array($prepared) ? $prepared : [] as $record) {
            if (!is_array($record)) {
                continue;
            }
            $roles = docs_resolve_record_roles_for_telegram_user(
                $record,
                $telegramUserId,
                $folder,
                $directoryEntries,
                $filter
            );
            if (empty($roles)) {
                continue;
            }
            $record['currentUserRoles'] = $roles;
            $record['organization'] = $organization;
            $record['documentFolder'] = $folder;
            $taskKey = docs_task_snapshot_key($record);
            if ($taskKey === '' || isset($seen[$taskKey])) {
                continue;
            }
            $seen[$taskKey] = true;
            $record['taskKey'] = $taskKey;
            $tasks[] = $record;
        }
    }
    return [
        'ok' => true,
        'source' => 'live_registry',
        'key' => '',
        'snapshot' => [
            'version' => 2,
            'source' => 'live_registry',
            'generatedAt' => date('c'),
            'tasksCount' => count($tasks),
            'tasks' => $tasks,
        ],
    ];
}
function docs_require_verified_telegram_user_id(array $requestContext): string
{
    $telegramInitData = isset($requestContext['telegramInitData']) && is_array($requestContext['telegramInitData'])
        ? $requestContext['telegramInitData']
        : [];
    if (!empty($telegramInitData['present']) && empty($telegramInitData['valid'])) {
        respond_error('Не удалось подтвердить данные Telegram. Откройте мини-приложение заново из чата с ботом.', 401, [
            'telegramInitDataError' => isset($telegramInitData['error']) ? (string) $telegramInitData['error'] : 'invalid',
            'telegramInitDataPresent' => true,
            'requiresTelegramReauth' => true,
        ]);
    }
    $requestedTelegramUserId = normalize_identifier_value($requestContext['raw']['telegram_user_id'] ?? '');
    $impersonation = isset($requestContext['impersonation']) && is_array($requestContext['impersonation'])
        ? $requestContext['impersonation']
        : [];
    if (!empty($impersonation['active'])) {
        $targetTelegramUserId = normalize_identifier_value($impersonation['targetTelegramId'] ?? '');
        if ($targetTelegramUserId === ''
            || ($requestedTelegramUserId !== '' && !hash_equals($targetTelegramUserId, $requestedTelegramUserId))
        ) {
            respond_error('Контекст тестового пользователя не подтверждён.', 403);
        }
        return $targetTelegramUserId;
    }
    $verifiedTelegramUserId = '';
    if (!empty($telegramInitData['valid'])) {
        $verifiedTelegramUserId = normalize_identifier_value(
            $telegramInitData['source']['telegram_user_id']
                ?? ($telegramInitData['user']['id'] ?? '')
        );
    } else {
        $sessionAuth = docs_get_session_auth();
        if (is_array($sessionAuth)) {
            $sessionRole = strtolower((string) ($sessionAuth['role'] ?? ''));
            if ($sessionRole === 'admin' && $requestedTelegramUserId !== '') {
                $verifiedTelegramUserId = $requestedTelegramUserId;
                log_docs_event('Admin Telegram user preview authorized', [
                    'telegramUserId' => $requestedTelegramUserId,
                    'adminLogin' => sanitize_text_field((string) ($sessionAuth['login'] ?? ''), 120),
                    'action' => docs_current_action(),
                ]);
            } else {
                foreach (['telegramId', 'chatId'] as $sessionIdField) {
                    $verifiedTelegramUserId = normalize_identifier_value($sessionAuth[$sessionIdField] ?? '');
                    if ($verifiedTelegramUserId !== '') {
                        break;
                    }
                }
            }
        }
    }
    if ($verifiedTelegramUserId === '') {
        respond_error('Поиск доступен только после подтверждения пользователя Telegram.', 401, [
            'requiresTelegramReauth' => true,
        ]);
    }
    if ($requestedTelegramUserId !== '' && !hash_equals($verifiedTelegramUserId, $requestedTelegramUserId)) {
        respond_error('Telegram ID запроса не совпадает с подтверждённым пользователем.', 403);
    }
    return $verifiedTelegramUserId;
}
function docs_task_rag_file_keys(array $file): array
{
    $keys = [];
    foreach (['storedName', 'url', 'originalName', 'name'] as $field) {
        $value = trim((string) ($file[$field] ?? ''));
        if ($value !== '') {
            $keys[] = $field . ':' . mb_strtolower($value, 'UTF-8');
        }
    }
    return array_values(array_unique($keys));
}
function docs_merge_existing_task_snapshot_data(array $currentTask, array $storedTask): array
{
    $mergedTask = array_replace($storedTask, $currentTask);
    if (!isset($currentTask['files']) || !is_array($currentTask['files'])) {
        return $mergedTask;
    }
    $storedFilesByKey = [];
    foreach (isset($storedTask['files']) && is_array($storedTask['files']) ? $storedTask['files'] : [] as $storedFile) {
        if (!is_array($storedFile)) {
            continue;
        }
        foreach (docs_task_rag_file_keys($storedFile) as $fileKey) {
            if (!isset($storedFilesByKey[$fileKey])) {
                $storedFilesByKey[$fileKey] = $storedFile;
            }
        }
    }
    $mergedFiles = [];
    foreach ($currentTask['files'] as $currentFile) {
        if (!is_array($currentFile)) {
            continue;
        }
        $storedFile = null;
        foreach (docs_task_rag_file_keys($currentFile) as $fileKey) {
            if (isset($storedFilesByKey[$fileKey])) {
                $storedFile = $storedFilesByKey[$fileKey];
                break;
            }
        }
        if (!is_array($storedFile)) {
            $mergedFiles[] = $currentFile;
            continue;
        }
        $mergedFile = array_replace($storedFile, $currentFile);
        if (isset($storedFile['ocr']) && is_array($storedFile['ocr'])
            && isset($currentFile['ocr']) && is_array($currentFile['ocr'])
        ) {
            $mergedFile['ocr'] = array_replace($storedFile['ocr'], $currentFile['ocr']);
        }
        $currentOcrText = isset($currentFile['ocrText']) && is_string($currentFile['ocrText'])
            ? trim($currentFile['ocrText'])
            : '';
        $storedOcrText = isset($storedFile['ocrText']) && is_string($storedFile['ocrText'])
            ? trim($storedFile['ocrText'])
            : '';
        $ocrText = $currentOcrText !== '' ? $currentOcrText : $storedOcrText;
        if ($ocrText !== '') {
            $mergedFile['ocrText'] = $ocrText;
            $mergedFile['ocrTextLength'] = mb_strlen($ocrText, 'UTF-8');
        }
        $mergedFiles[] = $mergedFile;
    }
    $mergedTask['files'] = $mergedFiles;
    return $mergedTask;
}
function docs_merge_task_rag_ocr_snapshot(array $liveTasks, array $storedSnapshot): array
{
    $storedTasks = isset($storedSnapshot['tasks']) && is_array($storedSnapshot['tasks'])
        ? $storedSnapshot['tasks']
        : [];
    $liveTaskKeys = [];
    foreach ($liveTasks as $liveTask) {
        if (!is_array($liveTask)) {
            continue;
        }
        $liveTaskKey = docs_task_snapshot_key($liveTask);
        if ($liveTaskKey !== '') {
            $liveTaskKeys[$liveTaskKey] = true;
        }
    }
    if (empty($liveTaskKeys)) {
        return $liveTasks;
    }
    $storedByTaskKey = [];
    foreach ($storedTasks as $storedTask) {
        if (!is_array($storedTask)) {
            continue;
        }
        $taskKey = docs_task_snapshot_key($storedTask);
        if ($taskKey !== '' && isset($liveTaskKeys[$taskKey])) {
            $storedByTaskKey[$taskKey] = $storedTask;
        }
    }
    foreach ($liveTasks as &$liveTask) {
        if (!is_array($liveTask)) {
            continue;
        }
        $taskKey = docs_task_snapshot_key($liveTask);
        if ($taskKey === '' || !isset($storedByTaskKey[$taskKey])) {
            continue;
        }
        $liveTask = docs_merge_existing_task_snapshot_data($liveTask, $storedByTaskKey[$taskKey]);
    }
    unset($liveTask);
    return array_values($liveTasks);
}
function docs_prepare_task_rag_snapshot(string $telegramUserId, array $tasks): array
{
    $preparedTasks = [];
    foreach ($tasks as $task) {
        if (!is_array($task)) {
            continue;
        }
        $sourceTaskId = sanitize_text_field((string) ($task['id'] ?? ''), 200);
        $taskId = docs_task_snapshot_key($task);
        if ($taskId === '') {
            continue;
        }
        $files = [];
        foreach (isset($task['files']) && is_array($task['files']) ? $task['files'] : [] as $file) {
            if (!is_array($file)) {
                continue;
            }
            $ocrText = isset($file['ocrText']) && is_string($file['ocrText'])
                ? trim($file['ocrText'])
                : '';
            if (mb_strlen($ocrText, 'UTF-8') > DOCS_AI_TASK_SEARCH_OCR_TEXT_MAX_LENGTH) {
                $ocrText = mb_substr($ocrText, 0, DOCS_AI_TASK_SEARCH_OCR_TEXT_MAX_LENGTH, 'UTF-8');
            }
            $ocr = isset($file['ocr']) && is_array($file['ocr']) ? $file['ocr'] : [];
            $expectedOcrTextLength = max(
                0,
                (int) ($file['ocrTextLength'] ?? 0),
                (int) ($ocr['archiveTextLength'] ?? 0)
            );
            $files[] = [
                'id' => docs_ai_task_search_short_text($file['id'] ?? '', 120),
                'originalName' => sanitize_text_field(
                    (string) ($file['originalName'] ?? ($file['name'] ?? ($file['storedName'] ?? ''))),
                    255
                ),
                'storedName' => docs_ai_task_search_short_text($file['storedName'] ?? '', 255),
                'url' => sanitize_text_field((string) ($file['url'] ?? ''), 1000),
                'aiBrief' => docs_ai_task_search_short_text($file['aiBrief'] ?? '', 2000),
                'ocrText' => $ocrText !== ''
                    ? mb_substr($ocrText, 0, DOCS_AI_BRIEF_MAX_SOURCE_CHARS, 'UTF-8')
                    : '',
                'ocrTextLength' => $ocrText !== ''
                    ? mb_strlen($ocrText, 'UTF-8')
                    : $expectedOcrTextLength,
            ];
        }
        $preparedTask = [
            'id' => $taskId,
            'sourceId' => $sourceTaskId,
            'entryNumber' => docs_ai_task_search_short_text($task['entryNumber'] ?? '', 80),
            'registryNumber' => docs_ai_task_search_short_text($task['registryNumber'] ?? '', 120),
            'documentNumber' => docs_ai_task_search_short_text($task['documentNumber'] ?? '', 120),
            'organization' => sanitize_text_field((string) ($task['organization'] ?? ''), 200),
            'folderId' => docs_ai_task_search_task_folder_id($task, $telegramUserId),
            'title' => docs_ai_task_search_short_text(
                $task['title'] ?? ($task['document'] ?? docs_ai_task_search_result_title($task)),
                500
            ),
            'summary' => sanitize_text_field(
                (string) ($task['summary'] ?? ($task['contentCompact'] ?? ($task['correspondent'] ?? ''))),
                4000
            ),
            'correspondent' => docs_ai_task_search_short_text($task['correspondent'] ?? '', 1000),
            'executor' => docs_ai_task_search_short_text(
                $task['executor'] ?? ($task['assignee'] ?? ($task['responsible'] ?? '')),
                1000
            ),
            'instruction' => sanitize_text_field(
                (string) ($task['instruction'] ?? ($task['resolution'] ?? '')),
                4000
            ),
            'resolution' => docs_ai_task_search_short_text($task['resolution'] ?? '', 4000),
            'notes' => docs_ai_task_search_short_text($task['notes'] ?? '', 4000),
            'question' => docs_ai_task_search_short_text($task['question'] ?? '', 4000),
            'comment' => docs_ai_task_search_short_text($task['comment'] ?? '', 4000),
            'status' => sanitize_text_field((string) ($task['status'] ?? ''), 160),
            'registrationDate' => sanitize_date_field(isset($task['registrationDate']) ? (string) $task['registrationDate'] : ''),
            'documentDate' => sanitize_date_field(isset($task['documentDate']) ? (string) $task['documentDate'] : ''),
            'dueDate' => sanitize_date_field(isset($task['dueDate']) ? (string) $task['dueDate'] : ''),
            'updatedAt' => docs_ai_task_search_short_text($task['updatedAt'] ?? '', 100),
            'files' => $files,
        ];
        $peopleFields = [
            'name',
            'responsible',
            'fio',
            'fullName',
            'role',
            'assignmentInstruction',
            'assignmentComment',
            'reviewComment',
            'assignmentDueDate',
            'status',
        ];
        foreach (['directors', 'responsibles', 'assignees', 'executors', 'subordinates'] as $peopleField) {
            $entries = docs_ai_task_search_compact_entries(
                $task[$peopleField] ?? [],
                $peopleFields,
                20,
                500
            );
            if (!empty($entries)) {
                $preparedTask[$peopleField] = $entries;
            }
        }
        $responses = [];
        foreach (['responses', 'answers', 'executorResponses'] as $responseField) {
            foreach (docs_ai_task_search_compact_entries(
                $task[$responseField] ?? [],
                ['originalName', 'name', 'storedName', 'textContent', 'comment', 'note', 'uploadedBy'],
                20,
                2000
            ) as $response) {
                $responses[] = $response;
                if (count($responses) >= 20) {
                    break 2;
                }
            }
        }
        if (!empty($responses)) {
            $preparedTask['responses'] = $responses;
        }
        foreach ([
            'questions' => ['text', 'question', 'content', 'comment', 'author', 'organization'],
            'comments' => ['text', 'comment', 'content', 'note', 'author', 'organization'],
        ] as $collectionField => $collectionFields) {
            $entries = docs_ai_task_search_compact_entries(
                $task[$collectionField] ?? [],
                $collectionFields,
                30,
                2000
            );
            if (!empty($entries)) {
                $preparedTask[$collectionField] = $entries;
            }
        }
        $preparedTask = array_filter($preparedTask, static function ($value): bool {
            return is_array($value) ? !empty($value) : $value !== '' && $value !== null;
        });
        $taskHashPayload = $preparedTask;
        unset($taskHashPayload['sourceId'], $taskHashPayload['updatedAt']);
        if (isset($taskHashPayload['files']) && is_array($taskHashPayload['files'])) {
            foreach ($taskHashPayload['files'] as &$hashFile) {
                if (is_array($hashFile)) {
                    unset($hashFile['id'], $hashFile['url'], $hashFile['ocrTextLength']);
                }
            }
            unset($hashFile);
        }
        $taskHashPayload['_indexVersion'] = DOCS_TASK_RAG_INDEX_SCHEMA_VERSION;
        $encodedPreparedTask = json_encode(
            $taskHashPayload,
            JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
        );
        if (!is_string($encodedPreparedTask)) {
            continue;
        }
        $preparedTask['contentHash'] = hash('sha256', $encodedPreparedTask);
        $preparedTasks[] = $preparedTask;
    }
    return [
        'version' => 2,
        'indexVersion' => DOCS_TASK_RAG_INDEX_SCHEMA_VERSION,
        'source' => 'mini_app_tasks',
        'telegramUserId' => $telegramUserId,
        'generatedAt' => date('c'),
        'tasksCount' => count($preparedTasks),
        'tasks' => $preparedTasks,
    ];
}
function docs_task_rag_evaluate_remote_index_contract(array $snapshot, int $encodedBytes): array
{
    $tasks = isset($snapshot['tasks']) && is_array($snapshot['tasks'])
        ? $snapshot['tasks']
        : [];
    if (count($tasks) > DOCS_TASK_RAG_REMOTE_MAX_TASKS) {
        return [
            'requiresLocalSearch' => true,
            'reason' => 'remote_tasks_limit',
            'message' => 'Архив задач слишком большой для полного ИИ-индекса. Выполняю прямой поиск по Telegram JSON без обрезки текста.',
        ];
    }
    if ($encodedBytes > DOCS_TASK_RAG_REMOTE_MAX_SNAPSHOT_BYTES) {
        return [
            'requiresLocalSearch' => true,
            'reason' => 'remote_snapshot_size_limit',
            'message' => 'Архив документов превышает безопасный размер ИИ-индекса. Выполняю прямой поиск по Telegram JSON без обрезки текста.',
        ];
    }
    foreach ($tasks as $task) {
        if (!is_array($task)) {
            continue;
        }
        foreach (isset($task['files']) && is_array($task['files']) ? $task['files'] : [] as $file) {
            if (!is_array($file) || !isset($file['ocrText']) || !is_string($file['ocrText'])) {
                continue;
            }
            if (mb_strlen($file['ocrText'], 'UTF-8') > DOCS_TASK_RAG_REMOTE_MAX_OCR_TEXT_LENGTH) {
                return [
                    'requiresLocalSearch' => true,
                    'reason' => 'remote_ocr_text_limit',
                    'message' => 'Один из документов длиннее лимита полного ИИ-индекса. Выполняю прямой поиск по Telegram JSON без обрезки текста.',
                ];
            }
        }
    }
    return [
        'requiresLocalSearch' => false,
        'reason' => '',
        'message' => '',
    ];
}
function docs_task_rag_resolve_base_url(): string
{
    $env = docs_ai_task_search_load_env();
    $configured = trim((string) (
        $env['TASK_RAG_BASE_URL']
            ?? ($env['BIMMAX_TASK_RAG_BASE_URL'] ?? DOCS_TASK_RAG_DEFAULT_BASE_URL)
    ));
    if (filter_var($configured, FILTER_VALIDATE_URL) === false) {
        return DOCS_TASK_RAG_DEFAULT_BASE_URL;
    }
    return rtrim($configured, '/');
}
function docs_task_rag_decode_response_payload(string $responseBody): ?array
{
    $normalizedBody = preg_replace('/^\xEF\xBB\xBF/', '', trim($responseBody));
    if (!is_string($normalizedBody) || $normalizedBody === '') {
        return null;
    }
    $decodeJson = static function (string $value) {
        $flags = defined('JSON_INVALID_UTF8_SUBSTITUTE') ? JSON_INVALID_UTF8_SUBSTITUTE : 0;
        return json_decode(trim($value), true, 512, $flags);
    };
    $decoded = $decodeJson($normalizedBody);
    if ($decoded === null && json_last_error() !== JSON_ERROR_NONE) {
        // Некоторые reverse proxy и webhook-обёртки добавляют перед JSON
        // служебную строку. Извлекаем объект только когда он занимает остаток
        // ответа целиком; HTML-страницы и произвольный текст не принимаем.
        $objectStart = strpos($normalizedBody, '{');
        $arrayStart = strpos($normalizedBody, '[');
        $starts = array_filter([$objectStart, $arrayStart], static function ($position) {
            return $position !== false;
        });
        if (!empty($starts)) {
            $jsonStart = min($starts);
            $opening = $normalizedBody[$jsonStart];
            $closing = $opening === '{' ? '}' : ']';
            $jsonEnd = strrpos($normalizedBody, $closing);
            if ($jsonEnd !== false && $jsonEnd >= $jsonStart) {
                $suffix = trim(substr($normalizedBody, $jsonEnd + 1));
                if ($suffix === '') {
                    $decoded = $decodeJson(substr($normalizedBody, $jsonStart, $jsonEnd - $jsonStart + 1));
                }
            }
        }
    }
    for ($depth = 0; $depth < 4; $depth++) {
        if (is_string($decoded)) {
            $nested = $decodeJson($decoded);
            if ($nested === null && json_last_error() !== JSON_ERROR_NONE) {
                return null;
            }
            $decoded = $nested;
            continue;
        }
        if (!is_array($decoded)) {
            return null;
        }
        $hasResponseFields = array_key_exists('ok', $decoded)
            || array_key_exists('success', $decoded)
            || array_key_exists('status', $decoded)
            || array_key_exists('action', $decoded)
            || array_key_exists('tasks', $decoded);
        if ($hasResponseFields) {
            return $decoded;
        }
        $wrappedPayload = null;
        foreach (['body', 'json', 'data', 'result', 'output'] as $wrapperKey) {
            if (array_key_exists($wrapperKey, $decoded)
                && (is_array($decoded[$wrapperKey]) || is_string($decoded[$wrapperKey]))) {
                $wrappedPayload = $decoded[$wrapperKey];
                break;
            }
        }
        if ($wrappedPayload !== null) {
            $decoded = $wrappedPayload;
            continue;
        }
        if (count($decoded) === 1 && array_key_exists(0, $decoded)
            && (is_array($decoded[0]) || is_string($decoded[0]))) {
            $decoded = $decoded[0];
            continue;
        }
        return null;
    }
    return is_array($decoded) ? $decoded : null;
}
function docs_task_rag_request(string $path, array $curlOptions): array
{
    if (!function_exists('curl_init')) {
        return [
            'ok' => false,
            'httpStatus' => 0,
            'error' => 'PHP cURL недоступен.',
        ];
    }
    $curl = curl_init(docs_task_rag_resolve_base_url() . '/' . ltrim($path, '/'));
    if ($curl === false) {
        return [
            'ok' => false,
            'httpStatus' => 0,
            'error' => 'Не удалось подготовить запрос к ИИ-поиску.',
        ];
    }
    curl_setopt_array($curl, array_replace([
        CURLOPT_POST => true,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FAILONERROR => false,
        CURLOPT_CONNECTTIMEOUT => DOCS_TASK_RAG_CONNECT_TIMEOUT_SECONDS,
        CURLOPT_TIMEOUT => DOCS_TASK_RAG_REQUEST_TIMEOUT_SECONDS,
        CURLOPT_FOLLOWLOCATION => false,
        CURLOPT_ENCODING => '',
    ], $curlOptions));
    try {
        $rawResponse = curl_exec($curl);
        $curlErrorNumber = curl_errno($curl);
        $httpStatus = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
        $curlError = trim((string) curl_error($curl));
    } finally {
        curl_close($curl);
    }
    if ($curlErrorNumber !== 0 || !is_string($rawResponse)) {
        return [
            'ok' => false,
            'httpStatus' => $httpStatus,
            'error' => $curlError !== '' ? $curlError : 'Сервер ИИ-поиска не вернул ответ.',
            'curlErrorNumber' => $curlErrorNumber,
            'diagnosticCode' => $curlErrorNumber > 0 ? 'RAG-CURL-' . $curlErrorNumber : 'RAG-NO-RESPONSE',
        ];
    }
    if (strlen($rawResponse) > DOCS_TASK_RAG_MAX_RESPONSE_BYTES) {
        return [
            'ok' => false,
            'httpStatus' => $httpStatus,
            'error' => 'Ответ сервера ИИ-поиска превышает допустимый размер.',
            'diagnosticCode' => 'RAG-TOO-LARGE',
            'responseBytes' => strlen($rawResponse),
        ];
    }
    $decoded = docs_task_rag_decode_response_payload($rawResponse);
    if ($httpStatus < 200 || $httpStatus >= 300) {
        $serverError = is_array($decoded)
            ? sanitize_text_field((string) ($decoded['error'] ?? ($decoded['message'] ?? '')), 500)
            : '';
        return [
            'ok' => false,
            'httpStatus' => $httpStatus,
            'error' => $serverError !== ''
                ? $serverError
                : ($curlError !== '' ? $curlError : 'Сервер ИИ-поиска вернул HTTP ' . $httpStatus . '.'),
            'payload' => is_array($decoded) ? $decoded : [],
            'rawResponse' => $rawResponse,
            'diagnosticCode' => 'RAG-HTTP-' . $httpStatus,
        ];
    }
    if (!is_array($decoded)) {
        return [
            'ok' => false,
            'httpStatus' => $httpStatus,
            'error' => 'Сервер ИИ-поиска вернул некорректный JSON.',
            'responsePreview' => sanitize_text_field($rawResponse, 4000),
            'rawResponse' => $rawResponse,
            'diagnosticCode' => 'RAG-JSON',
        ];
    }
    return [
        'ok' => true,
        'httpStatus' => $httpStatus,
        'payload' => $decoded,
        'rawResponse' => $rawResponse,
    ];
}
function docs_task_rag_token_secret(): string
{
    $botToken = docs_resolve_telegram_bot_token();
    if (is_string($botToken) && $botToken !== '') {
        return hash('sha256', 'task-rag|' . $botToken, true);
    }
    $mainAdminSecret = docs_load_mainadmin_secret();
    return is_string($mainAdminSecret) ? hash('sha256', 'task-rag|' . $mainAdminSecret, true) : '';
}
function docs_task_rag_base64url_encode(string $value): string
{
    return rtrim(strtr(base64_encode($value), '+/', '-_'), '=');
}
function docs_task_rag_base64url_decode(string $value): string
{
    $padding = strlen($value) % 4;
    if ($padding !== 0) {
        $value .= str_repeat('=', 4 - $padding);
    }
    $decoded = base64_decode(strtr($value, '-_', '+/'), true);
    return is_string($decoded) ? $decoded : '';
}
function docs_task_rag_issue_ready_token(
    string $telegramUserId,
    string $generatedAt,
    int $tasksCount,
    string $folderId = 'all',
    string $organization = ''
): string
{
    $secret = docs_task_rag_token_secret();
    if ($secret === '') {
        return '';
    }
    $payload = json_encode([
        'telegramUserId' => $telegramUserId,
        'generatedAt' => $generatedAt,
        'tasksCount' => max(0, $tasksCount),
        'folderId' => docs_ai_task_search_normalize_folder_filter_id($folderId) ?: 'all',
        'organization' => docs_normalize_organization_candidate($organization),
        'expiresAt' => time() + DOCS_TASK_RAG_READY_TOKEN_TTL_SECONDS,
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if (!is_string($payload)) {
        return '';
    }
    $encodedPayload = docs_task_rag_base64url_encode($payload);
    $signature = docs_task_rag_base64url_encode(hash_hmac('sha256', $encodedPayload, $secret, true));
    return $encodedPayload . '.' . $signature;
}
function docs_task_rag_ready_token_is_valid(
    string $token,
    string $telegramUserId,
    string $folderId = 'all',
    string $organization = ''
): bool
{
    $secret = docs_task_rag_token_secret();
    $parts = explode('.', trim($token), 2);
    if ($secret === '' || count($parts) !== 2 || $parts[0] === '' || $parts[1] === '') {
        return false;
    }
    $expectedSignature = docs_task_rag_base64url_encode(hash_hmac('sha256', $parts[0], $secret, true));
    if (!hash_equals($expectedSignature, $parts[1])) {
        return false;
    }
    $payload = json_decode(docs_task_rag_base64url_decode($parts[0]), true);
    if (!is_array($payload)) {
        return false;
    }
    $tokenTelegramUserId = normalize_identifier_value($payload['telegramUserId'] ?? '');
    $tokenFolderId = docs_ai_task_search_normalize_folder_filter_id($payload['folderId'] ?? 'all') ?: 'all';
    $requestedFolderId = docs_ai_task_search_normalize_folder_filter_id($folderId) ?: 'all';
    $tokenOrganization = docs_normalize_organization_candidate((string) ($payload['organization'] ?? ''));
    $requestedOrganization = docs_normalize_organization_candidate($organization);
    $expiresAt = (int) ($payload['expiresAt'] ?? 0);
    $tokenGeneratedAt = sanitize_text_field((string) ($payload['generatedAt'] ?? ''), 100);
    $tokenTasksCount = max(0, (int) ($payload['tasksCount'] ?? 0));
    $syncCache = docs_task_rag_load_sync_cache($telegramUserId);
    $cacheFolderId = docs_ai_task_search_normalize_folder_filter_id($syncCache['folderId'] ?? 'all') ?: 'all';
    $cacheOrganization = docs_normalize_organization_candidate((string) ($syncCache['organization'] ?? ''));
    $cacheGeneratedAt = sanitize_text_field((string) ($syncCache['generatedAt'] ?? ''), 100);
    return $tokenTelegramUserId !== ''
        && hash_equals($telegramUserId, $tokenTelegramUserId)
        && hash_equals($requestedFolderId, $tokenFolderId)
        && hash_equals(
            mb_strtolower($requestedOrganization, 'UTF-8'),
            mb_strtolower($tokenOrganization, 'UTF-8')
        )
        && $expiresAt >= time()
        && (string) ($syncCache['status'] ?? '') === 'ready'
        && (int) ($syncCache['readyUntil'] ?? 0) >= time()
        && $tokenGeneratedAt !== ''
        && hash_equals($tokenGeneratedAt, $cacheGeneratedAt)
        && hash_equals($requestedFolderId, $cacheFolderId)
        && hash_equals(
            mb_strtolower($requestedOrganization, 'UTF-8'),
            mb_strtolower($cacheOrganization, 'UTF-8')
        )
        && $tokenTasksCount === max(0, (int) ($syncCache['indexedTasks'] ?? 0));
}
function docs_task_rag_sync_cache_path(string $telegramUserId): string
{
    $safeTelegramUserId = docs_sanitize_mini_app_user_tasks_snapshot_id($telegramUserId);
    return rtrim(sys_get_temp_dir(), DIRECTORY_SEPARATOR)
        . DIRECTORY_SEPARATOR
        . 'bimmax_task_rag_sync_'
        . $safeTelegramUserId
        . '.json';
}
function docs_task_rag_load_sync_cache(string $telegramUserId): array
{
    $path = docs_task_rag_sync_cache_path($telegramUserId);
    $decoded = docs_read_json_array_file_with_backup($path);
    return is_array($decoded) ? $decoded : [];
}
function docs_task_rag_save_sync_cache(string $telegramUserId, array $cache): bool
{
    $encoded = json_encode($cache, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if (!is_string($encoded)) {
        return false;
    }
    return docs_write_json_content_atomically(
        docs_task_rag_sync_cache_path($telegramUserId),
        $encoded,
        false
    );
}
function docs_task_rag_invalidate_sync_cache(string $telegramUserId): bool
{
    $telegramUserId = normalize_identifier_value($telegramUserId);
    if ($telegramUserId === '') {
        return false;
    }
    $cache = docs_task_rag_load_sync_cache($telegramUserId);
    $cache['status'] = 'stale';
    $cache['readyUntil'] = 0;
    $cache['invalidatedAt'] = time();
    return docs_task_rag_save_sync_cache($telegramUserId, $cache);
}
function docs_task_rag_snapshot_fingerprint(array $snapshot): string
{
    $hash = hash_init('sha256');
    if ($hash === false) {
        return '';
    }
    foreach (['version', 'indexVersion', 'source', 'telegramUserId', 'tasksCount', 'folderId', 'organization'] as $field) {
        $encoded = json_encode([$field => $snapshot[$field] ?? null], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if (!is_string($encoded)) {
            return '';
        }
        hash_update($hash, strlen($encoded) . ':' . $encoded . "\n");
    }
    $tasks = isset($snapshot['tasks']) && is_array($snapshot['tasks']) ? $snapshot['tasks'] : [];
    foreach ($tasks as $task) {
        $encodedTask = json_encode($task, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if (!is_string($encodedTask)) {
            return '';
        }
        hash_update($hash, strlen($encodedTask) . ':' . $encodedTask . "\n");
    }
    return hash_final($hash);
}
function docs_task_rag_build_ready_payload(
    string $telegramUserId,
    array $remotePayload,
    string $generatedAt,
    int $fallbackTasksCount,
    string $folderId = 'all',
    string $organization = ''
): array {
    $indexedTasks = max(0, (int) ($remotePayload['indexedTasks'] ?? $fallbackTasksCount));
    $normalizedFolderId = docs_ai_task_search_normalize_folder_filter_id($folderId) ?: 'all';
    $normalizedOrganization = docs_normalize_organization_candidate($organization);
    $localFallbackReason = sanitize_text_field(
        (string) ($remotePayload['localFallbackReason'] ?? ''),
        120
    );
    $usesLocalFallback = $localFallbackReason !== '';
    $readyToken = docs_task_rag_issue_ready_token(
        $telegramUserId,
        $generatedAt,
        $indexedTasks,
        $normalizedFolderId,
        $normalizedOrganization
    );
    if ($readyToken === '') {
        return [];
    }
    return [
        'ok' => true,
        'status' => 'ready',
        'action' => sanitize_text_field((string) ($remotePayload['action'] ?? 'snapshot'), 80),
        'message' => $usesLocalFallback
            ? sanitize_text_field(
                (string) ($remotePayload['message'] ?? 'Выполняю прямой поиск по полному Telegram JSON.'),
                500
            )
            : ($indexedTasks > 0
            ? 'Поиск готов. Можно задавать вопросы по задачам и текстам документов.'
            : 'У вас пока нет доступных задач.'),
        'telegramUserId' => $telegramUserId,
        'snapshotId' => sanitize_text_field((string) ($remotePayload['snapshotId'] ?? ''), 500),
        'indexedTasks' => $indexedTasks,
        'indexedChunks' => max(0, (int) ($remotePayload['indexedChunks'] ?? 0)),
        'indexedOcrFiles' => max(0, (int) ($remotePayload['indexedOcrFiles'] ?? 0)),
        'changedTasks' => max(0, (int) ($remotePayload['changedTasks'] ?? 0)),
        'unchangedTasks' => max(0, (int) ($remotePayload['unchangedTasks'] ?? 0)),
        'deletedTasks' => max(0, (int) ($remotePayload['deletedTasks'] ?? 0)),
        'generatedAt' => $generatedAt,
        'folderId' => $normalizedFolderId,
        'organization' => $normalizedOrganization,
        'readyToken' => $readyToken,
        'readyUntil' => time() + DOCS_TASK_RAG_READY_TOKEN_TTL_SECONDS,
        'localFallback' => $usesLocalFallback,
        'localFallbackReason' => $localFallbackReason,
        'searchMode' => $usesLocalFallback ? 'local' : 'ai',
    ];
}
function docs_ai_task_search_result_title(array $task): string
{
