        }
    }
    if (empty($entries)) {
        return [];
    }
    usort($entries, static function ($a, $b) {
        return strcmp($a['changedAt'], $b['changedAt']);
    });
    $deduplicated = [];
    foreach ($entries as $entry) {
        $key = $entry['changedAt'] . '|' . $entry['status'];
        if (isset($deduplicated[$key])) {
            if (!empty($entry['changedBy']) && empty($deduplicated[$key]['changedBy'])) {
                $deduplicated[$key]['changedBy'] = $entry['changedBy'];
            }
            continue;
        }
        $deduplicated[$key] = $entry;
    }
    return array_values($deduplicated);
}
function docs_register_task_view_event(string $organizationName, string $documentId, array $requestContext, array $details = []): array
{
    $result = [
        'recorded' => false,
        'alreadyRecorded' => false,
    ];
    $organization = docs_normalize_organization_candidate($organizationName);
    $documentId = sanitize_text_field($documentId, 200);
    if ($organization === '' || $documentId === '') {
        return $result;
    }
    $folder = sanitize_folder_name($organization);
    $records = load_registry($folder);
    $recordIndex = null;
    foreach ($records as $index => $record) {
        if (!is_array($record) || !isset($record['id'])) {
            continue;
        }
        if ((string) $record['id'] === $documentId) {
            $recordIndex = $index;
            break;
        }
    }
    if ($recordIndex === null) {
        docs_log_view_status_event('documents:register_view document_not_found', [
            'organization' => $organization,
            'documentId' => $documentId,
        ]);
        return $result;
    }
    $assignees = docs_extract_view_participants($records[$recordIndex]);
    if (empty($assignees)) {
        docs_log_view_status_event('documents:register_view no_assignees', [
            'organization' => $organization,
            'documentId' => $documentId,
        ]);
        return $result;
    }
    $assigneeIndex = docs_index_assignees($assignees);
    if (empty($assigneeIndex)) {
        docs_log_view_status_event('documents:register_view assignee_index_empty', [
            'organization' => $organization,
            'documentId' => $documentId,
            'assigneesCount' => count($assignees),
        ]);
        return $result;
    }
    $candidateKeys = docs_collect_view_candidate_keys($requestContext, $details);
    $assigneeKeys = array_keys($assigneeIndex);
    docs_log_view_status_event('documents:register_view candidates', [
        'organization' => $organization,
        'documentId' => $documentId,
        'candidateKeysCount' => count($candidateKeys),
        'candidateKeysSample' => array_slice($candidateKeys, 0, 12),
        'assigneeKeysCount' => count($assigneeKeys),
        'assigneeKeysSample' => array_slice($assigneeKeys, 0, 12),
    ]);
    $matchedKey = '';
    $matchedAssignee = null;
    foreach ($candidateKeys as $candidateKey) {
        if (isset($assigneeIndex[$candidateKey])) {
            $matchedKey = $candidateKey;
            $matchedAssignee = $assigneeIndex[$candidateKey];
            break;
        }
    }
    if ($matchedAssignee === null) {
        $rawContext = isset($requestContext['raw']) && is_array($requestContext['raw'])
            ? $requestContext['raw']
            : [];
        $userContext = isset($requestContext['user']) && is_array($requestContext['user'])
            ? $requestContext['user']
            : [];
        $userSummary = [
            'primaryId' => $requestContext['primaryId'] ?? null,
            'identity' => $requestContext['identity'] ?? null,
            'telegramUserId' => $rawContext['telegram_user_id'] ?? null,
            'telegramUsername' => $rawContext['telegram_username'] ?? null,
            'user' => [
                'id' => $userContext['id'] ?? null,
                'username' => $userContext['username'] ?? null,
                'fullName' => $userContext['fullName'] ?? null,
            ],
        ];
        docs_log_view_status_event('documents:register_view no_match', [
            'organization' => $organization,
            'documentId' => $documentId,
            'candidateKeysCount' => count($candidateKeys),
            'candidateKeysSample' => array_slice($candidateKeys, 0, 12),
            'assigneeKeysCount' => count($assigneeKeys),
            'assigneeKeysSample' => array_slice($assigneeKeys, 0, 12),
            'requestUser' => $userSummary,
        ]);
        $fallbackUserNames = [];
        $addFallbackUserName = static function ($value) use (&$fallbackUserNames): void {
            $normalized = docs_normalize_name_candidate_value($value ?? '');
            if ($normalized !== '') {
                $fallbackUserNames[$normalized] = true;
            }
        };
        $addFallbackUserName($requestContext['primaryId'] ?? '');
        $addFallbackUserName($userContext['fullName'] ?? null);
        $addFallbackUserName($userContext['firstName'] ?? null);
        $addFallbackUserName($userContext['lastName'] ?? null);
        $addFallbackUserName($rawContext['telegram_full_name'] ?? null);
        $fallbackMatchedAssignee = null;
        $fallbackMatchedKey = '';
        if (!empty($fallbackUserNames)) {
            foreach ($assignees as $assignee) {
                if (!is_array($assignee)) {
                    continue;
                }
                foreach (['fullName', 'name', 'responsible'] as $field) {
                    if (!isset($assignee[$field])) {
                        continue;
                    }
                    $normalizedName = docs_normalize_name_candidate_value($assignee[$field]);
                    if ($normalizedName === '') {
                        continue;
                    }
                    if (isset($fallbackUserNames[$normalizedName])) {
                        $fallbackMatchedAssignee = $assignee;
                        $fallbackMatchedKey = 'name::' . $normalizedName;
                        break 2;
                    }
                }
            }
        }
        if ($fallbackMatchedAssignee === null) {
            return $result;
        }
        $matchedAssignee = $fallbackMatchedAssignee;
        $matchedKey = $fallbackMatchedKey;
        docs_log_view_status_event('documents:register_view fallback_name_match', [
            'organization' => $organization,
            'documentId' => $documentId,
            'matchedKey' => $matchedKey,
        ]);
    }
    $timestamp = null;
    if (isset($details['viewedAt']) && is_string($details['viewedAt'])) {
        $normalizedTimestamp = docs_normalize_datetime_iso($details['viewedAt']);
        if ($normalizedTimestamp !== null) {
            $timestamp = $normalizedTimestamp;
        }
    }
    if ($timestamp === null) {
        $timestamp = date('c');
    }
    $normalizedKey = mb_strtolower($matchedKey, 'UTF-8');
    $normalizedId = '';
    if (strpos($normalizedKey, 'id::') === 0) {
        $normalizedId = substr($normalizedKey, 4);
    }
    if ($normalizedId === '') {
        $normalizedId = docs_normalize_identifier_candidate_value($matchedAssignee['id'] ?? '');
    }
    if ($normalizedId === '') {
        $normalizedId = docs_normalize_identifier_candidate_value($requestContext['primaryId'] ?? '');
    }
    if ($normalizedId === '') {
        $normalizedId = docs_normalize_identifier_candidate_value($requestContext['raw']['telegram_user_id'] ?? '');
    }
    if ($normalizedId === '') {
        return $result;
    }
    $viewerName = '';
    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $viewerName = sanitize_text_field((string) ($requestContext['user']['fullName'] ?? ''), 200);
        if ($viewerName === '') {
            $firstName = sanitize_text_field((string) ($requestContext['user']['firstName'] ?? ''), 120);
            $lastName = sanitize_text_field((string) ($requestContext['user']['lastName'] ?? ''), 160);
            $viewerName = trim($firstName . ' ' . $lastName);
        }
        if ($viewerName === '' && !empty($requestContext['user']['username'])) {
            $viewerName = '@' . sanitize_text_field((string) $requestContext['user']['username'], 120);
        }
    }
    if ($viewerName === '' && isset($details['viewerName'])) {
        $viewerName = sanitize_text_field((string) $details['viewerName'], 200);
    }
    if ($viewerName === '' && isset($matchedAssignee['name'])) {
        $viewerName = (string) $matchedAssignee['name'];
    } elseif ($viewerName === '' && isset($matchedAssignee['responsible'])) {
        $viewerName = (string) $matchedAssignee['responsible'];
    }
    $viewsMap = [];
    $orderedKeys = [];
    if (isset($records[$recordIndex]['assigneeViews']) && is_array($records[$recordIndex]['assigneeViews'])) {
        foreach ($records[$recordIndex]['assigneeViews'] as $entry) {
            if (!is_array($entry)) {
                continue;
            }
            $entryKey = '';
            if (!empty($entry['assigneeKey'])) {
                $entryKey = mb_strtolower((string) $entry['assigneeKey'], 'UTF-8');
            }
            if ($entryKey === '' && !empty($entry['id'])) {
                $candidate = docs_normalize_identifier_candidate_value($entry['id']);
                if ($candidate !== '') {
                    $entryKey = 'id::' . $candidate;
                }
            }
            if ($entryKey === '') {
                continue;
            }
            if (!isset($viewsMap[$entryKey])) {
                $viewsMap[$entryKey] = $entry;
                $orderedKeys[] = $entryKey;
            }
        }
    }
    $existingEntry = null;
    if (isset($viewsMap[$normalizedKey]) && is_array($viewsMap[$normalizedKey])) {
        $existingEntry = $viewsMap[$normalizedKey];
    } elseif ($normalizedId !== '') {
        $idKey = 'id::' . $normalizedId;
        if (isset($viewsMap[$idKey]) && is_array($viewsMap[$idKey])) {
            $existingEntry = $viewsMap[$idKey];
            $normalizedKey = $idKey;
            $matchedKey = $idKey;
        }
    }
    if (is_array($existingEntry) && isset($existingEntry['viewedAt']) && $existingEntry['viewedAt'] !== '') {
        $result['alreadyRecorded'] = true;
        $result['viewedAt'] = (string) $existingEntry['viewedAt'];
        if (isset($existingEntry['assigneeKey'])) {
            $result['assigneeKey'] = (string) $existingEntry['assigneeKey'];
        }
        if (isset($existingEntry['id'])) {
            $result['id'] = (string) $existingEntry['id'];
        }
        if (isset($existingEntry['name'])) {
            $result['name'] = (string) $existingEntry['name'];
        }
        return $result;
    }
    $viewEntry = [
        'assigneeKey' => $matchedKey,
        'viewedAt' => $timestamp,
    ];
    if ($normalizedId !== '') {
        $viewEntry['id'] = $normalizedId;
    }
    if ($viewerName !== '') {
        $viewEntry['name'] = $viewerName;
    }
    $updatedEntry = is_array($existingEntry)
        ? array_merge($existingEntry, $viewEntry)
        : $viewEntry;
    $updatedEntry['assigneeKey'] = $matchedKey;
    $updatedEntry['viewedAt'] = $timestamp;
    $viewsMap[$normalizedKey] = $updatedEntry;
    if (!in_array($normalizedKey, $orderedKeys, true)) {
        $orderedKeys[] = $normalizedKey;
    }
    $updatedViews = [];
    foreach ($orderedKeys as $key) {
        if (!isset($viewsMap[$key])) {
            continue;
        }
        $updatedViews[] = $viewsMap[$key];
    }
    $sanitizedViews = docs_sanitize_assignee_views_payload($updatedViews);
    if (empty($sanitizedViews)) {
        return $result;
    }
    $records[$recordIndex]['assigneeViews'] = $sanitizedViews;
    save_registry($folder, $records);
    $logContext = [
        'organization' => $organization,
        'folder' => $folder,
        'documentId' => $documentId,
        'assigneeKey' => $matchedKey,
        'viewerId' => $normalizedId,
    ];
    if (isset($details['trigger'])) {
        $logContext['trigger'] = sanitize_text_field((string) $details['trigger'], 120);
    }
    log_docs_event('Task view recorded', $logContext);
    $result['recorded'] = true;
    $result['viewedAt'] = $timestamp;
    $result['assigneeKey'] = $matchedKey;
    if ($normalizedId !== '') {
        $result['id'] = $normalizedId;
    }
    if ($viewerName !== '') {
        $result['name'] = $viewerName;
    }
    return $result;
}
function load_registry(string $folder): array
{
    $file = get_registry_path($folder);
    $context = [
        'folder' => $folder,
        'path' => $file,
    ];
    if (!is_file($file)) {
        log_docs_event('Registry file missing', $context);
        return docs_load_registry_backup($folder, 'primary_missing');
    }
    $size = @filesize($file);
    if ($size !== false) {
        $context['fileSize'] = $size;
    }
    $raw = file_get_contents($file);
    if ($raw === false) {
        log_docs_event('Registry file read failed', $context);
        return docs_load_registry_backup($folder, 'primary_read_failed');
    }
    $context['rawLength'] = strlen($raw);
    if (trim($raw) === '') {
        log_docs_event('Registry file empty', $context);
        return docs_load_registry_backup($folder, 'primary_empty');
    }
    $data = json_decode($raw, true);
    if (!is_array($data)) {
        $context['jsonError'] = json_last_error_msg();
        log_docs_event('Registry decode error', $context);
        return docs_load_registry_backup($folder, 'primary_decode_failed');
    }
    $context['recordsCount'] = count($data);
    $sampleIds = [];
    $sampleRecords = [];
    foreach (array_slice($data, 0, 5) as $record) {
        if (!is_array($record)) {
            continue;
        }
        if (isset($record['id'])) {
            $sampleIds[] = (string) $record['id'];
        } elseif (isset($record['entryNumber'])) {
            $sampleIds[] = (string) $record['entryNumber'];
        }
        $summary = [];
        if (isset($record['id'])) {
            $summary['id'] = (string) $record['id'];
        }
        if (isset($record['entryNumber'])) {
            $summary['entryNumber'] = (string) $record['entryNumber'];
        }
        if (isset($record['status']) && $record['status'] !== '') {
            $summary['status'] = (string) $record['status'];
        }
        $assignees = docs_extract_assignees($record);
        if (!empty($assignees)) {
            $assignee = $assignees[0];
            if (!empty($assignee['name'])) {
                $summary['assigneeName'] = (string) $assignee['name'];
            } elseif (!empty($assignee['responsible'])) {
                $summary['assigneeName'] = (string) $assignee['responsible'];
            }
            foreach (['id', 'telegram', 'chatId'] as $field) {
                if (!empty($assignee[$field])) {
                    $summary['assignee' . ucfirst($field)] = (string) $assignee[$field];
                    break;
                }
            }
            $summary['assigneesCount'] = count($assignees);
        } elseif (isset($record['responsible']) && is_scalar($record['responsible']) && $record['responsible'] !== '') {
            $summary['assigneeName'] = (string) $record['responsible'];
        } elseif (isset($record['responsible']) && is_array($record['responsible'])) {
            $responsibleName = sanitize_text_field((string) (
                $record['responsible']['name']
                ?? ($record['responsible']['responsible'] ?? '')
            ), 200);
            if ($responsibleName !== '') {
                $summary['assigneeName'] = $responsibleName;
            }
        }
        if (!empty($summary)) {
            $sampleRecords[] = $summary;
        }
    }
    if (!empty($sampleIds)) {
        $context['sampleIds'] = array_values(array_unique($sampleIds));
    }
    if (!empty($sampleRecords)) {
        $context['sampleRecords'] = $sampleRecords;
    }
    log_docs_event('Registry file loaded', $context);
    return $data;
}
function docs_registry_backup_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . REGISTRY_BACKUP_FILENAME;
}
function docs_load_registry_backup(string $folder, string $reason): array
{
    $backupPath = docs_registry_backup_path($folder);
    if (is_file($backupPath) && is_readable($backupPath)) {
        $raw = @file_get_contents($backupPath);
        $records = is_string($raw) && trim($raw) !== '' ? json_decode($raw, true) : null;
        if (is_array($records) && !empty($records)) {
            log_docs_event('Registry backup loaded', [
                'folder' => $folder,
                'path' => $backupPath,
                'reason' => $reason,
                'recordsCount' => count($records),
            ]);
            return array_values($records);
        }
        log_docs_event('Registry backup unavailable', [
            'folder' => $folder,
            'path' => $backupPath,
            'reason' => $reason,
            'jsonError' => json_last_error_msg(),
        ]);
    }
    return docs_load_registry_s3_backup($folder, $reason);
}
function docs_load_registry_s3_backup(string $folder, string $reason): array
{
    $key = docs_build_cold_storage_key($folder, REGISTRY_S3_BACKUP_RELATIVE_PATH);
    if ($key === '') {
        return [];
    }
    $tempPath = tempnam(sys_get_temp_dir(), 'docs_registry_s3_restore_');
    if (!is_string($tempPath) || $tempPath === '') {
        return [];
    }
    try {
        $download = docs_run_rclone_command(
            ['copyto', docs_cold_storage_remote_path($key), $tempPath],
            30
        );
        if (empty($download['ok']) || !is_file($tempPath) || (int) @filesize($tempPath) < 1) {
            docs_write_response_log('Registry S3 backup unavailable', [
                'folder' => $folder,
                'reason' => $reason,
                'key' => $key,
                'error' => (string) ($download['error'] ?? ''),
            ]);
            return [];
        }
        $raw = @file_get_contents($tempPath);
        $records = is_string($raw) && trim($raw) !== '' ? json_decode($raw, true) : null;
        if (!is_array($records) || empty($records)) {
            docs_write_response_log('Registry S3 backup invalid', [
                'folder' => $folder,
                'reason' => $reason,
                'key' => $key,
                'bytes' => (int) @filesize($tempPath),
                'jsonError' => json_last_error_msg(),
            ]);
            return [];
        }
        if (!docs_write_registry_backup($folder, $raw, true)) {
            docs_write_response_log('Registry S3 backup loaded without local backup refresh', [
                'folder' => $folder,
                'reason' => $reason,
                'key' => $key,
                'recordsCount' => count($records),
            ]);
        }
        return array_values($records);
    } finally {
        @unlink($tempPath);
    }
}
function docs_registry_json_diagnostic(string $path, string $label): array
{
    $result = [
        'label' => $label,
        'exists' => is_file($path),
        'readable' => is_file($path) && is_readable($path),
        'writable' => is_file($path) && is_writable($path),
        'bytes' => is_file($path) ? max(0, (int) (@filesize($path) ?: 0)) : 0,
        'jsonValid' => null,
        'recordsCount' => null,
    ];
    if (!$result['readable']) {
        return $result;
    }
    $raw = @file_get_contents($path);
    $decoded = is_string($raw) && trim($raw) !== '' ? json_decode($raw, true) : null;
    $result['jsonValid'] = is_array($decoded);
    $result['recordsCount'] = is_array($decoded) ? count($decoded) : null;
    if (!is_array($decoded)) {
        $result['jsonError'] = is_string($raw) && trim($raw) === ''
            ? 'empty_file'
            : json_last_error_msg();
    }
    return $result;
}
function docs_registry_write_diagnostic(string $folder): array
{
    $primaryPath = get_registry_path($folder);
    $directory = dirname($primaryPath);
    return [
        'code' => 'documents_registry_write_failed',
        'folder' => $folder,
        'directoryExists' => is_dir($directory),
        'directoryWritable' => is_dir($directory) && is_writable($directory),
        'primary' => docs_registry_json_diagnostic($primaryPath, REGISTRY_FILENAME),
        'localBackup' => docs_registry_json_diagnostic(
            docs_registry_backup_path($folder),
            REGISTRY_BACKUP_FILENAME
        ),
        's3BackupKey' => docs_build_cold_storage_key($folder, REGISTRY_S3_BACKUP_RELATIVE_PATH),
        'serverTime' => date('c'),
    ];
}
function docs_write_registry_backup(string $folder, string $raw, bool $contentValidated = false): bool
{
    if (trim($raw) === '') {
        return false;
    }
    if (!$contentValidated) {
        $decoded = json_decode($raw, true);
        if (!is_array($decoded) || empty($decoded)) {
            return false;
        }
    }
    return docs_replace_json_content_atomically(
        docs_registry_backup_path($folder),
        $raw,
        0664,
        true
    );
}
function docs_copy_file_atomically(string $sourcePath, string $targetPath, int $defaultMode = 0664): bool
{
    if (!is_file($sourcePath) || !is_readable($sourcePath)) {
        return false;
    }
    $directory = dirname($targetPath);
    if (!is_dir($directory) && !@mkdir($directory, 0775, true) && !is_dir($directory)) {
        return false;
    }
    $sourceSize = @filesize($sourcePath);
    if (!is_int($sourceSize) || $sourceSize < 1) {
        return false;
    }
    $tempPath = tempnam($directory, '.documents_copy_');
    if (!is_string($tempPath) || $tempPath === '') {
        return false;
    }
    try {
        if (!@copy($sourcePath, $tempPath)) {
            return false;
        }
        clearstatcache(true, $tempPath);
        if ((int) @filesize($tempPath) !== $sourceSize) {
            return false;
        }
        $handle = @fopen($tempPath, 'r+');
        if ($handle === false) {
            return false;
        }
        $flushed = @fflush($handle);
        $synced = !function_exists('fsync') || @fsync($handle);
        fclose($handle);
        if (!$flushed || !$synced) {
            return false;
        }
        $mode = is_file($targetPath)
            ? ((int) @fileperms($targetPath) & 0777)
            : ((int) @fileperms($sourcePath) & 0777);
        @chmod($tempPath, $mode > 0 ? $mode : $defaultMode);
        return @rename($tempPath, $targetPath);
    } finally {
        if (is_file($tempPath)) {
            @unlink($tempPath);
        }
    }
}
function docs_registry_s3_backup_state_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . REGISTRY_S3_BACKUP_STATE_FILENAME;
}
function docs_registry_s3_backup_lock_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . REGISTRY_S3_BACKUP_LOCK_FILENAME;
}
function docs_default_registry_s3_backup_state(): array
{
    return [
        'status' => 'idle',
        'recordsCount' => 0,
        'fileSize' => 0,
        'startedAt' => '',
        'syncedAt' => '',
        'attempts' => 0,
        'remoteKey' => '',
        'error' => '',
    ];
}
function docs_load_registry_s3_backup_state(string $folder): array
{
    $path = docs_registry_s3_backup_state_path($folder);
    $decoded = docs_read_json_array_file_with_backup($path);
    return is_array($decoded)
        ? array_replace(docs_default_registry_s3_backup_state(), $decoded)
        : docs_default_registry_s3_backup_state();
}
function docs_save_registry_s3_backup_state(string $folder, array $state): bool
{
    $path = docs_registry_s3_backup_state_path($folder);
    $state['updatedAt'] = date('c');
    return docs_write_json_file_atomically($path, $state);
}
function &docs_pending_registry_s3_backups(): array
{
    static $backups = [];
    return $backups;
}
function docs_has_pending_registry_s3_backups(): bool
{
    $backups = &docs_pending_registry_s3_backups();
    return !empty($backups);
}
function docs_schedule_registry_s3_backup(
    string $folder,
    string $registryPath,
    int $recordsCount,
    int $fileSize
): void {
    $backups = &docs_pending_registry_s3_backups();
    $backups[$folder] = [
        'folder' => $folder,
        'registryPath' => $registryPath,
        'recordsCount' => max(0, $recordsCount),
        'fileSize' => max(0, $fileSize),
    ];
}
function docs_run_pending_registry_s3_backups(): void
{
    $backups = &docs_pending_registry_s3_backups();
    $pending = array_values($backups);
    $backups = [];
    foreach ($pending as $backup) {
        if (!is_array($backup)) {
            continue;
        }
        $folder = sanitize_folder_name((string) ($backup['folder'] ?? ''));
        $registryPath = (string) ($backup['registryPath'] ?? '');
        if ($folder === '' || $registryPath === '') {
            continue;
        }
        if (!docs_backup_registry_to_s3(
            $folder,
            $registryPath,
            (int) ($backup['recordsCount'] ?? 0),
            (int) ($backup['fileSize'] ?? 0)
        )) {
            log_docs_event('Registry S3 backup failed', [
                'folder' => $folder,
                'path' => $registryPath,
                'recordsCount' => (int) ($backup['recordsCount'] ?? 0),
            ]);
        }
    }
}
function docs_backup_registry_to_s3(string $folder, string $registryPath, int $recordsCount, int $fileSize): bool
{
    $lockHandle = @fopen(docs_registry_s3_backup_lock_path($folder), 'c+');
    if ($lockHandle === false || !@flock($lockHandle, LOCK_EX)) {
        if (is_resource($lockHandle)) {
            fclose($lockHandle);
        }
        return false;
    }
    try {
        $state = docs_load_registry_s3_backup_state($folder);
        $state['recordsCount'] = max(0, $recordsCount);
        $state['fileSize'] = max(0, $fileSize);
        $state['startedAt'] = date('c');
        $state['attempts'] = max(0, (int) ($state['attempts'] ?? 0)) + 1;
        if ($recordsCount < 1 || !is_file($registryPath) || !is_readable($registryPath)) {
            $state['status'] = 'error';
            $state['error'] = 'S3-копия отменена: локальный registry.json пуст или недоступен.';
            docs_save_registry_s3_backup_state($folder, $state);
            return false;
        }
        $upload = docs_upload_file_to_cold_storage(
            $registryPath,
            $folder,
            REGISTRY_S3_BACKUP_RELATIVE_PATH
        );
        if (empty($upload['ok'])) {
            $state['status'] = 'error';
            $state['error'] = sanitize_text_field(
                (string) ($upload['error'] ?? 'Не удалось создать S3-копию registry.json.'),
                500
            );
            docs_save_registry_s3_backup_state($folder, $state);
            return false;
        }
        $state['status'] = 'synced';
        $state['syncedAt'] = date('c');
        $state['remoteKey'] = sanitize_text_field((string) ($upload['key'] ?? ''), 500);
        $state['error'] = '';
        docs_save_registry_s3_backup_state($folder, $state);
        return true;
    } finally {
        @flock($lockHandle, LOCK_UN);
        fclose($lockHandle);
    }
}
function save_registry(string $folder, array $records, bool $trustedRecords = false): bool
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . REGISTRY_FILENAME;
    $recordsAreList = true;
    $expectedIndex = 0;
    foreach ($records as $index => $_record) {
        if ($index !== $expectedIndex) {
            $recordsAreList = false;
            break;
        }
        $expectedIndex++;
    }
    $recordsForEncoding = $recordsAreList ? $records : array_values($records);
    $json = json_encode(
        $recordsForEncoding,
        JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE
    );
    unset($recordsForEncoding);
    if (!is_string($json)) {
        log_docs_event('Registry encode failed', [
            'folder' => $folder,
            'path' => $file,
            'jsonError' => json_last_error_msg(),
        ]);
        return false;
    }
    if (!$trustedRecords) {
        $currentRaw = is_file($file) && is_readable($file) ? @file_get_contents($file) : false;
        if (is_string($currentRaw) && trim($currentRaw) !== '') {
            $currentRecords = json_decode($currentRaw, true);
            if (!is_array($currentRecords)) {
                $backupRecords = docs_load_registry_backup($folder, 'primary_invalid_before_save');
                if (empty($backupRecords)) {
                    log_docs_event('Registry save refused: invalid primary without backup', [
                        'folder' => $folder,
                        'path' => $file,
                    ]);
                    return false;
                }
            }
        } elseif (is_file($file)) {
            $backupRecords = docs_load_registry_backup($folder, 'primary_empty_before_save');
            if (empty($backupRecords)) {
                log_docs_event('Registry save refused: empty primary without backup', [
                    'folder' => $folder,
                    'path' => $file,
                ]);
                return false;
            }
        }
    }
    if (!docs_replace_json_content_atomically($file, $json, 0664, true)) {
        log_docs_event('Registry atomic replace failed', ['folder' => $folder, 'path' => $file]);
        return false;
    }
    if (!docs_copy_file_atomically($file, docs_registry_backup_path($folder))) {
        // Основной registry.json уже сохранён атомарно. Не отменяем создание задачи
        // из-за недоступности дополнительной локальной копии.
        docs_write_response_log('Registry local backup refresh failed', [
            'folder' => $folder,
            'path' => $file,
        ]);
    }
    docs_schedule_registry_s3_backup($folder, $file, count($records), strlen($json));
    return true;
}
function docs_lock_registry(string $folder): array
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . REGISTRY_FILENAME;
    $lockFile = $dir . '/' . REGISTRY_LOCK_FILENAME;
    $handle = @fopen($lockFile, 'c+');
    if ($handle === false) {
        log_docs_event('Registry file open failed', [
            'file' => $file,
            'lockFile' => $lockFile,
            'folder' => $folder,
        ]);
        return [null, []];
    }
    if (!flock($handle, LOCK_EX)) {
        log_docs_event('Registry file lock failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        fclose($handle);
        return [null, []];
    }
    $primaryInvalid = false;
    $raw = is_file($file) ? @file_get_contents($file) : false;
    if ($raw === false) {
        log_docs_event('Registry file read failed (locked)', [
            'file' => $file,
            'folder' => $folder,
        ]);
        $records = docs_load_registry_backup($folder, 'locked_primary_read_failed');
        $primaryInvalid = is_file($file);
    } elseif (trim($raw) === '') {
        $records = docs_load_registry_backup($folder, 'locked_primary_empty');
        $primaryInvalid = true;
    } else {
        $decoded = json_decode($raw, true);
        if (!is_array($decoded)) {
            log_docs_event('Registry decode error (locked)', [
                'file' => $file,
                'folder' => $folder,
                'jsonError' => json_last_error_msg(),
            ]);
            $records = docs_load_registry_backup($folder, 'locked_primary_decode_failed');
            $primaryInvalid = true;
        } else {
            $records = $decoded;
        }
    }
    if ($primaryInvalid && empty($records)) {
        log_docs_event('Registry mutation refused: invalid primary without backup', [
            'file' => $file,
            'folder' => $folder,
        ]);
        flock($handle, LOCK_UN);
        fclose($handle);
        return [null, []];
    }
    register_shutdown_function(function () use ($handle) {
        if (is_resource($handle)) {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    });
    return [$handle, $records];
}
