            return true;
        }
        $assignedById = docs_normalize_identifier_candidate_value($candidate);
        if ($assignedById !== '' && in_array($assignedById, $userCandidates['ids'], true)) {
            return true;
        }
    }
    return false;
}
function docs_find_responsible_by_candidate(array $responsibles, string $candidate): ?array
{
    if ($candidate === '') {
        return null;
    }
    foreach ($responsibles as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        if (docs_entry_matches_candidate($entry, $candidate)) {
            return $entry;
        }
    }
    return null;
}
function docs_resolve_responsible_identifier(array $entry, string $candidate): string
{
    $normalizedCandidate = docs_normalize_identifier_candidate_value($candidate);
    if ($normalizedCandidate !== '') {
        foreach (['telegram', 'chatId', 'id', 'number', 'email', 'login'] as $field) {
            if (!isset($entry[$field])) {
                continue;
            }
            $value = docs_normalize_identifier_candidate_value($entry[$field]);
            if ($value !== '' && $value === $normalizedCandidate) {
                return (string) $entry[$field];
            }
        }
    }
    $entryName = $entry['responsible'] ?? ($entry['name'] ?? '');
    $compositeKey = docs_build_responsible_composite_key($entry['number'] ?? '', $entryName);
    $candidateComposite = docs_normalize_responsible_composite_key_value($candidate);
    if ($compositeKey !== '' && $candidateComposite !== '' && $compositeKey === $candidateComposite) {
        return (string) $candidate;
    }
    if (isset($entry['responsible'])) {
        $entryName = docs_normalize_name_candidate_value($entry['responsible']);
        $candidateName = docs_normalize_name_candidate_value($candidate);
        if ($entryName !== '' && $candidateName !== '' && $entryName === $candidateName) {
            return (string) $entry['responsible'];
        }
    }
    return (string) $candidate;
}
function docs_build_assignee_from_responsible_entry(array $entry, string $candidate): array
{
    $assignee = [
        'id' => docs_resolve_responsible_identifier($entry, $candidate),
        'name' => $entry['responsible'] ?? '',
        'department' => $entry['department'] ?? '',
        'telegram' => $entry['telegram'] ?? '',
        'chatId' => $entry['chatId'] ?? '',
        'login' => $entry['login'] ?? '',
        'email' => $entry['email'] ?? '',
        'note' => $entry['note'] ?? '',
    ];
    return sanitize_assignee_payload($assignee, true);
}
function docs_find_subordinate_by_candidate(array $subordinates, string $candidate): ?array
{
    return docs_find_responsible_by_candidate($subordinates, $candidate);
}
function docs_build_subordinate_assignment_from_entry(array $entry, string $candidate): array
{
    $assignee = docs_build_assignee_from_responsible_entry($entry, $candidate);
    if (empty($assignee)) {
        return [];
    }
    $assignee['role'] = 'subordinate';
    return sanitize_assignee_payload($assignee, false);
}
function docs_pick_responsible_candidate(array $entry): string
{
    $fields = ['telegram', 'chatId', 'id', 'number', 'email', 'login', 'responsible'];
    foreach ($fields as $field) {
        if (!isset($entry[$field])) {
            continue;
        }
        $value = docs_normalize_identifier_candidate_value($entry[$field]);
        if ($value !== '') {
            return (string) $entry[$field];
        }
    }
    return '';
}
function docs_build_director_assignment_from_entry(array $entry, string $authorLabel = '', string $authorRole = ''): array
{
    $candidate = docs_pick_responsible_candidate($entry);
    $director = docs_build_assignee_from_responsible_entry($entry, $candidate !== '' ? $candidate : ($entry['responsible'] ?? ''));
    if (empty($director)) {
        return [];
    }
    if ($authorLabel !== '') {
        $assignments = docs_assign_author_to_assignees([$director], $authorLabel, $authorRole);
        $director = $assignments[0] ?? $director;
    }
    return $director;
}
function save_admin_settings(string $folder, array $settings): bool
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . SETTINGS_FILENAME;
    $existing = docs_read_json_array_file_with_backup($file);
    $existing = is_array($existing) ? $existing : [];
    if (isset($settings['columnWidths'])) {
        $settings['columnWidths'] = docs_normalize_column_width_map($settings['columnWidths']);
    } elseif (isset($existing['columnWidths']) && is_array($existing['columnWidths'])) {
        $settings['columnWidths'] = docs_normalize_column_width_map($existing['columnWidths']);
    }
    if (isset($settings['columnOrders'])) {
        $settings['columnOrders'] = docs_normalize_column_order_map($settings['columnOrders']);
    } elseif (isset($existing['columnOrders']) && is_array($existing['columnOrders'])) {
        $settings['columnOrders'] = docs_normalize_column_order_map($existing['columnOrders']);
    }
    if (isset($settings['outgoingColumnOrders'])) {
        $settings['outgoingColumnOrders'] = docs_normalize_outgoing_column_order_map($settings['outgoingColumnOrders']);
    } elseif (isset($existing['outgoingColumnOrders']) && is_array($existing['outgoingColumnOrders'])) {
        $settings['outgoingColumnOrders'] = docs_normalize_outgoing_column_order_map($existing['outgoingColumnOrders']);
    }
    if (isset($settings['ordersColumnOrders'])) {
        $settings['ordersColumnOrders'] = docs_normalize_orders_column_order_map($settings['ordersColumnOrders']);
    } elseif (isset($existing['ordersColumnOrders']) && is_array($existing['ordersColumnOrders'])) {
        $settings['ordersColumnOrders'] = docs_normalize_orders_column_order_map($existing['ordersColumnOrders']);
    }
    if (isset($settings['directivesColumnOrders'])) {
        $settings['directivesColumnOrders'] = docs_normalize_orders_column_order_map($settings['directivesColumnOrders']);
    } elseif (isset($existing['directivesColumnOrders']) && is_array($existing['directivesColumnOrders'])) {
        $settings['directivesColumnOrders'] = docs_normalize_orders_column_order_map($existing['directivesColumnOrders']);
    }
    if (isset($settings['disciplinaryColumnOrders'])) {
        $settings['disciplinaryColumnOrders'] = docs_normalize_orders_column_order_map($settings['disciplinaryColumnOrders']);
    } elseif (isset($existing['disciplinaryColumnOrders']) && is_array($existing['disciplinaryColumnOrders'])) {
        $settings['disciplinaryColumnOrders'] = docs_normalize_orders_column_order_map($existing['disciplinaryColumnOrders']);
    }
    if (isset($settings['tablePreferences'])) {
        $settings['tablePreferences'] = docs_normalize_table_preferences_map($settings['tablePreferences']);
    } elseif (isset($existing['tablePreferences']) && is_array($existing['tablePreferences'])) {
        $settings['tablePreferences'] = docs_normalize_table_preferences_map($existing['tablePreferences']);
    }
    if (isset($settings['assignmentTemplatesByTelegram'])) {
        $settings['assignmentTemplatesByTelegram'] = docs_sanitize_assignment_templates_by_telegram($settings['assignmentTemplatesByTelegram']);
    } elseif (isset($existing['assignmentTemplatesByTelegram']) && is_array($existing['assignmentTemplatesByTelegram'])) {
        $settings['assignmentTemplatesByTelegram'] = docs_sanitize_assignment_templates_by_telegram($existing['assignmentTemplatesByTelegram']);
    }
    if (array_key_exists('aiBriefProvider', $settings)) {
        $settings['aiBriefProvider'] = docs_normalize_ai_brief_provider($settings['aiBriefProvider']);
    } else {
        $settings['aiBriefProvider'] = docs_normalize_ai_brief_provider($existing['aiBriefProvider'] ?? 'default');
    }
    $json = json_encode(
        $settings,
        JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE
    );
    if (!is_string($json) || !docs_write_json_content_atomically($file, $json)) {
        log_docs_event('Admin settings write failed', ['folder' => $folder, 'path' => $file]);
        return false;
    }
    return true;
}
function docs_sanitize_object_ids($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $normalized = [];
    foreach ($value as $candidate) {
        $objectId = is_scalar($candidate) ? strtolower(trim((string) $candidate)) : '';
        if (!preg_match('/^obj_[a-f0-9]{16}$/', $objectId)) {
            continue;
        }
        $normalized[$objectId] = true;
    }
    return array_keys($normalized);
}
function docs_sanitize_object_column_ids($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $normalized = [];
    foreach ($value as $candidate) {
        $columnId = is_scalar($candidate) ? strtolower(trim((string) $candidate)) : '';
        if (!preg_match('/^col_[a-f0-9]{16}$/', $columnId)) {
            continue;
        }
        $normalized[$columnId] = true;
    }
    return array_keys($normalized);
}
function docs_objects_directory(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . DOCS_OBJECTS_DIRECTORY;
}
function docs_normalize_object_id($value): string
{
    $objectId = is_scalar($value) ? strtolower(trim((string) $value)) : '';
    return preg_match('/^obj_[a-f0-9]{16}$/', $objectId) ? $objectId : '';
}
function docs_sanitize_document_object_id($value, string $folder): string
{
    $rawObjectId = is_scalar($value) ? trim((string) $value) : '';
    if ($rawObjectId === '') {
        return '';
    }
    $objectId = docs_normalize_object_id($rawObjectId);
    if ($objectId === '' || !is_array(docs_load_object_file($folder, $objectId))) {
        respond_error('Выбранный объект не найден. Обновите список объектов и повторите сохранение.', 422, [
            'reason' => 'document_object_not_found',
        ]);
    }
    return $objectId;
}
function docs_generate_object_token(string $prefix): string
{
    try {
        return $prefix . bin2hex(random_bytes(8));
    } catch (Throwable $exception) {
        return $prefix . substr(hash('sha256', uniqid($prefix, true)), 0, 16);
    }
}
function docs_generate_object_id(): string
{
    return docs_generate_object_token('obj_');
}
function docs_generate_object_column_id(): string
{
    return docs_generate_object_token('col_');
}
function docs_generate_object_row_id(): string
{
    return docs_generate_object_token('row_');
}
function docs_object_file_path(string $folder, string $objectId): string
{
    $normalizedId = docs_normalize_object_id($objectId);
    if ($normalizedId === '') {
        return '';
    }
    return docs_objects_directory($folder) . '/' . $normalizedId . '.json';
}
function docs_normalize_object_column_type($value): string
{
    return strtolower(trim((string) $value)) === 'date' ? 'date' : 'text';
}
function docs_prepare_object_columns($input, array $existingColumns = []): array
{
    if (!is_array($input)) {
        return [];
    }
    $existingIds = [];
    foreach ($existingColumns as $existingColumn) {
        if (!is_array($existingColumn)) {
            continue;
        }
        $existingId = sanitize_text_field((string) ($existingColumn['id'] ?? ''), 40);
        if ($existingId !== '' && preg_match('/^col_[a-f0-9]{16}$/', $existingId)) {
            $existingIds[$existingId] = true;
        }
    }
    $columns = [];
    $seen = [];
    foreach ($input as $column) {
        if (!is_array($column) || count($columns) >= DOCS_OBJECT_MAX_COLUMNS) {
            continue;
        }
        $label = sanitize_text_field((string) ($column['label'] ?? ''), DOCS_OBJECT_COLUMN_NAME_MAX_LENGTH);
        if ($label === '') {
            continue;
        }
        $group = sanitize_text_field(
            (string) ($column['group'] ?? ''),
            DOCS_OBJECT_COLUMN_NAME_MAX_LENGTH
        );
        $requestedId = sanitize_text_field((string) ($column['id'] ?? ''), 40);
        $columnId = isset($existingIds[$requestedId]) ? $requestedId : docs_generate_object_column_id();
        while (isset($seen[$columnId])) {
            $columnId = docs_generate_object_column_id();
        }
        $seen[$columnId] = true;
        $columns[] = [
            'id' => $columnId,
            'label' => $label,
            'group' => $group,
            'type' => docs_normalize_object_column_type($column['type'] ?? 'text'),
        ];
    }
    return $columns;
}
function docs_prepare_object_values($input, array $columns, bool $strict = true): array
{
    $values = is_array($input) ? $input : [];
    $prepared = [];
    foreach ($columns as $column) {
        if (!is_array($column)) {
            continue;
        }
        $columnId = (string) ($column['id'] ?? '');
        if ($columnId === '') {
            continue;
        }
        $rawValue = isset($values[$columnId]) && is_scalar($values[$columnId])
            ? trim((string) $values[$columnId])
            : '';
        if (($column['type'] ?? 'text') === 'date' && $rawValue !== '') {
            $parts = explode('-', $rawValue);
            $isValidDate = count($parts) === 3
                && preg_match('/^\d{4}-\d{2}-\d{2}$/', $rawValue)
                && checkdate((int) $parts[1], (int) $parts[2], (int) $parts[0]);
            if (!$isValidDate) {
                if ($strict) {
                    respond_error('Дата должна быть указана в формате ГГГГ-ММ-ДД.', 422, [
                        'columnId' => $columnId,
                    ]);
                }
                $rawValue = '';
            }
            $prepared[$columnId] = $rawValue;
            continue;
        }
        $prepared[$columnId] = sanitize_text_field($rawValue, DOCS_OBJECT_TEXT_MAX_LENGTH);
    }
    return $prepared;
}
function docs_load_object_file(string $folder, string $objectId): ?array
{
    $path = docs_object_file_path($folder, $objectId);
    if ($path === '' || !is_file($path)) {
        return null;
    }
    $decoded = docs_read_json_array_file_with_backup($path);
    if (!is_array($decoded) || docs_normalize_object_id($decoded['id'] ?? '') !== $objectId) {
        return null;
    }
    $columns = docs_prepare_object_columns($decoded['columns'] ?? [], $decoded['columns'] ?? []);
    $rows = [];
    if (isset($decoded['rows']) && is_array($decoded['rows'])) {
        foreach ($decoded['rows'] as $row) {
            if (!is_array($row)) {
                continue;
            }
            $rowId = sanitize_text_field((string) ($row['id'] ?? ''), 40);
            if (!preg_match('/^row_[a-f0-9]{16}$/', $rowId)) {
                continue;
            }
            $rows[] = [
                'id' => $rowId,
                'version' => max(1, (int) ($row['version'] ?? 1)),
                'values' => docs_prepare_object_values($row['values'] ?? [], $columns, false),
                'createdAt' => sanitize_text_field((string) ($row['createdAt'] ?? ''), 40),
                'updatedAt' => sanitize_text_field((string) ($row['updatedAt'] ?? ''), 40),
                'updatedBy' => sanitize_text_field((string) ($row['updatedBy'] ?? ''), 200),
            ];
        }
    }
    return [
        'schemaVersion' => DOCS_OBJECT_SCHEMA_VERSION,
        'id' => $objectId,
        'name' => sanitize_text_field((string) ($decoded['name'] ?? ''), 160),
        'schemaRevision' => max(1, (int) ($decoded['schemaRevision'] ?? 1)),
        'revision' => max(1, (int) ($decoded['revision'] ?? 1)),
        'columns' => $columns,
        'rows' => $rows,
        'createdAt' => sanitize_text_field((string) ($decoded['createdAt'] ?? ''), 40),
        'updatedAt' => sanitize_text_field((string) ($decoded['updatedAt'] ?? ''), 40),
    ];
}
function docs_save_object_file(string $folder, array $object): bool
{
    $objectId = docs_normalize_object_id($object['id'] ?? '');
    $path = docs_object_file_path($folder, $objectId);
    if ($path === '') {
        return false;
    }
    return docs_write_json_file_atomically($path, $object);
}
function docs_object_mutation_lock(string $folder, string $objectId)
{
    $path = docs_object_file_path($folder, $objectId);
    if ($path === '') {
        return null;
    }
    $directory = dirname($path);
    if (!is_dir($directory) && !@mkdir($directory, 0775, true) && !is_dir($directory)) {
        return null;
    }
    $handle = @fopen($path . '.mutation.lock', 'c+');
    if ($handle === false || !@flock($handle, LOCK_EX)) {
        if (is_resource($handle)) {
            fclose($handle);
        }
        return null;
    }
    return $handle;
}
function docs_release_object_mutation_lock($handle): void
{
    if (!is_resource($handle)) {
        return;
    }
    @flock($handle, LOCK_UN);
    fclose($handle);
}
function docs_list_organization_objects(string $folder): array
{
    $directory = docs_objects_directory($folder);
    if (!is_dir($directory)) {
        return [];
    }
    $entries = @scandir($directory);
    if (!is_array($entries)) {
        return [];
    }
    $objects = [];
    foreach ($entries as $entry) {
        if (!is_string($entry) || !preg_match('/^(obj_[a-f0-9]{16})\.json$/', $entry, $matches)) {
            continue;
        }
        $object = docs_load_object_file($folder, $matches[1]);
        if (!is_array($object) || $object['name'] === '') {
            continue;
        }
        $objects[] = $object;
    }
    usort($objects, static function (array $left, array $right): int {
        return strnatcasecmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''));
    });
    return $objects;
}
function docs_object_summary(array $object): array
{
    return [
        'id' => (string) ($object['id'] ?? ''),
        'name' => (string) ($object['name'] ?? ''),
        'schemaRevision' => (int) ($object['schemaRevision'] ?? 1),
        'revision' => (int) ($object['revision'] ?? 1),
        'columns' => isset($object['columns']) && is_array($object['columns']) ? array_values($object['columns']) : [],
        'rowsCount' => isset($object['rows']) && is_array($object['rows']) ? count($object['rows']) : 0,
        'createdAt' => (string) ($object['createdAt'] ?? ''),
        'updatedAt' => (string) ($object['updatedAt'] ?? ''),
    ];
}
function docs_user_object_ids(array $settings, array $session): array
{
    if (($session['role'] ?? '') !== 'user') {
        return [];
    }
    $filter = docs_build_session_user_filter_from_auth($session);
    if (!is_array($filter)) {
        return [];
    }
    $objectIds = [];
    foreach (['responsibles', 'block2', 'block3'] as $groupKey) {
        $entries = isset($settings[$groupKey]) && is_array($settings[$groupKey]) ? $settings[$groupKey] : [];
        foreach ($entries as $entry) {
            if (!is_array($entry) || !docs_responsible_matches_filter($entry, $filter)) {
                continue;
            }
            foreach (docs_sanitize_object_ids($entry['objectIds'] ?? []) as $objectId) {
                $objectIds[$objectId] = true;
            }
        }
    }
    return array_keys($objectIds);
}
function docs_require_objects_admin_session(array $accessContext): array
{
    $session = docs_require_admin_session($accessContext);
    $adminScope = strtolower(sanitize_text_field((string) ($session['adminScope'] ?? ''), 60));
    if ($adminScope === 'director') {
        respond_error('Доступ к управлению объектами запрещён.', 403, ['requiresAdmin' => true]);
    }
    return $session;
}
function docs_session_can_access_object(string $folder, string $objectId, array $session): bool
{
    if (($session['role'] ?? '') === 'admin') {
        return true;
    }
    $settings = load_admin_settings($folder);
    return in_array($objectId, docs_user_object_ids($settings, $session), true);
}
function docs_object_updated_by(array $session): string
{
    foreach (['fullName', 'login', 'telegramId'] as $field) {
        $value = sanitize_text_field((string) ($session[$field] ?? ''), 200);
        if ($value !== '') {
            return $value;
        }
    }
    return 'Пользователь';
}
function docs_remove_object_from_admin_settings(string $folder, string $objectId): bool
{
    $settings = load_admin_settings($folder);
    foreach (['responsibles', 'block2', 'block3'] as $groupKey) {
        if (!isset($settings[$groupKey]) || !is_array($settings[$groupKey])) {
            continue;
        }
        foreach ($settings[$groupKey] as &$entry) {
            if (!is_array($entry)) {
                continue;
            }
            $entry['objectIds'] = array_values(array_filter(
                docs_sanitize_object_ids($entry['objectIds'] ?? []),
                static function (string $assignedId) use ($objectId): bool {
                    return $assignedId !== $objectId;
                }
            ));
        }
        unset($entry);
    }
    return save_admin_settings($folder, $settings);
}
function docs_detach_object_from_registry(string $folder, string $objectId): array
{
    [$registryHandle, $records] = docs_lock_registry($folder);
    if ($registryHandle === null) {
        return ['ok' => false, 'count' => 0];
    }
    $detachedCount = 0;
    try {
        foreach ($records as &$record) {
            if (!is_array($record) || docs_normalize_object_id($record['objectId'] ?? '') !== $objectId) {
                continue;
            }
            unset($record['objectId']);
            $record['updatedAt'] = date('c');
            $detachedCount += 1;
        }
        unset($record);
        if ($detachedCount > 0 && !docs_save_registry_locked($registryHandle, $records)) {
            return ['ok' => false, 'count' => 0];
        }
    } finally {
        docs_unlock_registry($registryHandle);
    }
    return ['ok' => true, 'count' => $detachedCount];
}
function sanitize_assignee_payload($value, bool $refreshTimestamp = false): array
{
    if (!is_array($value)) {
        return [];
    }
    $assignee = [
        'id' => sanitize_text_field($value['id'] ?? '', 120),
        'name' => sanitize_text_field($value['name'] ?? '', 200),
        'department' => sanitize_text_field($value['department'] ?? '', 160),
        'position' => sanitize_text_field($value['position'] ?? '', 160),
        'note' => sanitize_text_field($value['note'] ?? '', 200),
        'telegram' => sanitize_text_field($value['telegram'] ?? ($value['telegramId'] ?? ($value['telegram_id'] ?? '')), 120),
        'chatId' => sanitize_text_field($value['chatId'] ?? ($value['chat_id'] ?? ''), 40),
        'login' => sanitize_text_field($value['login'] ?? '', 120),
        'email' => sanitize_text_field($value['email'] ?? '', 160),
        'assignedBy' => sanitize_text_field($value['assignedBy'] ?? '', 200),
        'assignedByTelegram' => sanitize_text_field($value['assignedByTelegram'] ?? '', 120),
        'assignedById' => sanitize_text_field($value['assignedById'] ?? '', 120),
        'assignedByLogin' => sanitize_text_field($value['assignedByLogin'] ?? '', 120),
        'assignedByRole' => sanitize_text_field($value['assignedByRole'] ?? '', 60),
        'assignedAt' => sanitize_text_field($value['assignedAt'] ?? '', 40),
        'assignmentComment' => sanitize_assignment_comment($value['assignmentComment'] ?? ''),
        'assignmentDueDate' => sanitize_date_field($value['assignmentDueDate'] ?? ''),
        'assignmentInstruction' => sanitize_instruction($value['assignmentInstruction'] ?? ''),
        'submissionStatus' => docs_normalize_subordinate_submission_status($value['submissionStatus'] ?? ''),
        'submittedAt' => sanitize_text_field($value['submittedAt'] ?? '', 40),
        'submittedBy' => sanitize_text_field($value['submittedBy'] ?? '', 200),
        'submittedByTelegram' => sanitize_text_field($value['submittedByTelegram'] ?? '', 120),
        'submittedById' => sanitize_text_field($value['submittedById'] ?? '', 120),
        'submittedByLogin' => sanitize_text_field($value['submittedByLogin'] ?? '', 120),
        'reviewComment' => sanitize_assignment_comment($value['reviewComment'] ?? ''),
        'reviewedAt' => sanitize_text_field($value['reviewedAt'] ?? '', 40),
        'reviewedBy' => sanitize_text_field($value['reviewedBy'] ?? '', 200),
        'reviewedByTelegram' => sanitize_text_field($value['reviewedByTelegram'] ?? '', 120),
        'reviewedById' => sanitize_text_field($value['reviewedById'] ?? '', 120),
        'reviewedByLogin' => sanitize_text_field($value['reviewedByLogin'] ?? '', 120),
    ];
    if (isset($value['status'])) {
        $status = sanitize_status((string) $value['status']);
        if ($status !== '') {
            $assignee['status'] = $status;
        }
    }
    if (isset($value['reviewStatus'])) {
        $reviewStatus = docs_normalize_subordinate_review_status($value['reviewStatus']);
        if ($reviewStatus !== '') {
            $assignee['reviewStatus'] = $reviewStatus;
        }
    }
    if (isset($value['role'])) {
        $roleCandidate = sanitize_text_field((string) $value['role'], 60);
        $normalizedRole = strtolower($roleCandidate);
