function docs_extract_assignees(array $record): array
{
    $assignees = [];
    if (isset($record['assignees']) && is_array($record['assignees'])) {
        foreach ($record['assignees'] as $entry) {
            if (is_array($entry)) {
                $assignees[] = $entry;
