            }
            $normalizedRole = docs_normalize_assignment_role((string) $roleCandidate);
            if ($normalizedRole === 'admin') {
                $index['role::admin'] = $entry;
                break;
            }
        }
    }
    return $index;
}
function docs_normalize_assignee_comparison_value(array $assignee, string $field): string
{
    if (!array_key_exists($field, $assignee)) {
        return '';
    }
    $value = $assignee[$field];
    if ($value === null) {
        return '';
    }
    if (is_bool($value)) {
        return $value ? '1' : '0';
    }
    if (is_scalar($value)) {
        return (string) $value;
    }
    if (is_array($value)) {
        return json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }
    return (string) $value;
}
function docs_assignee_entries_differ(array $previous, array $current): bool
{
    $ignoredKeys = ['assignedAt'];
    $allKeys = array_keys(array_merge($previous, $current));
    if (empty($allKeys)) {
        return false;
    }
    sort($allKeys);
    foreach ($allKeys as $key) {
        if (in_array($key, $ignoredKeys, true)) {
            continue;
        }
        $previousValue = docs_normalize_assignee_comparison_value($previous, $key);
        $currentValue = docs_normalize_assignee_comparison_value($current, $key);
        if ($previousValue !== $currentValue) {
            return true;
        }
    }
    return false;
}
function docs_collect_changed_assignees(array $previousAssignees, array $currentAssignees): array
{
    if (empty($currentAssignees)) {
        return [];
    }
    $previousIndex = empty($previousAssignees) ? [] : docs_index_assignees($previousAssignees);
    $collected = [];
    $seen = [];
    foreach ($currentAssignees as $assignee) {
        if (!is_array($assignee) || empty($assignee)) {
            continue;
        }
        $keys = docs_collect_assignee_index_keys($assignee);
        $matched = null;
        foreach ($keys as $key) {
            if ($key === '') {
                continue;
            }
            if (isset($previousIndex[$key])) {
                $matched = $previousIndex[$key];
                break;
            }
        }
        $shouldInclude = false;
        if ($matched === null) {
            $shouldInclude = true;
        } elseif (docs_assignee_entries_differ($matched, $assignee)) {
            $shouldInclude = true;
        }
        if (!$shouldInclude) {
            continue;
        }
        $dedupeKey = '';
        if (!empty($keys)) {
            $dedupeKey = implode('|', $keys);
        }
        if ($dedupeKey === '') {
            $encoded = json_encode($assignee, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            $dedupeKey = $encoded !== false ? md5($encoded) : spl_object_hash((object) $assignee);
        }
        if (isset($seen[$dedupeKey])) {
            continue;
        }
        $seen[$dedupeKey] = true;
        $collected[] = $assignee;
    }
    return array_values($collected);
}
function generate_document_id(): string
{
    try {
        return 'doc_' . bin2hex(random_bytes(8));
    } catch (Throwable $exception) {
        return 'doc_' . sha1(uniqid('', true));
    }
}
function generate_entry_number(array $records): int
{
    $max = 0;
    foreach ($records as $record) {
        if (isset($record['entryNumber'])) {
            $value = (int) $record['entryNumber'];
            if ($value > $max) {
                $max = $value;
            }
        }
    }
    return $max + 1;
}
function generate_document_registry_number(array $records): string
{
    $max = 0;
    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }
        $raw = trim((string) ($record['registryNumber'] ?? ''));
        if ($raw === '' || !preg_match('/^(\d+)/', $raw, $matches)) {
            continue;
        }
        $value = (int) $matches[1];
        if ($value > $max) {
            $max = $value;
        }
    }
    return (string) ($max + 1);
}
function resolve_requested_entry_number($value, array $records, ?int $fallback = null): int
{
    if (is_scalar($value)) {
        $raw = trim((string) $value);
        if ($raw !== '') {
            $entryNumber = filter_var($raw, FILTER_VALIDATE_INT, [
                'options' => ['min_range' => 1],
            ]);
            if ($entryNumber !== false) {
                return (int) $entryNumber;
            }
        }
    }
    if ($fallback !== null && $fallback > 0) {
        return $fallback;
    }
    return generate_entry_number($records);
}
function docs_sanitize_file_component(?string $value, string $fallback): string
{
    if ($value === null) {
        $value = '';
    }
    $value = sanitize_text_field($value, 200);
    if ($value === '') {
        return $fallback;
    }
    $value = preg_replace('/[^\p{L}\p{N}\s_-]/u', '', $value);
    $value = preg_replace('/\s+/u', '_', trim((string) $value));
    $value = trim($value, '_-');
    if ($value === '') {
        return $fallback;
    }
    return $value;
}
function docs_sanitize_status_history_entry($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $status = sanitize_status($value['status'] ?? '', false);
    if ($status === '') {
        return [];
    }
    $changedAtRaw = $value['changedAt'] ?? ($value['timestamp'] ?? ($value['date'] ?? ''));
    $normalizedChangedAt = docs_normalize_datetime_iso(is_string($changedAtRaw) ? $changedAtRaw : null);
    if ($normalizedChangedAt === null) {
        return [];
    }
    $entry = [
        'status' => $status,
        'changedAt' => $normalizedChangedAt,
    ];
    $changedBy = sanitize_text_field($value['changedBy'] ?? '', 200);
    if ($changedBy !== '') {
        $entry['changedBy'] = $changedBy;
    }
    return $entry;
}
function docs_sanitize_status_history($value): array
{
    if (!is_array($value)) {
        return [];
    }
    $result = [];
    foreach ($value as $entry) {
        $sanitized = docs_sanitize_status_history_entry($entry);
        if (!empty($sanitized)) {
            $result[] = $sanitized;
        }
    }
    if (empty($result)) {
        return [];
    }
    usort($result, static function ($a, $b) {
        return strcmp($a['changedAt'], $b['changedAt']);
    });
    return $result;
}
function docs_append_assignee_status_history(array &$record, string $assigneeKey, array $entry): void
{
    $normalizedKey = mb_strtolower(trim($assigneeKey), 'UTF-8');
    if ($normalizedKey === '') {
        return;
    }
    $existing = [];
    if (isset($record['assigneeStatusHistory']) && is_array($record['assigneeStatusHistory'])) {
        $existing = docs_sanitize_assignee_status_history_collection($record['assigneeStatusHistory']);
    }
    $map = [];
    foreach ($existing as $historyEntry) {
        $key = mb_strtolower((string) $historyEntry['assigneeKey'], 'UTF-8');
        if ($key === '') {
            continue;
        }
        $map[$key] = $historyEntry;
    }
    if (!isset($map[$normalizedKey])) {
        $map[$normalizedKey] = [
            'assigneeKey' => $assigneeKey,
            'entries' => [],
        ];
    } else {
        $map[$normalizedKey]['assigneeKey'] = $assigneeKey;
    }
    $entries = isset($map[$normalizedKey]['entries']) && is_array($map[$normalizedKey]['entries'])
        ? $map[$normalizedKey]['entries']
        : [];
    $entries[] = $entry;
    $map[$normalizedKey]['entries'] = docs_sanitize_assignee_status_history_entry_collection($entries);
    $record['assigneeStatusHistory'] = docs_sanitize_assignee_status_history_collection(array_values($map));
}
function docs_clear_assignee_status_history(array &$record, string $assigneeKey): void
{
    $normalizedKey = mb_strtolower(trim($assigneeKey), 'UTF-8');
    if ($normalizedKey === '') {
        return;
    }
    $existing = [];
    if (isset($record['assigneeStatusHistory']) && is_array($record['assigneeStatusHistory'])) {
        $existing = docs_sanitize_assignee_status_history_collection($record['assigneeStatusHistory']);
    }
    if (empty($existing)) {
        unset($record['assigneeStatusHistory']);
        return;
    }
    $next = [];
    foreach ($existing as $historyEntry) {
        $key = mb_strtolower((string) ($historyEntry['assigneeKey'] ?? ''), 'UTF-8');
        if ($key === '' || $key === $normalizedKey) {
            continue;
        }
        $next[] = $historyEntry;
    }
    if (empty($next)) {
        unset($record['assigneeStatusHistory']);
        return;
    }
    $record['assigneeStatusHistory'] = docs_sanitize_assignee_status_history_collection($next);
}
function docs_match_status_change_assignee_key(array $record, array $requestContext, ?array $sessionAuth, string $statusChangeAuthor): ?string
{
    $assignees = docs_extract_assignees($record);
    if (empty($assignees)) {
        return null;
    }
    $index = docs_index_assignees($assignees);
    if (empty($index)) {
        return null;
    }
    $candidateKeys = docs_collect_status_change_candidate_keys($requestContext, $sessionAuth, $statusChangeAuthor);
    foreach ($candidateKeys as $candidateKey) {
        if (isset($index[$candidateKey])) {
            return $candidateKey;
        }
    }
    return null;
}
function docs_append_status_history(array &$record, string $status, string $changedBy = '', ?string $timestamp = null, ?string $assigneeKey = null): void
{
    $normalizedStatus = sanitize_status($status, false);
    if ($normalizedStatus === '') {
        return;
    }
    $normalizedTimestamp = $timestamp !== null
        ? docs_normalize_datetime_iso($timestamp)
        : null;
    if ($normalizedTimestamp === null) {
        $normalizedTimestamp = date('c');
    }
    $entry = [
        'status' => $normalizedStatus,
        'changedAt' => $normalizedTimestamp,
    ];
    $author = sanitize_text_field($changedBy, 200);
    if ($author !== '') {
        $entry['changedBy'] = $author;
    }
    $history = [];
    if (isset($record['statusHistory']) && is_array($record['statusHistory'])) {
        $history = docs_sanitize_status_history($record['statusHistory']);
    }
    if (!empty($history)) {
        $lastEntry = $history[count($history) - 1];
        if (
            isset($lastEntry['status'], $lastEntry['changedAt'])
            && $lastEntry['status'] === $entry['status']
            && $lastEntry['changedAt'] === $entry['changedAt']
        ) {
            if (!empty($entry['changedBy']) && empty($lastEntry['changedBy'])) {
                $history[count($history) - 1]['changedBy'] = $entry['changedBy'];
            }
            $record['statusHistory'] = $history;
            return;
        }
    }
    $history[] = $entry;
    usort($history, static function ($a, $b) {
        return strcmp($a['changedAt'], $b['changedAt']);
    });
    $record['statusHistory'] = $history;
    if ($assigneeKey !== null && $assigneeKey !== '') {
        docs_append_assignee_status_history($record, $assigneeKey, $entry);
    }
}
function docs_parse_datetime(string $value): ?DateTimeImmutable
{
    $value = trim($value);
    if ($value === '') {
        return null;
    }
    try {
        return new DateTimeImmutable($value);
    } catch (Exception $exception) {
        $timestamp = strtotime($value);
        if ($timestamp === false) {
            return null;
        }
        try {
            $dateTime = new DateTimeImmutable('@' . $timestamp);
            return $dateTime->setTimezone(new DateTimeZone(date_default_timezone_get()));
        } catch (Exception $innerException) {
            return null;
        }
    }
}
function docs_build_registration_datetime_component(array $record, int $sequence): string
{
    $date = '';
    $rawDate = (string) ($record['registrationDate'] ?? '');
    if ($rawDate !== '') {
        $dateTime = docs_parse_datetime($rawDate);
        if ($dateTime !== null) {
            $date = $dateTime->format('Y-m-d');
        }
    }
    if ($date === '') {
        $date = date('Y-m-d');
    }
    $time = '';
    foreach (['registrationTime', 'createdAt'] as $field) {
        if (empty($record[$field])) {
            continue;
        }
        $dateTime = docs_parse_datetime((string) $record[$field]);
        if ($dateTime !== null) {
            $time = $dateTime->format('H-i-s');
            break;
        }
    }
    if ($time === '') {
        $time = date('H-i-s');
    }
    $component = $date . '_' . $time;
    if ($sequence > 1) {
        $component .= '-' . $sequence;
    }
    return $component;
}
function normalize_file_name(string $original, array $record, int $sequence = 1): string
{
    $name = trim($original);
    if ($name === '') {
        $name = 'attachment';
    }
    $extension = pathinfo($name, PATHINFO_EXTENSION);
    if ($extension !== '') {
        $extension = preg_replace('/[^A-Za-z0-9]/', '', $extension);
    }
    $organization = docs_sanitize_file_component($record['organization'] ?? '', 'organization');
    $registryNumber = docs_sanitize_file_component($record['registryNumber'] ?? '', 'registry');
    $dateTimeComponent = docs_build_registration_datetime_component($record, $sequence);
    $components = array_filter([$organization, $registryNumber, $dateTimeComponent], static function ($item): bool {
        return $item !== '';
    });
    if (empty($components)) {
        $components[] = 'document';
    }
    $safe = implode('.', $components);
    if ($extension !== '') {
        $safe .= '.' . $extension;
    }
    return $safe;
}
function build_public_path(string $folder, ?string $fileName = null): string
{
    $parts = [$folder];
    if ($fileName !== null && $fileName !== '') {
        $pathSegments = preg_split('#/+#', str_replace('\\', '/', $fileName), -1, PREG_SPLIT_NO_EMPTY);
        if (is_array($pathSegments) && !empty($pathSegments)) {
            foreach ($pathSegments as $pathSegment) {
                $parts[] = $pathSegment;
            }
        }
    }
    $encodedParts = array_map(static function (string $part): string {
        return rawurlencode($part);
    }, $parts);
    return 'documents/' . implode('/', $encodedParts);
}
function docs_resolve_public_document_file(string $rawPath): ?array
{
    $rawPath = trim($rawPath);
    if ($rawPath === '') {
        return null;
    }
    $path = parse_url($rawPath, PHP_URL_PATH);
    if (!is_string($path) || $path === '') {
        $path = $rawPath;
    }
    $path = ltrim($path, "/\\");
    if (stripos($path, 'documents/') !== 0) {
        return null;
    }
    $relative = substr($path, strlen('documents/'));
    if (!is_string($relative) || trim($relative) === '') {
        return null;
    }
    $relative = rawurldecode(str_replace('\\', '/', $relative));
    $segments = preg_split('#/+#', $relative, -1, PREG_SPLIT_NO_EMPTY);
    if (!is_array($segments) || empty($segments)) {
        return null;
    }
    $safeSegments = [];
    foreach ($segments as $segment) {
        $decoded = (string) $segment;
        if ($decoded === '' || $decoded === '.' || $decoded === '..') {
            return null;
        }
        if (strpos($decoded, "\0") !== false || strpos($decoded, '/') !== false || strpos($decoded, '\\') !== false) {
            return null;
        }
        $safeSegments[] = $decoded;
    }
    $root = realpath(DOCUMENTS_ROOT);
    if (!is_string($root) || $root === '') {
        return null;
    }
    $filePath = $root . DIRECTORY_SEPARATOR . implode(DIRECTORY_SEPARATOR, $safeSegments);
    $realPath = realpath($filePath);
    if (!is_string($realPath) || !is_file($realPath) || !is_readable($realPath)) {
        return null;
    }
    $rootPrefix = rtrim($root, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;
    if (strpos($realPath, $rootPrefix) !== 0) {
        return null;
    }
    return [
        'path' => $realPath,
        'name' => basename($realPath),
        'folder' => (string) ($safeSegments[0] ?? ''),
    ];
}
function docs_build_short_download_reference(string $publicPath): string
{
    $path = parse_url($publicPath, PHP_URL_PATH);
    if (!is_string($path) || $path === '') {
        $path = $publicPath;
    }
    $path = ltrim(str_replace('\\', '/', trim($path)), '/');
    if (stripos($path, 'documents/') !== 0) {
        return '';
    }
    $binary = pack(
        'N2',
        hexdec(hash('crc32b', $path)),
        hexdec(hash('crc32b', 'docs-share-v1:' . $path))
    );
    return rtrim(strtr(base64_encode($binary), '+/', '-_'), '=');
}
function docs_find_public_document_path_by_short_reference(string $reference): ?string
{
    $reference = trim($reference);
    if (preg_match('/^[A-Za-z0-9_-]{11}$/', $reference) !== 1) {
        return null;
    }
    $matchedPath = null;
    $matchPath = static function (string $candidatePath) use ($reference, &$matchedPath): bool {
        if (docs_build_short_download_reference($candidatePath) !== $reference) {
            return false;
        }
        if ($matchedPath !== null && !hash_equals($matchedPath, $candidatePath)) {
            $matchedPath = '';
            return true;
        }
        $matchedPath = $candidatePath;
        return false;
    };
    foreach (load_organizations() as $organization) {
        if (!is_string($organization) || trim($organization) === '') {
            continue;
        }
        $folder = sanitize_folder_name($organization);
        foreach (load_registry($folder) as $record) {
            if (!is_array($record)) {
                continue;
            }
            foreach (($record['files'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                foreach (docs_file_public_relative_candidates($folder, $file) as $relativePath) {
                    if ($matchPath(build_public_path($folder, $relativePath))) {
                        return null;
                    }
                }
            }
            $documentId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
            foreach (($record['responses'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                $fallback = $documentId !== '' && $storedName !== ''
                    ? 'Ответы/' . $documentId . '/' . $storedName
                    : '';
                foreach (docs_file_public_relative_candidates($folder, $file, $fallback) as $relativePath) {
                    if ($matchPath(build_public_path($folder, $relativePath))) {
                        return null;
                    }
                }
            }
        }
        foreach (docs_load_outgoing_registry($folder) as $record) {
            if (!is_array($record)) {
                continue;
            }
            foreach (($record['files'] ?? []) as $file) {
                if (!is_array($file)) {
                    continue;
                }
                foreach (docs_file_public_relative_candidates($folder, $file) as $relativePath) {
                    if ($matchPath(build_public_path($folder, $relativePath))) {
                        return null;
                    }
                }
            }
        }
        foreach (['orders', 'directives', 'disciplinary'] as $journalType) {
            $meta = docs_get_orders_journal_meta($journalType);
            foreach (docs_load_orders_registry($folder, $journalType) as $record) {
                if (!is_array($record)) {
                    continue;
                }
                foreach (($record['files'] ?? []) as $file) {
                    if (!is_array($file)) {
                        continue;
                    }
                    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                    $fallback = $storedName !== '' ? $meta['directory'] . '/' . $storedName : '';
                    foreach (docs_file_public_relative_candidates($folder, $file, $fallback) as $relativePath) {
                        if ($matchPath(build_public_path($folder, $relativePath))) {
                            return null;
                        }
                    }
                }
            }
        }
    }
    return $matchedPath !== null && $matchedPath !== '' ? $matchedPath : null;
}
function docs_build_content_disposition_header(string $disposition, string $fileName): string
{
    $disposition = strtolower(trim($disposition)) === 'inline' ? 'inline' : 'attachment';
    $fileName = docs_sanitize_filename($fileName, 'document');
    $asciiName = preg_replace('/[^A-Za-z0-9._-]+/', '_', $fileName);
    $asciiName = is_string($asciiName) ? trim($asciiName, '._-') : '';
    if ($asciiName === '') {
        $extension = pathinfo($fileName, PATHINFO_EXTENSION);
        $asciiName = $extension !== '' ? 'document.' . $extension : 'document';
    }
    return $disposition
        . '; filename="' . addcslashes($asciiName, "\\\"") . '"'
        . "; filename*=UTF-8''" . rawurlencode($fileName);
}
function docs_detect_mime_type_by_extension(string $path): string
{
    $extension = strtolower((string) pathinfo($path, PATHINFO_EXTENSION));
    if ($extension === '') {
        return '';
    }
    $map = [
        'doc' => 'application/msword',
        'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'dot' => 'application/msword',
        'dotx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.template',
        'rtf' => 'application/rtf',
        'odt' => 'application/vnd.oasis.opendocument.text',
        'xls' => 'application/vnd.ms-excel',
        'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'ods' => 'application/vnd.oasis.opendocument.spreadsheet',
        'ppt' => 'application/vnd.ms-powerpoint',
        'pptx' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
        'odp' => 'application/vnd.oasis.opendocument.presentation',
    ];
    return $map[$extension] ?? '';
}
function docs_detect_download_mime_type(string $path, string $fileName = ''): string
{
    $extensionMime = docs_detect_mime_type_by_extension($path);
    if ($extensionMime !== '') {
        return $extensionMime;
    }
    $detectedMime = '';
    if (function_exists('finfo_open')) {
        $finfo = @finfo_open(FILEINFO_MIME_TYPE);
        if ($finfo) {
            $mime = @finfo_file($finfo, $path);
            @finfo_close($finfo);
            if (is_string($mime) && $mime !== '') {
                $detectedMime = strtolower(trim($mime));
            }
        }
    }
    if ($detectedMime === '' && function_exists('mime_content_type')) {
        $mime = @mime_content_type($path);
        if (is_string($mime) && $mime !== '') {
            $detectedMime = strtolower(trim($mime));
        }
    }
    $genericArchiveMimes = [
        'application/octet-stream',
        'application/zip',
        'application/x-zip',
        'application/x-zip-compressed',
        'application/x-ole-storage',
        'application/vnd.ms-office',
        'application/cdfv2',
    ];
    if ($detectedMime !== '' && !in_array($detectedMime, $genericArchiveMimes, true)) {
        return $detectedMime;
    }
    // S3-файл сначала попадает во временный docs_s3_* без расширения. Для ZIP-контейнеров
    // Office уточняем MIME по исходному имени, которое уже прошло серверную санацию.
    $fileNameMime = docs_detect_mime_type_by_extension($fileName);
    if ($fileNameMime !== '') {
        return $fileNameMime;
    }
    return $detectedMime !== '' ? $detectedMime : 'application/octet-stream';
}
function docs_stream_file_response(
    string $path,
    string $fileName,
    string $disposition,
    string $method,
    string $mimeFileName = ''
): void
{
    clearstatcache(true, $path);
    $size = @filesize($path);
    if ($size === false || $size < 0) {
        respond_error('Файл недоступен.', 404);
    }
    $fileSize = (int) $size;
    $modifiedAt = @filemtime($path);
    $modifiedAt = $modifiedAt !== false ? (int) $modifiedAt : 0;
    $normalizedDisposition = strtolower(trim($disposition)) === 'inline' ? 'inline' : 'attachment';
    $etagOpaque = $modifiedAt > 0 ? $modifiedAt . '-' . $fileSize : '';
    $etag = $etagOpaque !== '' ? 'W/"' . $etagOpaque . '"' : '';
    $start = 0;
    $end = max(0, $fileSize - 1);
    $status = 200;
    $range = isset($_SERVER['HTTP_RANGE']) ? trim((string) $_SERVER['HTTP_RANGE']) : '';
    $ifRange = isset($_SERVER['HTTP_IF_RANGE']) ? trim((string) $_SERVER['HTTP_IF_RANGE']) : '';
    if ($range !== '' && $ifRange !== '') {
        // Слабый ETag нельзя подтверждать через If-Range. Принимаем только дату,
        // которая доказывает, что локальная копия не менялась.
        $ifRangeTimestamp = strtotime($ifRange);
        if ($ifRangeTimestamp === false || $modifiedAt < 1 || $modifiedAt > $ifRangeTimestamp) {
            $range = '';
        }
    }
    if ($normalizedDisposition === 'inline' && $etag !== '') {
        $ifNoneMatch = isset($_SERVER['HTTP_IF_NONE_MATCH'])
            ? trim((string) $_SERVER['HTTP_IF_NONE_MATCH'])
            : '';
        $notModified = false;
        if ($ifNoneMatch !== '') {
            $etagCandidates = preg_split('/\s*,\s*/', $ifNoneMatch) ?: [];
            $notModified = in_array('*', $etagCandidates, true);
            foreach ($etagCandidates as $etagCandidate) {
                $candidateOpaque = preg_replace('/^W\//i', '', trim((string) $etagCandidate));
                if ($candidateOpaque === '"' . $etagOpaque . '"') {
                    $notModified = true;
                    break;
                }
            }
        } elseif (isset($_SERVER['HTTP_IF_MODIFIED_SINCE'])) {
            $ifModifiedSince = strtotime((string) $_SERVER['HTTP_IF_MODIFIED_SINCE']);
            $notModified = $ifModifiedSince !== false && $modifiedAt <= $ifModifiedSince;
        }
        if ($notModified) {
            http_response_code(304);
            header_remove('Content-Type');
            header_remove('Content-Length');
            header_remove('Pragma');
            header('ETag: ' . $etag);
            header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $modifiedAt) . ' GMT');
            header('Cache-Control: private, max-age=300, must-revalidate', true);
            header('Expires: ' . gmdate('D, d M Y H:i:s', time() + 300) . ' GMT', true);
            header('Accept-Ranges: bytes');
            exit;
        }
    }
    if ($range !== '' && preg_match('/^bytes=(\d*)-(\d*)$/', $range, $matches)) {
        if ($fileSize === 0) {
            http_response_code(416);
            header('Content-Range: bytes */0');
            exit;
        }
        $rangeStart = $matches[1] !== '' ? (int) $matches[1] : null;
        $rangeEnd = $matches[2] !== '' ? (int) $matches[2] : null;
        if ($rangeStart === null && $rangeEnd !== null) {
            $start = max(0, $fileSize - $rangeEnd);
        } elseif ($rangeStart !== null) {
            $start = $rangeStart;
        }
        if ($rangeEnd !== null && $rangeStart !== null) {
            $end = min($end, $rangeEnd);
        }
        if ($start > $end || $start >= $fileSize) {
            http_response_code(416);
            header('Content-Range: bytes */' . $fileSize);
            exit;
        }
        $status = 206;
    }
    $length = $fileSize === 0 ? 0 : $end - $start + 1;
    $mime = docs_detect_download_mime_type($path, $mimeFileName !== '' ? $mimeFileName : $fileName);
    http_response_code($status);
    header_remove('Content-Type');
    header_remove('Pragma');
    header('Content-Type: ' . $mime);
    header('X-Content-Type-Options: nosniff');
    header('Content-Disposition: ' . docs_build_content_disposition_header($disposition, $fileName));
    header('Content-Length: ' . $length);
    header('Accept-Ranges: bytes');
    if ($normalizedDisposition === 'attachment') {
        header('Cache-Control: private, no-store, no-cache, must-revalidate', true);
        header('Pragma: no-cache', true);
        header('Expires: 0', true);
    } else {
        header('Cache-Control: private, max-age=300, must-revalidate', true);
        header('Expires: ' . gmdate('D, d M Y H:i:s', time() + 300) . ' GMT', true);
        if ($etag !== '') {
            header('ETag: ' . $etag);
            header('Last-Modified: ' . gmdate('D, d M Y H:i:s', $modifiedAt) . ' GMT');
        }
    }
    if ($status === 206) {
        header('Content-Range: bytes ' . $start . '-' . $end . '/' . $fileSize);
    }
    if (strtoupper($method) === 'HEAD') {
        exit;
    }
    while (ob_get_level() > 0) {
        @ob_end_clean();
    }
    $handle = @fopen($path, 'rb');
    if ($handle === false) {
        exit;
    }
    if ($start > 0) {
        @fseek($handle, $start);
    }
    $remaining = $length;
    while ($remaining > 0 && !feof($handle)) {
        $chunkSize = min(DOCS_FILE_STREAM_CHUNK_BYTES, $remaining);
        $buffer = fread($handle, $chunkSize);
        if ($buffer === false || $buffer === '') {
            break;
        }
        echo $buffer;
        $remaining -= strlen($buffer);
        flush();
    }
    fclose($handle);
    exit;
}
function docs_handle_archived_attachment(string $method): void
{
    $method = strtoupper($method);
    if ($method !== 'GET' && $method !== 'HEAD') {
        respond_error('Некорректный метод запроса.', 405, ['allowedMethod' => 'GET']);
    }
    respond_error('ZIP-архивация вложений отключена.', 410, ['reason' => 'zip_archive_disabled']);
}
function docs_handle_mini_app_download_file(string $method): void
{
    $method = strtoupper($method);
    if ($method !== 'GET' && $method !== 'HEAD') {
        respond_error('Некорректный метод запроса.', 405, ['allowedMethod' => 'GET']);
    }
    $rawPath = isset($_GET['path']) && is_string($_GET['path']) ? $_GET['path'] : '';
    if ($rawPath === '' && isset($_GET['f']) && is_string($_GET['f'])) {
        $rawPath = docs_find_public_document_path_by_short_reference($_GET['f']) ?? '';
    }
    if ($rawPath === '' && isset($_GET['r']) && is_string($_GET['r'])) {
        $compactPath = trim($_GET['r']);
        if ($compactPath !== '' && preg_match('/^[A-Za-z0-9_-]+$/', $compactPath)) {
            $base64Path = strtr($compactPath, '-_', '+/');
            $base64Path .= str_repeat('=', (4 - strlen($base64Path) % 4) % 4);
            $decodedPath = base64_decode($base64Path, true);
            if (is_string($decodedPath)) {
                $rawPath = $decodedPath;
            }
        }
    }
    if ($rawPath === '' && isset($_GET['file']) && is_string($_GET['file'])) {
        $rawPath = $_GET['file'];
    }
    $resolved = docs_resolve_public_document_file($rawPath);
    if ($resolved === null) {
        $coldMatch = docs_find_cold_storage_file_by_public_path($rawPath);
        if ($coldMatch === null || !isset($coldMatch['file']) || !is_array($coldMatch['file'])) {
            respond_error('Файл не найден.', 404);
        }
        if (docs_is_outgoing_file_private($coldMatch['file'])) {
            respond_error('Доступ к приватному файлу запрещён.', 403, [
                'reason' => 'outgoing_private_file_forbidden',
            ]);
        }
        $fileName = isset($_GET['name']) && is_string($_GET['name'])
            ? sanitize_text_field($_GET['name'], 255)
            : '';
        if ($fileName === '') {
            $fileName = sanitize_text_field(
                (string) ($coldMatch['file']['originalName'] ?? ($coldMatch['file']['storedName'] ?? 'document')),
                255
            );
        }
        $disposition = isset($_GET['disposition']) && is_string($_GET['disposition'])
            ? $_GET['disposition']
            : 'attachment';
        $resolvedPath = docs_resolve_file_path_with_cold_storage(
            sanitize_folder_name((string) ($coldMatch['folder'] ?? '')),
            $coldMatch['file'],
            isset($coldMatch['paths']) && is_array($coldMatch['paths']) ? $coldMatch['paths'] : []
        );
        if ($resolvedPath === '') {
            respond_error('Файл не найден.', 404);
        }
        $mimeFileName = sanitize_text_field(
            (string) ($coldMatch['file']['originalName'] ?? ($coldMatch['file']['storedName'] ?? 'document')),
            255
        );
        docs_stream_file_response(
            $resolvedPath,
            $fileName !== '' ? $fileName : 'document',
            $disposition,
            $method,
            $mimeFileName
        );
    }
    $resolvedFolder = sanitize_folder_name((string) ($resolved['folder'] ?? ''));
    $privateOutgoingMatch = $resolvedFolder !== ''
        ? docs_find_private_outgoing_file_by_real_path($resolvedFolder, (string) $resolved['path'])
        : null;
    if (is_array($privateOutgoingMatch) && isset($privateOutgoingMatch['file']) && is_array($privateOutgoingMatch['file'])) {
        $accessContext = docs_resolve_access_context($resolvedFolder);
        $sessionAuth = docs_get_session_auth();
        $requestContext = docs_build_request_user_context();
        $currentUserKeys = docs_resolve_outgoing_private_user_keys($requestContext, is_array($sessionAuth) ? $sessionAuth : null);
        $canManageOutgoing = docs_user_can_manage_outgoing_records($accessContext, is_array($sessionAuth) ? $sessionAuth : null);
        $privateOutgoingRecord = isset($privateOutgoingMatch['record']) && is_array($privateOutgoingMatch['record'])
            ? $privateOutgoingMatch['record']
            : [];
        $hasInheritedOwner = docs_outgoing_file_has_inherited_private_owner($privateOutgoingMatch['file'], $privateOutgoingRecord);
        if (($hasInheritedOwner && !$canManageOutgoing) || !docs_outgoing_file_user_can_access($privateOutgoingMatch['file'], $canManageOutgoing, $currentUserKeys)) {
            respond_error('Доступ к приватному файлу запрещён.', 403, [
                'reason' => 'outgoing_private_file_forbidden',
            ]);
        }
    }
    $fileName = isset($_GET['name']) && is_string($_GET['name'])
        ? sanitize_text_field($_GET['name'], 255)
        : '';
    if ($fileName === '') {
        $fileName = (string) $resolved['name'];
    }
    $disposition = isset($_GET['disposition']) && is_string($_GET['disposition'])
        ? $_GET['disposition']
        : 'attachment';
    docs_stream_file_response(
        (string) $resolved['path'],
        $fileName,
        $disposition,
        $method,
        (string) ($resolved['name'] ?? $fileName)
    );
}
function load_organizations(): array
{
    $names = [];
    if (is_dir(DOCUMENTS_ROOT)) {
        $dir = opendir(DOCUMENTS_ROOT);
        if ($dir) {
            while (($entry = readdir($dir)) !== false) {
                if ($entry === '.' || $entry === '..') {
                    continue;
                }
                $entry = trim((string) $entry);
                if ($entry === '') {
                    continue;
                }
                $names[$entry] = true;
            }
            closedir($dir);
        }
    }
    $list = array_keys($names);
    sort($list, SORT_NATURAL | SORT_FLAG_CASE);
    return $list;
}
function docs_extract_identity_filter(string $identity): ?array
{
    $identity = trim($identity);
    if ($identity === '') {
        return null;
    }
    $source = [];
    if (preg_match('/telegram:(\d+)/i', $identity, $matches)) {
        $source['telegram_user_id'] = $matches[1];
    }
    if (preg_match('/@([A-Za-z0-9_]+)/', $identity, $matches)) {
        $source['telegram_username'] = $matches[1];
    }
    if (empty($source)) {
        return null;
    }
    return extract_assignee_filter_from_array($source);
}
function docs_collect_request_sources(): array
{
    $sources = [];
    $telegramContext = docs_resolve_telegram_init_data_context();
    if (isset($telegramContext['source']) && is_array($telegramContext['source']) && !empty($telegramContext['source'])) {
        $sources[] = $telegramContext['source'];
    }
    if (!empty($_GET) && is_array($_GET)) {
        $sources[] = $_GET;
    }
    if (!empty($_POST) && is_array($_POST)) {
        $sources[] = $_POST;
    }
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
        $jsonPayload = load_json_payload();
        if (!empty($jsonPayload) && is_array($jsonPayload)) {
            $sources[] = $jsonPayload;
        }
    }
    return $sources;
}
function docs_first_non_empty_string(array $sources, array $keys): string
{
    foreach ($keys as $key) {
        foreach ($sources as $source) {
            if (!is_array($source) || !array_key_exists($key, $source)) {
                continue;
            }
            $value = $source[$key];
            if (!is_string($value) && !is_numeric($value)) {
                continue;
            }
            $stringValue = trim((string) $value);
            if ($stringValue === '') {
                continue;
            }
            return $stringValue;
        }
    }
    return '';
}
function docs_load_mini_app_settings_for_request(string $folder): array
{
    static $settingsCache = [];
    if (!array_key_exists($folder, $settingsCache)) {
        $settingsCache[$folder] = load_admin_settings($folder);
    }
    return $settingsCache[$folder];
}
function docs_build_mini_app_impersonation_directory(string $actorTelegramId, ?array $sessionAuth = null): array
{
    $actorTelegramId = normalize_identifier_value($actorTelegramId);
    $result = [
        'allowed' => false,
        'actorTelegramId' => $actorTelegramId,
        'organizations' => [],
        'users' => [],
    ];
    if ($actorTelegramId === '') {
        return $result;
    }
    $allOrganizations = load_organizations();
    $sessionRole = is_array($sessionAuth)
        ? strtolower((string) ($sessionAuth['role'] ?? ''))
        : '';
    $sessionScope = is_array($sessionAuth)
        ? strtolower(sanitize_text_field((string) ($sessionAuth['adminScope'] ?? ''), 60))
        : '';
    $sessionOrganization = is_array($sessionAuth)
        ? docs_normalize_organization_candidate((string) ($sessionAuth['organization'] ?? ''))
        : '';
    $sessionAllowsAll = $sessionRole === 'admin'
        && in_array($sessionScope, ['global', 'mainadmin'], true);
    $actorFilter = [
        'ids' => [$actorTelegramId],
        'username' => '',
        'fullName' => '',
        'nameTokens' => [],
    ];
    $allowedOrganizations = [];
    $settingsByOrganization = [];
    foreach ($allOrganizations as $organization) {
        if (!is_string($organization) || $organization === '') {
            continue;
        }
        $folder = sanitize_folder_name($organization);
        $settings = docs_load_mini_app_settings_for_request($folder);
        $settingsByOrganization[$organization] = $settings;
        $directors = isset($settings['block2']) && is_array($settings['block2'])
            ? $settings['block2']
            : [];
        $allowedBySession = $sessionAllowsAll
            || ($sessionRole === 'admin'
                && $sessionOrganization !== ''
                && $sessionOrganization === $organization);
        $allowedByTelegramDirectory = false;
        foreach ($directors as $director) {
            if (is_array($director) && docs_director_participant_matches_filter($director, $actorFilter)) {
                $allowedByTelegramDirectory = true;
                break;
            }
        }
        if ($allowedBySession || $allowedByTelegramDirectory) {
            $allowedOrganizations[] = $organization;
        }
    }
    if (empty($allowedOrganizations)) {
        return $result;
    }
    $usersByTelegramId = [];
    $appendUser = static function ($entry, string $organization, string $directoryRole) use (&$usersByTelegramId): void {
        if (!is_array($entry)) {
            return;
        }
        $telegramId = '';
        foreach (['telegram', 'telegramId', 'telegram_id', 'chatId', 'chat_id'] as $field) {
            $telegramId = normalize_identifier_value($entry[$field] ?? '');
            if ($telegramId !== '') {
                break;
            }
        }
        if ($telegramId === '') {
            return;
        }
        $fullName = '';
        foreach (['responsible', 'name', 'fio', 'fullName', 'displayName'] as $field) {
            $fullName = sanitize_text_field((string) ($entry[$field] ?? ''), 200);
            if ($fullName !== '') {
                break;
            }
        }
        if ($fullName === '') {
            $fullName = 'Telegram ID ' . $telegramId;
        }
        $userId = '';
        foreach (['userId', 'user_id', 'id', 'number', 'responsibleNumber', 'responsible_number', 'login'] as $field) {
            $userId = sanitize_text_field((string) ($entry[$field] ?? ''), 120);
            if ($userId !== '') {
                break;
            }
        }
        $username = normalize_username_value(
            $entry['username'] ?? ($entry['telegramUsername'] ?? ($entry['telegram_username'] ?? ''))
        );
        $position = sanitize_text_field((string) ($entry['position'] ?? ''), 160);
        $role = sanitize_text_field((string) ($entry['role'] ?? ''), 80);
        if ($role === '') {
            $role = $directoryRole;
        }
        if (!isset($usersByTelegramId[$telegramId])) {
            $usersByTelegramId[$telegramId] = [
                'telegramId' => $telegramId,
                'userId' => $userId,
                'username' => $username,
                'fullName' => $fullName,
                'position' => $position,
                'role' => $role,
                'organizations' => [],
            ];
        } else {
            $candidateValues = [
                'userId' => $userId,
                'username' => $username,
                'fullName' => $fullName,
                'position' => $position,
                'role' => $role,
            ];
            foreach (['userId', 'username', 'fullName', 'position', 'role'] as $field) {
                if (($usersByTelegramId[$telegramId][$field] ?? '') === '' && $candidateValues[$field] !== '') {
                    $usersByTelegramId[$telegramId][$field] = $candidateValues[$field];
                }
            }
        }
        if (!in_array($organization, $usersByTelegramId[$telegramId]['organizations'], true)) {
            $usersByTelegramId[$telegramId]['organizations'][] = $organization;
        }
    };
    foreach ($allowedOrganizations as $organization) {
        $settings = $settingsByOrganization[$organization] ?? [];
        $groups = [
            'responsible' => isset($settings['responsibles']) && is_array($settings['responsibles'])
                ? $settings['responsibles']
                : [],
            'director' => isset($settings['block2']) && is_array($settings['block2'])
                ? $settings['block2']
                : [],
            'subordinate' => isset($settings['block3']) && is_array($settings['block3'])
                ? $settings['block3']
                : [],
        ];
        foreach ($groups as $directoryRole => $entries) {
            foreach ($entries as $entry) {
                $appendUser($entry, $organization, $directoryRole);
            }
        }
    }
    $users = array_values($usersByTelegramId);
    usort($users, static function (array $left, array $right): int {
        $leftName = mb_strtolower((string) ($left['fullName'] ?? ''), 'UTF-8');
        $rightName = mb_strtolower((string) ($right['fullName'] ?? ''), 'UTF-8');
        $nameCompare = strnatcasecmp($leftName, $rightName);
        if ($nameCompare !== 0) {
            return $nameCompare;
        }
        return strnatcasecmp((string) ($left['telegramId'] ?? ''), (string) ($right['telegramId'] ?? ''));
    });
    $result['allowed'] = true;
    $result['organizations'] = array_values($allowedOrganizations);
    $result['users'] = $users;
    return $result;
}
function docs_resolve_mini_app_impersonation_context(
    string $requestedTelegramId,
    array $telegramInitData,
    bool $includeDirectory = false
): array {
    $requestedTelegramId = normalize_identifier_value($requestedTelegramId);
    $actorTelegramId = '';
    if (!empty($telegramInitData['valid'])) {
        $actorTelegramId = normalize_identifier_value(
            $telegramInitData['source']['telegram_user_id']
                ?? ($telegramInitData['user']['id'] ?? '')
        );
    }
    $result = [
        'allowed' => false,
        'active' => false,
        'actorTelegramId' => $actorTelegramId,
        'targetTelegramId' => '',
        'target' => null,
        'organizations' => [],
        'users' => [],
    ];
    if ($actorTelegramId === '') {
        if ($requestedTelegramId !== '') {
            respond_error('Тестовый вход доступен только внутри авторизованного Telegram Mini App.', 401, [
                'requiresTelegramReauth' => true,
            ]);
        }
        return $result;
    }
    $directory = docs_build_mini_app_impersonation_directory($actorTelegramId, docs_get_session_auth());
    $result['allowed'] = !empty($directory['allowed']);
    $result['organizations'] = isset($directory['organizations']) && is_array($directory['organizations'])
        ? $directory['organizations']
        : [];
    if ($includeDirectory && $result['allowed']) {
        $result['users'] = isset($directory['users']) && is_array($directory['users'])
            ? $directory['users']
            : [];
    }
    if ($requestedTelegramId === '' || hash_equals($actorTelegramId, $requestedTelegramId)) {
        return $result;
    }
    if (!$result['allowed']) {
        respond_error('Тестовый вход от лица другого пользователя доступен только администратору.', 403, [
            'requiresAdmin' => true,
        ]);
    }
    $target = null;
    foreach ((array) ($directory['users'] ?? []) as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $candidateId = normalize_identifier_value($entry['telegramId'] ?? '');
        if ($candidateId !== '' && hash_equals($candidateId, $requestedTelegramId)) {
            $target = $entry;
            break;
        }
    }
    if (!is_array($target)) {
        respond_error('Выбранный пользователь недоступен для тестового входа.', 403, [
            'requiresAdmin' => true,
        ]);
    }
    $result['active'] = true;
    $result['targetTelegramId'] = $requestedTelegramId;
    $result['target'] = $target;
    log_docs_event('Mini app administrator impersonation authorized', [
        'actorTelegramId' => $actorTelegramId,
        'targetTelegramId' => $requestedTelegramId,
        'organizations' => $target['organizations'] ?? [],
        'action' => docs_current_action(),
    ]);
    return $result;
}
function docs_build_request_user_context(): array
{
    static $cached = null;
    if ($cached !== null) {
        return $cached;
    }
    $telegramInitData = docs_resolve_telegram_init_data_context();
    $sources = docs_collect_request_sources();
    $requestedImpersonationId = docs_first_non_empty_string($sources, [
        'impersonate_user_id',
        'impersonateUserId',
        'impersonated_telegram_user_id',
    ]);
    $shouldResolveImpersonation = $requestedImpersonationId !== ''
        || docs_current_action() === 'mini_app_tasks';
    $impersonation = [
        'allowed' => false,
        'active' => false,
        'actorTelegramId' => '',
        'targetTelegramId' => '',
        'target' => null,
        'organizations' => [],
        'users' => [],
    ];
    if ($shouldResolveImpersonation) {
        $impersonation = docs_resolve_mini_app_impersonation_context(
            $requestedImpersonationId,
            $telegramInitData,
            docs_current_action() === 'mini_app_tasks'
        );
    }
    if (!empty($impersonation['active']) && is_array($impersonation['target'] ?? null)) {
        $target = $impersonation['target'];
        $targetSource = [
            'telegram_user_id' => (string) ($target['telegramId'] ?? ''),
            'telegram_username' => (string) ($target['username'] ?? ''),
            'telegram_full_name' => (string) ($target['fullName'] ?? ''),
            'user_key' => (string) ($target['userId'] ?? ''),
        ];
        array_unshift($sources, array_filter($targetSource, static function ($value) {
            return $value !== '';
        }));
    }
    $identity = docs_first_non_empty_string($sources, ['identity', 'user_identity']);
    $rawData = [
        'telegram_user_id' => docs_first_non_empty_string($sources, ['telegram_user_id', 'telegramId', 'user_id', 'userid', 'id']),
        'telegram_chat_id' => docs_first_non_empty_string($sources, ['telegram_chat_id', 'chat_id', 'chatId']),
        'telegram_username' => docs_first_non_empty_string($sources, ['telegram_username', 'username', 'user_name']),
        'telegram_full_name' => docs_first_non_empty_string($sources, ['telegram_full_name', 'full_name', 'name']),
        'user_key' => docs_first_non_empty_string($sources, ['user_key', 'userKey', 'settings_user_key']),
    ];
    $filter = null;
    $filterSource = 'none';
    $identityUsed = false;
    $normalizedTelegramId = normalize_identifier_value($rawData['telegram_user_id']);
    if ($normalizedTelegramId !== '') {
        $filter = [
            'ids' => [$normalizedTelegramId],
            'username' => '',
            'nameTokens' => [],
            'fullName' => '',
        ];
        $filterSource = 'telegram_user_id';
    } else {
        $filterFromTelegram = extract_assignee_filter_from_array($rawData);
        if ($filterFromTelegram !== null) {
            $filter = $filterFromTelegram;
            $filterSource = 'telegram_payload';
        }
    }
    if ($filter === null && $identity !== '') {
        $filter = docs_extract_identity_filter($identity);
        if ($filter !== null) {
