            'id' => (string) ($user['id'] ?? ''),
            'username' => (string) ($user['username'] ?? ''),
            'firstName' => (string) ($user['firstName'] ?? ''),
            'lastName' => (string) ($user['lastName'] ?? ''),
            'fullName' => (string) ($user['fullName'] ?? ''),
