            || docs_truthy_value($payload['dry_run'] ?? false)
            || docs_truthy_value($_GET['dryRun'] ?? false)
            || docs_truthy_value($_GET['dry_run'] ?? false);
        respond_success([
            'digest' => docs_send_overdue_digest($dryRun),
