                ]);
            }
            $rawInstruction = isset($payload['instruction']) ? (string) $payload['instruction'] : '';
            $normalizedInstruction = sanitize_instruction($rawInstruction);
            $records[$recordIndex]['instruction'] = $normalizedInstruction;
            if ($normalizedInstruction === '') {
                $message = 'Поручение удалено.';
            } else {
                $message = 'Поручение обновлено.';
            }
        } elseif ($updateType === 'folder') {
            $rawFolderId = isset($payload['folderId']) ? (string) $payload['folderId'] : '';
            $normalizedFolderId = sanitize_text_field($rawFolderId, 120);
            $folderUserIdRaw = isset($payload['folderUserId']) ? (string) $payload['folderUserId'] : '';
            $folderUserId = sanitize_text_field($folderUserIdRaw, 200);
            if ($folderUserId === '' && isset($requestContext['primaryId'])) {
                $folderUserId = sanitize_text_field((string) $requestContext['primaryId'], 200);
            }
            if ($folderUserId === '') {
                respond_error('Не удалось определить пользователя для папки.', 400);
            }
            if (!isset($records[$recordIndex]['folderByUser']) || !is_array($records[$recordIndex]['folderByUser'])) {
                $records[$recordIndex]['folderByUser'] = [];
            }
            if ($normalizedFolderId === '') {
                unset($records[$recordIndex]['folderByUser'][$folderUserId]);
            } else {
                $records[$recordIndex]['folderByUser'][$folderUserId] = $normalizedFolderId;
            }
            $message = 'Папка задачи обновлена.';
        } elseif ($updateType === 'folder_state') {
            $folderUserIdRaw = isset($payload['folderUserId']) ? (string) $payload['folderUserId'] : '';
            $folderUserId = sanitize_text_field($folderUserIdRaw, 200);
            if ($folderUserId === '' && isset($requestContext['primaryId'])) {
                $folderUserId = sanitize_text_field((string) $requestContext['primaryId'], 200);
            }
            if ($folderUserId === '') {
                respond_error('Не удалось определить пользователя для сохранения папок.', 400);
            }
            $rawFolderState = isset($payload['folderState']) && is_array($payload['folderState'])
                ? $payload['folderState']
                : [];
            $sanitizedFolderState = [];
            foreach ($rawFolderState as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $folderId = sanitize_text_field((string) ($entry['id'] ?? ''), 120);
                $folderName = sanitize_text_field((string) ($entry['name'] ?? ''), 120);
                $folderColor = strtolower(trim((string) ($entry['color'] ?? '#4d91ff')));
                if (!preg_match('/^#[0-9a-f]{6}$/', $folderColor)) {
                    $folderColor = '#4d91ff';
                }
                if ($folderId === '' || $folderName === '') {
                    continue;
                }
                $sanitizedFolderState[] = [
                    'id' => $folderId,
                    'name' => $folderName,
                    'color' => $folderColor,
                ];
            }
            if (!isset($records[$recordIndex]['folderSettingsByUser']) || !is_array($records[$recordIndex]['folderSettingsByUser'])) {
                $records[$recordIndex]['folderSettingsByUser'] = [];
            }
            $records[$recordIndex]['folderSettingsByUser'][$folderUserId] = $sanitizedFolderState;
            $message = 'Список папок сохранён.';
        } else {
            respond_error('Неизвестный тип обновления.', 400, [
                'updateType' => $updateType,
            ]);
        }
        if ($originalDirector !== null) {
            $records[$recordIndex]['director'] = $originalDirector;
        }
        if ($originalDirectors !== null) {
            $records[$recordIndex]['directors'] = $originalDirectors;
        }
        $updatedTaskParticipation = docs_collect_record_telegram_participation(
            $records[$recordIndex],
            $folder,
            $participantDirectoryEntries
        );
        $records[$recordIndex]['updatedAt'] = date('c');
        if ($registryHandle !== null) {
            try {
                docs_save_registry_locked($registryHandle, $records);
            } finally {
                docs_unlock_registry($registryHandle);
            }
        } else {
            save_registry($folder, $records);
        }
        docs_log_file_debug('Mini app update task saved', [
            'clientRequestId' => $clientRequestId !== '' ? $clientRequestId : null,
            'organization' => $organizationCandidate,
            'documentId' => $documentId,
            'updateType' => $updateType,
            'durationMs' => (int) round((microtime(true) - $requestStartedAt) * 1000),
        ]);
        $preparedRecords = docs_prepare_records_for_response([$records[$recordIndex]], $organizationCandidate, $folder);
        $updatedRecord = $preparedRecords[0] ?? $records[$recordIndex];
        $updatedAssignees = docs_extract_assignees($updatedRecord);
        $primaryAssignee = $updatedAssignees[0] ?? null;
        log_docs_event('Mini app task updated', [
            'organization' => $organizationCandidate,
            'documentId' => $documentId,
            'updateType' => $updateType,
            'assigneeId' => in_array($updateType, ['assign', 'assign_add'], true)
                ? ($primaryAssignee['id'] ?? null)
                : null,
            'assigneeIds' => in_array($updateType, ['assign', 'assign_add'], true)
                ? array_values(array_filter(array_map(static function ($entry) {
                    if (!is_array($entry)) {
                        return null;
                    }
                    if (!empty($entry['id'])) {
                        return (string) $entry['id'];
                    }
                    if (!empty($entry['telegram'])) {
                        return (string) $entry['telegram'];
                    }
                    if (!empty($entry['chatId'])) {
                        return (string) $entry['chatId'];
                    }
                    if (!empty($entry['email'])) {
                        return (string) $entry['email'];
                    }
                    return null;
                }, $updatedAssignees)))
                : null,
            'subordinateIds' => in_array($updateType, ['subordinates', 'subordinates_add', 'subordinate_submit', 'subordinate_review'], true)
                ? array_values(array_filter(array_map(static function ($entry) {
                    if (!is_array($entry)) {
                        return null;
                    }
                    $roleValue = strtolower((string) ($entry['role'] ?? ''));
                    if ($roleValue !== 'subordinate') {
                        return null;
                    }
                    foreach (['id', 'telegram', 'chatId', 'email', 'login', 'number'] as $field) {
                        if (!empty($entry[$field])) {
                            return (string) $entry[$field];
                        }
                    }
                    return null;
                }, $updatedAssignees)))
                : null,
            'status' => $updateType === 'status' || $updateType === 'complete' ? ($updatedRecord['status'] ?? null) : null,
            'dueDate' => $updateType === 'due_date' ? ($updatedRecord['dueDate'] ?? null) : null,
            'telegramUserId' => $requestContext['primaryId'] ?? null,
        ]);
        // Маленькое изменение карточки не должно возвращать в HTTP-ответе
        // многомегабайтные OCR-тексты и все ответы задачи. Реестр уже сохранён,
        // а клиенту для синхронизации назначения/статуса достаточно полей
        // самой задачи. Это также исключает поздний memory_limit fatal после
        // успешной записи, который раньше выглядел в Mini App как «Ошибка 500».
        $responseTask = $updatedRecord;
        if ($updateType !== 'file_brief') {
            unset($responseTask['files'], $responseTask['responses']);
        } elseif (isset($responseTask['files']) && is_array($responseTask['files'])) {
            foreach ($responseTask['files'] as &$responseFile) {
                if (is_array($responseFile)) {
                    unset($responseFile['ocrText']);
                }
            }
            unset($responseFile);
        }
        $responsePayload = [
            'message' => $message,
            'organization' => $organizationCandidate,
            'task' => $responseTask,
        ];
        if ($updateType === 'subordinate_submit' && is_array($submittedSubordinate) && !empty($submittedSubordinate)) {
            $submittedSubordinateForNotification = $submittedSubordinate;
            if (!function_exists('fastcgi_finish_request')) {
                docs_notify_responsible_about_subordinate_submission(
                    $updatedRecord,
                    $folder,
                    $organizationCandidate,
                    $submittedSubordinateForNotification
                );
                docs_sync_task_snapshots_after_participation_change(
                    $updatedRecord,
                    $folder,
                    $previousTaskParticipation,
                    $updatedTaskParticipation
                );
                respond_success($responsePayload);
            }
            respond_success_with_background_task($responsePayload, static function () use (
                $submittedSubordinateForNotification,
                $updatedRecord,
                $folder,
                $organizationCandidate,
                $previousTaskParticipation,
                $updatedTaskParticipation
            ): void {
                docs_notify_responsible_about_subordinate_submission(
                    $updatedRecord,
                    $folder,
                    $organizationCandidate,
                    $submittedSubordinateForNotification
                );
                docs_sync_task_snapshots_after_participation_change(
                    $updatedRecord,
                    $folder,
                    $previousTaskParticipation,
                    $updatedTaskParticipation
                );
            });
        }
        if ($updateType === 'subordinate_review' && is_array($reviewedSubordinate) && !empty($reviewedSubordinate)) {
            $reviewedSubordinateForNotification = $reviewedSubordinate;
            if (!function_exists('fastcgi_finish_request')) {
                docs_notify_subordinate_about_review($updatedRecord, $organizationCandidate, $reviewedSubordinateForNotification);
                docs_sync_task_snapshots_after_participation_change(
                    $updatedRecord,
                    $folder,
                    $previousTaskParticipation,
                    $updatedTaskParticipation
                );
                respond_success($responsePayload);
            }
            respond_success_with_background_task($responsePayload, static function () use (
                $reviewedSubordinateForNotification,
                $updatedRecord,
                $organizationCandidate,
                $folder,
                $previousTaskParticipation,
                $updatedTaskParticipation
            ): void {
                docs_notify_subordinate_about_review($updatedRecord, $organizationCandidate, $reviewedSubordinateForNotification);
                docs_sync_task_snapshots_after_participation_change(
                    $updatedRecord,
                    $folder,
                    $previousTaskParticipation,
                    $updatedTaskParticipation
                );
            });
        }
        $isAssignmentUpdate = in_array($updateType, [
            'assign',
            'assign_add',
            'assign_remove',
            'subordinates',
            'subordinates_add',
            'subordinates_remove',
        ], true);
        if ($isAssignmentUpdate) {
            respond_success_with_background_fallback(
                $responsePayload,
                static function () use (
                    $assignedAssignees,
                    $updatedRecord,
                    $organizationCandidate,
                    $folder,
                    $previousTaskParticipation,
                    $updatedTaskParticipation
                ): void {
                    if (!empty($assignedAssignees)) {
                        docs_send_task_assignment_notifications($assignedAssignees, $updatedRecord, $organizationCandidate);
                    }
                    docs_sync_task_snapshots_after_participation_change(
                        $updatedRecord,
                        $folder,
                        $previousTaskParticipation,
                        $updatedTaskParticipation
                    );
                }
            );
        }
        if (!empty($previousTaskParticipation) || !empty($updatedTaskParticipation)) {
            respond_success_with_background_fallback(
                $responsePayload,
                static function () use (
                    $updatedRecord,
                    $folder,
                    $previousTaskParticipation,
                    $updatedTaskParticipation
                ): void {
                    docs_sync_task_snapshots_after_participation_change(
                        $updatedRecord,
                        $folder,
                        $previousTaskParticipation,
                        $updatedTaskParticipation
                    );
                }
            );
        }
        respond_success($responsePayload);
        break;
    case 'organization_template_file':
        $method = strtoupper($method);
        if ($method !== 'GET' && $method !== 'HEAD') {
            respond_error('Некорректный метод запроса.', 405, ['allowedMethod' => 'GET']);
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($_GET['organization'] ?? ''));
        $folder = sanitize_folder_name($requestedOrganization);
        if ($folder === '') {
            respond_error('Шаблон не найден.', 404, ['reason' => 'template_organization_required']);
        }
        $templateName = docs_get_organization_template_filename($folder);
        $resolvedPath = docs_resolve_organization_template_stream_path($folder, $templateName);
        if ($resolvedPath === '') {
            respond_error('Шаблон не найден.', 404, ['reason' => 'template_storage_missing']);
        }
        $disposition = isset($_GET['disposition']) && is_string($_GET['disposition'])
            ? $_GET['disposition']
            : 'inline';
        docs_stream_file_response($resolvedPath, $templateName, $disposition, $method);
        break;
    case 'get_organization_template':
        if ($method !== 'GET') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($_GET['organization'] ?? ''));
        $accessContext = docs_resolve_access_context($requestedOrganization);
        docs_require_admin_session($accessContext);
        $organization = $accessContext['active'];
        $template = docs_get_organization_template_descriptor($organization);
        respond_success([
            'organization' => $organization,
            'template' => $template,
        ]);
        break;
    case 'upload_organization_template':
        if ($method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $payload = load_json_payload();
        if (!is_array($payload) || empty($payload)) {
            $payload = $_POST;
        }
        if (!is_array($payload)) {
            $payload = [];
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($payload['organization'] ?? ''));
        $accessContext = docs_resolve_access_context($requestedOrganization);
        docs_require_admin_session($accessContext);
        if (!isset($_FILES['template']) || !is_array($_FILES['template'])) {
            respond_error('Файл шаблона не передан.');
        }
        $templateFile = $_FILES['template'];
        $uploadError = isset($templateFile['error']) ? (int) $templateFile['error'] : UPLOAD_ERR_NO_FILE;
        if ($uploadError !== UPLOAD_ERR_OK) {
            respond_error('Ошибка загрузки файла шаблона.', 400, ['uploadError' => $uploadError]);
        }
        $tmpName = isset($templateFile['tmp_name']) ? (string) $templateFile['tmp_name'] : '';
        if ($tmpName === '' || !is_uploaded_file($tmpName)) {
            respond_error('Не удалось обработать загруженный файл.', 400);
        }
        $originalName = isset($templateFile['name']) ? (string) $templateFile['name'] : '';
        $extension = strtolower((string) pathinfo($originalName, PATHINFO_EXTENSION));
        if ($extension !== 'docx' && $extension !== 'doc') {
            respond_error('Разрешены только файлы .docx или .doc.', 400);
        }
        $organization = $accessContext['active'];
        $folder = sanitize_folder_name($organization);
        $targetDir = DOCUMENTS_ROOT . '/' . $folder;
        if (!is_dir($targetDir) && !@mkdir($targetDir, 0775, true) && !is_dir($targetDir)) {
            respond_error('Не удалось создать папку организации.', 500);
        }
        $templateName = docs_get_organization_template_filename($folder);
        $targetPath = docs_get_organization_template_path($folder);
        if (!@move_uploaded_file($tmpName, $targetPath)) {
            respond_error('Не удалось сохранить шаблон.', 500);
        }
        @chmod($targetPath, 0664);
        $template = docs_get_organization_template_descriptor($organization);
        respond_success([
            'organization' => $organization,
            'message' => 'Шаблон успешно обновлён.',
            'template' => $template,
        ]);
        break;
    case 'admin_ocr_backfill':
        if ($method !== 'GET' && $method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) (
            $method === 'GET'
                ? ($_GET['organization'] ?? '')
                : ((load_json_payload()['organization'] ?? ($_POST['organization'] ?? '')))
        ));
        $accessContext = docs_resolve_access_context(
            $requestedOrganization !== '' ? $requestedOrganization : null,
            true
        );
        docs_require_document_management_admin_session($accessContext);
        if ($method === 'POST') {
            $payload = load_json_payload();
            if (!is_array($payload) || empty($payload)) {
                $payload = $_POST;
            }
            $operation = strtolower(sanitize_text_field((string) ($payload['operation'] ?? ''), 40));
            $controlled = docs_control_ocr_backfill($operation);
            if (empty($controlled['ok'])) {
                respond_error(
                    (string) ($controlled['error'] ?? 'Не удалось выполнить действие OCR.'),
                    503,
                    ['backfill' => docs_prepare_ocr_backfill_response(
                        (array) ($controlled['state'] ?? docs_load_ocr_backfill_state())
                    )]
                );
            }
        }
        $page = max(1, (int) ($_GET['page'] ?? 1));
        $pageSize = max(1, (int) ($_GET['pageSize'] ?? DOCS_OCR_BACKFILL_ITEMS_PAGE_SIZE));
        $query = sanitize_text_field((string) ($_GET['q'] ?? ''), 200);
        $statusFilter = strtolower(sanitize_text_field((string) ($_GET['status'] ?? ''), 40));
        $state = docs_load_ocr_backfill_state();
        $preparedBackfill = docs_prepare_ocr_backfill_response(
            $state,
            $page,
            $pageSize,
            $query,
            $statusFilter
        );
        if ($method === 'GET'
            && (string) ($state['status'] ?? '') === 'running'
            && empty($preparedBackfill['workerActive'])
        ) {
            $workerStart = docs_start_ocr_backfill_worker();
            if (empty($workerStart['ok'])) {
                $workerError = sanitize_text_field(
                    (string) ($workerStart['error'] ?? 'Не удалось продолжить OCR backfill worker.'),
                    500
                );
                docs_mutate_ocr_backfill_state(static function (array &$current) use ($workerError): array {
                    if ((string) ($current['status'] ?? '') === 'running') {
                        $current['status'] = 'paused';
                    }
                    $current['workerError'] = $workerError;
                    $current['heartbeatAt'] = date('c');
                    return ['workerStartFailed' => true];
                });
                $state = docs_load_ocr_backfill_state();
                $preparedBackfill = docs_prepare_ocr_backfill_response(
                    $state,
                    $page,
                    $pageSize,
                    $query,
                    $statusFilter
                );
            }
        }
        respond_success([
            'message' => $method === 'POST' ? 'Действие OCR принято.' : '',
            'backfill' => $preparedBackfill,
        ]);
        break;
    case 'admin_ocr_s3_users':
        if ($method !== 'GET') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $accessContext = docs_resolve_access_context(
            docs_normalize_organization_candidate((string) ($_GET['organization'] ?? '')) ?: null,
            true
        );
        docs_require_document_management_admin_session($accessContext);
        $usersResult = docs_list_admin_ocr_s3_users(
            max(1, (int) ($_GET['page'] ?? 1)),
            max(1, (int) ($_GET['pageSize'] ?? DOCS_OCR_S3_USERS_PAGE_SIZE)),
            sanitize_text_field((string) ($_GET['q'] ?? ''), 200),
            strtolower(sanitize_text_field((string) ($_GET['status'] ?? ''), 40))
        );
        if (empty($usersResult['ok'])) {
            respond_error((string) ($usersResult['error'] ?? 'Не удалось прочитать пользователей OCR из S3.'), 503);
        }
        unset($usersResult['ok']);
        respond_success(['users' => $usersResult]);
        break;
    case 'admin_ocr_s3_user_files':
        if ($method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $filesPayload = load_json_payload();
        if (!is_array($filesPayload) || empty($filesPayload)) {
            $filesPayload = $_POST;
        }
        $accessContext = docs_resolve_access_context(
            docs_normalize_organization_candidate((string) ($filesPayload['organization'] ?? '')) ?: null,
            true
        );
        docs_require_document_management_admin_session($accessContext);
        $filesResult = docs_list_admin_ocr_s3_user_files(
            (string) ($filesPayload['telegramUserId'] ?? ''),
            max(1, (int) ($filesPayload['page'] ?? 1)),
            max(1, (int) ($filesPayload['pageSize'] ?? DOCS_OCR_S3_FILES_PAGE_SIZE)),
            sanitize_text_field((string) ($filesPayload['q'] ?? ''), 200)
        );
        if (empty($filesResult['ok'])) {
            respond_error((string) ($filesResult['error'] ?? 'Не удалось прочитать OCR пользователя из S3.'), 503);
        }
        unset($filesResult['ok']);
        respond_success(['userFiles' => $filesResult]);
        break;
    case 'admin_ocr_s3_text':
        if ($method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $payload = load_json_payload();
        if (!is_array($payload) || empty($payload)) {
            $payload = $_POST;
        }
        $accessContext = docs_resolve_access_context(
            docs_normalize_organization_candidate((string) ($payload['organization'] ?? '')) ?: null,
            true
        );
        docs_require_document_management_admin_session($accessContext);
        $textResult = docs_read_admin_ocr_s3_text(
            (string) ($payload['telegramUserId'] ?? ''),
            (string) ($payload['entryToken'] ?? ''),
            max(0, (int) ($payload['offset'] ?? 0)),
            max(1, (int) ($payload['limit'] ?? 50000))
        );
        if (empty($textResult['ok'])) {
            respond_error((string) ($textResult['error'] ?? 'OCR-текст не найден в S3.'), 404);
        }
        unset($textResult['ok']);
        respond_success(['ocrTextResult' => $textResult]);
        break;
    case 'admin_cron_management':
        if ($method !== 'GET' && $method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $payload = $method === 'POST' ? load_json_payload() : $_GET;
        if (!is_array($payload) || empty($payload)) {
            $payload = $_POST;
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($payload['organization'] ?? ''));
        $accessContext = docs_resolve_access_context(
            $requestedOrganization !== '' ? $requestedOrganization : null,
            true
        );
        docs_require_admin_session($accessContext);
        $operation = $method === 'POST'
            ? strtolower(sanitize_text_field((string) ($payload['operation'] ?? 'status'), 40))
            : 'status';
        if ($operation === 'remove_legacy_ocr') {
            $result = docs_remove_legacy_ocr_cron();
            if (empty($result['ok'])) {
                respond_error((string) ($result['error'] ?? 'Не удалось удалить старый OCR-cron.'), 500, [
                    'cron' => $result['cron'] ?? docs_legacy_ocr_cron_status(),
                ]);
            }
            respond_success([
                'message' => (int) ($result['removed'] ?? 0) > 0
                    ? 'Старый OCR-cron удалён из crontab.'
                    : 'Старый OCR-cron уже отсутствует.',
                'cron' => $result['cron'] ?? docs_legacy_ocr_cron_status(),
            ]);
        }
        if ($operation !== 'status') {
            respond_error('Неизвестная операция управления cron.', 400);
        }
        respond_success([
            'cron' => docs_legacy_ocr_cron_status(),
        ]);
        break;
    case 'ai_response_ocr_texts':
        if ($method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $sessionAuth = docs_get_session_auth();
        $sessionRole = is_array($sessionAuth) ? strtolower((string) ($sessionAuth['role'] ?? '')) : '';
        $telegramContext = docs_resolve_telegram_init_data_context();
        if (!empty($telegramContext['present']) && empty($telegramContext['valid'])) {
            respond_error('Не удалось подтвердить данные Telegram. Откройте мини-приложение заново.', 401, [
                'requiresTelegramReauth' => true,
                'telegramInitDataError' => (string) ($telegramContext['error'] ?? 'invalid'),
            ]);
        }
        if (!in_array($sessionRole, ['admin', 'user'], true) && empty($telegramContext['valid'])) {
            respond_error('Для чтения OCR-текста требуется авторизация.', 401);
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($_POST['organization'] ?? ''));
        $taskId = sanitize_text_field((string) ($_POST['taskId'] ?? ($_POST['documentId'] ?? '')), 200);
        if ($requestedOrganization === '' || $taskId === '') {
            respond_error('Не указаны организация или идентификатор задачи.', 400);
        }
        $accessContext = docs_resolve_access_context($requestedOrganization);
        $organization = (string) ($accessContext['active'] ?? '');
        if ($organization === '') {
            respond_error('Организация недоступна.', 403);
        }
        $folder = sanitize_folder_name($organization);
        $records = load_registry($folder);
        $record = null;
        foreach ($records as $candidate) {
            if (is_array($candidate) && (string) ($candidate['id'] ?? '') === $taskId) {
                $record = $candidate;
                break;
            }
        }
        if (!is_array($record)) {
            respond_error('Задача не найдена.', 404);
        }
        $accessRecordList = docs_prepare_records_for_response([$record], $organization, $folder, false);
        $filter = !empty($accessContext['forceAccess']) ? null : ($accessContext['filter'] ?? null);
        if ($filter !== null) {
            $settings = load_admin_settings($folder);
            $responsibles = isset($settings['responsibles']) && is_array($settings['responsibles'])
                ? $settings['responsibles']
                : [];
            $accessRecordList = filter_documents_for_assignee($accessRecordList, $filter, $responsibles);
        }
        if (empty($accessRecordList)) {
            respond_error('Задача недоступна.', 403);
        }
        $preparedRecordList = docs_prepare_records_for_response([$record], $organization, $folder);
        $preparedRecord = isset($preparedRecordList[0]) && is_array($preparedRecordList[0])
            ? docs_hydrate_task_ocr_from_participant_snapshots($preparedRecordList[0], [])
            : [];
        $ocrFiles = [];
        foreach ((array) ($preparedRecord['files'] ?? []) as $file) {
            if (!is_array($file)) {
                continue;
            }
            $ocrText = isset($file['ocrText']) && is_string($file['ocrText'])
                ? trim($file['ocrText'])
                : '';
            $ocrFiles[] = [
                'id' => sanitize_text_field((string) ($file['id'] ?? ''), 200),
                'name' => sanitize_text_field(
                    (string) ($file['originalName'] ?? ($file['name'] ?? ($file['storedName'] ?? ''))),
                    255
                ),
                'originalName' => sanitize_text_field((string) ($file['originalName'] ?? ''), 255),
                'storedName' => sanitize_text_field((string) ($file['storedName'] ?? ''), 255),
                'url' => sanitize_text_field((string) ($file['url'] ?? ''), 1000),
                'ocrText' => $ocrText,
                'ocrTextLength' => $ocrText !== ''
                    ? mb_strlen($ocrText, 'UTF-8')
                    : max(0, (int) ($file['ocrTextLength'] ?? 0)),
            ];
        }
        respond_success([
            'organization' => $organization,
            'taskId' => $taskId,
            'files' => $ocrFiles,
        ]);
        break;
    case 'ai_brief_generate':
        if ($method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $sessionAuth = docs_get_session_auth();
        $sessionRole = is_array($sessionAuth) ? strtolower((string) ($sessionAuth['role'] ?? '')) : '';
        $telegramContext = docs_resolve_telegram_init_data_context();
        if (!empty($telegramContext['present']) && empty($telegramContext['valid'])) {
            respond_error('Не удалось подтвердить данные Telegram. Откройте мини-приложение заново.', 401, [
                'requiresTelegramReauth' => true,
                'telegramInitDataError' => (string) ($telegramContext['error'] ?? 'invalid'),
            ]);
        }
        if (!in_array($sessionRole, ['admin', 'user'], true) && empty($telegramContext['valid'])) {
            respond_error('Для запуска «Кратко ИИ» требуется авторизация.', 401);
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($_POST['organization'] ?? ''));
        if ($requestedOrganization === '') {
            respond_error('Не указана организация.', 400);
        }
        $accessContext = docs_resolve_access_context($requestedOrganization);
        $organization = (string) ($accessContext['active'] ?? '');
        if ($organization === '') {
            respond_error('Организация недоступна.', 403);
        }
        $ocrOnlyMode = strtolower(sanitize_text_field((string) ($_POST['mode'] ?? ''), 40)) === 'ocr_only';
        $settings = load_admin_settings(sanitize_folder_name($organization));
        if (!empty($telegramContext['valid'])) {
            $settings['aiBriefProvider'] = 'deepseek';
        }
        $aiConfig = [];
        if (!$ocrOnlyMode) {
            $aiConfig = docs_resolve_ai_brief_config($settings);
            if (trim((string) ($aiConfig['apiKey'] ?? '')) === '') {
                respond_error(
                    'Для провайдера «' . (string) ($aiConfig['providerLabel'] ?? 'ИИ') . '» не задан API-ключ в .env.',
                    503
                );
            }
        }
        if (!isset($_FILES['file']) || !is_array($_FILES['file'])) {
            respond_error('Файл для «Кратко ИИ» не передан.', 400);
        }
        $uploadedFile = $_FILES['file'];
        $uploadError = (int) ($uploadedFile['error'] ?? UPLOAD_ERR_NO_FILE);
        if ($uploadError !== UPLOAD_ERR_OK) {
            respond_error('Не удалось загрузить файл для анализа.', 400, ['uploadError' => $uploadError]);
        }
        $temporaryPath = (string) ($uploadedFile['tmp_name'] ?? '');
        $originalName = sanitize_text_field((string) ($uploadedFile['name'] ?? 'document'), 255);
        $size = (int) ($uploadedFile['size'] ?? 0);
        if ($temporaryPath === '' || !is_uploaded_file($temporaryPath)) {
            respond_error('Загруженный файл недоступен.', 400);
        }
        if ($size <= 0 || $size > DOCS_ATTACHMENT_MAX_FILE_SIZE) {
            respond_error('Размер файла должен быть от 1 байта до ' . docs_format_file_size(DOCS_ATTACHMENT_MAX_FILE_SIZE) . '.', 413);
        }
        if (!docs_is_live_ocr_supported_file(['originalName' => $originalName])) {
            respond_error('Этот формат не поддерживается приватным OCR.', 415);
        }
        @set_time_limit(DOCS_AI_BRIEF_OCR_WAIT_SECONDS + DOCS_AI_TASK_SEARCH_AI_TIMEOUT_SECONDS + 20);
        $ocrJob = docs_create_private_ocr_job($temporaryPath, $originalName);
        if (empty($ocrJob['ok'])) {
            respond_error('Не удалось запустить приватный OCR: ' . (string) ($ocrJob['error'] ?? 'неизвестная ошибка'), 502);
        }
        $requestedPageLimit = (int) ($_POST['pageLimit'] ?? 0);
        $ocrPageLimit = $ocrOnlyMode ? max(1, min(5, $requestedPageLimit > 0 ? $requestedPageLimit : 5)) : 0;
        $ocrResult = docs_wait_for_private_ocr_text((string) $ocrJob['jobId'], $ocrPageLimit);
        if (empty($ocrResult['ok'])) {
            $ocrErrorStatus = (int) ($ocrResult['httpStatus'] ?? 0);
            if ($ocrErrorStatus < 400 || $ocrErrorStatus > 599) {
                $ocrErrorStatus = 504;
            }
            respond_error((string) ($ocrResult['error'] ?? 'Приватный OCR не вернул результат.'), $ocrErrorStatus, [
                'ocrJobId' => (string) $ocrJob['jobId'],
                'ocrProgress' => (int) ($ocrResult['progress'] ?? 0),
            ]);
        }
        if ($ocrOnlyMode) {
            log_docs_event('Private OCR extracted for document AI', [
                'organization' => $organization,
                'fileName' => $originalName,
                'fileSize' => $size,
                'ocrJobId' => (string) $ocrJob['jobId'],
                'ocrPagesCount' => (int) ($ocrResult['pagesCount'] ?? 0),
                'ocrPagesUsed' => (int) ($ocrResult['pagesUsed'] ?? 0),
            ]);
            respond_success([
                'text' => (string) $ocrResult['text'],
                'ocrEngine' => 'private',
                'ocrJobId' => (string) $ocrJob['jobId'],
                'ocrPagesCount' => (int) ($ocrResult['pagesCount'] ?? 0),
                'ocrPagesUsed' => (int) ($ocrResult['pagesUsed'] ?? 0),
                'textTruncated' => !empty($ocrResult['textTruncated']),
            ]);
        }
        $briefResult = docs_generate_ai_brief_from_ocr_text((string) $ocrResult['text'], $aiConfig);
        if (empty($briefResult['ok'])) {
            respond_error(
                (string) ($briefResult['error'] ?? 'Не удалось получить краткий вывод.'),
                max(400, min(599, (int) ($briefResult['status'] ?? 502)))
            );
        }
        log_docs_event('AI brief generated through private OCR', [
            'organization' => $organization,
            'fileName' => $originalName,
            'fileSize' => $size,
            'ocrJobId' => (string) $ocrJob['jobId'],
            'ocrPagesCount' => (int) ($ocrResult['pagesCount'] ?? 0),
            'provider' => (string) $briefResult['provider'],
            'model' => (string) $briefResult['model'],
        ]);
        respond_success([
            'summary' => (string) $briefResult['summary'],
            'model' => (string) $briefResult['model'],
            'provider' => (string) $briefResult['provider'],
            'ocrEngine' => 'private',
            'ocrJobId' => (string) $ocrJob['jobId'],
            'ocrPagesCount' => (int) ($ocrResult['pagesCount'] ?? 0),
        ]);
        break;
    case 'objects_list':
        $requestedOrganization = docs_normalize_organization_candidate($_GET['organization'] ?? '');
        $accessContext = docs_resolve_access_context($requestedOrganization);
        $organization = (string) $accessContext['active'];
        $folder = sanitize_folder_name($organization);
        $session = docs_get_session_auth();
        if (!is_array($session) || !in_array($session['role'] ?? '', ['admin', 'user'], true)) {
            respond_error('Необходимо войти в документооборот.', 401);
        }
        $objects = docs_list_organization_objects($folder);
        $canManageObjects = ($session['role'] ?? '') === 'admin'
            && strtolower((string) ($session['adminScope'] ?? '')) !== 'director';
        if (($session['role'] ?? '') !== 'admin') {
            $allowedIds = array_fill_keys(docs_user_object_ids(load_admin_settings($folder), $session), true);
            $objects = array_values(array_filter($objects, static function (array $object) use ($allowedIds): bool {
                return isset($allowedIds[(string) ($object['id'] ?? '')]);
            }));
        }
        respond_success([
