        if (!is_array($payload) || empty($payload)) {
            $payload = $_POST;
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($payload['organization'] ?? ''));
        $accessContext = docs_resolve_access_context($requestedOrganization);
