        }
        foreach (docs_list_organization_objects($folder) as $existingObject) {
            if (mb_strtolower((string) ($existingObject['name'] ?? ''), 'UTF-8') === mb_strtolower($name, 'UTF-8')) {
                respond_error('Объект с таким названием уже существует.', 409);
            }
        }
        do {
            $objectId = docs_generate_object_id();
        } while (is_file(docs_object_file_path($folder, $objectId)));
        $now = date('c');
        $object = [
            'schemaVersion' => DOCS_OBJECT_SCHEMA_VERSION,
            'id' => $objectId,
            'name' => $name,
            'schemaRevision' => 1,
            'revision' => 1,
            'columns' => docs_prepare_object_columns([
                ['label' => 'Наименование', 'type' => 'text'],
            ]),
            'rows' => [],
            'createdAt' => $now,
            'updatedAt' => $now,
        ];
