    case 'object_schema_save':
        if ($method !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
        }
        $payload = load_json_payload();
        if (!is_array($payload) || empty($payload)) {
            $payload = $_POST;
        }
        $requestedOrganization = docs_normalize_organization_candidate((string) ($payload['organization'] ?? ''));
        $accessContext = docs_resolve_access_context($requestedOrganization);
        docs_require_objects_admin_session($accessContext);
        $organization = (string) $accessContext['active'];
        $folder = sanitize_folder_name($organization);
        $objectId = docs_normalize_object_id($payload['objectId'] ?? '');
        if ($objectId === '') {
            respond_error('Некорректный идентификатор объекта.', 422);
        }
        $lockHandle = docs_object_mutation_lock($folder, $objectId);
        if ($lockHandle === null) {
            respond_error('Объект занят другим изменением. Повторите попытку.', 423);
        }
        try {
            $object = docs_load_object_file($folder, $objectId);
            if (!is_array($object)) {
                respond_error('Объект не найден.', 404);
            }
            $expectedRevision = max(0, (int) ($payload['schemaRevision'] ?? 0));
            if ($expectedRevision !== (int) $object['schemaRevision']) {
                respond_error('Структура объекта уже изменена. Обновите данные.', 409, [
                    'object' => docs_object_summary($object),
                ]);
            }
            $name = sanitize_text_field((string) ($payload['name'] ?? ''), 160);
            if ($name === '') {
                respond_error('Укажите название объекта.', 422);
            }
            foreach (docs_list_organization_objects($folder) as $otherObject) {
                if (($otherObject['id'] ?? '') !== $objectId
                    && mb_strtolower((string) ($otherObject['name'] ?? ''), 'UTF-8') === mb_strtolower($name, 'UTF-8')
                ) {
                    respond_error('Объект с таким названием уже существует.', 409);
                }
            }
            $columns = docs_prepare_object_columns($payload['columns'] ?? [], $object['columns']);
            $remainingColumnIds = [];
            foreach ($columns as $column) {
                $remainingColumnIds[(string) ($column['id'] ?? '')] = true;
            }
            $removedColumnIds = [];
            foreach ($object['columns'] as $existingColumn) {
                $existingColumnId = (string) ($existingColumn['id'] ?? '');
                if ($existingColumnId !== '' && !isset($remainingColumnIds[$existingColumnId])) {
                    $removedColumnIds[] = $existingColumnId;
                }
            }
            $confirmedRemovedColumnIds = docs_sanitize_object_column_ids($payload['confirmedRemovedColumnIds'] ?? []);
            if (!empty(array_diff($removedColumnIds, $confirmedRemovedColumnIds))) {
                respond_error('Подтвердите удаление столбцов и связанных с ними значений.', 422, [
                    'removedColumnIds' => $removedColumnIds,
                ]);
            }
            $schemaChanged = $name !== $object['name']
                || json_encode($columns, JSON_UNESCAPED_UNICODE) !== json_encode($object['columns'], JSON_UNESCAPED_UNICODE);
            if ($schemaChanged) {
                foreach ($object['rows'] as &$row) {
                    $row['values'] = docs_prepare_object_values($row['values'] ?? [], $columns, false);
                    $row['version'] = max(1, (int) ($row['version'] ?? 1)) + 1;
                }
                unset($row);
                $object['name'] = $name;
                $object['columns'] = $columns;
                $object['schemaRevision'] = (int) $object['schemaRevision'] + 1;
                $object['revision'] = (int) $object['revision'] + 1;
                $object['updatedAt'] = date('c');
                if (!docs_save_object_file($folder, $object)) {
                    respond_error('Не удалось безопасно сохранить структуру объекта.', 500);
                }
            }
            respond_success([
                'organization' => $organization,
                'object' => docs_object_summary($object),
                'message' => $schemaChanged ? 'Объект и столбцы сохранены.' : 'Изменений нет.',
            ]);
        } finally {
            docs_release_object_mutation_lock($lockHandle);
        }
        break;
