            respond_error('Объект занят другим изменением. Повторите попытку.', 423);
        }
        $objectPath = docs_object_file_path($folder, $objectId);
        try {
            $object = docs_load_object_file($folder, $objectId);
            if (!is_array($object)) {
                respond_error('Объект не найден.', 404);
            }
            $confirmName = sanitize_text_field((string) ($payload['confirmName'] ?? ''), 160);
            if ($confirmName === '' || $confirmName !== $object['name']) {
                respond_error('Для удаления введите точное название объекта.', 422);
            }
            $registryDetach = docs_detach_object_from_registry($folder, $objectId);
            if (empty($registryDetach['ok'])) {
                respond_error('Не удалось очистить связи объекта с задачами документооборота.', 500);
            }
            if (!docs_remove_object_from_admin_settings($folder, $objectId)) {
