            }
            if (!is_file($objectPath) || !@unlink($objectPath)) {
                respond_error('Не удалось удалить файл объекта.', 500);
            }
        } finally {
            docs_release_object_mutation_lock($lockHandle);
        }
        foreach ([$objectPath . '.bak', $objectPath . '.write.lock', $objectPath . '.mutation.lock'] as $auxiliaryPath) {
            if (is_file($auxiliaryPath)) {
                @unlink($auxiliaryPath);
            }
        }
        respond_success([
            'organization' => $organization,
            'objectId' => $objectId,
            'detachedDocuments' => (int) ($registryDetach['count'] ?? 0),
            'message' => 'Объект и его таблица удалены. Связанные задачи отвязаны.',
        ]);
